(window.GIM_TP=window.GIM_TP||{})["Zevachim.1"]={"from":198,"a":[[["וחכמים עשו חיזוק לדבריהם יותר משל תורה","תנו רבנן (ויקרא י, יג) כי כן צויתי כאשר צויתי כאשר צוה ה' כי כן צויתי באנינות יאכלוה כאשר צויתי בשעת מעשה אמר להן כאשר צוה ה' לא מאליי אני אומר","ורמינהי מפני אנינות נשרפה לכך נאמר כאלה","אמר שמואל לא קשיא הא ר\"י הא ר\"נ","דתניא מפני אנינות שרפוה לכך נאמר כאלה דברי רבי נחמיה רבי יהודה ור\"ש אומרים מפני טומאה נשרפה שאם אתה אומר מפני אנינות נשרפה היו לשלשתן שישרפוה ד\"א היו ראוי לאוכלן לערב ד\"א והלא פינחס היה עמהן","רבא אמר אידי ואידי רבי נחמיה ולא קשיא כאן בקדשי שעה כאן בקדשי דורות","רבי נחמיה היכי מתריץ להני קראי ורבנן היכי מתרצי להו להני קראי","רבי נחמיה מתריץ להו הכי מדוע לא אכלתם אמר לו משה לאהרן שמא נכנס דמה לפני ולפנים אמר לו (ויקרא י, יח) הן לא הובא את דמה שמא חוץ למחיצתה יצאת אמר לו בקדש היתה","ודלמא באנינות אקריבתוה ופסלתוה אמר לו משה וכי הם הקריבו אני הקרבתי וא\"ל הן לא הובא את דמה ובקדש היתה אכול תאכלו אותה כאשר צויתי באנינות יאכלוה","אמר לו (ויקרא י, יט) ותקראנה אותי כאלה ואכלתי חטאת היום הייטב בעיני ה' שמא לא שמעת אלא בקדשי שעה","דאי בקדשי דורות ק\"ו ממעשר הקל ומה מעשר הקל אמרה תורה (דברים כו, יד) לא אכלתי באוני ממנו בקדשי דורות לא כל שכן","מיד (ויקרא י, כ) וישמע משה וייטב בעיניו הודה ולא בוש משה לומר לא שמעתי אלא אמר שמעתי ושכחתי","ור\"י ור\"ש היכי מתרצי להו הכי מתרצי להו (ויקרא י, יז) מדוע לא אכלתם את החטאת במקום [הקודש] שמא נכנס דמה לפני ולפנים אמר לו (ויקרא י, יח) הן לא הובא את דמה (אל הקדש פנימה)","שמא חוץ למחיצתה יצאת אמר לו הן בקודש היתה ודילמא באנינות אקריבתוה ופסלתוה אמר לו משה הן הקריבוה דפסלה בהו אנינות אני הקרבתיה","ודילמא אגב מררייכו פשעתו בה ואיטמאי אמר לו משה כך אני בעיניך שאני מבזה קדשי שמים ותקראנה אותי כאלה ואפילו אלה וכאלה אין אני מבזה קדשי שמים","אמר לו ואי הן לא הובא את דמה ובקודש היתה אכול תאכלו אותה בקודש כאשר צויתי באנינות יאכלוה","אמר לו שמא לא שמעת אלא בלילה דאי ביום ק\"ו ממעשר הקל ומה מעשר הקל אמרה תורה (דברים כו, יד) לא אכלתי באוני ממנו קודש חמור לא כל שכן","מיד וישמע משה"],[[0,"וחכמים עשו חיזוק לדבריהם יותר","ממה שעשתה תורה לדבריה:"],[1,"כי כן צויתי","במנחות שמיני כתיב קחו את המנחה וגו':"],[1,"באנינות","דנדב ואביהוא:"],[1,"כאשר צויתי","בחטאת דראש חדש שנשרפה כתיב. הן לא הובא את דמה וגו':"],[1,"בשעת מעשה","כשאירע להם אנינותם אמר להם שלא ימנעו מאכילת קדשים היום ששמע מפי הגבורה שחלוק אנינות היום בקדשים משאר ימים וכשראה שנשרפה אמר להם אכול תאכלו אותה היה להם לאוכלה כאשר צויתי אתכם בשעת מעשה:"],[1,"כאשר צוה ה'","באכילת חזה ושוק של צבור שקרבו בו ביום נאמר:"],[1,"ולא מאליי אני אומר","לאוכלם באנינות:"],[2,"מפני אנינות נשרפה","לכך נאמר ותקראנה אותי כאלה ומצינו שהודה לו משה כדכתיב וייטב בעיניו ואם מפי הגבורה שמע היתר אנינות לבו ביום למה הודה:"],[4,"מפני אנינות נשרפה","שלא הותרה להם אנינות לבו ביום ולית ליה לרבי נחמיה הך דרשא דבאנינות יאכלוה אלא הכי קאמר לו כי כן צויתי שאף מנחת צבור זו שלא מצינו מנחה קריבה לצבור כיוצא בה נאכלת ועל האנינות לא הוזכר למשה לדרוש ק\"ו ממעשר וכשהזכירו אהרן הודה לו:"],[4,"מפני טומאה נשרפה","שנגעה בה טומאה בחטאת של שעיר ראש חדש שקרבה (להם) בו ביום שהוקם המשכן בראש חדש ניסן והוא היה שמיני למלואים ושלשה שעירים קרבו בו ביום שעיר נחשון ושעיר ראש חדש ושעיר שבא לשעה כדכתיב (ויקרא ט׳:ג׳) קחו שעיר עזים לחטאת ושל ראש חדש נשרפה כדאמרינן לקמן:"],[4,"היה להם לשלשתן","דשלשה שעירים קרבו להם כדלקמן:"],[4,"היה להם לאוכלם לערב","לר' יהודה אע\"ג דאמר אנינות לילה דאורייתא מודה הוא דלאותו היום הותרה להן אנינות לילה וכל שכן לר\"ש דאף לדורות אינו אלא מדברי סופרים ולקמן מפרש טעם דרבי נחמיה:"],[4,"והלא פינחס היה עמהן","שלא היה אונן ולקמן פריך שפיר קאמרי ליה:"],[5,"אידי ואידי רבי נחמיה","ואית ליה לרבי נחמיה דהותרה אנינות במנחה דכתיב כי כן צויתי ואפי' הכי בשעיר של ראש חודש הודה לדברי אהרן ולא קשיא מנחה קדשי שעה היא והוראת שעה היתה בה שתאכל לאוננין אבל שעיר של ראש חדש קדשי דורות הן ומשה כשקצף טעה כסבור כיון ששמעתי היתר אנינות במנחה הוא הדין לחטאת ואמר לו אהרן שמא דוקא קדשי שעה שמעת והודה לו:"],[6,"רבי נחמיה","דאמר מפני אנינות נשרפה היכי מתרץ להני קראי דאותה פרשה מאי אמר משה ומאי אהדריה לענין אנינות ומה היה הקצפון ומה היא הודאה:"],[6,"ורבנן","רבי יהודה ורבי שמעון היכי מתרצי להו לענין טומאה:"],[7,"שמא נכנס דמו לפנים","מתשובתו אתה למד שכך אמר להם מתחילה מדקאמר הן לא הובא וגו' פנימה:"],[7,"אמר לו","אהרן למשה:"],[8,"משה הן הקריבו","בתמיה וכי בניי שהם הדיוטים שמשו היום והלא עלי הטלת כל העבודה כדכתיב (שם) קרב אל המזבח ועשה וגו' ואני כהן גדול אני ומקריב אונן:"],[8,"כאשר צויתי","במנחה:"],[9,"קדשי שעה","כגון מנחה שחובת שעה היתה ואינה נוהגת לדורות:"],[14,"מררייכו","צעריכם:"],[14,"שאני מבזה קדשי שמים","להסיח דעתי מהם אפי' אלה וכאלה אבלות אירעוני אין אני מבזה כו' והיינו דכתיב כאלה ולא כתיב אלה:"]],[[0,"וחכמים עשו חיזוק לדבריהם יותר משל תורה","אין פירושו יותר משל תורה דעלמא אלא כלומר חכמים עשו חיזוק לדבריהם יותר ממה שעשתה תורה לדבריה:"],[2,"ורמינהי מפני אנינות נשרפה","לכך נאמר כאלה פי' בקונטרס שהודה לו משה כדכתיב וייטב בעיניו ואם מפי הגבורה שמע היתר אנינות לבו ביום למה הודה ומשני שמואל דההיא כרבי נחמיה דאמר מפני אנינות נשרפה ולית ליה לרבי נחמיה דרשא דבאנינות יאכלוה אלא הכי אמר להן משה כי כן צויתי שאף מנחת צבור זו שלא מצינו מנחה קרבה לצבור כיוצא בה נאכלת ועל האנינות לא הוזכר לו למשה לדרוש קל וחומר ממעשר וכשהזכירו אהרן הודה לו כך פירש בקונטרס ולא מיסתבר ליה לשמואל לשנויי כדרבא אידי ואידי רבי נחמיה כאן בקדשי שעה כאן בקדשי דורות ששמע משה היתר אנינות במנחה שהיא קדשי שעה והיה סבור כמו כן בחטאת דראש חדש שהיא קדשי דורות דאין סברא שיהא משה טועה בין קדשי שעה לקדשי דורות וקשה לשמואל מאי הוה משני רבי נחמיה מקושיא דר' יהודה אם אתה אומר מפני אנינות נשרפה היה לשלשתן שישרפו ועוד משמע לקמן דיש חילוק לרבי נחמיה בין קדשי שעה לקדשי דורות דקאמר אלא לר' נחמיה מאי היום חובת היום היינו דורות ונראה לפרש דסלקא דעתך כאשר צויתי דכתיב בשעיר דראש חדש לא בעי למימר כאשר צויתי במנחה תעשו את החטאת אלא כאשר אני מצוה עכשיו תאכלו באנינות והיה סבור משה דכמו שהותר קדשי דורות אנינות לילה הוא הדין ביום ובין יום ללילה היה טועה לכך פריך ורמינהי מפני אנינות נשרפה ואם היתה אנינות לילה מותרת אמאי נשרפה היה להם לאכול בלילה ומשני הא רבי נחמיה הא ר' יהודה: (הג\"ה) ההיא דלעיל דהותר אנינות לילה בכל הקדשים לר' יהודה והא דנשרפה שעיר החדש מפני טומאה אבל רבי נחמיה סבר אף לילה נאסר בקדשי דורות בשעיר החדש ולא הותרה אנינות אלא בקדשי שעה אבל משה אמר כאשר צויתי חטאת החדש לאכול באנינות דהיה סבור שהתיר לו בכל הקדשים (הג\"ה) והא דלא משני כולה רבי נחמיה היא כאן בקדשי שעה כאן בקדשי דורות היינו משום דכאשר צויתי בחטאת כתיב דהוי בקדשי דורות ורבא סבירא ליה כאשר צויתי אמנחה קאי ולא אחטאת וה\"ק כאשר צויתי במנחה מפי הגבורה כך אני מצוה מעצמי בחטאת והשתא ניחא דלשמואל לא קשיא ליה היה לשלשתן שישרפו דיש חילוק לרבי נחמיה בין קדשי שעה לקדשי דורות:"],[10,"ומה מעשר הקל כו'","תימה מה למעשר שכן טעון כסף צורה דכה\"ג פריך בפרק אלו הן הלוקין (מכות דף יז:):"],[16,"דאי ביום קל וחומר ממעשר","תימה בלילה נמי נימא קל וחומר דהא רבי יהודה אית ליה אנינות לילה דאורייתא לדורות:"]]],[["וייטב בעיניו לא בוש משה לומר לא שמעתי אלא שמעתי ושכחתי","איבעי להו לשהוייה ולמיכלא באורתא טומאה באונס באתה","בשלמא לרבנן היינו דכתיב היום אלא לרבי נחמיה מאי היום חובת היום","בשלמא לרבי נחמיה היינו דכתיב הן היום אלא לרבנן מאי הן היום ה\"ק הן הקריבו אני הקרבתי","אמר מר היו לשלשתן שישרפו מאי שלשתן","דתניא (ויקרא י, טז) ואת שעיר החטאת דרש דרש משה שעיר זו שעיר נחשון חטאת זו חטאת שמיני דרש שעיר של ראש חודש","יכול שלשתן נשרפו ת\"ל והנה שורף אחד נשרף ולא שלשתן נשרפו דרש דרש שתי דרישות למה אמר להו מפני מה חטאת זו נשרפה ואלו מונחות ואיני יודע איזהו כשהוא אומר (ויקרא י, יז) ואותה נתן לכם לשאת את עון העדה הוי אומר זה שעיר של ראש חודש","שפיר קאמרי ליה רבי נחמיה לטעמיה דאמר קדשי שעה לא פסלה בהו אנינות","אמר מר היה לו לאכלה לערב שפיר קאמרי ליה קסבר אנינות לילה דאורייתא","דבר אחר והלא פינחס היה עמהן שפיר קאמרי ליה סבר לה כרבי אלעזר דאר\"א א\"ר חנינא לא נתכהן פינחס עד שהרגו לזמרי דכתיב (במדבר כה, יג) והיתה לו ולזרעו אחריו ברית כהונת עולם","רב אשי אמר עד ששם שלום בין השבטים שנאמר (יהושע כב, ל) וישמע פינחס הכהן ונשיאי העדה וראשי אלפי ישראל וגו'","ואידך נמי והכתיב והיתה לו ולזרעו אחריו כי כתיב ההוא בברכה הוא דכתיב","ואידך נמי הא כתיב וישמע פינחס הכהן ההוא ליחס זרעו אחריו","אמר רב משה רבינו כהן גדול וחולק בקדשי שמים היה שנאמר (ויקרא ח, כט) מאיל המלואים למשה היה למנה","מיתיבי והלא פינחס היה עמהן ואם איתא לימא והלא משה רבינו היה עמהן דילמא שאני משה דטריד בשכינה דאמר מר משה בהשכמה עלה ובהשכמה ירד","מיתיבי (ויקרא כא, כב) לחם אלהיו מקדשי הקדשים ומן הקדשים יאכל אם נאמרו קדשי קדשים למה נאמר קדשים קלים ואם נאמרו קדשים קלים למה נאמר קדשי קדשים","אילו לא נאמר קדשים קלים הייתי אומר קדשי קדשים הוא דאוכל . שהרי הותרו לזר ולהן קדשים קלים לא יאכל ואילו לא נאמרו קדשי קדשים הייתי אומר בקדשים קלים יהא אוכל שהן קלים בקדשי קדשים לא יהא אוכל לכך נאמרו קדשי קדשים ולכך נאמר קדשים קלים","קתני מיהא שהרי הותרו לזר ולהן לאו משה אמר רב ששת לא בבמה לזר וכדברי האומר יש מנחה בבמה","מיתיבי מרים מי הסגירה א\"ת משה הסגירה משה זר הוא"],[[1,"טומאה באונס","שרצו להשהותה עד הלילה ולאוכלן כולן יחד ונטמאת באונס:"],[2,"בשלמא לרבנן","דאמרי אחד קדשי שעה ואחד קדשי דורות לילה הותר להן ולא יום עד הלילה היו רוצין להשהותה היינו דכתיב ואכלתי חטאת היום אני אונן ואוכל היום חטאת שמא לא שמעת אלא בלילה:"],[2,"אלא לרבי נחמיה","דאמר מה שהותר להם הותר אפי' ביום כגון קדשי שעה ומה שנאסר נאסר אף בלילה:"],[2,"מאי ואכלתי חטאת היום","בלילה נמי קדשי דורות הוו אסירי דהאמר מפני אנינות נשרפה ולא המתינו עד הערב ויאכלוה אלמא קסבר אנינות לילה דאורייתא והכי אמר לקמן:"],[2,"מאי היום חובת היום","כלומר קדשי דורות שהן חובת היום של ר\"ח אתה אומר לי לאכול אונן והיינו חטאת היום חטאת הקבוע ליום:"],[3,"בשלמא לרבי נחמיה היינו דכתיב הן היום הקריבו","כלומר קרבן זה לחובת היום קרב וקדשי דורות הוא ואני אוכלן אונן בתמיה שמא לא שמעת אלא בשל שעה:"],[3,"אלא לרבנן","דאמרי שמא לא שמעת אלא בלילה קאמר ליה מאי היא דקאמר ליה הן היום הקריבו:"],[3,"הכי קאמר ליה","אמרת דילמא באנינות אקריבתיה וכי הן בניי הדיוטות היום הקריבו שום קרבן אני הקרבתי את הכל:"],[5,"שעיר נחשון","שאותו היום היה ראשון להקרבת נשיאים דתניא בסדר עולם בכ\"ג באדר התחילו המלואים וכל שבעת הימים היה משה מעמיד המשכן ומקריב את קרבנותיו בכל בקר ובקר ופרקו ובשמיני העמידו ולא פירקו והוא ראש חדש ניסן ואותו היום נטל עשר עטרות וכו':"],[5,"חטאת שמיני","שבא חובה לשעה דכתיב קחו שעיר עזים לחטאת:"],[6,"שתי דרישות","דרישה לנשרפות דרישה למונחות למה מונחות להמתין לערב ולא נאכלו ביום:"],[6,"הוי אומר זה שעיר ר\"ח","שמכפר על טומאת מקדש וקדשיו כדאמר בשבועות (דף ב.):"],[6,"ואיני יודע איזו היא","תנא דמתניתא הוא דקמהדר למילתיה:"],[7,"שפיר קא\"ל","לעיל קאי דאמרן לר' נחמיה היה להן לשלשתן שישרפו:"],[8,"קסבר לילה דאורייתא","ומהכא נ\"ל דמותקראנה אותי כאלה יליף מפני אנינות נשרפה ומדלא אכלוה לערב נפקא ליה אנינות לילה דאורייתא ור' יהודה לדורות אית ליה אנינות לילה דאורייתא אבל לאותו היום הותרה דדריש היום אני היום אסור ולילה מותר כו':"],[9,"ברית כהונת עולם","תחת אשר קנא אלמא מכאן ואילך הוא:"],[10,"ששם שלום בין השבטים","בימי יהושע בשבט בני גד ובני ראובן שבנו את המזבח בעבר הירדן ובקשו שאר שבטים לעלות עליהם לצבא ושלחו את פנחס לדבר עמהם:"],[10,"וישמע פינחס הכהן","בכל מקום אתה מוצא פינחס בן אלעזר בן אהרן הכהן אין כהונה כתובה אלא באלעזר וכאן כתובה בפנחס:"],[11,"ההוא","קרא התם בברכה כתיב בשרו שלא תפסוק כהונה מזרעו אבל עדיין לא נתכהן:"],[12,"לייחס זרעו אחריו","[מימי משה נתכהן וכששם שלום נתייחס ליקרא כהן ולייחס זרעו במעלות כהונה להיותם כהנים גדולים שלא הי' כהנים גדולים אלא מפנחס]:"],[13,"למשה היה למנה","לשון חלוקה בכהנים:"],[14,"טריד בשכינה","ולא היה עסוק באכילת קדשים שהדבור טורדו להיות תמיד בהר מבקר ועד ערב:"],[14,"בהשכמה עלה","להר בימי מתן תורה כשהיה עולה ויורד לקדש את העם ולהשיב את דברי העם אל ה' בפרק רבי עקיבא במסכת שבת (דף פו.) אלמא טרוד היה:"],[15,"לחם אלהיו וגו'","בבעל מום כתיב להתירו בקדשים:"],[16,"שהרי הותרו לזר ולהן","קא ס\"ד הותר לזה במשה קאמר שאכל חזה ושוק של איל המילואים וקדשי קדשים היה כדכתיב ביה בשלו את הבשר פתח אהל מועד ושם תאכלו אותו ולא נאכל אלא ליום ולילה דכתיב ואם יותר וגו':"],[16,"בקדשים קלים","בחזה ושוק של שלמי יחיד לא יחלוק עם אחיו שלא מצינו זר ופסול חולק בהן:"],[17,"לאו משה","דהא לאו זר אוכל בקדשים אלא במילואים:"],[17,"לא בבמה קאמר","דהותרו לזר וכדברי האומר בפרק אחרון (דף קיג.) יש מנחה בבמה קטנה ומנחה קדשי קדשים היא ואוכלין שיריה זרים שהיו עובדים בבמה קטנה שהזר עובד שם כדאמר בפרק בתרא אבל קדשים קלים לא יאכל בחזה ושוק של כהנים שהרי לא הותרו לזר דלא אשכחן זר חולק במורם משלמי יחיד דאילו במקדש נאכל לכהנים ובבמה קטנה לא היה חזה ושוק כדתניא בפרק בתרא חזה ושוק בבמה גדולה ואין חזה ושוק בבמה קטנה והאי דבעי למינקט כדברי האומר יש מנחה בבמה דאי אין מנחה בבמה אין לך עוד קדשי קדשים נאכלין בבמה דאילו חטאת ואשם בבמה לא קרבי דתנן מגילה (דף ט:) כל שאין נידר ונידב אין קרב בבמה אין לך נדר ונדבה בקדשי קדשים אלא עולה ומנחה:"]],[[3,"בשלמא לרבי נחמיה היינו דכתיב הן היום הקריבו","כלומר קרבן זה לחובת היום קרב וקדשי דורות הוא ואכלתי חטאת היום בתמיה לא שמעת אלא בשל שעה אלא לרבנן דאמרי שמא לא שמעת אלא בלילה קאמר ליה מאי היא דקאמר ליה הן היום הקריבו הכי קאמר ליה אמרת לי דילמא באנינות אקריבתיה וכי הן בניי הדיוטות היום הקריבו שום קרבן אני הקרבתי אותם זו היא גירסת הקונט' ופירושו והשתא לפי זה למ\"ד מפני אנינות נשרפה הוי הן היום בניחותא ולמ\"ד מפני טומאה הוי בתמיה וקשה דלעיל בריש פ\"ב (זבחים דף טז.) משמע איפכא ונראה דגרסינן נמי בהך פירכא בתרייתא בשלמא לרבנן היינו דכתיב הן היום כמו בקמייתא ובתרוייהו פריך לר' נחמיה מדכתיב היום כדמפרש בקונט' בקמייתא ומשני הכי קאמר וכי הן הקריבו אני הקרבתי כל הקרבנות שקרבו היום:"],[11,"ההוא בברכה הוא דכתיב","שברכו הקב\"ה שיהיה כהן ומיד היה יכול להיות כהן אלא שתחילה צריך להלבישו ולמושחו ולחנכו בחביתין כדין הדיוטות המתחנכים בחביתין כדאמרינן בסוף התכלת (מנחות דף נא:) אבל שמא לא נתרצו לו כל ישראל באותה שעה מפני שהרג נשיא שבט עד ששם שלום בין השבטים בימי יהושע ואז נתרצו לו והלבישוהו [ומשחוהו] וחנכוהו בחביתין:"],[12,"ואידך נמי הכתיב וישמע פנחס הכהן ההוא לייחס זרעו אחריו","פי' מימי משה נתכהן וכששם שלום נתייחס ליקרא כהן ולייחס זרעו במעלות כהונה להיותם כהנים גדולים שכן מצינו בדברי הימים (א' ה') שלא היו כהנים גדולים אלא מפנחס ובספרי מפיק ליה מאת בריתי שלום שעמדו ממנו שמונים כהנים בבית ראשון ושלש מאות בבית שני וכולם נמנו בספרי:"]]],[["ואין זר רואה את הנגעים וא\"ת אהרן הסגירה אהרן קרוב הוא ואין קרוב רואה את הנגעים אלא כבוד גדול חלק לה הקב\"ה למרים אותה שעה אני כהן ואני מסגירה אני חולטה ואני פוטרה","קתני מיהת משה זר ואין זר רואה את הנגעים","אמר רב נחמן בר יצחק שאני מראות נגעים דאהרן ובניו כתובין בפרשה","מיתיבי חמש שמחות היתה אלישבע יתירה על בנות ישראל יבמה מלך אישה כהן גדול בנה סגן בן בנה משוח מלחמה ואחיה נשיא שבט ואבילה על שני בניה","קתני מיהת יבמה מלך מלך אין כ\"ג לא אימא אף מלך","כתנאי (שמות ד, יד) ויחר אף ה' במשה רבי יהושע בן קרחה אומר כל חרון אף שבתורה נאמר בו רושם וזה לא נאמר בו רושם","ר\"ש בן יוחי אומר אף זה נאמר בו רושם שנאמר (שמות ד, יד) הלא אהרן אחיך הלוי והלא כהן הוא הכי קאמר אני אמרתי אתה כהן והוא לוי עכשיו הוא כהן ואתה לוי","וחכמים אומרים לא נתכהן משה אלא שבעת ימי המלואים בלבד ויש אומרים לא פסקה כהונה אלא מזרעו של משה שנאמר (דברי הימים א כג, יד) ומשה איש האלהים בניו יקראו על שבט הלוי ואומר (תהלים צט, ו) משה ואהרן בכהניו ושמואל בקוראי שמו","מאי ואומר וכי תימא לדורות הוא דכתיב ואומר משה ואהרן בכהניו","וכל חרון אף שבתורה נאמר בו רושם והכתיב (שמות יא, ח) ויצא (משה) מעם פרעה בחרי אף ולא א\"ל ולא מידי אמר ר\"ל סטרו ויצא","ומי אמר ר\"ל הכי והכתיב (שמות ז, טו) ונצבת לקראתו על שפת היאור ואמר ר\"ל מלך הוא והסביר לו פנים ורבי יוחנן אמר רשע הוא והעיז פניך בו איפוך","א\"ר ינאי לעולם תהא אימת מלכות עליך דכתיב (שמות יא, ח) וירדו כל עבדיך אלה אלי ואילו לדידיה לא קאמר ליה","רבי יוחנן אמר מהכא (מלכים א יח, מו) ויד ה' היתה אל אליהו וישנס מתניו וירץ לפני אחאב","אמר עולא בקש משה מלכות ולא נתנו לו דכתיב (שמות ג, ה) אל תקרב הלום ואין הלום אלא מלכות שנאמר (שמואל ב ז, יח) מי אנכי ה' אלהים [וגו'] כי הביאתני עד הלום","מתיב רבא רבי ישמעאל אומר יבמה מלך אמר רבא לו ולזרעו קאמר","וכל היכא דכתיב הלום לדורות הוא והא גבי שאול דכתיב (שמואל א י, כב) הבא עוד הלום איש הוא אין זרעו לא","איבעית אימא הא הוה איש בשת ואיבעית אימא שאני שאול דאפי' בגויה לא קאים","כדר' אלעזר אמר רבי חנינא בשעה שפוסקים גדולה לאדם פוסקים לו ולזרעו עד סוף כל הדורות שנאמר (איוב לו, ז) לא יגרע מצדיק עיניו ואת מלכים לכסא וגו' ואם הגיס דעתו הקב\"ה משפילו שנאמר (איוב לו, ח) ואם אסורים בזקים ילכדון בחבלי עוני:","בעלי מומין בין בעלי מומין כו': מנא ה\"מ דת\"ר (ויקרא ו, יא) כל זכר לרבות בעלי מומין","למאי אי לאכילה הרי כבר נאמר (ויקרא כא, כב) לחם אלהיו מקדשי הקדשים יאכל אלא לחלוקה","תניא אידך כל זכר לרבות בעלי מומין למאי אי לאכילה הרי כבר אמור אי לחלוקה הרי כבר אמור שיכול אין לי אלא תם ונעשה בעל מום בעל מום מעיקרו מנין ת\"ל כל זכר","תניא אידך כל זכר לרבות בעל מום למאי אי לאכילה הרי כבר אמור ואי לחלוקה הרי כבר אמור ואי לבעל מום מעיקרו הרי כבר אמור שיכול אין לי אלא בעל מום קבוע בעל מום עובר מנין ת\"ל כל זכר","כלפי לייא אמר רב ששת איפוך","רב אשי אמר לעולם לא תיפוך ואיצטריך סלקא דעתך אמינא"],[[0,"ואין זר רואה את הנגעים","דכתיב (ויקרא י״ג:ב׳) והובא אל אהרן וגו':"],[0,"ואין קרוב רואה את הנגעים","כדתניא בסנהדרין (דף לד:) כל ריב וכל נגע מה ריבים שלא בקרובים אף נגעים שלא בקרובים:"],[3,"היתה אלישבע יתירה","ביום שהוקם המשכן קאי בסדר עולם:"],[3,"בנה סגן","אלעזר:"],[3,"בן בנה","פנחס משוח מלחמה כדאשכחן במדין אותם ואת פנחס בן אלעזר הכהן לצבא והוא המדבר אל העם שמע ישראל אתם קרבים היום למלחמה על אויביכם:"],[3,"אחיה","נחשון:"],[5,"כתנאי","אם משה כהן היה:"],[5,"נאמר בו רושם","סימן מה של חרון היה שם פעמים הכאה פעמים נזיפה פעמים קללה וגידוף כגון (שמואל א כ׳:ל׳) ויחר אף שאול כתיב בתריה בן נעות המרדות ויחר אף אליהוא (איוב ל״ב:ב׳) לא רבים יחכמו (שם) ויחר אף יעקב ברחל התחת אלהים (בראשית ל׳:ב׳) לשון נזיפה הוא:"],[6,"הלא אהרן אחיך","שהיה ראוי להיות לוי ידעתי כי דבר ידבר הוא ומשם זכה לכהונה:"],[7,"לא נתכהן משה","ולא פסקו לו כהונה מעולם:"],[7,"ויש אומרים","לא פסקה כהונה אלא מזרעו אבל הוא כל ימיו כהן היה ורב דאמר כיש אומרים:"],[7,"בניו יקראו על שבט הלוי","אבל הוא כהן:"],[8,"וכי תימא לדורות הוא דכתיב","לאחר זמן נכתב כשהיו מייחסים את הכהונה ואת הלויה ולהכי נקט בניו יקראו דלא הוה ליה למימר משה יקרא על שבט הלוי שהרי לא קיים ואין לו לומר אלא על המתייחסים:"],[9,"סטרו","הכהו על לחיו:"],[10,"הסביר לו פנים","והיינו ונצבת לקראתו לפי גדולתו הכון לקראתו:"],[10,"העיז בו פניך","היינו ונצבת לקראתו למלחמה ולדבר עזות:"],[11,"ואילו לדידיה לא קאמר ליה","וירדת אלי והשתחוית לי לאמר וגו' ואע\"ג דמסקנא הכי הוה דכתיב (שמות י״ב:ל״א) ויקרא למשה ולאהרן לילה ויאמר קומו וגו':"],[12,"וירץ לפני אחאב","אחאב רוכב והוא רץ לפניו שהיה אחאב יחידי ולאו אורח ארעא:"],[13,"מי אנכי","דוד אמרה:"],[16,"שאני שאול דאפי' בגויה לא קמא","ומיהו הלום מלכות עולמית הוא וכשפסקו לו לשאול מלכות עולמית פסקו לו אבל הוא גרם לעצמו שתנטל הימנו:"],[17,"כדרבי אלעזר","דאמר אם הגיס כו' ויגבהו ואם אסורים בזקים גבהות לבם גורם להם להיות אסורים בזקים ילכדו בחבלי עוני:"],[18,"כל זכר","קמא במנחה כתיב בצו את אהרן:"],[19,"אם לאכילה","להתירו לאכול מחלק חביריו אם יזמנוהו עמהם אבל הוא לא יחלוק:"],[20,"לחלוקה","ליטול חלק כאחד הכשרים:"],[20,"כל זכר","תניינא בחטאת כתיב והשלישי באשם וברייתות הללו בת\"כ במדרש המקראות:"],[22,"כלפי לייא","בעל מום עובר משמע להתירו טפי מבעל מום קבוע:"],[23,"לא תיפוך","ואיצטריך קרא למידרשיה הכי מהו דתימא קרא קמא קבוע הוא דאכשר דרחמנא חס עליה משום דלית ליה היתירא למחר וליומא אחרינא אבל עובר דאית ליה היתירא למחרת:"]],[[0,"אהרן קרוב הוא ואין קרוב רואה את הנגעים","פלוגתא היא במסכת נגעים פ\"ב (מ\"ה) דתנן כל הנגעים אדם רואה חוץ מנגעי עצמו ר\"מ אומר אף לא נגעי קרוביו ותנא ברייתא דהכא כרבי מאיר וטעמא דרבי מאיר כדמפרש באחד דיני ממונות מקיש ריבים לנגעים מה נגעים ביום אף ריבים ביום ומה ריבים שלא בקרובים אף נגעים שלא בקרובים ורבנן לא מקשי דסברי דיני ממונות בלילה:"],[0,"אני מסגירה אני חולטה אני פוטרה","בספרי תניא אמר אהרן נמצאת מפסיד לאחותנו שאינו יכול להסגירה ולא לטמאה ולא לטהרה לפי דבריו למדנו שהיה אהרן דורש אין אדם רואה בנגעי קרובו ותימה במה היה מפסידה הא דאין אדם רואה את הנגעים כל שכן שהיתה טהורה:"],[21,"בעל מום עובר מנין ת\"ל כל זכר","תימה דלמא איצטריך לבעל מום מעיקרו חד לאכילה וחד לחלוקה דאי מחד ה\"א דוקא אכילה ולא חלוקה כמו קטן דאוכל ואינו חולק וי\"ל כיון דאשכחן תם ונעשה בעל מום דאין חילוק בין אכילה לחלוקה דבסתמא ה\"ה לבעל מום מעיקרו וא\"ת דהכא מייתרי ליה הנך תלתא כל זכר דכתיבי במנחה וחטאת ואשם משמע דילפי מהדדי וגבי טבול יום בדינא דר\"א בר' שמעון מצריך תלת קראי למנחת ישראל וחטאת וחזה ושוק:"]]],[["כי טמא מה טמא כמה דלא טהור לא אכיל אף האי נמי כמה דלא מתקן לא אכיל קא משמע לן:","כל שאינו ראוי וכו': ולא והרי בעל מום דלא ראוי לעבודה וחולק ותו הא ראוי לעבודה חולק הרי טמא בקרבנות ציבור דראוי לעבודה ואינו חולק","ראוי לאכיל' קאמר","והרי קטן דראוי לאכילה ואינו חולק הא לא קתני","השתא דאתית להכי לעולם כדקאמר מעיקרא אי משום טמא טמא לא קתני ואי משום בעל מום רחמנא רבייה:","אפי' טמא בשעת זריקת דמים וטהור בשעת הקטר חלבים אינו חולק: הא טהור בשעת זריקת דמים וטמא בשעת הקטר חלבים חולק","מתניתין דלא כאבא שאול דתניא אבא שאול אומר לעולם אינו אוכל עד שיהא טהור משעת זריקה עד שעת הקטר חלבים דאמר קרא (ויקרא ז, לג) המקריב את דם השלמים ואת החלב דאפי' הקטר חלבים נמי בעי:","בעי רב אשי נטמא בינתיים מהו בשעת זריקה ובשעת הקטרה בעינן והאיכא או דלמא עד שיהא טהור משעת זריקה ועד שעת הקטר חלבים תיקו","אמר רבא האי דינא מרבי אלעזר ברבי שמעון גמירנא דאמר בבית הכסא דנתה בא טבול יום ואמר תן לי ממנחה ואוכל","אמר לו ומה אם במקום שיפה כחך בחטאתך דחיתיך מחטאת ישראל מקום שהורע כחך במנחתך אינו דין שאדיחך ממנחת ישראל","ומה אם דחיתני מחטאת ישראל שכשם שיפה כחי כך יפה כחך תדחיני ממנחה שכשם שהורע כחי כך הורע כחך","הרי הוא אומר (ויקרא ז, ט) לכהן המקריב אותה לו תהיה בא הקרב ואכול","תן לי מחטאת ישראל ואוכל","א\"ל ומה במקום שהורע כחי במנחתי דחיתיך ממנחת ישראל מקום שיפה כחי בחטאתי אינו דין שאדיחך מחטאת ישראל","א\"ל ומה אם שדחיתני ממנחת ישראל שכשם שהורע כחך כך הורע כחי תדחיני מחטאת ישראל שכשם שיפה כחך כך יפה כחי","הרי הוא אומר (ויקרא ו, יט) הכהן המחטא אותה יאכלנה בא חטא ואכול","אמר ליה תן לי מחזה ושוק ואוכל","אמר ליה ומה במקום שיפה כחך בחטאתך דחיתיך [מחטאת ישראל] (מחזה ושוק) מקום שהורע כחך בשלמים שאין לך בהן אלא חזה ושוק אינו דין שאדיחך","מה אם דחיתני מחטאת שכן הורע כחי אצל נשיי ועבדיי תדחיני מחזה ושוק שכן יפה כחי אצל נשיי ועבדיי","הרי הוא אומר (ויקרא ז, יד) לכהן הזורק את דם השלמים לו יהיה בא זרוק ואכול","יצא טבול יום קוליו וחמוריו על ראשו אונן מימינו מחוסר כפרה משמאלו","פריך רב אחאי לימא ליה תן לי מבכור ואוכל","משום דא\"ל ומה במקום שהורע כחי בחטאת אצל נשיי ועבדיי דחיתיך מחטאת ישראל מקום שיפה כחי בבכור דכוליה דילי היא אינו דין שאדחך ממנו","ומה אם דחיתני מחטאת שכשם שהורע כחך כך הורע כחי תדיחני מבכור שכשם שיפה כחך כך יפה כחי","הרי הוא אומר (במדבר יח, יז) את דמם תזרוק על המזבח ואת חלבם תקטיר ובשרם יהיה לך בא זרוק ואכול","ואידך פריך מי כתיב ובשרם לכהן הזורק ובשרם יהיה לך כתיב אפי' לכהן אחר","והיכי עביד הכי והאמר רבה בר בר חנה א\"ר יוחנן בכל מקום מותר להרהר חוץ ממרחץ ומבית הכסא לאונסו שאני:"],[[0,"","(אימא כי טמא כו':)"],[1,"[הרי] טמא בקרבנות ציבור","אמרן לעיל בריש פירקין (זבחים דף צט:) דאין חולק:"],[3,"קטן אינו חולק","דכתיב איש כאחיו ודרשינן ליה במנחות (דף עג.) ובקדושין (דף נג.) איש חולק אפילו בעל מום ואין קטן חולק אפילו תם:"],[3,"הא לא קתני","הא ראוי לאכילה חולק דדייקת לא קתני דתיקשי לך קטן לא תדוק מיניה הכי דהיא גופה איצטריך לאשמועינן דכל שאינו ראוי אינו חולק ולאו דיוקא תני:"],[4,"כדאמרינן מעיקרא","ראוי לעבודה:"],[4,"הא לא קתני","הא ראוי לעבודה חולק דקא דייקת וקשיא לך עלה טמא בקרבנות ציבור לא קתני לה מתניתין ואת לא תיתי מדיוקא דלאשמועינן היא גופה אתאי מתני' ולאו לדיוקא דילה:"],[6,"דאפילו הקטר חלבים נמי בעי","שיהא ראוי להקטיר ות\"ק סבר לו תהיה שוק הימין למנה אהמקריב דם השלמים קאי כדאשכחן קרא אחרינא לכהן הזורק את דם השלמים לו יהיה (ויקרא ז׳:י״ד) ולא כתיב מקטיר חלבים והכא דכתיב את החלב לא לראוי אתא אלא למודה בעבודות כדדריש ליה בשחיטת חולין (דף קלב:) רבי שמעון אומר כל כהן שאינו מודה בעבודה אינו חולק בכהונה שנאמר המקריב את דם השלמים אין לי אלא זריקה מנין לרבות הקטר חלבים ת\"ל ואת החלב מנין לרבות שאר כל עבודות ת\"ל מבני אהרן עבודה המסורה לבני אהרן כל כהן שאינו מודה בה אינו חולק בכהונה:"],[7,"בעי רב אשי","אליבא דאבא שאול:"],[8,"דנתה","יכול אתה לדון:"],[8,"בא טבול יום ואמר","לחבירו טהור של בית אב שלו:"],[8,"תן לי","בחלק מן המנחה של ישראל ואוכל לערב:"],[9,"א\"ל","טהור לטבול יום כלומר כן יש לו להשיבו:"],[9,"ומה אם במקום שיפה כחך בחטאתך","דכהן המחוייב חטאת מביאו ומקריב אפילו במשמר שאינו שלו ועבודתה ועורה שלו בפרק הגוזל בב\"ק (דף קט:) מנין לכהן שבא ומקריב קרבנותיו בכל עת ובכל שעה שירצה ת\"ל ובא בכל אות נפשו ושרת ומנין שעבודתה ועורה שלו ת\"ל ואיש את קדשיו לו יהיו:"],[9,"דחיתיך מחטאת ישראל","דטבול יום אינו חולק בה דכתיב (ויקרא ו׳:י״ט) הכהן המחטא אותה יאכלנה ואוקימנא לעיל (זבחים דף צט.) יחלקנה:"],[9,"מקום שהורע כחך במנחתך","שאם התנדבת מנחה והקרבת אפילו אתה טהור אי אתה אוכלה כדכתיב כל מנחת כהן כליל וגו' (ויקרא ו׳:ט״ז):"],[9,"אינו דין שאדיחך","כל זמן שאתה טבול יום ואינך ראוי להקריב ממנחת ישראל:"],[10,"כך יפה כחך","בחטאתך:"],[10,"שכשם שהורע כחי","במנחתי כך הורע כחך במנחתך:"],[11,"לכהן המקריב אותה לו תהיה","במנחה כתיב:"],[13,"ומה במקום כו'","טהור קמהדר ליה לטבול יום הכי שלא יחלוק עמו:"],[16,"תן לי מחזה ושוק","חלק כמוך ואוכל לערב:"],[18,"שכן הורע כחי אצל נשיי ועבדיי","אף כשאני טהור שאיני רשאי להאכילה להם:"],[20,"יצא טבול יום","בפחי נפש:"],[20,"קוליו וחומריו","שהיה דורש להנאתו ואומר למה דחיתני כו':"],[20,"אונן מימינו כו'","שאף הם נדחים מן המקראות הללו שאינן ראויין לעבודה:"],[21,"פריך רב אחאי ולימא","וליתני ר' אלעזר בר' שמעון בהאי דינא:"],[21,"תן לי מבכור ואוכל","לערב אמר לו טהור מה אם במקום כו':"],[24,"את דמם תזרוק","בבכור כתיב בא זרוק ואכול ואע\"ג דאין בכור נאכל במחלוקת שאינו ניתן לאנשי משמר אלא לכל כהן שירצה כתרומה וכפדיון הבכור מיהו תיפוק לן מינה דלא יתנו בכור אלא למי שראוי לעבודה באותה שעה:"],[26,"והיכי עביד הכי","רבי אלעזר ברבי שמעון דאמר האי דינא בבית הכסא:"],[26,"לאונסו","שהיתה שמועתו שגורה בפיו ומהרהר בה על כרחו ודוגמתו שמעתי בקדושין (דף לג.):"]],[[1,"הרי טמא בקרבנות ציבור דראוי לעבודה ואינו חולק","תימה דפריך מטמא בקרבנות ציבור שהיא בעיא לעיל והוה מצי למיפרך מכהן גדול אונן וראוי לעבודה דאינו חולק דפשיטא לן לעיל בריש פירקין כדתניא בהדיא:"],[18,"מה אם דחיתני מחטאת שכן הורע כחי אצל נשיי ועבדיי","תימה אמאי לא קאמר כדקאמר לעיל ומה אם דחיתני מחטאת שכשם שיפה כחי כך יפה כחך תדיחני מחזה ושוק שכשם שהורע כחי כך הורע כחך:"],[21,"פריך רב אחאי","בכל מקום לשונו משונה כדאשכחן בריש כתובות (דף ב:) פשיט רב אחאי ומתוך כך היה אומר רבינו שמואל דהוא רב אחאי שעשה השאלתות שהיה מרבנן סבוראי דבתר רבינא ורב אשי דהוסיף הוראה וכתבו אחרי כן דבריו בסוף הש\"ס ומיהו בההיא דכתובות אשכח רב אשי דמיירי בתריה:"]]],[["\u0001מתני׳\u0002 כל שלא זכה המזבח בבשרה לא זכו כהנים בעורה שנאמר (ויקרא ז, ח) עולת איש עולה שעלתה לאיש","עולה שנשחטה שלא לשמה אע\"פ שלא עלתה לבעלים עורה לכהנים אחד עולת האיש ואחד עולת האשה עורותיהן לכהנים","עורות קדשים קלים לבעלים עורות קדשי קדשים לכהנים קל וחומר ומה אם עולה שלא זכו בבשרה זכו בעורה קדשי קדשים שזכו בבשרה אינו דין שיזכו בעורה אין מזבח יוכיח שאין לו עור בכל מקום:","\u0001גמ׳\u0002 ת\"ר עולת איש פרט לעולת הקדש דברי ר' יהודה רבי יוסי בר' יהודה אומר פרט לעולת גרים","מאי פרט לעולת הקדש אמר רבי חייא בר יוסף פרט לעולה הבאה מן המותרות","הניחא למ\"ד מותרות לנדבת ציבור אזלי אלא למ\"ד מותרות לנדבת יחיד אזלי מאי איכא למימר","כדאמר רבא העולה עולה ראשונה ה\"נ העולה עולה ראשונה","רבי אייבו א\"ר ינאי פרט למתפיס עולה לבדק הבית","לא מיבעיא למ\"ד קדשי בדק הבית תפסי מדאורייתא אלא אפילו למ\"ד לא תפסי הני מילי בשר אבל עור תפיס","וכן אמר רב נחמן אמר רבה בר אבוה פרט לעולה הבאה מן המותרות","א\"ל רב המנונא לרב נחמן כמאן כרבי יהודה הא הדר ביה דתניא ששה לנדבה לעולה הבאה מן המותרות שלא יהו כהנים זכאין בעורה דברי רבי יהודה","אמר לו רבי נחמיה ואמרי לה ר\"ש אם כן ביטלת מדרשו של יהוידע הכהן דתניא זה מדרש דרש יהוידע הכהן (ויקרא ה, יט) אשם הוא אשם אשם לה' כל שבא משום חטאת ומשום אשם ילקח בו עולות הבשר לשם עורה לכהנים","א\"ל אלא מר במאי מוקים לה א\"ל מוקמינא ליה במקדיש נכסיו","וכדרבי יהושע דתנן המקדיש נכסיו והיו בהן בהמות הראויות לגבי מזבח זכרים ונקבות ר\"א אומר זכרים ימכרו לצורכי עולות נקבות ימכרו לצורכי זבחי שלמים ודמיהן יפלו עם שאר נכסים לבדק הבית","רבי יהושע אומר זכרים עצמם יקרבו עולות ונקבות ימכרו לצורכי שלמים ויביא בדמיהן עולות ושאר נכסים יפלו לבדק הבית","ואפי' לרבי יהושע דאמר אדם חולק הקדישו הני מילי בשר אבל עור תפיס","רבי יוסי ברבי יהודה אומר פרט לעולת גרים אמר ליה רב סימאי בר חילקאי לרבינא אטו גר לאו איש הוא אמר ליה פרט לגר שמת ואין לו יורשים","תנו רבנן עולת איש אין לי אלא עולת איש עולת גרים נשים ועבדים מנין ת\"ל עור העולה ריבה","אם כן מה תלמוד לומר עולת איש עולה שעלתה לאיש פרט לשנשחטה חוץ לזמנה וחוץ למקומה שלא יהו הכהנים זכאין בעורה","יכול שאני מרבה שנשחטה שלא לשמה הואיל ולא עלתה לבעלים"],[[0,"מתני' כל שלא זכה המזבח בבשרה","כגון שאירע בה פסול קודם זריקה דלא היתה לה שעת היתר למזבח:"],[1,"עורה לכהנים","מקראי איתרבאי בברייתא בגמרא:"],[1,"ואחד עולת האשה","דאיתרבאי נמי מקרא:"],[2,"עורות קדשי קדשים","חטאות ואשמות לכהנים כדמפרש טעמא ואזיל:"],[2,"אין המזבח מוכיח","כלומר ואין לך לומר מזבח יוכיח שזכה בבשר העולה ולא זכה בעורה ואף אתה אל תתמה בקדשי קדשים שאע\"פ שזכו כהנים בבשרן לא יזכו בעורן אין זו הוכחה שאין למזבח עור בכל מקום אבל לכהנים מצינו שזכו בעור העולה וקל וחומר שיזכו בעורות קדשי קדשים:"],[3,"גמ' פרט לעולת הקדש","לקמיה מפרש לה:"],[3,"פרט לעולת גרים","לקמיה פריך אטו גר לאו איש הוא:"],[4,"מן המותרות","דכל אשמות של רעייה כגון תמורת אשם ואשם שמתו בעליו ושכיפרו בעליו באחר דקיימא לן ירעו וימכרו ויפלו דמיהן לנדבה והוא עולת קיץ המזבח דלאו עולת איש הוא אלא נדבת צבור היא ונסכיה משל צבור ואין בעליו סומך עליה ואינו שוחטה כדתנן בתמורה (דף כ:):"],[5,"הניחא כו'","פלוגתא דרבי אליעזר ורבנן היא בתמורה (שם):"],[5,"לנדבת צבור","לקיץ המזבח:"],[5,"לנדבת יחיד","בעליו של אשם שניתותר הוא עצמו מביא עולה בדמיו והוא סומך עליה ושוחטה ונסכיה קריבין משלו:"],[6,"כדאמר רבא","(יומא דף לד.) גבי וערך עליה העולה דילפינן מינה מנין שלא יהא דבר קודם לתמיד של שחר ת\"ל וערך עליה העולה וגו' ואמרינן מאי תלמודא ואמר רבא העולה משמע העולה ראשונה האמורה בסדר קרבנות היום הכא נמי עור העולה כתיב העולה ראשונה שהופרשה מתחילה לשם עולה ולא הבאה ממותר אשם וממותר חטאת ולקמיה פריך והא קי\"ל עורה לכהנים ממדרש יהוידע הכהן:"],[7,"פרט למתפיס עולתו לבדק הבית","שאין עורה לכהנים:"],[8,"ולא מיבעיא וכו'","בפ' בתרא דתמורה (דף לב:) דקאמר עולא המתפיס עולה לבדק הבית אין בה אלא עיכוב גיזברים בלבד ומותבינן לעולא המתפיס עולה לבדק הבית אסור לשוחטה עד שתפדה ומשני עולא האי דמצריך ליה פדיה מדרבנן מכלל מאן דמותיב בעי למימר דאורייתא ולענין עורה לא מיבעיא למ\"ד מדאורייתא תפסה בה קדושת בדק הבית דאין עורה לכהנים אם שחטה עד שלא נפדית דלאו עולת איש הוא אלא עולת הקדש:"],[8,"אלא אפי' למ\"ד","מדרבנן בעלמא אבל מדאורייתא לא הני מילי דמדאורייתא לא בשר דשל מזבח הוא ואין קדושה חלה עליו שאינו שלו על פיו אבל עור דלאו ממון מזבח הוא וכהנים אכתי לא זכו ביה תפוס:"],[10,"כמאן כרבי יהודה","לקמן מייתי לה דאמר אין עורה לכהנים:"],[10,"הא הדר ביה","דקאמרי ליה אם כן בטלת מדרשו של יהוידע הכהן ולא אהדר להו מידי:"],[10,"ששה לנדבה","בי\"ג שופרות שהיו במקדש קמיירי דכתוב עליהן תקלין חדתין [ותקלין עתיקין] קינין וגוזלי עולה עצים ולבונה וזהב לכפרת וששה לנדבה ומפרש מאי ניהו ששה לנדבה:"],[10,"","ה\"ג ששה לנדבה לעולה הבאה מן המותרות שאין הכהנים זכאין בעורה:"],[11,"אשם לה'","אי אפשר אשם לה' שכבר נאמר אשם לכהן כחטאת כאשם תורה אחת להם וגו' הא כיצד כל דבר הבא ממותר חטאת כגון מפריש מעות לחטאתו וניתותר מהן וממותר אשמות כגון הנך דאזלי לראייה דקיימא לן (תמורה דף יח.) כל שבחטאת מתה באשם רועה:"],[11,"ילקח בהן כו'","נמצאו שני כתובים מקויימין אשם לה' בשר לעולה ואשם לכהן העור והיינו דכתיב כסף אשם וכסף חטאות לא יובא וגו':"],[12,"אלא מר במאי מוקי לה","להא דתני לעיל פרט לעולת הקדש:"],[13,"וכרבי יהושע","דאמר זכרים עצמן יקרבו עולות והך עולת הקדש היא וכדמסיים ואזיל דכי א\"ר יהושע דחייל שם מזבח עלייהו מעיקרא אמאי דחזי למזבח קאמר אבל בעור מודה דחייל עלה קדושת בדק הבית:"],[13,"המקדיש נכסיו","לבדק הבית:"],[13,"הראויות למזבח","תמימים:"],[13,"זכרים ימכרו לצרכי עולות כו'","דקי\"ל בתמורה (דף לג:) המתפיס תמימים לבדק הבית כשהן נפדין אינן נפדין אלא למזבח שכל הראוי למזבח אינו יוצא מידי מזבח לעולם:"],[14,"זכרים עצמן יקרבו עולות","לשם אותו האיש דקסבר אדם חולק הקדישו ואע\"ג דמקדיש סתמא דעתיה הוה להקריב למזבח הראוי לו:"],[14,"ונקבות ימכרו כו'","אבל הן עצמן לא יקרבו שלמים עד שימכרו דכיון דמקדיש סתמא הכל הקדיש הראוי למזבח דומיא דבדק הבית שכולו קדוש הלכך לדמי עולה אקדשינהו ובהך עולה דרבי יהושע זכרים הקריבים עולות קא\"ר יהודה לעיל פרט לעולת הקדש:"],[15,"ואפי' לרבי יהושע","כלומר ואע\"ג דאמר ר' יהושע אדם חולק הקדישו הראוי למזבח למזבח ושאינו ראוי למזבח יהא לבדק הבית לא שיהו כשאר קדשי מזבח שעורותיהן לכהנים דמודה הוא שהעור נתפס לבדק הבית כשאר נכסים שלו:"],[16,"ואין לו יורשין","דאין לה בעלים:"],[17,"","ה\"ג עולת איש אין לי אלא עולת איש עולת נשים ועבדים מנין ת\"ל כו':"],[17,"העולה","קרא יתירא הוא דלא איצטריך למכתב אלא העור לכהן אלא לרבות בא:"],[19,"הואיל ולא עלתה לבעלים","ואף על פי שהיא כשרה לא יזכו בעורה:"]],[[5,"הניחא למ\"ד מותרות לנדבת ציבור אזלי","תימה לדידיה מ\"ש דממעט מותרות טפי מעולת תמיד וי\"ל דסברא הוא למעוטי טפי מותרות משום דהיו מעיקרא לאיש:"],[5,"אלא למ\"ד לנדבת יחיד מאי איכא למימר","תימה מאי קשיא ליה הא רבי יהודה דממעט הכא עולת הקדש הוא דקאמר בסמוך לנדבת ציבור אזלי דקתני ששה לנדבה ואי לנדבת יחיד לא היה משימה בשופר דקרבן יחיד בעי סמיכה וי\"ל דלא שמיע ליה ההיא ברייתא תדע דאי שמיע ליה הא הדר ביה רבי יהודה ממדרשו של יהוידע:"],[8,"לא מיבעיא למ\"ד קדשי בדק הבית תפסי מדאורייתא","תימה לדידיה אמאי איצטריך קרא הכא דאם שחט קודם פדייה אין עורה לכהנים פשיטא דקדשי בדק הבית היו בכלל העמדה והערכה:"],[17,"אין לי אלא עולת איש גרים נשים ועבדים מנין","משמע מחד קרא הוה ממעטינן נשים ועבדים ודין הוא דהא ילפינן מהדדי בג\"ש דלה לה מאשה והקשה הר\"ר חיים דבפרק החובל (ב\"ק דף פח.) מצריך תרי קראי גבי עדות חד למעוטי נשים וחד למעוטי עבדים וי\"ל דגבי מצות הוא דילפינן מהדדי בג\"ש דלה לה אבל גבי עדות לא שייך למילף דאין תלוי בנאמנות שהרי משה ואהרן לא מעידין לא משום דלא מהימני הלכך היכא דגלי גלי:"]]],[["לא יהו כהנים זכאין בעורה ת\"ל עור העולה מ\"מ","עור העולה אין לי אלא עור העולה עורות קדשי קדשים מנין ת\"ל עור העולה אשר הקריב יכול שאני מרבה אף קדשים קלים ת\"ל עולה מה עולה קדשי קדשים אף כל קדשי קדשים","רבי ישמעאל אומר עור העולה אין לי אלא העולה עורות קדשי קדשים מנין ודין הוא ומה עולה שלא זכו בבשרה זכו בעורה קדשי קדשים שזכו בבשרן אינו דין שזכו בעורן","מזבח יוכיח שזכה בבשר ולא זכה בעור מה למזבח שכן לא זכה במקצת תאמר בכהנים שזכו במקצת הואיל וזכו במקצת זכו בכוליה","רבי אומר כל עצמו לא הוצרכנו אלא לעור העולה בלבד שבכל מקום העור מהלך אחר הבשר","פרים הנשרפין ושעירים הנשרפין הן ועורותיהן [נשרפין] עמהן חטאת ואשם וזבחי שלמי ציבור מתנה לכהן רצו מפשיטין אותן לא רצו אוכלין אותן ע\"ג עורן קדשים קלים לבעלים רצו מפשיטין אותן רצו אוכלין אותן על גב עורן","אבל עולה נאמר בה (ויקרא א, ו) והפשיט את העולה ונתח אותה לנתחיה יכול לא יהו הכהנים זכאין בעורה ת\"ל (ויקרא ז, ח) עור העולה אשר הקריב","לו יהיה פרט לטבול יום (ומחוסר כיפורים) ואונן שיכול לא יזכו בבשר שהוא לאכילה יזכו בעור שאינו לאכילה ת\"ל לו יהיה פרט למחוסר כיפורים וטבול יום ואונן","ות\"ק נמי תיפוק לי מדינא מילתא דאתיא בקל וחומר טרח וכתב לה קרא","ורבי ישמעאל האי אשר הקריב מאי עביד ליה פרט לטבול יום ומחוסר כיפורים ואונן","ותיפוק ליה מלו יהיה רבי ישמעאל לטעמיה דאמר רבי יוחנן משום רבי ישמעאל נאמר בעולה לו יהיה ונאמר באשם לו יהיה מה להלן עצמותיו מותרין אף כאן עצמותיו מותרין","מופני דאי לא מופני איכא למיפרך מה לאשם שכן בשרו מותר לו יהיה קרא יתירא הוא:","\u0001מתני׳\u0002 כל הקדשים שאירע בהן פסול קודם להפשיטן אין עורותיהן לכהנים לאחר הפשיטן עורותיהן לכהנים אמר רבי חנינא סגן הכהנים מימי לא ראיתי עור שיוצא לבית השריפה","אמר רבי עקיבא מדבריו למדנו שהמפשיט את הבכור ונמצא טריפה שיאותו הכהנים בעורוו חכמים אומרים אין לא ראינו ראיה אלא יצא לבית השריפה:","\u0001גמ׳\u0002 כל שלא זכה המזבח בבשרה לא זכו הכהנים בעורה ואע\"ג דאפשטיה לעור קודם זריקה מני רבי אלעזר ברבי שמעון היא דאמר אין הדם מרצה על העור בפני עצמו","אימא סיפא כל הקדשים שאירע בהן פסול קודם הפשיטן אין עורותיהן לכהנים לאחר הפשיטן עורותיהן לכהנים אתאן לרבי דאמר הדם מרצה על העור בפני עצמו רישא רבי אלעזר ברבי שמעון סיפא רבי","אמר אביי מדסיפא רבי היא רישא נמי רבי היא ומודה רבי שאין הפשט קודם זריקה","רבא אמר מדרישא ר\"א ברבי שמעון סיפא נמי ר\"א בר\"ש מאי קודם הפשט"],[[1,"אשר הקריב","כל הקרבנות במשמע:"],[3,"שזכה בבשר","באימורים:"],[3,"שכן לא זכה במקצת","עורות שלא מצינו עור למזבח תאמר בכהנים שזכו במקצת בעור העולה:"],[4,"כל עצמו כו'","אין לנו להביא ראיה לשאר עורות מעולה שפרט בה הכתוב לבדה מפני שלא הוצרכנו ללמוד על שאר עורות מה תהא עליהן אלא על של עולה בלבד:"],[5,"ועורותיהן עמהן","כדכתיב ואת הפר ואת עורו וגו':"],[5,"רצו מפשיטין","שהרי לא הצריכו להפשיט ונתנו לכהן כמות שהן כדכתיב כחטאת כאשם תורה אחת וגו':"],[6,"נאמר בה והפשיט","והבשר למזבח ועל העור שהזקיקו להפשיט לא אמור מה תהא עליו ולמזבח אינך יכול להביאו (זה) דבהדיא פרט לך הקטר באברים מופשטין ולא פרט לך העור עמהן:"],[7,"לו יהיה","רישיה דקרא המקריב את עולת איש ועליה קאי לו יהיה:"],[7,"פרט לאונן כו'","דלא חזי להקרבה:"],[7,"שיכול לא יזכו בבשר","כלומר אע\"פ שנתמעטו מלחלוק בבשר מלאכול לערב הוצרכו למעטן מן העורות:"],[7,"שיכול לא יזכו בבשר","מפני שהוא ראוי לאכילה והן אינן ראוים לאכילת היום:"],[8,"מדינא","כי היכי דנפקא ליה לרבי ישמעאל ולמה לי קרא לעורות קדשי קדשים:"],[9,"אשר הקריב","דיליף ת\"ק מיניה עורות קדשי קדשים מאי עביד ליה:"],[10,"תיפוק ליה מלו יהיה","כדנפקא ליה לרבי:"],[10,"רבי ישמעאל לטעמיה","דדריש לו יהיה לדרשא אחריתי:"],[11,"קרא יתירא הוא","דמצי למכתב עור העולה אשר הקריב לכהן ולשתוק:"],[12,"מתני' אין עורותיהן לכהנים","אלא נשרפים עם עורן:"],[12,"לא ראיתי עור יוצא לשריפה","משהופשט הכי מפרש לה בגמרא:"],[13,"ונמצא טריפה","ואפילו שפסול זה היה בו קודם הפשט הואיל ולא ניכר עד לאחר הפשט יאותו הכהנים בעורו:"],[13,"אין לא ראיתי ראיה","שמא לא אירע בימיו שימצא טריפה אחר הפשט ואם אירע ושרפוה הוא לא ראה:"],[13,"אלא יצא לבית השריפה","הואיל וקודם הפשט הוה ביה:"],[14,"","גמ' ה\"ג בגמ' כל שלא זכה המזבח בבשרה לא זכו הכהנים בעורה ואע\"ג דאפשטיה לעור קודם זריקה ול\"ג כל שאין לו בבשר דההיא מאי בעיא לענין דם מרצה על העור הא ההיא בכהן טמא קאמר אלא רישיה דהך דלעיל מהך נקט ואותיב הכי קתני רישא כל שלא זכה המזבח בבשרה כגון שאירע בו פסול קודם זריקה דלא היה לה לבשר שעת היתר למזבח לא זכו הכהנים בעורה ולא פליג בין שהופשט קודם הפסול בין לא הופשט אלמא אע\"ג דאפשטיה לעור קודם זריקה ונפסל הבשר ואח\"כ זרק קאמר דלא זכו בעורה:"],[14,"מני ר' אלעזר בר' שמעון היא","דאמר לקמן (זבחים דף קד.) אין הדם מרצה על עור חלוץ בפני עצמו בלא בשר כגון אם נפסל הבשר ואין הדם מרצה עליו אף העור לא יצא מידי מעילה להיות ניתר לכהנים אחר הפשטן:"],[15,"עורותיהן לכהנים","ואפילו אירע פסול זה קודם זריקה:"],[15,"אתאן לרבי","דפליג עליה דרבי אלעזר לקמן (שם) ואמר הדם מרצה על עור חלוץ בפני עצמו בלא הרצאת בשר:"],[16,"ומודה רבי שאין הפשט קודם זריקה","אע\"ג דאמר הדם מרצה על העור בפני עצמו היכא דאיתרמי דאיפשט קודם זריקה מודה הוא שאין כהנים רגילין בכך שאסור לשהות הדם כל כך הלכך נמי דקתני כל שלא זכה המזבח בבשרה לא זכו הכהנים בעורה טעמא משום דפסול דקודם זריקה קודם הפשט הוא ומיהו היכא דאיתרמי דהפשיט קודם זריקה ונפסל אחר הפשט אע\"פ שלא זכה מזבח בבשר יזכו הכהנים בעורה ומשנתינו דברה בהוה:"]],[[16,"ומודה רבי שאין הפשט קודם זריקה","משמע הכא דלכ\"ע היכא דנולד פסול קודם הפשט וקודם זריקה אין הדם מרצה על העור ותימה דבסוף הגוזל קמא (ב\"ק דף קיא.) אמר גבי נתן אשם ליהויריב וכסף לידעיה דאם קדמו בני יהויריב והקריבו את האשם זכו במה שבידם ופריך למאי חזי אשם פסול הוא אמר רבא לעורו והשתא עורו גופיה הא. לא חזי דהיינו קודם הפשט וזריקה דתחלת הבאתו בפסול וי\"ל דהתם לאחר שחיטת האשם יכול להביא כסף קודם זריקה קרינא ביה מלבד איל הכפורים אשר יכפר בו כיון דעדיין לא נכפר הלכך לא חשיב פסול דקודם זריקה ומיהו קשה כיון דאיכא הפסול בידם מה לי קודם זריקה ומה לי לאחר זריקה וי\"ל דהוי כמו שנמצא טריפה בבני מעיים לרבי חנינא סגן הכהנים הואיל ולא הוכר פסולו קודם הפשט לרבי וקודם זריקה לרבי אלעזר מרצה על העור (הג\"ה) וקשה דתניא בתוספתא דפסחים הביא את אשמו קודם גזילו לא יהא אחר ממרס בדמו עד שיביא גזילו אלא תעובר צורתו ותצא לבית השריפה אלמא אין תקנה להביא הגזל קודם שנשחט ואין לומר היינו מדרבנן הא תניא בסיפא גבי מצורע (לעיל) (. דף ה) הקדים חטאתו לאשמו לא יהא אחר ממרס בדמו אלא תעובר צורתו ותצא לבית השריפה ומהכא מוכח פ' קמא דמנחות (דף ה.) יש מחוסר זמן לבו ביום ואע\"ג דמן התורה פסול צריך עבור צורה כדתניא פרק כיצד צולין (פסחים דף ס) כל שפסולו בגופו ישרף מיד בדם ובבעלים תעובר צורתו ופסולו בגופו הוי כמו פיגול וטריפה ונבלה אבל הקדמה לא. ברוך:"]]],[["ומאי אחר הפשט קודם שנראו להפשט אחר שנראו להפשט","מאי רבי ומאי רבי אלעזר בר' שמעון דתניא רבי אומר הדם מרצה על העור בפני עצמו וכשהוא עם הבשר נולד בו פסול בין קודם זריקה בין לאחר זריקה הרי הוא כיוצא בו","רבי אלעזר בר\"ש אומר אין הדם מרצה על העור בפני עצמו וכשהוא עם הבשר נולד בו פסול קודם זריקה הרי הוא כיוצא בו אחר זריקה הורצה בשר שעה אחת יפשיטנו ועורו לכהנים","לימא בדרבי אליעזר ורבי יהושע קמיפלגי (דברים יב, כז) ועשית עולותיך הבשר והדם רבי יהושע אומר אם אין דם אין בשר אם אין בשר אין דם","רבי אליעזר אומר דם אע\"פ שאין בשר שנאמר (דברים יב, כז) ודם זבחיך ישפך א\"כ מה ת\"ל ועשית עולותיך הבשר והדם לומר לך מה דם בזריקה אף בשר בזריקה הא למדת שריוח יש בין כבש למזבח","לימא מ\"ד הורצה כר\"א ומ\"ד לא הורצה כר' יהושע","אליבא דר\"א כ\"ע לא פליגי כי פליגי אליבא דרבי יהושע","מ\"ד לא הורצה כרבי יהושע מ\"ד הורצה אמר לך עד כאן לא קאמר רבי יהושע התם אלא בבשר דליכא פסידא לכהנים אבל עור דאיכא פסידא לכהנים אפילו רבי יהושע מודה","מידי דהוה אדיעבד דתנן נטמא בשר או נפסל או שיצא חוץ לקלעים ר\"א אומר יזרוק רבי יהושע אומר לא יזרוק ומודה רבי יהושע שאם זרק הורצה:","א\"ר חנינא סגן הכהנים כו': ולא הרי פרים הנשרפים ושעירים הנשרפים","למצותן לא קאמרינן","הרי קודם הפשט וקודם זריקה חלוץ קאמרינן","והאיכא אחר הפשט וקודם זריקה לרבי אלעזר ברבי שמעון דאמר אין הדם מרצה על העור בפני עצמו","רבי חנינא כרבי סבירא ליה ואיבעית אימא אפילו תוקמא כרבי אלעזר ברבי שמעון מודה רבי שאין הפשט קודם זריקה","והאיכא נמצאת טריפה בבני מעיים","קסבר נמצאת טריפה בבני מעיים מרצה דיקא נמי דקתני א\"ר עקיבא מדבריו למדנו שהמפשיט את הבכור ונמצא טריפה שיאותו הכהנים בעורו ש\"מ","ואלא מאי קמ\"ל ר\"ע הא קמ\"ל אפילו בגבולין","א\"ר חייא בר אבא א\"ר יוחנן הלכה כר\"ע ואף ר\"ע לא אמר אלא כשהתירו מומחה אבל לא התירו מומחה לא","והלכתא כדברי חכמים (בשר בקבורה והעור בשריפה):","\u0001מתני׳\u0002 פרים הנשרפים ושעירים הנשרפים בזמן שהן נשרפין כמצותן נשרפים בבית הדשן ומטמאין בגדים ואם אינן נשרפין כמצותן נשרפין בבית הבירה ואינן מטמאין בגדים"],[[0,"קודם שנראו להפשט","קודם זריקה אין עורותיהן לכהנים ואפי' הופשט ואח\"כ נפסל וכל שכן כשהוא עם הבשר דאין דם מרצה על העור בלא בשר:"],[0,"לאחר שנראו להפשט","דהיינו לאחר זריקה עורותיהן לכהנים ואפי' עורו עם הבשר כשנפסל כדקאמר רבי אלעזר דכיון שנזרק הדם והורצה בשר שעה אחת יפשיטנו ועורו לכהנים:"],[1,"על העור בפני עצמו","אם הופשט ונפסל הבשר קודם זריקה וזרק הדם הותר העור דקסבר רבי אין עור פסול אלא הנפסל עם הבשר אבל הופשט קודם פסולו אפי' קודם זריקה אתיא זריקה ושריא ליה וכל שכן אחר הפשט ואחר זריקה אבל אם קודם הפשט נפסל ואפילו אחר זריקה הרי הוא כבשר:"],[2,"רבי אלעזר ברבי שמעון כו'","קסבר בזריקה כשרה תליא היתר העור אבל נפסל בשר קודם זריקה אין העור מותר ואפילו הופשט קודם פסולו:"],[5,"מ\"ד","הדם מרצה על העור לאחר שנפסל בשר:"],[5,"כרבי אליעזר","דאמר דם אע\"פ שאין בשר:"],[6,"אליבא דר' אליעזר כ\"ע לא פליגי","כלומר מילתיה דרבי אלעזר ברבי שמעון דאמר לא הורצה ודאי פלוגתא היא דעל כרחך מודה הוא דאילו רבי אליעזר לא קאי כוותיה דהא קאמר יזרוק לכתחילה אף ע\"פ שאין בשר כגון אבד או נשרף אלמא זריקה מעלייתא היא:"],[6,"כי פליגי אליבא דרבי יהושע","כלומר הא דאמר דמ\"ד הורצה כר' אליעזר ולא כרבי יהושע ליתא דאפילו אליבא דרבי יהושע אמרה רבי למילתיה:"],[7,"ה\"ג עד כאן לא א\"ר יהושע אלא בבשר דליכא פסידא לכהנים","ע\"כ לא קאמר רבי יהושע אם אין בשר אין דם אלא לענין לעלות קרבן לבעלים לחובה דליכא פסידא לכהנים והתורה אמרה (דברים יב) הבשר והדם:"],[7,"אבל לענין עור דאיכא פסידא דכהנים אפילו רבי יהושע מודה","דלא מפסידנא להו שלא כדין ואם נשרף בשר או אבד קודם זריקה לכתחילה לא יזרוק וליכא פסידא דכהנים שהרי לא קרב הקרבן ואם עבר וזרק הדם הויא זריקה להתיר העור אע\"פ שלא עלה לו הקרבן הקרבה הוי וקרינא ביה עור העולה אשר הקריב:"],[8,"מידי דהוה אדיעבד","דקתני אם זרק הורצה הניחא גבי נטמא איכא למימר הציץ מרצה אבל גבי יוצא לא מרצה הציץ וקאמר אם זרק הורצה אלמא ק\"ל היה לו לרבי יהושע בדרשה זו דאם אין בשר אין דם דאם זרק הורצה הלכך גבי אבוד ושרוף נמי אע\"ג דבדיעבד נמי פסול כדאמרינן בכיצד צולין (פסחים עח:) לענין עור מיהא מודה:"],[10,"למצותן לא קאמר","דהני הכשר מצותן בכך וכי קאמר ר' חנינא בנשרפין מחמת פסולן:"],[11,"והאיכא קודם הפשט וקודם זריקה","דבין לרבי בין לרבי אלעזר ברבי שמעון נשרף לרבי משום דקודם הפשט ולרבי אלעזר משום דקודם זריקה:"],[11,"חלוץ קאמרי'","מימי לא ראיתי עור מופשט יוצא לבית השריפה והנפסל קודם הפשט עורו נשרף בבשרו ואין מפשיטים אותו:"],[12,"והאיכא אחר הפשט קודם זריקה","דלרבי אלעזר ברבי שמעון חלוץ ונשרף הוא:"],[13,"ומשני רבי חנינא כרבי ס\"ל","דאמר הדם מרצה על העור:"],[13,"ה\"ג ואב\"א אפילו תימא כר' אלעזר בר\"ש ומודה רבי שאין הפשט קודם זריקה","אפילו תימא רבי חנינא כרבי אלעזר ס\"ל ודקא קשיא לך הא איכא אירע בו אחר הפשט קודם זריקה לא איתרמי בימיו דאפילו לרבי דאמר הדם מרצה על העור בפני עצמו מודה הוא דאין הפשט קודם זריקה (ולא הורגלו בכך) וכל שכן לרבי אלעזר ברבי שמעון לא הורגלו בכך:"],[14,"והאיכא נמצאת טריפה בבני מעיים","לא נמצא פסולו עד שהופשט ופסול זה קודם זריקה וקודם הפשט היה בו דקס\"ד דבין לרבי ובין לרבי אלעזר נשרף כדאמרן לרבי משום דקודם הפשט ולרבי אלעזר משום קודם זריקה:"],[15,"מרצה","הואיל ולא הוכר פסולו קודם הפשט לרבי וקודם זריקה לרבי אלעזר מרצה על העור והבשר ישרף כשאר פסולי קדשים:"],[16,"אלא מאי קמ\"ל רבי עקיבא","כיון דשמעיה לרבי חנינא דאמר בשאר קדשים מרצה למה לי לאשמועינן בכור:"],[16,"דאפילו בגבולין","בכור בעל מום הנשחט בו במדינה על מומו ולא התירו הכתוב אלא באכילה כדכתיב (דברים ט״ו:כ״ב) בשעריך תאכלנו אבל אם מת עורו אסור וטעון קבורה ואשמועינן רבי עקיבא דהיכא דלא ניכר טריפתו עד לאחר הפשט שראה שחיטתו והפשיט עורו כאילו נזרק דמו במקדש ונמצא טריפה לאחר הפשט:"],[18,"בשר בקבורה","דאין מאכילין קדשים לכלבים ושריפה ליכא דאין שריפה בקדשים אלא כשהובאה לעזרה ונפסל לאחר שחיטה:"],[18,"והעור בשריפה","לא ידענא טעמא ונראה בעיני דל\"ג האי פירושא אלא ה\"ג והלכה כדברי חכמים ותו לא מידי ותוספתא זו גירסא דתלמידי תרביצאי היא וטעו במה ששנינו במשנתינו במילתייהו דרבנן לבית השריפה יצא ואני אומר דרבנן לאו אדר\"ע קיימי דאיירי בבכור בגבולין אלא אדרבי חנינא קיימי דאיירי בקדשי המקדש:"],[19,"מתני' נשרפין בבית הדשן","חוץ לג' מחנות כדיליף לקמן בפירקין:"],[19,"ומטמאין בגדים","לעסוקין בהן כדכתיב (ויקרא טז) והשורף אותם וגו':"],[19,"שלא כמצותן","שנפסלו טעונין שריפה כשאר פסולי קדשים:"],[19,"בבית הבירה","פעמים בעזרה פעמים בהר הבית כדאמרינן בגמרא:"]],[[7,"מאן דאמר לא הורצה כרבי יהושע","תימה היכי מצי סבר כוותיה הא קתני ומודה רבי יהושע דאם זרק הורצה כדבסמוך ונראה לפרש ומ\"ד לא הורצה כר' יהושע דגזר נטמא בשר או נפסל דלא יזרוק אטו אבוד ושרוף דליכא בשר כלל דהתם אפילו בדיעבד לא הורצה והכא נמי אין הדם מרצה על העור בפני עצמו אפילו בדיעבד בנטמא גזירה אטו אבוד ושרוף ולא מיירי הכא באבוד ושרוף אלא בנטמא או נפסל ומ\"ד הורצה ע\"כ לא קאמר רבי יהושע דגזר אטו אבוד ושרוף ולא יזרוק אלא גבי בעלים דליכא פסידא דכהנים שעדיין לא זכו בעורו אבל עור דאיכא פסידא [דכהנים] דכבר זכו כהנים משנזרק הדם התם לא גזרינן אטו אבוד ושרוף מידי דהוה אדיעבד פי' בפסול יוצא וטומאה דדיעבד אם זרק הורצה ולא גזרינן הכא נמי מרצה הדם על העור בפני עצמו ופירוש הקונטרס דחוק:"],[9,"א\"ר עקיבא מדבריו למדנו כו'","משמע דוקא בעורו יאותו הכהנים אבל בבשרו לא דאפילו לעובדי כוכבים אסור והקשה ה\"ר אפרים דבפרק כל פסולי המוקדשים (בכורות דף לב:) מתיר רבי עקיבא אפילו לעובדי כוכבים ולעיל פי' בריש פ' התערובת (זבחים דף עא:) אבל לא התירו מומחה לא משמע דוקא משום טריפות הא לאו הכי לא והיינו דלא כר\"מ דקניס בפ' כל פסולי המוקדשין (בכורות דף לג) בבכור שנשחט שלא על פי מומחה מכאן דקדק בהלכות גדולות דהא דקיימא לן כרבי מאיר בגזירותיו דוקא בגזירותיו ולא בקנסיו:"]]],[["היו סובלין אותו במוטות יצאו הראשונים חוץ לחומת העזרה והאחרונים לא יצאו הראשונים מטמאין בגדים והאחרונים אינן מטמאין בגדים עד שיצאו יצאו אלו ואלו מטמאין בגדים רבי שמעון אומר אינן מטמאין עד שיוצת האור ברובן ניתך הבשר אין השורף מטמא בגדים:","\u0001גמ׳\u0002 מאי בירה אמר רבה בר בר חנה אמר רבי יוחנן מקום יש בהר הבית ובירה שמו ור\"ל אמר כל הבית כולו קרוי בירה שנאמר (דברי הימים א כט, יט) (ואל) הבירה אשר הכינותי","אמר רב נחמן אמר רבה בר אבוה שלשה בית הדשנין הן בית הדשן גדול היה בעזרה ששם שורפין פסולי קדשי קדשים ואימורי קדשים קלים ופרים הנשרפין ושעירים הנשרפין שאירע בהן פסול קודם זריקה","ובית הדשן אחר היה בהר הבית ששם שורפין פרים הנשרפים ושעירים הנשרפים שאירע בהן פסול אחר זריקה וכמצותן חוץ לשלש מחנות","תני לוי שלשה בית הדשנין הן בית הדשן גדול היה בעזרה ששם שורפין פסולי קדשי קדשים ואימורי קדשים קלים ופרים הנשרפים ושעירים הנשרפים שאירע בהן פסול בין קודם זריקה בין לאחר זריקה ובית הדשן אחר היה בהר הבית ששם שורפין פרים הנשרפין ושעירים הנשרפין שאירע בהן פסול ביציאתן וכמצותן חוץ לשלש מחנות","בעי רבי ירמיה לינה מהו שתועיל בפרים הנשרפים ובשעירים הנשרפים מי אמרינן כי מהניא לינה בבשר דבר אכילה אבל הני דלאו בני אכילה נינהו לא או דלמא לא שנא","אמר רבא הא מילתא איבעיא ליה לאביי ופשטנא ליה מהא ושוין שאם חישב באכילת פרים ובשריפתן שלא עשה כלום מאי לאו מדמחשבה לא פסלה לינה נמי לא פסלה","ודלמא מחשבה הוא דלא פסלה אבל לינה פסלה","תא שמע פרים הנשרפים ושעירים הנשרפין מועלין בהן משהוקדשו נשחטו הוכשרו ליפסל בטבול יום ובמחוסר כיפורים ובלינה מאי לאו לינת בשר","לא לינת אימורין","והא מדקתני סיפא כולן מועלין בהן בבית הדשן עד שיותך הבשר מדסיפא בשר רישא נמי בשר מידי איריא סיפא בשר רישא אימורין","תא שמע דתני לוי שאירע בהן פסול ביציאתן מאי לאו לינה לא פסול טומאה ופסול יציאה","בעי ר\"א יציאה מהו שתועיל בפרים הנשרפים ושעירים הנשרפים","מאי קמיבעיא ליה א\"ר ירמיה בר אבא אליבא דמ\"ד עדיין לא הגיע זמנו לצאת","מי אמרינן ה\"מ בשר דאין סופו לצאת חובה אבל הני דסופן לצאת חובה לא או דלמא ה\"נ לא הגיע זמנו לצאת","ת\"ש דתני לוי שאירע בו פסול ביציאתו מאי לאו פסול יציאה לא פסול טומאה ופסול לינה","בעי רבי אלעזר פרים הנשרפים ושעירים הנשרפים שיצא רובו במיעוט אבר מהו הך מיעוטא דאבר בתר רובא שדינן ליה והא לא נפקא ליה או דלמא בתר רובא דבהמה שדינן","פשיטא דלא שבקינן רובא דבהמה ואזלינן בתר רובא דאברים אלא שיצא חציו ברוב אבר האי מיעוטא דאבר"],[[0,"היו סובלין אותו","הנשרפין כמצותן במוטות לקמן יליף לה:"],[0,"הראשונים","בני אדם הנושאין במוט אותן שבראש האחר יוצאים ראשונים:"],[0,"עד שיצאו","האחרונים בגמרא יליף לה:"],[0,"ניתך הבשר","דגמרה שריפתן אין המסייע שוב בהן מטמא בגדים אבל מקמי הכי כל המסייעין בשעת שריפה מטמאין בגדים וכולה יליף בגמרא:"],[2,"גמ' ששם שורפים פסולי בשר קדשי קדשים","שמחיצת אכילתן בעזרה ופסולי אימורים אפילו של קדשים קלים דהואיל והקטרת הכשירין בעזרה אף שריפת פסוליהן בעזרה כדילפינן בפסחים בפרק כל שעה (פסחים דף כד.) מבקדש באש תשרף:"],[2,"קודם זריקה","שלא הגיע זמנו לצאת לפיכך נשרפין בעזרה:"],[3,"אחר זריקה","שהגיע זמנו לצאת לפיכך נשרפין חוץ לעזרה:"],[3,"וכמצותן","וכשהן נשרפין כמצותן שלא אירע בהן שום פסול:"],[3,"נשרפין חוץ לג' מחנות","כדילפינן בפירקין:"],[4,"בין לאחר זריקה","הואיל ועדיין לא יצאו:"],[4,"ביציאתן","לאחר שיצאו:"],[5,"מהו שתועיל","לפוסלן אם לנו:"],[5,"בבשר דבר אכילה","עולה או אימורין שהן לאכילת מזבח אבל הני דלשריפה קיימי דלא אשכחן לה אלא או באכילת מזבח כדכתיב (שמות כג) לא ילין חלב חגי וגו' או באכילת אדם כדכתיב (שם יב) לא תותירו וגו':"],[6,"ושוין שאם חישב כו'","ושוין ר\"ש וחכמי' שנחלקו בפ' ב\"ש (לעיל זבחים מג.) אם פיגול נוהג בחטאות הפנימיות שאם חישב לאכול מבשר הפרים למחר או אם חישב בשחיטה על מנת לשורפן חוץ לג' מחנות למחר לא עשה כלום דמחשבת אכילה בדבר שדרכו לאכול בעינן והני לאו דרכן לאכול וגבי שריפה נמי אע\"ג דכי אורחיה חשיב אכילת מזבח או אכילת אדם בעינן לפגל ומ\"ד פיגול נוהג בפנימיים כגון אם חישב על הקטרת אימורים להקריבו למחר:"],[6,"לינה נמי לא פסלה","בבשרו קס\"ד דאי לינה פסלה מחשבת לינה נמי פסלה:"],[9,"לינת אימורין","דבמידי דהקטרה ודאי פסלה לינה:"],[10,"עד שיותך הבשר","דכל זמן שלא נעשית מצותן מועלין בהן:"],[10,"מדסיפא","לענין מעילה בבשר איירי:"],[10,"רישא נמי","לענין לינה לענין בשר קאמר:"],[11,"דתני לוי","במתניתא דלעיל:"],[11,"ופסול יציאה","כגון שיצאו לפני זריקת דמים שעדיין לא הגיע זמנן לצאת:"],[12,"יציאה מהו שתועיל","לפוסלן אם יצאו מן העזרה לפני זריקת דמים:"],[13,"מאי קמיבעיא ליה","אמאי תיפסול הרי סופן לצאת:"],[13,"א\"ר ירמיה בר אבא","כי קא מיבעיא ליה אליבא דמאן דפסיל בשר קדשים קלים שיצא לפני זריקת דמים משום דעדיין לא הגיע זמנו לצאת בפרק כל התדיר (לעיל זבחים פט:) הכא מאי מי אמרינן הני מילי בבשר קדשים קלים דאין סופן חובה לצאת אבל הני שסופן לצאת חובה לא מיפסלי ביציאתן:"],[15,"לא פסול טומאה ולינה","דקאי הכא ומדחי ליה קאי הכא ומדחי ליה:"],[16,"שיצא רובו","ומיעוט אחד מן האברים משלים לרובא של בהמה ליציאתה:"],[16,"מהו","מי הוי יציאה לטמא את המתעסקין בהוצאת רובן או לא הוי יציאה מי אמרינן שדי מיעוטא דאבר בתר רוב האבר והוה ליה כמאן דלא נפק ואין כאן רוב הבהמה לחוץ ולענין טומאת בגדים מחוץ למחנה בעי (האי מיעוטא דאבר שיצא לחוץ):"],[17,"אלא שיצא חציו","של פר ברוב אבר בחצי הפר (הג\"ה) יצא רוב אחד מן האברים ומיעוטו בחצי הפר שבפנים האי מיעוטא דאבר שנשאר בפנים בתר רובא דאבר שיצא שדינן ליה והוה ליה כמאן דנפק ואשתכח רוב בהמה מבחוץ:"]],[[7,"לא מחשבה הוא דלא פסלה אבל לינה פסלה","תימה דבריש הוציאו לו (יומא דף מח.) בעי רב פפא חישב בחפינת קטרת מהו ת\"ש הוסיף רבי עקיבא הקומץ והקטרת כו' מדפסיל טבול יום פסולה נמי מלינה ומדפסלה לינה פסלה נמי מחשבה ולא דחי כדהכא וי\"ל דהתם דבאכילת מזבח מה לי מחשבה מה לי לינה אבל הכא בבשר פרים הנשרפין וא\"ת היכי פסלה מחשבה בקטרת הא תנן לעיל בפרק ב\"ש (זבחים דף מב:) דקטרת ולבונה אין בהן משום פיגול וי\"ל דנהי דכרת ליכא מחשבה מיהא פסלה מידי דהוה אחטאות הפנימיות לרבי שמעון דאמר בפ\"ק (לעיל זבחים יד.) מודה היה רבי שמעון לפסול מק\"ו משלא לשמו ובקטרת נמי אהני ג\"ש דמלא מלא ממנחה והתם הקשה בקונטרס אמאי הוצרך לדקדק מטבול יום הוה ליה לאתויי ממתני' דמעילה (דף י.) דקתני בהדיא הוכשרו ליפסל בטבול יום ובמחוסר כיפורים ובלינה ותירץ רבינו יב\"א משום דההיא מיירי בקטרת דכל השנה כדקתני קדשו בכלי וההוא דמיקדש בכלי פסלה ביה לינה אבל התם בקטרת דיום הכיפורים דעיקרה אינה בכלי אלא משום דלא אפשר כדאמר התם לעיל והא אמרי' דלא מיפסלה בלינה אבל ההיא דרבי עקיבא משמע דמיירי בכל קטרת ועוד י\"ל דההיא דמעילה איכא לדחויי מדרבנן וכן מחייבין עליה משום פיגול וטמא הוה אמינא מכת מרדות כמו אכל אוכלין טמאין ושתה משקין טמאין ושתה רביעית יין ונכנס למקדש ושהה כדי אכילת פרס חייב דהיינו מדרבנן דפסול גויה [הוי דרבנן] כדאמרינן בפרק בתרא דיומא (דף פ:) אבל ההיא דר' עקיבא פשיטא דאורייתא מדפסל טבול יום ע\"י צירוף דאי מדרבנן לא הוה מחמירין נמי האי פסול על ידי צירוף וא\"ת והיכי דייק מדפסיל טבול יום פסלה נמי לינה והא משניתנה במכתשת נפסלת בטבול יום ולינה לא פסלה עד שתנתן במחתה כדאמר פרק קמא דשבועות (דף יא.) וי\"ל דהא דנפסלת בטבול יום היינו מדרבנן:"],[16,"שיצא רובו במיעוט אבר","פי' בקונטרס דמיבעיא ליה לענין טמא המתעסק בהן וקשה דבסוף כיצד צולין (פסחים פה:) אמרינן המוציא בשר פסח מחבורה לחבורה אינו חייב עד שיניח הוצאה כתיב ביה כשבת ופריך ממתני' דהכא דהיו סובלין אותו במוטות דקתני ראשונים מטמאין בגדים אחרונים אין מטמאין בגדים עד שיצאו ואף על גב דלא נח ומשני בנגררים ואם כן רובו במיעוט אבר דהכא לא מחייב לענין שבת כיון דאגודו בפנים לא יטמא בגדים ונראה לפרש דמבעיא ליה לענין לשורפו בפנים:"]]],[["בתר רוב אבר שדינן ליה והא נפק ליה או דלמא בתר בהמה שדינן ליה תיקו","רבה בר רב הונא מתני לה בגברי במתעסקין בו חמשה בני אדם ונפקו תלתא ופשו להו תרי מאי בתר רוב מתעסקין אזלינן או בתר בהמה אזלינן תיקו","בעי רבי אלעזר פרים ושעירים הנשרפים שיצאו וחזרו מהו מי אמרינן כיון דנפקי להו איטמו להו או דלמא כיון דהדור הדור","אמר ר' אבא בר ממל ת\"ש היו סובלין אותן במוטות הראשונים יצאו חוץ לחומת העזרה והאחרונים לא יצאו הראשונים שיצאו חוץ לחומת העזרה מטמאין בגדים והאחרונים אין מטמאין בגדים עד שיצאו ואי ס\"ד כיון דנפקי להו איטמו הנך דאיכא גואי ליטמא","אמר רבינא ותסברא הא בעינא (ויקרא יד, ח) ואחר יבא אל המחנה וליכא","אלא רבי אלעזר היכי בעי לה כגון דנקיטי לה בבקולסי","ת\"ר פרים ופרה ושעיר המשתלח המשלח השורפן והמוציאן מטמא בגדים והן עצמן אין מטמאין בגדים אבל מטמאין אוכלין ומשקין דברי ר\"מ וחכ\"א פרה ופרים מטמאין אוכלין ומשקין שעיר המשתלח אינו מטמא שהוא חי והחי אינו מטמא אוכלין ומשקין","בשלמא לרבי מאיר כדתנא דבי ר' ישמעאל דתנא דבי רבי ישמעאל (ויקרא יא, לז) על כל זרע זרוע","מה זרעים שאין סופן ליטמא טומאה חמורה וצריכין הכשר אף כל שאין סופן ליטמא טומאה חמורה צריכין הכשר יצתה נבלת עוף טהור שסופה ליטמא טומאה חמורה ואין צריכה הכשר","אלא לרבנן אי אית להו דתנא דבי רבי ישמעאל אפילו שעיר המשתלח אי לית ליה אפי' פרה ופרים מנלן","כי אתא רב דימי אמר אמרי במערבא צריכין הכשר טומאה ממקום אחר","בעי רבי אלעזר פרים ושעירים הנשרפים מהו שיטמאו אוכלין ומשקין בפנים כבחוץ מחוסר יציאה כמחוסר מעשה דמי או לא","בתר דבעיא הדר פשטה מחוסר יציאה כמחוסר מעשה דמי","בעא מיניה רבי אבא בר שמואל מרבי חייא בר אבא נבלת עוף טהור לר' מאיר מהו שיטמא בכזית","דמחתא לארעא לא תיבעי לך דנקיט בפומיה לא תיבעי לך כי תיבעי לך דנקיט ליה בידיה מחוסר קריבה כמחוסר מעשה דמי או לא","(בתר דבעיא הדר פשטה)"],[[0,"או דלמא בתר בהמה","דמיחבר בה והיכא דאיתא שדינן לה ואע\"ג דלאו רובא דבהמה היא אלא פלגא וליכא למימר כדאמרן לעיל שבקינן רובא דבהמה אפילו הכי כיון דאין האבר נתוק לא אזלינן ביה בתר רובא ולא הויא יציאה ואם נטמא הפר שורפו בפנים:"],[1,"מתני לה","להך בעיא ברובא דמניינא דגברי:"],[2,"שיצאו וחזרו מהו","קס\"ד לענין טומאת בגדים של אלו שהוציאום קמיבעיא ליה:"],[2,"איטמו להו","בגדיהם:"],[2,"כיון דהדור הדור","והוו להו כמי שלא יצאו:"],[3,"הנך דאיכא גוואי נמי נטמאו","דהא יציאה לענין טומאת בגדים בפרים כתיבא יוציא אל מחוץ למחנה ושרפו וגו' ומיניה ילפינן לקמן בפירקין (זבחים דף קה:) לומר לך כיון שיצא הפר חוץ למחנה אחת מטמא בגדים אע\"פ דלא נפוק גברי נטמאו אלא לאו משום דאמר דאי הדר הדור וכל שכן אלו שמוחזרים ועומדין שהרי לא יצאו:"],[4,"אמר רבא ותסברא","דהך דקמייתי ראיה מילתא היא:"],[4,"הא בעינן ואחר יבא אל המחנה","אלמא קרא בדנפיק לבראי קאי דכל כמה דלא נפק לא קרינא ביה ואחר יבא וכיון דלא קרינא ביה ואחר יבא לא קרינא ביה יכבס בגדיו:"],[5,"ופרכינן אלא ר' אלעזר היכי בעי לה","דכיון דבהכי תליא מילתא מכי נפק קרינא ביה יכבס בגדיו ואי אהדרינהו ואתו אחריני לאפוקינהו אפי' חשבת להו מוציאין לא מטמאו הנך בתראי עד דנפקי דהא לא קרינא בהו ואחר יבא:"],[5,"דנקיטי לה בבקולסי","שאחזום במקלות ועומדין מבחוץ להוציאם לאחר שחזרו וקמיבעיא ליה מי אמרינן כיון שיצאו חוץ לעזרה כל העסוקים בהן מכאן ואילך חוץ לעזרה מטמאין בגדים או דלמא כיון דהדור הדור ועד דנפקי לא מטמאו: בקולסי בלשון הש\"ס ירושלמי מקל וראיתי דוגמתו בצילמי תרח נטל בקולסא ותברינון:"],[6,"השורף פרה אדומה ופרים הנשרפים מטמאין בגדים","פרה בהדיא כתיב בה (במדבר יט) פרים פר כהן משיח ופר העדה ופר יום הכיפורים גמרי מקרא יתירא דחטאת חטאת בשילהי כל הזבחים שנתערבו (לעיל זבחים פג.) ופר יוה\"כ בהדיא כתיב (ויקרא טז):"],[6,"והן אינן מטמאין בגדים","פרה ופרים עצמן אין מטמאין בגדים הנוגעין בהן בלא מתעסקין אבל מטמאין אוכלין ומשקין הנוגעין בהן ולקמן מפרש טעמא:"],[8,"כדתנא דבי ר' ישמעאל מה זרעים שאין סופן לטמא טומאה חמורה","כגון אדם ובגדים:"],[8,"וצריכין הכשר","דבר המכשירן לקבל טומאה כגון נתינת מים ומגע שרץ:"],[8,"אף כל שאין סופו לטמא כו'","כגון שאר אוכלין אבל הני פרה ופרים ושעיר הואיל וסופן לטמא אדם ובגדים כגון המתעסקין בהן אין צריכין הכשר טומאה הלכך מטמאו מחיים ואע\"ג דלא איטמויי שאר בעלי חיים דעלמא:"],[9,"אלא לרבנן אי דאית להו דתנא דבי רבי ישמעאל אפי' שעיר המשתלח ואי לית להו דתנא דבי רבי ישמעאל פרה ופרים מנא להו","הרי טהורין הן ולא נאמרה בהן טומאה אלא למתעסקים בהן:"],[10,"אמרי במערבא צריכין הכשר טומאה ממקום אחר","הא דתנא דבי רבי ישמעאל ה\"ק כל שאין סופו לטמא טומאה חמורה צריך הכשר טומאה ממקום אחר שיגע בשרץ או בנבילה ולא שיטמאו מאיליו אבל מי שסופו לטמא טומאה חמורה אין צריך ליגע בטומאה ומטמא טומאת אוכלין מאיליו כגון פרה ופרים אבל חזי לטומאה מיהת בעלמא בעינן ולא בעלי חיים דלא אשכחן בבהמות בעלי חיים מטמאין:"],[11,"מהו שיטמאו בפנים אוכלין ומשקין","הואיל ועדיין לא הגיעו להיות מטמאין טומאה חמורה לא מטמאו טומאה קלה או דלמא הואיל וסופן לטמא לכשיצאו מטמאו:"],[13,"נבלת עוף טהור","מטמאה טומאה חמורה בבית הבליעה בכזית:"],[13,"מהו שיטמא","לרבי מאיר אוכלין ומשקין בכזית לרבנן לא תיבעי לך דאמרי מידי דחזי לטומאה בעינן ובכזית אין לזו טומאה אלא בבית הבליעה אבל לענין מגע ליכא שיעורא בכזית אלא לרבי מאיר דאמר כל שסופו לטמא טומאה חמורה אין צריך ראויה לטומאה מהו שתטמא בכזית מאליה:"],[14,"דמחתא על ארעא לא תיבעי לך","דלא מיטמאה דהא אכתי לא הוגעה לסוף טומאה חמורה שמא לא תיכנס לבית הבליעה לעולם:"],[14,"דנקט בפומיה לא תיבעי לך","דאם היו אוכלים אחרים לתוך פיו מטמאתן דהא הגיעה לטומאה חמורה בהאי שיעורא כי תיבעי לך כו':"]],[[0,"או דלמא בתר בהמה אזלינן","תימה אם הבהמה בפנים פשיטא דגברי טהורים כדמוכח כולה שמעתין ויש לומר דה\"ק בתר בהמה דוקא אזלינן בתר רובא אבל בגברי לא:"],[2,"או דלמא כיון דהדור הדור","פי' בקונטרס דמבעיא ליה לענין טומאת בגדים של אלו שהוציאו וקשה אטו מחיצות עזרה מקום טהרה דכיון שנטמאו מי יטהרם ונראה לפרש דמבעיא ליה לענין הנוגע בפנים דדלמא כיון דיצאו בחוץ אע\"ג דחזרו הנוגע בפנים טמא ומסיק דמיבעיא ליה כיון דנקטי בבקולסי ומיירי בעומד בחוץ ואוחז במקלות להוציאם לאחר שיחזרו כדפירש בקונטרס. הג\"ה:"],[6,"פרים הנשרפים","שיצאו הפרים והאנשים וחזרו הפרים וגברי מהו פשיטא האנשים וגם בגדים שהיו עליהם טמאים ובחזרתן לא נטהרו אלא אם אנשים אחרים נכנסו בעזרה ויתעסקו בהוצאתן או הראשונים לבשו בגדים אחרים מי הוו טמאים בעסק זה קודם שיצאו חוץ לעזרה כיון שיצאו הפרים כבר חשוב כאילו מוציאים אותם מפתח עזרה ולחוץ וקאמר מי תלי מילתא בהוצאת הפר לבדו אע\"פ שלא יצאו האנשים א\"כ גבי סובלין אותן במוטות כיון שיצא הפר ולכך נטמאו הראשונים אם כן גם דגואי נטמאו ותסברא שיהא תלוי ביציאת הפר לבדו והא בעינן ואחר יבא אל המחנה אלא פשיטא דבעיא גם שיצאו האנשים עם הפרים ולכך דגואי לא מטמאי וגם בבעיא דילך אנשים אחרים שמעולם לא יצאו פשיטא דטהורין או גברי קדמאי אם לבשו בגדים אחרים אלא רבי אלעזר הכי בעי דנקטי בבקולסי שהפרים יצאו וחזרו אנשים אחרים ועמדו חוץ לעזרה ומוציאין הפרים שבתוך העזרה במקלות מי אמרינן כיון שהפרים כבר יצאו והאנשים עומדים בחוץ חשוב כאילו מוציאין אותן מפתח עזרה ולחוץ וטמאין או חשוב כאילו לא יצאו הפרים מעולם לחוץ וטהורים אבל אם נכנסו בפנים גברי חדשים או הראשונים בבגדים חדשים כיון שמעולם אלו לא יצאו פשיטא דטהורים אע\"פ שיצאו כבר הפרים: מה שבפנים אינו מבואר וזה עיקר. ברוך ד\"ך:"],[11,"מחוסר יציאה כמחוסר מעשה דמי או לא","וא\"ת אי מטמאו בפנים אם כן יטמאו את האימורים ויש לומר דמחוסר חתיכה פשיטא דהוי כמחוסר מעשה ולא תטמאו בשעת פרישתן דמיירי בניתזין בעל כרחו ובירושלמי גרסינן בסוף פרק שני שעירים רבי אליעזר שאל פרים הנשרפין ושעירים הנשרפים מהו שיטמאו בגדים בלא הכשר ובלא טומאה מפני שסופן לטמאות טומאה חמורה השיב רבי שמואל קפודקיא מעתה יטמאו אימורים אלא כשפרשו ואפילו תימא דלא פירשו כהדא אין מי חטאת מטמאין דבר לחזור ולטמאות ממנו:"]]],[["מחוסר קריבה לאו כמחוסר מעשה דמי","איתיביה שלשה עשר דברים נאמרו בנבלת עוף טהור וזה אחד מהן צריכה מחשבה ואין צריכה הכשר ומטמא טומאת אוכלין בכביצה מאי לאו ר\"מ היא","לא רבנן היא","והא קתני רישא צריכה מחשבה ואין צריכה הכשר ומאן שמעת ליה האי סברא ר\"מ ומדרישא ר\"מ סיפא נמי ר\"מ","מידי איריא הא כדאיתא והא כדאיתא","והא מדקתני סיפא שחיטתה ומליקתה מטהרת טריפתה מטומאתה מאן שמעת ליה האי סברא ר\"מ רישא וסיפא רבי מאיר ומציעתא רבנן","אין רישא וסיפא רבי מאיר ומציעתא רבנן","אמר ליה רב המנונא לרבי זירא לא תיתיב אכרעך עד דאמרת לי הא מילתא נבלת עוף טהור לר\"מ מונין לה ראשון ושני או אין מונין ראשון ושני","א\"ל כל היכא דמטמא אדם במגע מונין בו ראשון ושני כל היכא דאין מטמא אדם במגע אין מונין בו ראשון ושני","בעא מיניה רבי זירא מרבי אמי בר חייא ואמרי לה מר' אבין בר כהנא הא דתנן חיבורי אוכלין ע\"י משקין חיבור לטומאה קלה ואין חיבור לטומאה חמורה","מונין בו ראשון ושני או אין מונין בו ראשון ושני","א\"ל כל היכא דמטמא אדם מונין בו ראשון ושני אין מטמא אדם אין מונין בו ראשון ושני:","יצאו אלו ואלו: מה\"מ דת\"ר להלן הוא אומר חוץ לג' מחנות כאן למחנה אחת לומר לך כיון שיצא חוץ למחנה אחת מטמא בגדים","והיא גופה מנלן דת\"ר (ויקרא ד, יב) והוציא את כל הפר אל מחוץ למחנה חוץ לג' מחנות אתה אומר חוץ לג' מחנות או אינו אלא מחנה אחת","כשהוא אומר בפר העדה (ויקרא ד, יב) מחוץ למחנה שאין צריך לומר שהרי כבר נאמר (ויקרא ד, כא) כאשר שרף את הפר הראשון ליתן לו מחנה שניה","כשהוא אומר מחוץ למחנה בדשן שאצ\"ל שהרי כבר נאמר (ויקרא ד, יב) על שפך הדשן ישרף ליתן לו מחנה שלישית","ור\"ש האי מחוץ למחנה מאי עביד ליה מיבעי ליה לכדתניא רבי אליעזר אומר נאמר כאן חוץ למחנה ונאמר להלן (במדבר יט, ג) חוץ למחנה מה להלן חוץ לג' מחנות אף כאן חוץ לג' מחנות ומה להלן למזרחה של ירושלים"],[[0,"","הכי גרסינן אמר ליה מחוסר קריבה לאו כמחוסר מעשה דמי:"],[1,"צריכה מחשבה","להצטרף פחות מכזית ממנה להשלים פחות מכביצה אוכלין לקבל טומאת אוכלין במגע:"],[1,"ואינה צריכה הכשר","לטמא לא למים ולא למגע שרץ שמאליה מטמאה הואיל וסופה לטמא טומאה חמורה:"],[1,"ומטמאה טומאת אוכלין בכביצה","מדקתני צריכה מחשבה ואינה צריכה הכשר אלמא בדנקיט ליה בידיה עסקינן דאי מחתא אארעא אמאי אינה צריכה הכשר ואי דנקט לה בפומיה אמאי צריכה מחשבה אין לך מחשבה גדולה מזו וקתני כביצה אין כזית לא:"],[5,"","ה\"ג שחיטתה ומליקתה מטהרת טריפתה מטומאתה:"],[5,"האי סברא ר' מאיר","בפרק חטאת העוף (לעיל זבחים סט.):"],[7,"נבלת עוף טהור לר' מאיר","דמטמא טומאת אוכלין מאליה בכזית מונין בו ראשון ושני או לא:"],[8,"כל היכא דלא מטמא אדם במגע אין מונין בו ראשון ושני","דגמר משרץ דכתיב ביה מנין ראשון ושני דכתיב (ויקרא י״א:ל״ג) כל אשר בתוכו יטמא דהוה ליה הכלי ראשון והאוכל שני ונבלת עוף טהור לא מטמא אדם במגע:"],[9,"חיבורי אוכלין על ידי משקין","חצי זית נבלה מכאן וחצי זית נבלה מכאן ומשקה טופח באמצע ונוגע בשניהם מחברן לטמא אוכלין ומשקין הנוגעים באחד מן החצאין האלו:"],[9,"ואין חיבור לטומאה חמורה","לטמא אדם וכלים וטעמא לא ידענא:"],[12,"ה\"ג להלן אתה נותן להם שלש מחנות וכאן מחנה אחת א\"כ למה נאמר אל מחוץ למחנה לומר לך כיון שיצא חוץ למחנה אחת מטמאים בגדים","והא מתניא בת\"כ גבי פר יוה\"כ דכתיב (ויקרא ט״ז:כ״ז) ואת פר החטאת ואת שעיר החטאת אשר הובא וגו' וקמתמה תנא ואמר להלן בפר העדה וכהן משיח אתה נותן להם מקום שריפתן חוץ לשלש מחנות כדיליף לקמיה וכאן אתה אומר אל מחוץ למחנה ושרפו דמשמע ששורפן חוץ לעזרה מיד בהר הבית והלא אף אלו פנימיים ואייתי לכולהו כי הדדי בריבויא דחטאת החטאת בשילהי כל הזבחים ואמר נמי בפ' בית שמאי (לעיל זבחים לט.) לפר זה פר יום הכיפורים:"],[12,"לומר לך כיון שיצאו חוץ לעזרה","המתעסקין בהן מטמאין בגדים:"],[15,"מחוץ למחנה בדשן","בהוצאת דשן המזבח והוציא את הדשן אל מחוץ למחנה (שם ו):"],[16,"ור' שמעון","דאמר במתני' אין מטמאין בגדים עד שיוצת האור ברובו האי מחוץ למחנה דכתיב בפר ושעיר של יום הכיפורים מאי עביד ליה:"],[16,"נאמר כאן","בפר יום הכיפורים:"],[16,"ונאמר להלן","בפרה אדומה (במדבר י״ט:ג׳) והוציא אותה אל מחוץ:"],[16,"מה כאן","בפרים הנשרפים חוץ לג' מחנות אף שחיטת פרה אדומה חוץ לג' מחנות:"],[16,"מה להלן","בפרה אדומה במזרחו של ירושלים דכתיב בה והזה אל נוכח פני אהל מועד אלמא עומד במזרח ופניו למערב כנגד פתחו של היכל שהוא בכותל מזרחי ופתחו למזרח אף כאן כו':"]],[[1,"ומטמא טומאת אוכלין בכביצה","פי' בקונטרס מדקתני צריכה מחשבה ואין צריכה הכשר אלמא בדנקיט ליה בידיה עסקינן דאי מחתא אארעא אמאי אינה צריכה הכשר ואי דנקיט ליה בפומיה אמאי צריכה מחשבה אין לך מחשבה גדולה מזו וקתני כביצה אין כזית לא וקשה כיון דיש בו כביצה אע\"ג דמחית אארעא מטמא בלא הכשר משום דסופו לטמא טומאה חמורה ולא דמי למחוסר יציאה דבפנים אין ראוי כלל לטמא ומשום הכי לא מבעיא ליה לרבנן בכביצה דנקיט בידיה ונראה לפרש דהיינו טעמא דמשמע ליה דמיירי בנקיט בידיה משום דאז איכא חידוש לאשמועינן דבעי כביצה ולא חשיב כנקיט בפומיה אבל במחית אארעא פשיטא דבעי כביצה (ופי' הקונטרס יש לישב כמו שפירשתי לעיל בהגהה וכן עיקר):"],[3,"ומדסיפא ר\"מ רישא נמי ר\"מ","הוה מצי למימר וליטעמיך הא קתני מציעתא האוכל אבר מן החי ממנה סופג את הארבעים והיינו דלא כרבי מאיר דקסבר אינו נוהג אלא בטהורה בפרק גיד הנשה (חולין דף קב:) (כדפרישית לעיל):"],[9,"חיבורי אוכלין ע\"י משקין","פי' בקונט' חצי זית נבלה מכאן וחצי זית נבלה מכאן ומשקה טופח באמצע ונוגע בשניהן מחברן לטמא אוכלין ומשקין הנוגעין באחד מן החצאין האלו ואין חיבור לטומאה חמורה לטמא אדם וכלים וטעמא לא ידענא וכענין זה פירש בהקומץ רבה (מנחות דף כד.) גבי צירוף כלי וחיבור מים מהו דפירש התם בקונטרס כלומר חצי עשרון שנטמא בצירוף כלי מהו שמטמא אחר בחיבור מים כגון אם יש שתי חצאי עשרון בכלי ואין נוגעין וחצי עשרון יש חוץ לכלי השני וחיבור מים כגון ניצוק או צינור מחבר את של חוץ לכלי ואת שבתוך הכלי ונגע טומאה לזה שבכלי שאין נוגע במים ונטמא חבירו משום צירוף כלי מהו שיטמא זה את של חוץ בחיבור מים ודבר תימה הוא לומר שמשקין מחברין אוכלין לקבל טומאה ולטמא אחרים דאפילו עור אין מצרפו כדאיתא בהעור והרוטב (חולין דף קיז:) ועוד שפירש שמחברין ע\"י ניצוק והלא אפי' למים עצמן קי\"ל דאין ניצוק חיבור לטומאה וקצת היה נראה לפרש דמיירי בשנימוחו ע\"י המים ונדבקו יחד ומיהו כעין פירוש הקונטרס יש משנה אחת במסכת טהרות (פ\"ח מ\"ח) עריבה שהיא קטפרס וניצוק מלמעלן ומשקה טופח מלמטן וג' חתיכות כביצה אינן מצטרפות וב' מצטרפות ור' יוסי אומר אף שתים אינן מצטרפות אלא א\"כ רוצצות משקה ואם היה משקה עומד אפי' כעין החרדל מצטרף ובתוספתא תניא אתרוג שנפרץ ותחבו בכוש או בקיסם אינו חיבור שאין חיבורי אדם חיבור עיסה שנילושה במי פירות טהורה שאין לך דבר שהוא מחבר את האוכלין אלא שבעה משקין ודבר תימה הוא אם אין לישת פירות מועלת לחבר את הקמח ושמא לשה לאו דוקא אלא אורחא דמילתא נקט [דבר שאדם] לש במי פירות פעמים שמי פירות מחברים שני חצאי זיתים של עיסה במשקים הבאים מזה לזה:"],[16,"מה כאן חוץ לשלש מחנות ביום הכיפורים אף להלן בפרה אדומה כן","תימה הא בפר יוה\"כ לא ידעי' שלש מחנות אלא מהיקשא דלפר זה פר יום הכיפורים בפרק ב\"ש (לעיל זבחים דף לט.) כדפירש בקונט' ומספקינן אי דבר הלמד בהיקש חוזר ומלמד בג\"ש או לא ואפי' תימצי לומר דאתא מריבוי דחטאת דבסוף התערובת (לעיל זבחים פג.) ההוא נמי היקשא הוא ושמא ג\"ש הוא ויש לפרש דפרה קדשי בדק הבית היא והשתא נמי אתי שפיר דיליף בג\"ש מזרחה של ירושלים אע\"ג דשריפת פרה ילפא מהזאתה לקמן בפרק בתרא (זבחים דף קיג.):"]]],[["אף כאן למזרחה של ירושלים","אלא לרבנן היכא שריף להו כדתניא היכן נשרפין לצפון ירושלים חוץ לשלש מחנות רבי יוסי הגלילי אומר אבית הדשן נשרפין","אמר רבא מאן תנא דפליג עליה דר' יוסי הגלילי ר' אליעזר בן יעקב היא דתניא (ויקרא ד, יב) על שפך הדשן ישרף שיהא שם דשן (שיקדים לשם דשן) ר' אליעזר בן יעקב אומר שיהא מקומו משופך","אמר ליה אביי דילמא במקומו משופך פליגי","תנו רבנן השורף מטמא בגדים ולא המצית את האור מטמא בגדים ולא המסדר את המערכה מטמא בגדים ואיזהו השורף המסייע בשעת שריפה","יכול אף משנעשו אפר מטמא בגדים תלמוד לומר אותם אותם מטמאין בגדים ומשנעשין אפר אין מטמאין בגדים רבי שמעון אומר אותם מטמאין בגדים ניתך הבשר אין מטמאין בגדים","מאי בינייהו אמר רבא איכא בינייהו דשוייה חרוכא:","\u0001הדרן עלך טבול יום\u0002","מתני׳ \u0001השוחט\u0002 והמעלה בחוץ חייב על השחיטה וחייב על העלאה","רבי יוסי הגלילי אומר שחט בפנים והעלה בחוץ שחט בחוץ והעלה בחוץ פטור שלא העלה אלא דבר פסול אמרו לו אף השוחט בפנים ומעלה בחוץ כיון שהוציאו פסלו","הטמא שאכל בין קדש טמא בין קדש טהור חייב רבי יוסי הגלילי אומר טמא שאכל טהור חייב וטמא שאכל טמא פטור שלא אכל אלא דבר טמא אמרו לו אף טמא שאכל את הטהור כיון שנגע בו טמאוהו","וטהור שאכל טמא פטור שאינו חייב אלא על טומאת הגוף:","\u0001גמ׳\u0002 בשלמא העלה כתיב עונש וכתיב אזהרה עונש דכתיב (ויקרא יז, ד) ואל פתח אהל מועד לא הביאו אזהרה דכתיב (דברים יב, יג) השמר לך פן תעלה עולותיך וכי הא דא\"ר אבין א\"ר אלעזר כל מקום שנאמר השמר פן ואל אינו אלא לא תעשה","אלא שחיטה בשלמא עונש דכתיב (ויקרא יז, ד) ואל פתח אהל מועד לא הביאו אלא אזהרה מנלן אמר קרא (ויקרא יז, ז) ולא יזבחו עוד","האי מיבעי ליה לכדר\"א דאמר מנין לזובח בהמה למרקוליס שהוא חייב דכתיב ולא יזבחו עוד את זבחיהם אם אינו ענין לכדרכה דכתיב (דברים יב, ל) איכה יעבדו תנהו ענין לשלא כדרכה","אמר רבה קרי ביה ולא יזבחו וקרי ביה ולא עוד","אכתי מיבעי ליה לכדתניא עד כאן הוא מדבר בקדשים שהקדישן בשעת איסור הבמות והקריבן בשעת איסור הבמות"],[[1,"ורבנן","דמפקי ליה לקרא לטומאת בגדים ולית להו ג\"ש:"],[1,"היכא שריף להו","לאיזו רוח של ירושלים:"],[1,"לצפונה של ירושלים","שכל מעשה חטאת בצפון:"],[1,"אבית הדשן","צריך שיקדים לשם דשן מזבח שיהא נקרא קודם לכן מקום שפך הדשן מכלל דלת\"ק לא צריך:"],[2,"רבי אליעזר בן יעקב היא","דאמר לא אשמועינן על שפך אלא שיהא מקומו מדרון שיהא דשנו משתפך:"],[2,"ודילמא במקומו משופך הוא דפליגי","ומודה רבי אליעזר בן יעקב שיקדים שם דשן אלא דבעי נמי מקומו משופך:"],[4,"השורף","המתעסק בצרכי שריפתן כגון המסייע בשעת שריפה והאי תנא אית ליה כרבי שמעון דאין מטמאין בגדים עד שיוצת בהן האור:"],[6,"דשוייה חרוכא","דהוי ניתך הבשר ואפר מיהא לא הוה לתנא קמא מטמאין עד שיעשו אפר דאותם קרינא בהו אבל אפר לא מיקרי ולרבי אלעזר ברבי שמעון אין מטמאין בגדים:"],[8,"מתני' השוחט קדשים בחוץ והעלה","בחוץ. בהעלם אחד:"],[8,"חייב על השחיטה וחייב על העלייה","שהן שני גופי עבירה דתרוייהו כתיבי אשר ישחט ואשר יעלה (ויקרא יז):"],[9,"שלא העלה אלא דבר פסול","ואנן מתקבל בפנים בעינן דכתיב ואל פתח אהל מועד לא יביאנו (שם):"],[9,"כיון שהוציאו פסלו","ואפ\"ה חייב וה\"ה לשוחט בחוץ ומעלה בחוץ:"],[10,"הטמא שאכל כו'","משום דפליגי ר' יוסי הגלילי ורבנן בתרוייהו ודמו הנך פלוגתא להדדי תנינהו גבי הדדי:"],[10,"כיון שנגע בו טמאוהו","ואפ\"ה הדר אכיל ליה מחייב ומה לי נטמא בשר על ידו מה לי נטמא ע\"י אחרים:"],[11,"שאינו חייב אלא על טומאת הגוף","כדכתיב וטומאתו עליו ונכרתה ודרשינן בפ' בית שמאי (לעיל זבחים דף מג.) בטומאת הגוף הכתוב מדבר מי שטומאה פורחת ממנו:"],[12,"","גמ' שחיטה והעלאה ב' פרשיות סמוכות זו לזו באחרי מות:"],[13,"אלא אזהרה מנלן","דקא מחייבינן ליה עליה חטאת שאין חטאת באה אלא על לאו וכרת כדתנן הפסח והמילה מצות עשה ואין חייבין עליהן חטאת במסכת כריתות (דף ב.):"],[14,"למרקוליס","אע\"פ שעבודתו דרך בזיון לסקלו באבנים וזה עובדו דרך כבוד ולא קרינא ביה איכה יעבדו ואעשה כן ואפ\"ה מניין שהוא חייב:"],[15,"קרי ביה ולא יזבחו וקרי ביה ולא עוד","דאי לכדרבי אלעזר לכתוב ולא עוד את זבחיהם לשעירים והאי דכתיב ולא יזבחו לאזהרת שחוטי חוץ אתא דסמיך לההיא פרשתא:"],[16,"ע\"כ","עד המקרא הזה דלא יזבחו כל הענין העליון שנענש כרת על שחיטת חוץ ועל העלאת חוץ:"],[16,"מדבר בקדשים שהקדישן בשעת איסור הבמות","משהוקם המשכן דאילו הנך דהוקדשו מעיקרא אי לא מרבי להו קרא בהדיא מסתמא לא שמעינן להו:"]],[[10,"כיון שנגע בו טימאהו","אע\"ג דמשכחת לה כשתחב לו חבירו בבית הבליעה סתמא דמילתא מיירי קרא אפילו בנותן לתוך פיו:"],[13,"אזהרה מנלן","פי' בקונטרס דקא מחייבי ליה עלה [חטאת] שאין חטאת באה אלא על לאו וכרת כדתנן הפסח והמילה מצות עשה ואין חייבין עליהן חטאת במסכת כריתות (דף ב.) וקשה לפי' דבריש אלו הן הלוקין (מכות דף יג:) משמע דקרבן לא בעי אזהרה דפריך התם ודילמא אזהרה לקרבן הוא דהא פסח ומילה דלית בהו אזהרה לא מייתי קרבן ומשני התם היינו טעמא משום דאיתקוש כל התורה כולה לעבודת כוכבים מה עבודת כוכבים שב ואל תעשה לאפוקי הני דקום עשה נינהו ונראה לפרש דהאי דבעי הכא אזהרה מנא לן היינו משום דחשיב ליה בפרק אלו הן הלוקין (שם.) השוחט והמעלה בחוץ ולאו אמתני' קאי והאי דקתני בכריתות (דף ב.) הפסח והמילה מצות עשה היינו כלומר דקום עשה נינהו ולהכי לית בהו חטאת ומיהו לקמן בשמעתין משמע דלאפוקי לאו קאתיא דפריך רבא הא דתנן פסח ומילה מצות עשה תיתי בק\"ו ממותיר ומה מותיר שלא ענש הזהיר כו' וכן פ' המוצא תפילין (עירובין דף צו.) יצא פסח [ומילה] שהן מצות עשה [ופריך] הא כתיב ושמרת את החוקה וא\"ר אילעאי כל מקום שנאמר השמר פן ואל הוי לא תעשה אלמא הוי פירושא יצא פסח [ומילה] שיש בעשה היינו שאין בהן לאו ואזהרה ואין לומר דסוגיא דידן כרבינא דמשני שינויא אחרינא בפרק אלו הן הלוקין (מכות דף יג:) ומצי למימר אליביה דקרבן קבעי אזהרה דמ\"מ קשיא דרבא אדרבא דהיינו רבא בשמעתין וההיא מסקנא דמכות דקרבן לא בעי אזהרה אליבא דרבא ולפירוש הקונטרס נמי קשה קצת דאמאי תלי טעמא דפסח ומילה משום דלית בהו לאו תיפוק ליה משום דלית בהו מעשה דאפילו לר\"ע דאמר לא בעי מעשה הא אמר ריש לקיש בריש כריתות (דף ג:) נהי דלא בעי ר\"ע מעשה רבה מעשה זוטא בעי מיהו איכא לאוקמה שמעתין כרבי יוחנן דאמר ר\"ע לא בעי מעשה כלל ונראה לפרש דלישנא דמתני' קא דייק דקתני פסח ומילה מצות עשה היינו שהם בקום עשה ומשמע נמי הלשון דלית בהו אזהרה כלל:"],[14,"מניין לזובח בהמה למרקוליס שהוא חייב","פי' בקונטרס אע\"פ שעבודתו דרך בזיון לסקלו באבנים וזה עובדו דרך כבוד ולא קרינא ביה איכה יעבדו הגוים האלה את אלהיהם ואעשה כן אפ\"ה מניין שחייב ונראה דכל הנהו דלאו אורחייהו בזביחה אע\"ג דמכובדים נינהו לא נפקא מאיכה יעבדו כדמוכח בפרק ארבע מיתות (סנהדרין דף סג.) דאמר אביי שלש השתחואות בעבודת כוכבים [למה] אחת לכדרכה ואחת לשלא כדרכה ואחת לחלק ופריך כדרכה מאיכה יעבדו נפקא אלא אחת לשלא כדרכה ואפילו לשלא כדרכה כלל שעובדין אותה בבזיון כגון פעור ומרקוליס ואחת כדרכה ושלא כדרכה פי' כדרכה בעבודת כבוד אלא שאין דרכה בהשתחואה ואם תאמר מנלן הכא זובח בהמה למרקוליס אימא כי אתא קרא למכובדים שאין דרכן בזביחה אבל למבוזין כגון פעור ומרקוליס לא וי\"ל דגלי ליה בהשתחואה דמכובדים ומבוזין שוין הוא הדין בזביחה ור\"ת מפרש דתרי קראי בזביחה כתיבי האי קרא דהכא ולא יזבחו ועוד כתיב זובח לאלהים יחרם דדרשינן בפ' ארבע מיתות (סנהדרין דף סא.) דיצתה זביחה ללמד על הכלל לחייב בכל עבודת פנים אפילו בשלא כדרכה וקשה לפי' דמהאי קרא לא שמעינן אלא אזהרה אבל עונש במבוזין מנא לן ועוד תרוייהו למכובדין צריכי חד לעונש וחד לאזהרה ועוד דלא ה\"ל לאיתויי איכה יעבדו אלא הוה ליה למימר אם אינו ענין לכדרכה של מכובדין דכתיב זובח לאלהים יחרם תנהו ענין לשלא כדרכה כלומר מבוזין אלא כמו שפירשנו נראה דרבי אלעזר אכל שלא כדרכה אתא לאשמועי' דחייב אלא דנקט מרקוליס לרבותא ומהשתחואה נפקא לן דאין חילוק בין מכובדין למבוזין כדפרי' תדע דהא אמר בפרק ד' מיתות (סנהדרין דף סד:) ג' כריתות בעבודת כוכבים למה אחת לכדרכה ואחת לשלא כדרכה ואחת למולך ולא מיבעיא לן קרא אחרינא חד למכובדין וחד למבוזין וק\"ק הא דפריך בפ' ד' מיתות אימא יצתה השתחואה ללמד על הכלל כולו ודקאמרת זובח למה לי לגופיה דמחשבין מעבודה לעבודה ומתמה עליה הש\"ס אלא הא דקאמר רבי אלעזר מניין לזובח בהמה למרקוליס כו' מהשתחואה נפקא מאי קושיא דילמא איצטריך לאזהרה במחשב מעבודה לעבודה דהא לעולם הוא כך דלא יזבחו אזהרה לעונש דזובח לאלהים יחרם וי\"ל דאם איתא דהשתחואה ללמד על הכלל א\"כ לא תעבדם דאוקמינן (סנהדרין דף ס:) למגפף ומנשק הוה מייתר לן לאזהרה אזביחה דמהשתחואה הוה ילפינן אפילו חיוב מיתה במגפף ומנשק:"]]],[["שהרי עונשן אמור (ויקרא יז, ד) ואל פתח אהל מועד אזהרה דכתיב (דברים יב, יג) השמר לך פן תעלה עולותיך","מכאן ואילך בזבחים שהקדישן בשעת היתר הבמות והקריבן בשעת איסור הבמות","שנא' (ויקרא יז, ה) למען אשר יביאו בני ישראל את זבחיהם אשר הם זובחים זבחים שהתרתי לך כבר על פני השדה לומר לך הזובח בשעת איסור הבמות מעלה עליו הכתוב כאילו הקריב על פני השדה","(ויקרא יז, ה) והביאום לה' זו מצות עשה לא תעשה מניין ת\"ל (ויקרא יז, ז) ולא יזבחו עוד","יכול יהא ענוש כרת ת\"ל (ויקרא יז, ז) חוקת עולם תהיה זאת להם לדורותם זאת להם ולא אחרת להם","אלא אמר (ר' אבין) ק\"ו ומה במקום שלא ענש הזהיר מקום שענש אינו דין שהזהיר","א\"ל רבינא לרב אשי א\"כ לא יאמר לאו בחלב ותיתי ק\"ו מנבילה מה נבילה שלא ענש הזהיר חלב. שענש אינו דין שהזהיר","אתא לקמיה דרבא א\"ל מנבלה נמי לא אתיא דאיכא למיפרך מה לנבלה שכן מטמא","משרצים טמאין מה לשרצים טמאין שמטמאין במשהו","משרצים טהורים מה לשרצים טהורים שאיסורן במשהו","מערלה וכלאי הכרם מה לערלה וכלאי הכרם שכן אסורין בהנאה","משביעית מה לשביעית שכן תופסת דמיה","מתרומה שכן לא הותר מכללה מכולהו נמי שכן לא הותרו מכללן","אמר רבא אי קשיא לי הא קשיא לי הא דתנן פסח ומילה מצות עשה","תיתי בק\"ו ממותיר מה מותיר שלא ענש הזהיר פסח ומילה שענש אינו דין שהזהיר","אמר רב אשי אמריתה לשמעתא קמיה דרב כהנא ואמר לי ממותיר לא אתיא דאיכא למיפרך מה למותיר שכן אין לו תקנה תאמר פסח יש לו תקנה","וכי מזהירין מן הדין אפילו למ\"ד עונשין מן הדין אין מזהירין מן הדין","אלא כדרבי יוחנן דאמר אתיא הבאה הבאה","מה להלן לא ענש אא\"כ הזהיר אף כאן לא ענש אא\"כ הזהיר"],[[0,"שהרי עונשן אמור","כלומר דמסתמא בהו משתעי קרא לאסור והרי עונשן אמור כאן:"],[1,"מכאן ואילך כו'","שנאמר למען אשר יביאו וגו' דמדכתיב אשר הם זובחים משמע שהיו עומדים לישחט בבמה ומכאן ואילך והביאום לה':"],[2,"כזובח בשדה","שלא לשם שמים:"],[3,"(מצות) לא תעשה","בהנך דהוקדשו בשעת היתר מניין:"],[3,"ת\"ל ולא יזבחו עוד","משמע מעכשיו אסורין ועד עכשיו מותרין:"],[4,"זאת להם","עונש עשה ולא תעשה:"],[4,"ולא אחרת להם","כרת:"],[5,"מקום שלא ענש","כגון בקדשים שהקדישן בשעת היתר:"],[5,"הזהיר","כדאמרן כאן:"],[5,"שענש","כשהוקדשו בשעת איסור:"],[5,"אינו דין שהזהיר","ולקמן פריך וכי מזהירין מן הדין:"],[8,"משרצים","וא\"ת תיתי אזהרה בחלב בק\"ו משרצים טמאין כגון שמונה שרצים:"],[8,"במשהו","טומאתן בכעדשה אבל חלב בכזית:"],[9,"משרצים טהורים","שאין מטמאין כגון צפרדע ונמלה:"],[10,"שכן אסורין במשהו","לאכילה בכעדשה כדתניא במעילה בגמרא בפרק קדשי מזבח (מעילה דף טז:) ולא תשקצו את נפשותיכם בבהמה ובעוף וגו' פתח הכתוב באכילה וסיים בטומאה לומר לך כשיעור טומאתן של שרצים טמאים שיעור אכילתן של כל השרצים דהא כולהו כייל להו בהאי קרא ובכל אשר תרמוש האדמה וגו' ושיעור טומאתן נפקא לן בהכל חייבים (חגיגה דף יא:) שכן חומט תחילת ברייתו בכעדשה:"],[11,"שכן תופסת את דמיה","באיסורא כדתניא במסכת סוכה (דף מ:) קדש תהיה לכם מה קדש תופס את דמיו אף שביעית תופסת את דמיה:"],[12,"מכללו","חלב הותר מכללו בחיה ובכולהו נמי איכא למיפרך הא פירכא ומש\"ה איצטריך אזהרה בחלב:"],[13,"אי קשיא","בהאי דאייתינא אזהרה לשחוטי חוץ בהאי ק\"ו הא קשיא לי הא דתנן בפרק קמא דכריתות (דף ב) דקחשיב ל\"ו כריתות להתחייב עליהם חטאת וקתני והפסח והמילה כרת שלהם על מצות עשה היא באה ואין חייבין חטאת על שגגתה דחטאת אינה באה אלא על לאו וכרת כדכתיב אשר לא תעשינה (ויקרא ד):"],[14,"תיתי","בו אזהרה מק\"ו ממותיר ממנו עד בוקר:"],[15,"שיש לו תקנה","בתשלומי פסח שני:"],[16,"וכי מזהירין מן הדין","לעיל קאי דמייתי אזהרה לשחוטי חוץ מק\"ו:"],[16,"אפילו למ\"ד","במסכת מכות עונשין מדין ק\"ו מודה דאין מזהירין מן הדין דתניא בפ\"ק דמכות (דף ה:) איש כי יקח את אחותו וגו' אין לי אלא בת אביו שלא בת אמו בת אמו שלא בת אביו בת אביו ובת אמו מנין תלמוד לומר ערות אחותו גילה והלא קל וחומר הוא למדתה שאין עונשין מן הדין וכן לענין אזהרת ערות אחותך בת אביך וגו' אין לי כו' עד שאין מזהירין מן הדין ופליגי תנאי בפ' בתרא ואיכא דדריש להאי אחותו גילה דגבי עונש לדרשא ועונש דבת אביו ובת אמו קסבר עונשין מן הדין ואילו אחותך היא דגבי אזהרה דילפינן מיניה אין מזהירין מן הדין דלא אפנייה לדרשא אחריתי:"],[17,"אתיא הבאה הבאה","שחיטה מהעלאה כתיב בשחיטה (ויקרא יז) לא הביאו וכתיב בהעלאה (שם) לא יביאנו וגזירה שוה הואיל ומופנה היא לכך הרי היא כמי שמפרש בה ואין זה מן הדין כק\"ו שאדם דן מעצמו:"]],[[0,"אזהרה מניין ת\"ל השמר לך פן תעלה עולותיך","הא דמייתי אזביחה אזהרה דהעלאה אמסקנא סמיך דילפי הבאה הבאה או שם שם אבל לאביי דבסמוך קשה דק\"ו הו\"ל לאתויי:"],[5,"מקום שענש אינו דין שהזהיר","ולא שייך למימר פסח ומילה יוכיחו דאיכא למיפרך שכן קום עשה:"],[9,"מה לשרצים טהורים שכן אסורין במשהו","פי' בקונטרס דתניא במסכת מעילה בפרק קדשי מזבח (מעילה דף טז:) ולא תשקצו את נפשותיכם בבהמה ובעוף וגו' פתח הכתוב באכילה וסיים בטומאה לומר כשיעור טומאתן של שרצים טמאים שיעור אכילתן של כל השרצים דהא כולהו כייל להו בהאי קרא ובכל אשר תרמוש וגו' ושיעור טומאתן נפקא לן בהכל חייבין (חגיגה דף יא:) שכן חומט תחילת ברייתו בכעדשה עד כאן לשון הקונטרס ואגב חורפיה לא עיין בה ובהדיא מסיק התם דוקא בשרצים טמאים ולא בטהורים דאמרינן במובדלין דיבר הכתוב דכתיב בסיפיה דקרא אשר הבדלתי לכם לטמא וצ\"ל דכל שהוא דהכא בבריה קמיירי דבכל שהוא מיחייב משום בריה כדאמרינן בפ\"ק דחגיגה (דף י.) ובפ' כהן גדול ונזיר (נזיר דף נב.) ובמכות (דף יז.) ובפ' גיד הנשה (חולין דף צו:):"],[12,"מכולהו שכן לא הותר מכללן","תימה נילף בכולהו כרת בק\"ו מחלב שהותר מכללו:"],[14,"תיתי בק\"ו ממותיר","הא דנקט מותיר טפי מגזל וגניבה וכמה לאוין שבתורה משום דמותיר לא עביד מעשה דומיא דפסח ומילה ומש\"ה לא נקט נמי הנך דלעיל דאיכא למיפרך שכן יש בהן מעשה:"]]],[["רבא אמר כדרבי יונה דאמר רבי יונה אתיא שם שם מה להלן לא ענש אלא א\"כ הזהיר אף כאן לא ענש אלא אם כן הזהיר","אשכחן מוקטרי פנים שהעלן לחוץ מוקטרי חוץ שהעלן לחוץ מנין","אמר רב כהנא אמר קרא ואליהם תאמר על הסמוכין תאמר","מתקיף לה רבא מי כתיב ועליהם ואליהם כתיב אלא כדתנא דבי ר' ישמעאל ואליהם תאמר לערב פרשיות","ר' יוחנן אמר אתיא הבאה הבאה מה להלן מוקטרי חוץ אף כאן מוקטרי חוץ","מתקיף לה רב ביבי הא דתנן שלשים ושש כריתות בתורה תלתין ושב הויין דאיכא המעלה והמעלה קשיא","והדתנן הזורק מקצת דמים בחוץ חייב מנלן נפקא ליה מדתניא (ויקרא יז, ד) דם יחשב לרבות הזורק דברי רבי ישמעאל ר\"ע אומר (ויקרא יז, ח) או זבח לרבות את הזורק","ורבי ישמעאל האי או זבח מאי עביד ליה לחלק","ור' עקיבא לחלק מנא ליה נפקא ליה (ויקרא יז, ט) מלא יביאנו","ורבי ישמעאל ההוא מיבעי ליה על השלם הוא חייב ואינו חייב על החסר ורבי עקיבא נפקא ליה (ויקרא יז, ט) מלעשות אותו","ור' ישמעאל חד למוקטרי פנים שחסרו והעלו בחוץ וחד למוקטרי חוץ שחסרו והעלו בחוץ והא תניא רבי ישמעאל אומר יכול מוקטרי פנים שחסרו והעלו בחוץ חייב ת\"ל לעשות אותו על השלם חייב ואינו חייב על החסר","ורבי עקיבא מוקטרי פנים שחסרו והעלו בחוץ חייב","ורבי עקיבא האי דם יחשב מאי עביד ליה לרבות שחיטת העוף ורבי ישמעאל נפקא ליה (ויקרא יז, ג) מאו אשר ישחט","ורבי עקיבא אמר לך ההוא מיבעי ליה על השוחט הוא חייב ולא על המולק ור' ישמעאל נפקא ליה מזה הדבר","דתניא אשר ישחט אין לי אלא שוחט בהמה שחט עוף מנ\"ל ת\"ל או אשר ישחט","יכול אף המולק ודין הוא מה שחיטה דאין דרך הכשירה בפנים חייב מליקה שדרך הכשירה בפנים אינו דין שהוא חייב ת\"ל (ויקרא יז, ב) זה הדבר","ורבי עקיבא אמר לך ההוא מיבעי ליה לגזירה שוה","והא דתנן הקומץ והמקבל דמים בחוץ פטור מנלן ומהיכא תיתי דחייב","תיתי משחיטה מה לשחיטה שכן נפסלת שלא לאוכלין בפסח","תיתי מזריקה מה לזריקה שכן זר חייב עליה מיתה"],[[0,"ה\"ג דאמר רבי יונה אמר קרא שם תעלה עולותיך ושם תעשה","איתקש שאר עשיות להעלאה מה העלאה לא ענש אלא אם כן הזהיר אף שחיטה לא ענש אלא א\"כ הזהיר:"],[1,"אשכחן מוקטרי בפנים שהעלן בחוץ","שחוטי פנים שהיו עומדים להקטירן בפנים והעלו בחוץ חייב כדכתיב בהעלאה (ויקרא י״ז:ד׳) ואל פתח אהל מועד לא יביאנו בראויין להביאן לפנים ולהעלותן הכתוב מדבר:"],[1,"מוקטרי חוץ","שחוטי חוץ שעומדין ליקטר בחוץ ולא בפנים:"],[2,"ואליהם תאמר","זהו תחילת פרשת העלאה וסמוכה לפרשת שחוטי חוץ על הראשונים דמשתעי בשחוטי חוץ שאמר שאם העלו בחוץ חייב ועליהם קרינן:"],[3,"ואליהם כתיב","לשון קושיא הוא:"],[3,"ה\"ג אלא כדתנא דבי ר' ישמעאל ואליהם תאמר לערב פרשיות","וי\"ו מוסיף על ענין ראשון ומערב הפרשיות לומר שאף שחוטי חוץ שהעלן בחוץ חייב:"],[5,"ל\"ו כריתות בתורה","וקחשיב התם המעלה בחוץ והוינן בה מניינא למה לי ואמר רבי יוחנן שאם עשאן כולן בהעלם אחד חייב על כל אחת ואחת הא תרתי נינהו לחיובא המעלה איברי פנים והמעלה איברי חוץ דכיון דגמרת להו בהיקשא או בגזירה שוה הוה ליה כל חד וחד גוף עבירה וחייב על כל אחת ואחת אפילו בהעלם אחד וניתני שלשים ושבע והא ליכא לשנויי שם העלאה קתני כי היכי דקא חשיב המחלל את השבת והעובד עבודת כוכבים בחדא ואע\"ג דטובא חיובי איכא דהכי שנינו בכריתות ואקשינן עלה שבת ועבודת כוכבים [ומשני] תנא חילוקין שלהן במקומן דתנן במסכת שבת (דף עג.) אבות מלאכות ארבעים חסר אחת ודעבודת כוכבים תנינא בסנהדרין (דף ס:) אחד העובד ואחד הזובח ואחד המקטר ואחד המנסך אבל הכא לא תנא בהדיא המעלה איברי פנים והמעלה איברי חוץ ואף על גב דאיכא למשמע מפלוגתא דרבי יוסי הגלילי ורבנן בהדיא מיהא לא תנינהי בתרתי:"],[6,"והא דתנן","לקמן במתניתין (דף קי.) הזורק [מקצת] דמים בחוץ שלא נתן ארבע מתנות אלא מתנה אחת חייב דהויא זריקה בפנים דכוותיה דתנן (לעיל זבחים דף לו:) כל הניתנין על מזבח החיצון שנתנן במתנה אחת כיפר:"],[6,"מנלן","דאיחייב אזריקת דם בחוץ הא שחיטה והעלאה הוא דכתיבן:"],[6,"דם יחשב דם שפך","לרבות את הזורק והאי קראי בשחוטי חוץ כתיבי:"],[6,"או זבח","כתיב גבי העלאה או לרבות את הזורק:"],[7,"לחלק","דלא תימא עד דמסיק עולה ושלמים:"],[8,"לא יביאנו","משמע חד:"],[9,"ואינו חייב על החסר","לקמן פליגי בה איכא למאן דאמר על אבר חסר ואיכא למאן דאמר על בהמה חסירה עד שיעלה כל הבהמה ואיכא למאן דאמר על הקטרה חסירה כגון פחות מכזית:"],[9,"אותו","שלם משמע:"],[10,"חד למוקטרי פנים כו'","דאי כתב חד הוה אמינא הני מילי מוקטרי חוץ אבל מוקטרי פנים מיחייב דהא מהדרינן פוקעין דחסרו אלמא הקטרה היא:"],[10,"והא תניא","בניחותא:"],[11,"ור\"ע סבר מוקטרי פנים","שחוטי פנים שחסרו כגון פקעו מעל האור והעלן בחוץ חייב דהא מהדרינן פוקעין:"],[12,"ור' ישמעאל נפקא ליה מאו אשר ישחט","אע\"ג דאיצטריך מחוץ למחנה כדלקמן אפילו הכי אשר ישחט יתירא הוא דמצי למיכתב אל מחוץ למחנה אייתר ליה אשר ישחט לרבות שחיטת העוף:"],[13,"ההוא מיבעיא ליה השוחט העוף חייב ואינו חייב על המולק","והילכך איצטריכו תרוייהו דאי כתיב אשר ישחט לרבות שחיטת העוף הוה אמינא כל שכן מליקה שהיא דרך הכשירו בפנים להכי כתיב דם שפך לרבות את העוף והדר כתיב אשר ישחט למעוטי מולק:"],[14,"אין לי אלא שוחט בהמה","כדכתיב אשר ישחט שור או כשב:"],[15,"ומה שחיטה","שאין זה דרך הכשירו של עוף בפנים חייב עליה בחוץ מליקה לא כ\"ש:"],[15,"ת\"ל זה הדבר","אשר צוה וגו' וסמיך ליה אשר ישחט שחיטה ולא מליקה:"],[16,"לגזירה שוה","מפורשת ביש נוחלין (ב\"ב דף קכ:) ובנדרים בפרק בתרא (דף עח.):"],[17,"הקומץ מנחה בחוץ","ולא הקטיר פטור:"],[17,"מנא ליה","דפטור:"],[17,"ופרכינן מהי תיתי לחיובא","דאיצטריך קרא למיפטריה:"],[18,"מה לשחיטה שכן פוסלת בפסח ששחטו שלא לאוכלין","כגון לחולה וזקן שאין יכול לאכול כזית כדכתיב (שמות י״ב:ד׳) איש לפי אכלו תכוסו תאמר בקומץ מנחה דלא שייך פסול שלא לאוכליו ובקבלה נמי אפילו בפסח לא מיפסלא כדאמרן בפרק תמיד נשחט (פסחים דף סא.) רבי אומר לשון סורסי הוא זה כאדם שאומר כוס לי טלה זה דבשחיטה לחודה הוא דפסלה מחשבת אוכלין:"],[19,"תיתי מזריקה","דלא פסלה שלא לשם אוכלין בפסח ומחייב עלה בחוץ וה\"ה לקמיצה וקבלה:"],[19,"שכן זר חייב עליה מיתה","מה שאין כן בקמיצה וקבלה דבעינן עבודה תמה ולא עבודה שיש אחריה עבודה כדאמרינן פרק בראשונה בסדר יומא (דף כד.) והני תרוייהו יש אחריהן עבודה:"]],[[0,"ה\"ג דאמר רבי יונה","בפ\"ק דכריתות (דף ג:) מהיקשא יליף:"],[5,"הני תלתין ושב הויין דאיכא המעלה והמעלה","דכיון דגמרת להו בהיקשא או בגזירה שוה הוה ליה כל חד וחד גוף עבירה וחייב על כל אחת ואחת אפי' בהעלאה אחת והשוחט ומעלה נמי דקתני התם בתרתי לא ידעינן בהו תרתי לאוי אלא בגזירה שוה פי' בקונטרס והא ליכא לשנויי שם העלאה קתני כי היכי דקא חשיב המחלל את השבת בחדא ואע\"ג דטובא חיובי איכא דהכי שנינן לה בכריתות (דף ג:) דאקשינן עליה שבת ועבודת כוכבים תנא חלוקים שלהן במקומן דתנן במס' שבת (דף עג:) אבות מלאכות מ' חסר אחת ודעבודת כוכבים תנינן בסנהדרין (דף ס:) אחד העובד ואחד הזובח ואחד המקטר ואחד המנסך אבל הני לא תנא הכא בהדיא המעלה איברי פנים והמעלה איברי חוץ ואע\"ג דאיכא למשמעה מפלוגתא דרבי יוסי הגלילי ורבנן בהדיא מיהא לא תננהי בתרתי עכ\"ל וקצת תימה גבי עבודת כוכבים היכי קאמר התם בפ' קמא דכריתות (דף ג:) דקתני יתהון אבינכיהון פירוש במקומן הא ליכא למשמע ממתני' דד' מיתות אלא חיוב חטאת אהנך עבודות אבל חילוק חטאות לא שמעינן מינה:"],[5,"דאיכא המעלה והמעלה קשיא","קשה מהא דלא משני ההיא דכריתות (ג\"ז שם) כרבי יוסי הגלילי דפטר מוקטרי חוץ:"],[7,"מאי עביד ליה לחלק","תימה דהך סוגיא דלא כרבא אלא כאביי דפ' השואל (ב\"מ דף צה:) דסבר לה כרבי יאשיה דפ' ד' מיתות (סנהדרין דף סו:) דבעי קרא לחלק גבי אביו ואמו:"],[10,"חד למוקטרי פנים שחסרו וחד למוקטרי חוץ שחסרו","הכא לא שייך למילף מואליהם תאמר או הבאה הבאה משום דבפנים טעמא דמהדרינן פוקעין וחשיבה הקטרה ולא שייך למילף למוקטרי חוץ:"]]],[["תיתי מבינייא","א\"כ לא יאמר בזריקה ותיתי מבינייא","ותיתי משחיטה מה לשחיטה שכן נפסלת שלא לשם אוכלין בפסח תיתי מהעלאה מה להעלאה שכן ישנה במנחה ותיתי מבינייא","להכי כתיב קרא למימר דלא אתא מבינייא","אמר ר' אבהו שחט וזרק לדברי ר' ישמעאל חייב אחת לדברי ר\"ע חייב שתים","אביי אמר אפי' [לדברי] ר\"ע אינו חייב אלא אחת דאמר קרא שם תעשה הכתוב עשאן לכולן עבודה אחת","זרק והעלה לדברי ר' ישמעאל חייב שתים לדברי ר\"ע אינו חייב אלא אחת","אביי אמר אפי' [לדברי] ר\"ע חייב שתים להכי פלגינהו קרא (דברים יב, יד) שם תעלה ושם תעשה","שחט וזרק והעלה לדברי הכל חייב שתים","ת\"ר (במחנה יכול השוחט עולה בדרום יהא חייב ת\"ל אל) מחוץ למחנה","יכול חוץ לשלש מחנות [ת\"ל (ויקרא יז, ג) או עז במחנה] (מנין אף במחנה לוייה ת\"ל במחנה)","אי במחנה יכול השוחט עולה בדרום יהא חייב ת\"ל או אל מחוץ למחנה","מה חוץ למחנה מיוחד שאין ראוי לשחיטת קדשים ולשחיטת כל זבח יצא דרום שאע\"פ שאין ראוי לשחיטת קדשי קדשים ראוי לשחיטת קדשים קלים","אמר עולא השוחט על גגו של היכל חייב הואיל ואין ראוי לשחיטת כל זבח מתקיף לה רבא א\"כ ניכתוב קרא (אל) מחוץ למחנה ולא בעי אל פתח אהל מועד אל פתח אהל מועד ל\"ל לאו למעוטי גגו","ולרבא א\"כ נכתוב אל פתח אהל מועד במחנה (ואל) מחוץ למחנה ל\"ל לאו לאתויי גגו","אמר רב מרי לאיתויי כולה בפנים וצוארה בחוץ","[צוארה] בחוץ פשיטא אמאי קפיד רחמנא אשחיטה ושחיטה בחוץ היא אלא לאיתויי כולה בחוץ וצוארה בפנים","איתמר המעלה בזמן הזה ר' יוחנן אמר חייב ריש לקיש אמר פטור","ר' יוחנן אמר חייב קדושה ראשונה קידשה לשעתה וקידשה לעתיד לבא ריש לקיש אמר פטור קדושה ראשונה קידשה לשעתה ולא קידשה לעתיד לבא","נימא דבפלוגתא דר\"א ור' יהושע קמיפלגי דתנן א\"ר אליעזר כשהיו בונין בהיכל היו עושים קלעים בהיכל קלעים בעזרות אלא שבהיכל בונין מבחוץ ובעזרה בונין מבפנים","א\"ר יהושע שמעתי שהיו מקריבין אע\"פ שאין בית ואוכלים קדשי קדשים אע\"פ שאין קלעים קדשים קלים ומעשר שני אע\"פ שאין חומה מפני שקדושה ראשונה קידשה לשעתה וקידשה לעתיד לבא","לאו מכלל דר\"א סבר לא קידשה","א\"ל רבינא לרב אשי ממאי דלמא דכולי עלמא קדושה ראשונה קידשה לשעתה וקידשה לעתיד לבא ומר מאי דשמיע ליה קאמר ומר מאי דשמיע ליה קאמר וכי תימא קלעים לר' אליעזר למה לי לצניעותא בעלמא","איתמר המעלה ואין בו כזית ועצם משלימו לכזית רבי יוחנן אמר חייב ריש לקיש אמר פטור","ר' יוחנן אמר חייב חיבורי עולין כעולין דמי ריש לקיש אמר פטור חיבורי עולין לאו כעולין דמו","בעי רבא המעלה"],[[0,"תיתי מבינייא","משחיטה וזריקה דכי פרכת מה לשחיטה שכן פוסלת שלא לשם אוכלין בפסח זריקה תוכיח מה לזריקה שכן זר חייב עליה מיתה שחיטה תוכיח וחזר הדין הצד השוה שבהן שהן עבודה וחייבין עליהן בחוץ אף אני אביא קמיצה וקבלה שהן עבודה ויתחייב עליהן בחוץ:"],[1,"אם כן","דמייתי מבינייא לחייב בחוץ על עבודות שאינם מפורשות בפרשה ויש להביאן במה הצד לא יאמר בזריקה ותיתי מבינייא משחיטה והעלאה:"],[3,"ה\"ג להכי כתבה קרא דלא אתיא מבינייא","למימר דאע\"ג דאתיא מבינייא לא תיתי מבינייא:"],[4,"שחט וזרק בהעלם אחד לר' ישמעאל","דנפקא ליה זריקה מדם שפך בעונש של שחיטה:"],[5,"אינו חייב אלא אחת","דחד כרת וחד לאו הוא:"],[5,"לר\"ע","נפקא ליה מאו זבח דכתיב (ויקרא יז) גבי העלאה:"],[6,"חייב שתים","משום דשמות מוחלקין:"],[7,"שם תעלה ושם תעשה","הזכיר העלאה לבדה והשאר כללן בעשיה אחת למימרא דלא מחייב אכולהו אלא חדא:"],[7,"פלגינהו קרא","הוציא העלאה מכלל שאר עשיות למימרא דמחייב עלה באפי נפשה ואשארא באפי נפשייהו:"],[8,"שחט וזרק והעלה לד\"ה","בין לר' ישמעאל בין לר\"ע חייב שתים לר' ישמעאל כיון דכולם בהעלם [אחד] מחייב בהעלאה חדא דאית לה קרא בהדיא ואשחיטה וזריקה חדא דמחד קרא נפקי ולר\"ע אשחיטה מיחייב חדא והעלאה וזריקה חדא ובהא לא פליג אביי אדר' אבהו דלאביי נמי לדברי הכל חייב שתים חדא אהעלאה וחדא אשאר עשיות:"],[9,"ת\"ר או אשר ישחט מחוץ למחנה יכול עד שישחט חוץ לשלש מתנות","ונילף גז\"ש מפרים הנשרפים כדילפינן בהרוגי ב\"ד בסנהדרין (דף מב:):"],[10,"ת\"ל","ברישיה דקרא או עז במחנה:"],[11,"אי במחנה יכול אף במחנה שכינה","אלא ששינה מקום שחיטתו כגון שחט עולה בדרום יהא חייב:"],[11,"ת\"ל מחוץ למחנה","דמשמע חוץ לשלש מחנות:"],[12,"מה להלן","מיוחד שאינו ראוי לשחיטת שום זבח אף במחנה כגון במחנה לויה שאינו ראוי לשחיטה לשום זבח:"],[13,"נכתוב קרא במחנה ואל מחוץ למחנה","חוץ למעוטי עולה בדרום ובמחנה לפרושי דלא בעינן חוץ לשלש מחנות ואל פתח אהל מועד לא הביאו למה לי:"],[13,"לאו למעוטי גגו של היכל","דהכי משמע שלא הביאו לפתח אהל מועד יצא זה שהביאו לעזרה:"],[14,"ופרכינן ולרבא","דפטר אגגו דמשמע כל חללה של עזרה קרי אל פתח:"],[14,"ניכתוב אל פתח","למעוטי גגו ולמעוטי עולה בדרום שהרי באו אל פתח וממילא משתמע חיובא במחנה לויה שלא הביאו אל פתח:"],[14,"מחוץ למחנה ובמחנה ל\"ל לאו לאיתויי גגו","אתא במחנה והדר אתא מחוץ דלא תימא מבמחנה איתרבי נמי שוחט עולה בדרום ת\"ל מחוץ למידרש דבעינן מקום שאינו ראוי לשחיטת שום זבח ואל פתח איצטריך לדרשא אחריתי הראוי לפתח אהל מועד חייבין עליו בחוץ יצאו פרת חטאת וקדשי בדק הבית:"],[14,"(לאו) לאיתויי [כולה] בפנים כו'","לעולם גג היכל לא מיחייב דלא קרינא ביה ואל פתח אהל מועד לא הביאו שהרי הביאו אלא לאיתויי היא בפנים וצוארה בחוץ דלא תימא פתח אהל מועד היא לכך נאמר במחנה לאיתויי לחיובא והדר אתא מחוץ דלא תרבי מבמחנה שוחט עולה בדרום ומהו אל פתח אהל מועד לא הביאו שלא הביאו כדרך הבאת קדשי קדשים בצפון תלמוד לומר מחוץ דלא חייב אלא משום חוץ דאינו ראוי לשום זבח יצא זה ואתא אל פתח למעוטי גגו דלא תרבייה כדקאמרת שהוא מקום שאינו ראוי לשחיטת כל זבח דכיון דאשמעינן מחוץ דעולה בדרום פטור שמע מינה אל פתח אהל מועד לא אכדרך הבאתו קפיד אלא אהבאה כל דהו ובלבד שיהא כולו לתוך חלל העזרה:"],[16,"שחיטה בחוץ היא","והרי לא הביאו לבית השחיטה אל פתח ומאל פתח נפקא:"],[17,"המעלה בזמן הזה","בחוץ:"],[18,"וקידשה לעתיד לבא","והויא לה ירושלים בית הבחירה ושעת איסור הבמות היא:"],[19,"כשהיו בונין בהיכל","בימי עזרא:"],[21,"לאו מכלל דר' אליעזר סבר לא קידשה","הלכך עושין קלעים במקום חומה וחזרו וקדשו בקידוש המפורש במסכת שבועות (דף יד.):"],[23,"עצם","אין מצוה להעלותו אם פירש כדאמרן בפרק המזבח מקדש (לעיל זבחים דף פה:):"]],[[3,"להכי כתביה קרא דלא תיתי מבינייא","תימה על סוגיא זו דבפ' בתרא (דף קטו:) דרשינן אשר יעלה עולה מה העלאה שהיא גמר עבודה אף כל שהיא גמר עבודה למעוטי קומץ ומקבל והיוצק והבולל והפותת והמולח כו':"],[10,"יכול חוץ לשלש מחנות","ונילף גז\"ש מפרים הנשרפים כדילפי' בהרוגי ב\"ד בפ' נגמר הדין (סנהדרין דף סב:) ואפי' אינה מופנה ילפינן בגילוי מלתא כיון דלא אשכחן מחוץ למחנה אלא חוץ לשלש מחנות:"],[13,"ולא בעי אל פתח אהל מועד","אע\"ג דאיצטריך לקמן (זבחים דף קיג:) למעוטי רובע ונרבע ופרת חטאת וקדשי בדק הבית טובא פתח אהל מועד כתיבי:"],[14,"ה\"ג ולרבא נכתוב רחמנא ואל פתח אהל מועד מחוץ למחנה ובמחנה למה לי","וקא קשיא ליה לרבא ל\"ל דכתב רחמנא כלל מחוץ למחנה ובמחנה וכן פי' הקונט':"],[17,"המעלה בזמן הזה","לעיל פירשתי בריש קדשי קדשים (זבחים דף ס.) גבי מזבח שנפגם ופירשתי מ\"ט [נקט] הכא המעלה ולא נקט השוחט:"],[17,"ריש לקיש אמר פטור קדושה ראשונה כו'","תימה דלא פריך עליה מהנך משניות דפריך בפ\"ק דמגילה (דף י.) אר' יצחק דאמר שמעתי שמקריבין בבית חוניו:"],[24,"רבי יוחנן אמר חייב חיבורי עולין כעולין דמו","וא\"ת למה לי חיבורי הא שמעינן ליה לר' יוחנן דאמר בפ' הקומץ רבה (מנחות דף כו:) יש הקטרה בפחות מכזית וכיון דחשיב הקטרה בפנים מחייב בחוץ כדאמר לקמן (זבחים דף קח:) גבי מוקטרי פנים שחסרו דחייבין עליהם בחוץ כיון דבפנים הויא הקטרה דמהדרינן פוקעין וי\"ל הא דחשיב ליה לר' יוחנן הקטרה היינו לענין מקטיר לחצאין שמשלים אח\"כ ואע\"ג דבפרק כל המנחות באות מצה (מנחות דף נח.) חשיב ליה הקטרה גבי שאור ודבש דאמרי' יש קומץ פחות משני זיתים ויש הקטרה פחות מכזית שאני התם דכתיב קרא ועוד דבשחוטי חוץ מיפטר טפי כדדרשינן הכא על השלם הוא חייב ואינו חייב על החסר ועוד דהא איתקש מחשבות זו לזו אכילת מזבח לאכילת אדם ומדחשב על מנת להקטיר חוץ למקומו לא מיפסלא בפחות מכזית ש\"מ דמקטיר בחוץ לא מחייב בפחות מכזית:"]]],[["ראש בן יונה שאין בו כזית ומלח משלימו לכזית מהו","א\"ל רבא מפרזקיא לרב אשי לאו היינו פלוגתייהו דר' יוחנן ור\"ל תיבעי לרבי יוחנן ותיבעי לר\"ל","תיבעי לר' יוחנן ע\"כ לא קאמר ר' יוחנן התם אלא עצם דמינא דבשר הוא אבל מלח דלאו מינא דבר יונה הוא לא תיבעי לר\"ל ע\"כ לא קאמר ר\"ל התם אלא דאי פריש מינה לאו מצוה לאסוקי אבל הכא דאי פריש מצוה לאסוקי לא או דלמא ל\"ש","תיקו:","ר' יוסי הגלילי אומר כו':","השיב רבי תחת רבי יוסי הגלילי מה לשוחט בפנים ומעלה בחוץ שהיתה לו שעת הכושר תאמר בשוחט חוץ ומעלה בחוץ שלא היתה לו שעת הכושר","השיב ר\"א בר' שמעון תחת ר\"י הגלילי מה לשוחט בפנים ומעלה בחוץ שכן קודש מקבלו תאמר בשוחט בחוץ שאין קודש מקבלו","מאי בינייהו אמר זעירי שחיטת לילה איכא בינייהו","רבה אמר קבלה בכלי חול איכא בינייהו:","טמא שאכל בין קודש כו':","שפיר קאמרי ליה רבנן לרבי יוסי הגלילי","אמר רבא כל היכא דנטמא טומאת הגוף ואחר כך נטמא בשר דכולי עלמא לא פליגי דחייב שכן טומאת הגוף בכרת","כי פליגי בשנטמא בשר ואח\"כ נטמא הגוף","דרבנן סברי אמרינן מיגו ור' יוסי הגלילי סבר לא אמרינן מיגו","ורבי יוסי נהי דמיגו לא אמרינן תיתי טומאת הגוף דחמירא ותחול על טומאת בשר","אמר רב אשי ממאי דטומאת הגוף חמורה דלמא טומאת בשר חמורה שכן אין לה טהרה במקוה:","\u0001מתני׳\u0002 חומר בשחיטה מבעלייה ובעלייה מבשחיטה","חומר בשחיטה שהשוחט להדיוט חייב והמעלה להדיוט פטור חומר בעלייה שנים שאחזו בסכין ושחטו פטורים אחזו באבר והעלו חייבין","העלה חזר והעלה וחזר והעלה חייב על כל עלייה דברי ר\"ש ר' יוסי אומר אינו חייב אלא אחת","ואינו חייב עד שיעלה לראש המזבח ר\"ש אומר אפילו העלה על הסלע או על האבן חייב:","\u0001גמ׳\u0002 מאי שנא המעלה להדיוט דפטור דכתיב (ויקרא יז, ד) לה' בשחיטה נמי הכתיב לה'","שאני התם דאמר קרא (ויקרא יז, ג) איש איש גבי העלאה נמי כתיב איש איש מיבעי ליה לשנים שהעלו באבר חייבין","אי הכי ה\"נ מיבעי ליה לשנים שאחזו בסכין ושחטו שחייבין שאני התם דאמר קרא ההוא אחד ולא שנים","אי הכי גבי העלאה נמי הא כתיב ההוא מיבעי ליה"],[[0,"ראש יונה","של עולת העוף והעלו בחוץ: מלח אי פריש מצוה לחזור ולמולחו כדכתיב (ויקרא ב) ולא תשבית מלח ברית:"],[5,"שעת הכושר","ליקרב בפנים:"],[6,"שכן קדש מקבלו","אע\"פ שהוציאו אם חזר והכניסו והעלהו לא ירד כדאמרן בהמזבח מקדש (לעיל זבחים דף פד.) הלן והיוצא כו':"],[7,"שחיטת לילה איכא בינייהו","לרבי שחט בהמה בלילה בפנים והעלה בחוץ פטור שלא היתה לה שעת הכושר דבשחיטתה נפסלה לר\"א חייב שהרי הקדש מקבלו שאם עלה לא ירד:"],[8,"רבה אמר קבלה בכלי חול איכא בינייהו","שעת הכושר ליכא קדש מקבלו איכא דכל שפסולו בקדש הקדש מקבלו:"],[11,"כל היכא דנטמא גופו של זה ואח\"כ נטמא הבשר","ואפילו ע\"י אחרים מודה ר' יוסי הגלילי דחייב כדאמרן מה לי על ידו מה לי ע\"י אחרים דטעמא דר' יוסי משום דאין איסור חל על איסור הוא וכאן איסור טומאת הגוף קודם:"],[12,"כי פליגי בשנטמא בשר תחילה","ונאסר על זה משום טומאת בשר שאין חייבין עליו חטאת וכי הדר נטמא הגוף אית ליה לר' יוסי אין איסור טומאת הגוף חל על איסור זה ואע\"ג דאיסור כולל הוא דאיכא למימר דמיגו דמיתסר בשאר חתיכות טהורות משום טומאת הגוף נתסר נמי בהך לא אמרינן האי מיגו הלכך אין ראיה מטמא שאכל את הטהור לכאן דהתם טומאת הגוף קדים:"],[13,"ורבנן סברי אמרינן מגו","ואיסור כולל חל על איסור אחר דהא דאמרינן אין איסור חל על איסור באיסורי דעלמא קאמרינן:"],[14,"נהי דלא אמרינן מגו","לחול איסור על איסור ואפילו הוא כולל מיהו הני מילי היכא דשניהן שוין אבל הכא תיתי טומאת הגוף דחמירא ותיחול בכולל על טומאת בשר דקילא דהכי אמרינן בשחיטת חולין בפרק גיד הנשה (חולין דף קא.) דרבי יוסי הגלילי לית ליה איסור חל על איסור אפילו ע\"י כולל ובאיסור חמור אית ליה איסור חל על איסור כשהוא איסור כולל גבי אוכל גיד הנשה של עולה דאוקימנא כרבי יוסי הגלילי דקתני חייב שתים:"],[17,"מתני' השוחט קדשים בחוץ","לאכילת הדיוט חייב:"],[17,"והמעלה להדיוט פטור","משום העלאת חוץ וחייב משום עובד עבודת כוכבים ואם הזיד בעבודת כוכבים ושגג בהעלאת חוץ אינו מביא על שגגתו חטאת וטעמא מפרש בגמ':"],[17,"שנים שאחזו","בגמרא מפרש לה:"],[18,"העלה ונודע לו וחזר והעלה","מאותה בהמה עצמה ובגמרא מפרש פלוגתייהו:"],[19,"שיעלה לראש המזבח","שיבנה מזבח לשם כך ויעלה וטעמא מפרש בגמ':"],[20,"גמ' דכתיב לה'","ואל פתח אהל מועד לא יביאנו לעשות אותו לה' (ויקרא י״ז:ט׳) מכלל דבעושה לשם הכתוב מדבר:"],[20,"בשחיטת חוץ נמי כתיב","(שם) ואל פתח אהל מועד לא הביאו להקריב קרבן לה':"],[21,"איש איש","להביא איש ששחט לאיש:"],[22,"שאני התם","בשחיטה לא מצית למידרש איש איש לחייב שנים שאחזו בסכין ושחטו:"],[23,"דהא כתיב ההוא","וקא סלקא דעתך ונכרת האיש ההוא (שם):"]],[[7,"שחיטת לילה איכא בינייהו","לכאורה רבי ורבי אלעזר בר\"ש סברי כר\"ש דאמר בפרק המזבח מקדש (לעיל זבחים דף פד.) נשחטה בלילה אם עלתה לא תרד דהשתא קדש מקבלו ולא היתה לו שעת הכושר אבל לרבי יהודה דאמר אם עלתה תרד בין לרבי בין לרבי אלעזר בר\"ש שחט בלילה בפנים והעלה בחוץ לא מבעיא (ליה) לרבי יוסי הגלילי דפטור אלא אפילו לרבנן נמי פטור כדמוכח בסוף פירקין (לקמן זבחים קיא:) גבי הא דתנן ר\"ש אומר כל שחייבין עליו בחוץ חייבין על כיוצא בו בפנים שהעלה בחוץ ומפרש זעירי גופיה שחיטת בהמה בלילה איכא בינייהו וה\"ק השוחט בהמה בלילה בפנים והעלה בחוץ פטור פירוש דאין מתקבל בפנים כר' יהודה דאמר אם עלה (לא) ירד שחט בחוץ והעלה בחוץ חייב אלמא דאפילו לרבנן דמחייבי שוחט בחוץ ומעלה בחוץ מודו בשוחט בלילה בפנים ומעלה בחוץ דפטור לר' יהודה וקצת תימה זעירי ורבה אמאי נקטי הכא שחיטת לילה וקבלה בכלי חול דהיינו כמו נשפך דמה דלא הוי אלא לר\"ש דלרבי יהודה תרוייהו ירדו הוי להו למימר איכא בינייהו נשחטה חוץ לזמנו וחוץ למקומו דלכולי עלמא לא ירד דהרי קדש מקבלו ולא היתה לו שעת הכושר ושמא אגב דנקטי רבה וזעירי בסוף פירקין (שם) גבי פלוגתא דר\"ש ורבנן שחיטת לילה וקבלה בכלי חול נקטי נמי הכא וצריך לדקדק לר' יהודה דאמר (לעיל זבחים דף פד.) ביצא דמה אם עלה ירד הרי זורק מקצת דמים בחוץ דחייב אע\"ג דאין קדש מקבלו ושמא לרבי יהודה לא היה חייב והא דדרשינן מקרא לרבות הזורק דלמא בשחוטי חוץ ולא בשחוטי פנים מידי דהוה אשחיטת לילה בסוף פירקין אבל לרבי יוסי הגלילי אליבא דרבי יהודה ודאי לא משכחת לה זורק בחוץ דחייב ועוד נראה דהא דמיפטר לר' יהודה משום דאין קדש מקבלו היינו כשאין קדש מקבלו מחמת פסול אחר מלבד פסול זה שיצא לחוץ והעלהו וניחא נמי דמתני' מחייב הקומץ והלבונה והקטרת ומנחת כהנים שהעלן בחוץ אף על גב דאמרינן בריש המזבח (לעיל זבחים דף פג:) דמנחות לר\"י הגלילי ירדו וכן נסכים הבאים עם הזבח דאמרינן לדברי כולן ירדו וברייתא דבסמוך (דף קט.) דמרבי פסולין לא חשיב נשחטה בלילה ונשפך דמה שמע מינה דרבי יהודה היא ולא מחייבי אהני משום דירדו ואפילו הכי מחייב אקומץ ומנחת נסכים וניסוך היין והמים והיינו טעמא כדפרישית וקצת קשה דלרבי יהודה אין מתיישב מה שהשיב ר' אלעזר בר\"ש תחת ר\"י הגלילי דאכתי תיקשי ליה אף הקומץ בפנים והעלה בחוץ כיון שהוציאו פסלו:"],[12,"רבנן סברי מיגו","באיסור כולל פליגי כדמפרש בסוף גיד הנשה (חולין דף קא.):"]]],[["למעוטי שוגג אנוס ומוטעה אי הכי הכא נמי מיבעי למעוטי אנוס שוגג ומוטעה","תרי ההוא כתיבי","ואלא לה' למה לי להוציא שעיר המשתלח:","חומר בהעלאה כו':","ת\"ר (ויקרא יז, ג) איש איש מה ת\"ל לרבות שנים שאחזו באבר והעלו שחייבין שיכול והלא דין הוא ומה השוחט להדיוט שחייב שנים שאחזו בסכין ושחטו פטורין המעלה להדיוט שפטור אינו דין ששנים שאחזו פטורין ת\"ל איש איש דברי ר\"ש","רבי יוסי אומר ההוא אחד ולא שנים א\"כ מה ת\"ל איש איש דברה תורה כלשון בני אדם","ור\"ש האי ההוא מיבעי ליה למעוטי שוגג אנוס מוטעה ורבי יוסי מהוא ההוא ור\"ש הוא ההוא לא דריש","ורבי יוסי מדהאי איש איש דברה תורה כלשון בני אדם ההוא איש איש נמי דברה תורה כלשון בני אדם ואלא השוחט להדיוט מנא ליה דחייב נפקא ליה (ויקרא יז, ד) מדם יחשב לאיש ההוא דם שפך ואפילו השוחט לאיש:","העלה וחזר והעלה כו':","אמר ר\"ל מחלוקת בד' וה' אברים דמר סבר כי כתיב לעשות אותו על השלם הוא חייב ואינו חייב על החסר אכל בהמה כתיב ומר סבר אכל אבר ואבר כתיב אבל אבר אחד דברי הכל אינו חייב אלא אחת","ור' יוחנן אמר מחלוקת באבר אחד דמר סבר מוקטרי פנים שחסרו והעלה בחוץ חייב ומר סבר פטור אבל בד וה' איברין דברי הכל חייב על כל אבר ואבר","ופליגא דעולא דאמר עולא הכל מודים במוקטרי פנים שחסרו והעלו בחוץ שחייב לא נחלקו אלא במוקטרי בחוץ שחסרו והעלו בחוץ דמר סבר פטור ומ\"ס חייב","איכא דאמרי אמר עולא הכל מודים במוקטרי חוץ שחסרו והעלו בחוץ שהוא פטור לא נחלקו אלא במוקטרי פנים שחסרו והעלו בחוץ דמ\"ס פטור ומ\"ס חייב","ופליגי דאבוה דשמואל אלישנא קמא דעולא דאמר אבוה דשמואל כמאן מהדרינן פוקעין לגבי מזבח כמאן דלא כר' יוסי:","ואינו חייב עד שיעלה כו': אמר רב הונא מאי טעמא דרבי יוסי דכתיב (בראשית ח, כ) ויבן נח מזבח לה'","א\"ר יוחנן מ\"ט דר\"ש דכתיב (שופטים יג, יט) ויקח מנוח את גדי העזים ואת המנחה ויעל על הצור לה'","ואידך נמי והכתיב ויבן מזבח לה' ההוא גובהה בעלמא ואידך נמי הא כתיב ויקח מנוח הוראת שעה היתה","ואיבעית אימא ה\"ט דר\"ש כדתניא ר\"ש אומר (ויקרא יז, ו) מזבח פתח אהל מועד ואין מזבח בבמה לפיכך העלה על הסלע או על האבן חייב","יצא מיבעי ליה ה\"ק לפיכך בשעת איסור הבמות העלה על הסלע או על האבן חייב","בעי רבי יוסי בר' חנינא קרן וכבש ויסוד וריבוע מהו שיעכבו בבמה","א\"ל רבי ירמיה תניא קרן וכבש וריבוע ויסוד מעכבין בבמה גדולה ואין מעכבין בבמה קטנה:"],[[0,"למעוטי שוגג אנוס ומוטעה","דהכי דריש בת\"כ כל ההוא דגבי ונכרת כשישנו בהווייתו ובדעתו ולא אנוס ולא שוגג מאיליו או מוטעה ע\"י אחרים:"],[1,"תרי ההוא כתיבי","דם יחשב לאיש ההוא בשחיטה כתיב (ויקרא י״ז:ד׳):"],[2,"אלא לה'","דכתיב גבי שחיטה:"],[2,"ל\"ל להוציא שעיר המשתלח","דמשמע הראוי ליקרב לשם חייבין עליו בחוץ ושאינו עומד לשם אין חייבין עליו בחוץ ולקמן בפ' בתרא (זבחים דף קיג:) דריש לה תנא דברייתא הכי וגלי בשחיטה והוא הדין להעלאה דהא מיגמר גמירי מהדדי כדאמרן לערב פרשיות בר מהנך תרי חומרי דמתני' דמפרשי קראי בכולהו בין לחיובא בין לפטורא:"],[4,"ושחטו פטורין","כדילפינן לעיל דכתיב ההוא:"],[4,"מה ת\"ל איש איש","גבי העלאה:"],[9,"אכל בהמה כתיב","על כל הבהמה הוא חייב ואינו חייב על אבר אחד הלכך כולה חדא העלאה היא:"],[9,"אבל באבר אחד","והקריבו לחצאין לאחר שהקריב שאר האיברים דאילו עליו לבדו אפילו הקריב שלם פטר ליה ר' יוסי או מיירי שפקע מעל האש וחזר והחזירו:"],[9,"דברי הכל העלאה אחת היא","דהא אותו כתיב שלם ולא חסר:"],[10,"ור' יוחנן אמר מחלוקת באבר אחד","ודכולי עלמא אותו אכל אבר ואבר כתיב ומאן דמחייב סבר מוקטרי פנים שחסרו והעלו בחוץ חייב דהא מהדרינן פוקעין למזבח דהוו להו חסר וכי כתיב אותו אמוקטרי חוץ כתיב:"],[10,"ומ\"ס פטור","דנפקא ליה מלא יביאנו כר' ישמעאל:"],[11,"לא נחלקו אלא במוקטרי חוץ כו'","מר סבר חייב דכי כתיב אותו למעוטי פחות מכזית אתא שאין הקטרה שלימה וכדדריש ליה לקמן:"],[13,"פוקעין","שפוקעין מעל האש:"],[13,"דלא כר' יוסי","דכיון דבפנים בני הקטרה נינהו ואע\"ג דחסרו בחוץ נמי מיחייב במוקטרי פנים שחסרו והעלו בחוץ אלמא קסבר אבוה דשמואל דרבי יוסי אמוקטרי פנים שחסרו והעלו בחוץ פליג:"],[14,"ויבן נח מזבח","אלמא אפילו במת יחיד שהיא בחוץ אינה העלאה בלא מזבח:"],[15,"על הצור","בלא בנין מזבח לשם כך וקרי ליה העלאה:"],[16,"גובהה בעלמא","כדרך כל הארץ שיהא נוח להשתמש ולא לחובת מזבח:"],[17,"מזבח פתח אהל מועד כו'","האי קרא דריש ליה ר\"ש בת\"כ הכי וזרק הכהן את הדם על מזבח ה' פתח אהל מועד ולא מזבח בבמת יחיד בשעת היתר הבמות ובפ' המעלה בחוץ כתיב:"],[17,"","ה\"ג חייב יצא מיבעי ליה ה\"ק לפיכך בשעת איסור הבמות העלה ע\"ג הסלע או על גבי האבן חייב:"],[18,"יצא מיבעי ליה","כיון דאמר אין מזבח בבמה בשעת היתר הבמות קאי הילכך יצא מיבעי ליה:"],[18,"ה\"ק לפיכך","הואיל ובבמה בשעת היתר הבמות הויא הקטרה בשעת איסורו אם העלו על הסלע חייב:"],[19,"קרן וכבש ויסוד וריבוע","דקי\"ל דמעכבי במזבח המשכן בפרק קדשי קדשים (לעיל זבחים דף סב.) מהו שיעכבו בבמת יחיד:"],[20,"בבמה גדולה","אף נוב וגבעון שהיו במות ציבור וכל שכן שילה ובית עולמים:"]],[[0,"שוגג אנוס ומוטעה","קצת קשה אנוס ל\"ל קרא פשיטא דאונס רחמנא פטריה ושמא האי אנוס פרט לאומר מותר ותימה ל\"ל קרא למיפטריה מכרת כשהוא שוגג. פשיטא בר קרבן הוא י\"ל ס\"ד אמינא אי לא מייתי קרבן ליהוי בכרת דהא לאחר הבאת קרבן דוקא כתיב ונסלח לו:"],[2,"להוציא שעיר המשתלח","היינו לאחר הגרלה דקודם הגרלה מיחייב אתרוייהו כדמוכח פרק שני שעירי (יומא דף סב:):"],[4,"והמעלה להדיוט פטור","פי' בקונטרס פטור משום העלאת חוץ וחייב משום עובד עבודת כוכבים ואם הזיד בעבודת כוכבים ושגג בהעלאת חוץ אינו מביא על שגגתו חטאת ותימה אמאי יתחייב מעלה לחבירו משום מעלה בחוץ כיון דמזיד בעבודת כוכבים לאו שב מידיעתו הוא דמומר לעבודת כוכבים מומר לכל התורה כולה ובחנם דחק עצמו בקונטרס דמעלה לחבירו אין שייך לחייבו משום עבודת כוכבים כיון דאין מתכוין לשם עבודת כוכבים:"],[5,"דברה תורה כלשון בני אדם","בפרק אלו מציאות (ב\"מ דף לא:) פירשתי:"],[9,"אכל בהמה כתיב","לפיכך העלה כמה אברים זה אחר זה אינו חייב אלא אחת אקמא מיחייב דאייתיה לכולה בהמה ואאחריני פטור דכבר חסרה דמה שהעלה הרי הוא כנאבד ומ\"ס אכל אבר ואבר אבל אבר אחד שהעלה לחצאין לכ\"ע לא מיחייב אלא אחת ומיחייב אזית קמא ורבי יוחנן אמר מחלוקת באבר אחד דמר סבר מוקטרי פנים שחסרו והעלן בחוץ חייב וכי כתיב לעשות אותו אשחוטי חוץ אבל לא אשחוטי פנים דהא מהדרינן פוקעין ומר סבר פטור כר' ישמעאל דלעיל וקסבר דלא מהדרינן פוקעין [אבל בד' וה' אברים חייב על כל אבר] לכ\"ע וא\"ת מאי טעמא לא מיחייב אכזית שני נהי דלא מהדרינן פוקעין מ\"מ אם מחתך אבר אחד לכמה זיתים חייב להעלות את כולן א\"כ הקטרה הוא ואמאי לא מיחייב עלה בחוץ וי\"ל דהא מיחייב להקטיר הכל לאו משום דתיהוי חשובה הקטרה בחצי אבר אלא משום דכולה חדא הקטרה היא וכיון שהתחיל בה גומר אבל אי מהדרי פוקעין שחסרה ונקטרה שאר מזה יש ללמוד דחשיבא הקטרה בחצי אבר וכ\"נ שיטה זו ובקונטרס פי' בע\"א:"],[11,"לא נחלקו אלא במוקטרי חוץ שחסרו והעלן בחוץ מר סבר חייב","פי' בקונטרס וכי כתיב אותו למעוטי פחות מכזית אתא שאין הקטרה שלימה וכדדריש לקמן וא\"ת ומאי טעמא בעי קרא למעוטי פחות מכזית היכן מצינו שחייבה תורה בחצי שיעור וחצי זית חצי שיעור הוא דלא מצינו הקטרה להתחייב בפחות מכזית לא לענין מחשבה ושום דבר אלא דוקא גבי שאור ודבש דחייב בפחות מכזית למאן דאית ליה מכח קראי ויש לומר דשמא כיון דמהדרי' פוקעין פחות מכזית הוה אמינא דמחייב בחוץ אי לאו דכתיב אותו:"],[13,"כמאן מהדרינן פוקעין כו'","הא דמיחייבינן בריש פירקין (זבחים דף קז.) לר״ע מוקטרי פנים שחסרו והקריבן בחוץ היינו דוקא כגון אימורי או איברי עולה שחסרו דלא מפסלי בהכי אבל מנחה שחסרה וקטרת ולבונה שחסרו דמיפסלי מחמת חסרון פטור כדתנן לקמן (זבחים דף קט:) וכולן שחסרו כל שהוא והקריבן בחוץ פטור וגבי עולה קתני המעלה (עולת כזית) חייב ומצטרפין לכזית להעלותן בחוץ וליחייב עליהן משום פיגול נותר וטמא (ואימורים ומן האימורין בחוץ חייב) ומשמע בגמרא דבניתותרו מיירי דקתני בברייתא עולה ואימורין אין שלמים ואימוריהן לא ומוקי לה בניתותרו וכר' יהושע וקצת תימה קומץ ולבונה אמאי לא מיחייב עלייהו בחוץ כשחסרו נהי דמיפסלי לכתחילה מ״מ מתקבלין הם בפנים דאם עלו לא ירדו דהוה ליה פסולו בקדש כשחסר בין קמיצה להקטרה ולמאן דחשיב במנחות פ' קמא (דף ט:) חסרון כבעל מום ניחא וי״ל דאפילו תמצא לומר דאם עלה לא ירד מ״מ סברא הוא למעוטיה מדכתיב אותו על השלם הוא חייב ואינו חייב על החסר כיון דלכתחילה לא יעלה וצריך לדקדק אי מהדרינן פוקעין דידהו ובפרק המזבח מקדש (לעיל זבחים דף פג:) איכא כמה קראי לרבן גמליאל מהיא העולה על מוקדה ולאידך מאשר תאכל האש ועוד דדרשינן לעיל (זבחים דף פו.) ועשית עולותיך הבשר והדם עיכולי עולה אתה מחזיר ואי אתה מחזיר עיכולי גידין ועצמות משמע הא בשר דומיא דגידים ועצמות מהדרינן אפילו במקצת ותימה אי פליג עליה רבי יוסי:"]]],[["\u0001מתני׳\u0002 אחד קדשים כשרין ואחד קדשים פסולין שהיה פסולן בקודש והקריבן בחוץ חייב","המעלה כזית מן העולה ומן האימורין בחוץ חייב:","\u0001גמ׳\u0002 ת\"ר (ויקרא יז, ח) אשר יעלה עולה או זבח אין לי אלא עולה מנין לרבות אימורי אשם ואימורי חטאת ואימורי קדשי קדשים ואימורי קדשים קלים ת\"ל זבח","מנין לרבות הקומץ והלבונה והקטורת ומנחת כהנים ומנחת כהן משיח והמנסך שלשת לוגין יין ושלשת לוגין מים ת\"ל (ויקרא יז, ט) ואל פתח אהל מועד לא יביאנו כל הבא לפתח אהל מועד חייבין עליו בחוץ","ואין לי אלא קדשים כשרים מנין לרבות פסולין","כגון הלן והיוצא והטמא ושנשחט חוץ לזמנו וחוץ למקומו ושקבלו פסולין וזרקו את דמו והניתנין למטה שנתנן למעלה והניתנין למעלה שנתנן למטה והניתנין בחוץ שנתנן בפנים והניתנין בפנים שנתנן בחוץ ופסח וחטאת שנתנן שלא לשמן","מנין ת\"ל לא יביאנו לעשות כל המתקבל בפתח אהל מועד חייבין עליו בחוץ:","המעלה כזית מן העולה כו': עולה ואימוריה אין שלמים ואימוריהן לא","תנינא להא דת\"ר עולה ואימוריה מצטרפין לכזית להעלותן בחוץ ולחייב עליהן משום פיגול נותר וטמא","בשלמא העלאת עולה דכליל אין שלמים לא אלא פיגול ונותר וטמא מ\"ט","והא תנן כל הפגולין מצטרפין וכל הנותרין מצטרפין קשיא פיגול אפיגול קשיא נותר אנותר","פיגול אפיגול לא קשיא כאן בפיגול כאן במחשבת פיגול","נותר אנותר לא קשיא כאן בנותר כאן בשניתותרו עד שלא נזרק הדם","ומני רבי יהושע היא דתניא ר' יהושע אומר כל הזבחים שבתורה שנשתייר בהן כזית בשר"],[[0,"מתני' ואחד קדשים פסולין שהיה פסולן בקדש","הואיל ובפנים אם עלו לא ירדו מתקבל בפנים קרינא ביה וחייבין עליהן בחוץ כדיליף בגמ':"],[1,"המעלה כזית מן העולה ומאימוריה","חצי זית מזה וחצי זית מזה חייב דכולה כליל:"],[2,"גמ' ואימורי קדשי קדשים","כבשי עצרת:"],[3,"הלבונה","של מנחת נדבה:"],[3,"ומנחת כהנים","שהיא כליל וראויה להעלאה כקומץ מנחת ישראל אבל שירי מנחת ישראל אינו חייב על העלאתם:"],[3,"מנחת כהן משיח","עשירית האיפה שהוא מביא בכל יום:"],[3,"ושלשת לוגין יין","שהוא פחות שבנסכים:"],[3,"ושלשת לוגין מים","בחג קאמר ובמוקדשין לחג שאין העלאת חוץ נוהגת בחולין:"],[4,"מנין לרבות פסולין","הנך דאם עלו לא ירדו דלא מתרבו מלא יביאנו דהא אינם ראויין להביא לכתחילה:"],[6,"ת\"ל לעשות","משמע הראויין לעשות אפילו אינו ראוי לבא מחוץ לפנים והני נמי כיון דאם עלו לא ירדו וכהן נזקק להפך בהם בצינורא או להעלותן מראש המזבח למערכה ראויין ליעשות קרינא ביה:"],[7,"שלמים לא","אין בשרן מצטרף עם אימוריהן לכזית העלאת חוץ משום דבשר שלמים לאו בר הקטרה הוא ולא קרינא ביה אל פתח אהל מועד לא יביאנו:"],[8,"ולחייב עליהן משום פיגול ונותר וטמא","קא ס\"ד באוכל כזית בשר ואימורין מעולת פיגול או נותר או בטומאת הגוף אכלו:"],[9,"מאי טעמא","לא מצטרף נמי בשר שלמים עם אימוריו לפיגול ונותר וטמא הא בין בבשר בין באימורין שייך פיגול נותר וטמא כדאמר בפ' בית שמאי (לעיל זבחים דף מג.) דכל שיש לו מתירין בין לאדם בין למזבח חייבין עליו משום פיגול והרי הדם מתיר את הבשר לאדם ואת האימורין למזבח ותנן נמי התם דברים שאין חייבין עליהם משום פיגול כגון הקומץ והלבונה והקטרת שאין להם מתירין אלא הם עצמן מתירין חייבין עליהן משום נותר ומשום טמא וכל שכן אימורין שהפיגול נוהג בהן ומקראי ילפינן להו:"],[10,"כל הפיגולין מצטרפין","משנה היא במעילה:"],[11,"כאן בפיגול כאן במחשבת פיגול","הא דקתני מצטרפין באוכל פיגול קאמר ולהתחייב חטאת והא דקתני עולה אין שלמים לא במחשבת פיגול שאם שחט או זרק על מנת להקטיר חצי זית בשר עולה וחצי זית מאימורין חוץ לזמנו פיגל אבל בשלמים חישב לאכול או להקטיר חצי זית בשר וחצי זית אימורין לא פיגל שאין מחשבת אכילה בנקטרין ואין מחשבת הקטרה בנאכלין:"],[12,"כאן בנותר כאן בשניתותרו עד שלא נזרק הדם","הא דקתני מצטרפין באוכל נותר קאמר והא דקתני עולה אין שלמים לא בשניתותרו מאיבוד ושריפה כגון אבדו הבשר והאימורין קודם זריקה ונשתייר חצי זית מזה וחצי זית מזה בעולה דכולה כליל הויא זריקת דם זריקה דהא איכא אכילת מזבח וכר' יהושע דאמר בפרק טבול יום (לעיל זבחים דף קד.) אם אין בשר אין דם וכיון דזריקה היא חייבין עליו משום נותר אם ניתותרו ואכל ממנו כדאמרן (לעיל זבחים דף מה:) דברים שאין חייבין עליהם משום פיגול חייבין משום נותר כגון קומץ שהוא אכילת מזבח כעולה וכל שכן דברים שחייבין עליהן משום פיגול כגון בשר עולה אבל שלמים אין חצי זית מבשרן וחצי זית מאימוריהן מצטרפין להיות שיור לזרוק עליהם את הדם דלא אכילת אדם איכא ולא אכילת מזבח איכא וכיון דלא הויא זריקה אם זרק אין חייבין עליהן משום נותר וטמא דקי\"ל (מנחות דף כה:) כל הניתר לטהורין חייבין עליו משום טומאה ובפ' ב\"ש (לעיל זבחים דף מה:) אתי נותר חילול חילול מטומאה ובמס' מעילה (דף ו:) לענין יוצא אמרינן לר\"א דאמר אין זריקה מועלת ליוצא אין חייבין עליו משום נותר וטמא:"],[13,"כל הזבחים","בר מעולה:"]],[[3,"ומנחת כהנים ומנחת כהן משיח","הא דפלגינהו משום דמנחת כהנים באה עשרון ומנחת כהן משיח חצי עשרון ותימה דלא תני מנחת נסכים:"],[8,"עולה ואימורין מצטרפין לכזית להעלותן בחוץ ולחייב עליהם משום פיגול נותר וטמא","במסכת מעילה פרק קדשי מזבח (מעילה דף טו:) תנן חמשה דברים בעולה מצטרפין זה עם זה הבשר והחלב והסלת והיין והשמן וששה בתודה דאיכא לחם ותימה לענין מאי קאמר אי לענין מעילה הא תנא ליה רישא (שם.) קדשי מזבח מצטרפין זה עם זה למעילה כו' ועוד דתודה אין בה מעילה כי אם לאחר זריקה באימורין אבל בלחם לא ואי (לא יתחייב) בחוץ הא לא תני בשמעתין אלא עולה ואימורין אבל חמשה דברים לא דאף על גב דמיחייבי בחוץ כדדריש לעיל מקרא הני מילי בפני עצמן אבל איצטרופי לא ועוד דלא מיחייב בחוץ אלחם שבתודה ועוד חלב ויין היאך מצטרפין והא אין שיעורן שוה שזה בכזית וזה בשלשה לוגין ואי לענין לזרוק עליהן הדם הא אמר ובמנחה אפילו כולה קיימת לא יזרוק ואי לענין מחשבת פיגול אין אכילה והקטרה מצטרפין ונראה דמיירי לענין אכילה דמיחייב האוכל משום פיגול נותר וטמא ואי מרישא דקתני קדשי מזבח מצטרפין הוה אמינא במין אחד קמ\"ל אפילו בכמה מינין ועוד תנינהו למעוטי דאין דם חייבין עליו משום פיגול ועוד אשמעינן דחל פיגול אהנך דברים חמשה וששה וצריך לומר דאתיא כר\"מ דתנן לעיל בפרק ב\"ש (זבחים דף מג:) [ואלו] דברים שאין חייבין עליהן משום פיגול מנחת נסכים והנסכים הבאין בפני עצמן דברי ר\"מ וחכ\"א אף הבאים עם הבהמה ובהקומץ זוטא (מנחות דף טו:) תנן נמי הזבח מפגל את הנסכים משקדש בכלי דברי ר\"מ והא דחלב ויין מצטרפין אע\"ג דחלב בכזית ומשקין ברביעית ה\"מ בשתיה אבל דרך אכילה ששרה פתו ביין שיעורו בכזית וקצת תימה מאי איריא דנקט חמשה דברים בעולה הא בשלמים נמי מצטרפין לחייב משום פיגול ויש לומר דנקט עולה משום דאיירי נמי במעילה אף על גב דבתודה לא איירי במעילה:"],[10,"כל הפיגולין מצטרפין","תימה דלא מייתי מרישא דקתני (מעילה דף טו.) קדשי מזבח מצטרפין לפיגול ויש לומר דהוה מוקמינן לה בעולה דהא תני נמי מעילה אבל הך משמע טפי:"],[10,"וכל הנותרות מצטרפין","תימה דלא תני כל הטומאות מצטרפין ויש לומר דהוה משמע אפילו שרץ ונבלה ובשר המת והנהו לא מצטרפין כדתנן התם (דף יז:):"],[12,"כאן בשניתותרו [עד] שלא נזרק הדם ומני רבי יהושע","ה\"ג לה במעילה בפ' קדשי מזבח (מעילה דף טו:) אלא אימא עולה ואימורים מצטרפין זה עם זה לכזית לזרוק עליהם את הדם ומאן קתני לה רבי יהושע וגירסא דשמעתין נמי יש ליישב דהכי נמי קאמר וקשה לישנא דברייתא דקתני ולחייב עליהם משום פיגול נותר וטמא ויש לפרש דכשניתותרו כזית מעולה ואימורין אשמעינן דזריקה מעלייתא היא לאיחיובי משום פיגול נותר וטמא דקרבו מתיריו קרינא ביה והשתא לא צריכי להא דקאמר הכא פיגול אפיגול לא קשיא כאן בפיגול כאן במחשבת פיגול דבשינוייא דניתותרו מתרצי תרוייהו פיגול ונותר ובמסכת מעילה לא גרסינן ליה ויש מוחקין טמא מן הברייתא משום דמטמא לא משני מידי אבל לפי מה שפירשתי ניחא דכולהו מיתרצי וע\"כ גרסינן ליה דאי לא גרסינן ליה הא דקאמר התם במעילה תנינא להא דתנו רבנן מנא ליה הא דקתני בברייתא דמצטרפין לענין אכילה ואימא פיגול אפיגול לא קשיא כאן בפיגול כאן במחשבת פיגול ונותר אנותר לא קשיא כאן בנותר כאן בשניתותרו דלמא איירי להצטרף לענין להכשיר הקרבן ולזרוק עליהם את הדם אבל לאכילה לא מצטרפין אבל מכיון דתני טמא על כרחין לענין אכילה קאמר דמצטרפין דהיינו תנינא להא דתנו רבנן:"]]],[["וכזית חלב זורק את הדם","חצי זית בשר וחצי זית חלב אינו זורק את הדם ובעולה חצי זית בשר וחצי זית חלב זורק את הדם מפני שכולה כליל ומנחה אפילו כולה קיימת לא יזרוק","מנחה מאי עבידתה אמר רב פפא מנחת נסכים הבאה עם הזבח:","\u0001מתני'\u0002 הקומץ והלבונה והקטרת ומנחת כהנים ומנחת כהן משיח ומנחת נסכים שהקריב מאחת מהן כזית בחוץ חייב ר\"א פוטר עד שיקריב את כולן וכולן שהקריב בפנים ושייר מהן כזית והקריבו בחוץ חייב","וכולן שחסרו כל שהו והקריבו בחוץ פטור","המקריב קדשים ואימורים בחוץ חייב:","\u0001גמ'\u0002 ת\"ר המקטיר כזית בחוץ חייב חצי פרס בפנים פטור","קס\"ד מאי פטור פטור זר אמאי הקטרה היא","א\"ר זירא אמר רב חסדא אמר רב ירמיה בר אבא אמר רב מאי פטור פטור ציבור","א\"ר זירא אי קשיא לי הא קשיא לי הא דאמר רב עלה בהא אפילו ר' אליעזר מודה דהא ר' אליעזר לאו הקטרה היא קאמר","אמר רבה בהקטרה דהיכל דכולי עלמא לא פליגי","כי פליגי בהקטרה דפנים דמר סבר (ויקרא טז, יב) מלא חפניו דוקא ומ\"ס מלא חפניו לאו דוקא","א\"ל אביי והא כי קא כתיבא חוקה בהקטרה דפנים הוא דכתיב","אלא אמר אביי בהקטרה בפנים כ\"ע לא פליגי","כי פליגי בהקטרה דחוץ מ\"ס ילפינן פנים מחוץ ומ\"ס לא ילפינן","אמר רבא השתא חוץ מחוץ לא ילפי רבנן פנים מחוץ מיבעי","מה היא דתניא יכול המעלה פחות מכזית קומץ ופחות מכזית אימורין והמנסך פחות משלשת לוגין יין [פחות] מג' לוגין מים יהא חייב תלמוד לומר לעשות על השלם חייב ואינו חייב על החסר","והא פחות משלשת לוגין דאית בהו כמה זיתים ולא ילפי רבנן חוץ מחוץ","אלא אמר רבא כגון דקבעינהו שני חצאי פרס"],[[0,"או כזית חלב","דכתיב וזרק הכהן את הדם וגו' והקטיר החלב אע\"פ שאין בשר זורק עליו את הדם והכי מפרש במנחות בהקומץ רבה (מנחות דף כו.):"],[1,"אין זורק את הדם","דאית ליה לר' יהושע אם אין בשר אין דם מועשית עולותיך הבשר והדם ובזבחים כתיב (דברים י״ב:כ״ז) ודם זבחיך ישפך והבשר תאכל הזקיקן הכתוב זה לזה:"],[2,"ובמנחה מאי עבידתה","מאי זריקת דם איכא במנחה:"],[2,"מנחת נסכים שבאה עם הזבח","ואבד בשר הזבח והמנחה קיימת לא יזרוק את הדם בשבילה דלאו גופא דזביחה הוא:"],[3,"מתני' הלבונה","של מנחה:"],[3,"והקטרת","שבכל יום פרס שחרית ופרס של בין הערבים שהקטיר כזית מהן בחוץ חייב קסבר כי כתיב אותו על השלם הוא חייב ואינו חייב על החסר אשיעור הקטרה כתיב והיינו כזית ורבי אליעזר נמי מדלא פליג ארישא גבי עולה הכי נמי דריש ליה אותו אשיעור הקטרה כרבנן ומיהו עולה דלא מיפסלא בחסרון דכל עצמה בדם תלויה כפרתה חייב בכזית אבל בהני פליג דקא סבר קומץ כוליה היינו שיעור הקטרתו אף בפנים דהא מיפסל בחסרון וכן כולם שכולם מתירין הם כל זמן שלא קרבו כולם לא הויא הקטרה לצאת בעלים ידי חובתן ולרבנן בהני נמי הויא הקטרתן בכזית היכא דכוליה קיים ולא חסרו קודם הקטרה ותנן מנחות (דף כו.) הקטיר קומצה פעמים כשירה הילכך הקטרה היא:"],[3,"וכולן שהקריבן בפנים ושייר מהן כו'","חייב שהרי בזה נגמרה הקטרתן ולר' אליעזר נמי כי דריש אותו אשיעור הקטרה דריש ליה ושיעור הקטרה בכזית היכא דבפנים הויא הקטרה גמורה:"],[4,"וכולן שחסרו כל שהוא","קודם הקטרה ע\"י איבוד או שריפה נפסלו בחסרונן כדאמר במנחות (דף ט:) מן המנחה פרט לשחסרה היא ושחסר קומצה והאי וכולן לאו אלבונה קאי דהא מיפליג פליגי בה במנחות בפרק קמא (דף יא:) בלבונה שחסרה דלר\"ש כשירה אפילו עמדה על קורט אחד ולר' יהודה בשני קרטין ואי אלבונה נמי קאי מיירי שחסרה משיעור הכשרה למר כדאית ליה ולמר כדאית ליה:"],[4,"והקריבו בחוץ פטור","הואיל ואין מתקבלין בפנים:"],[5,"המעלה קדשים ואימוריהן","שהקריב הבשר והאימורין מחוברין בו חייב משום אימורין:"],[6,"גמ' חצי פרס בפנים","לאו דוקא חצי פרס נקט דה\"ה לכזית אלא פחות מכשיעור הכשר מצותה נקט:"],[7,"קס\"ד מאי פטור פטור זר","דאי לאו בזרות קאמר מאי פטור שייך למימר בפנים ואמאי פטור הא הקטרה היא דהא האי תנא דקמחייב עלה בחוץ:"],[8,"מאי פטור פטור ציבור","דיצאו ידי חובתן דכזית הויא הקטרה:"],[9,"בהא אפילו רבי אליעזר מודה","ואע\"ג דפליג במתני' אבחוץ מודה הוא להאי תנא בהאי סיפא דפטור ציבור וקשיא לי עלה אמאי מודה והא רבי אליעזר לאו הקטרה היא קאמר מדפטר עלה בחוץ:"],[10,"אמר רבה בהקטרה דהיכל","שבכל יום שלא נאמר בו שיעור והאי פרס שיעור דרבנן הוא מודה רבי אליעזר דבכזית הויא הקטרה לחייב עליה בחוץ ולהוציא ציבור ידי חובתן בפנים ומתני' כולה רישא וסיפא דברי הכל היא ובהקטרה דהיכל מיירי:"],[11,"כי פליגי","במתני' בהקטרה דיום הכפורים דלפני ולפנים שנאמר בה שיעור (ויקרא טז):"],[11,"מלא חפניו דוקא","ובבת אחת הילכך בחוץ נמי לא מיחייב אלא אשלימה:"],[12,"והא כי כתיבא חוקה בפנים כתיבא","כדכתיב (שם) והיתה (זאת) לכם לחוקת עולם לכפר וגו' דברים שאין נעשין אלא אחת בשנה וחוקה עיכובא הוא:"],[13,"ה\"ג אלא אמר אביי בהקטרה דפנים דכולי עלמא לא פליגי כי פליגי בהקטרה דחוץ","אביי נמי כרבה מתרץ לה דברייתא דמודה בה רבי אליעזר בהקטרה דהיכל ומתניתין בהקטרה דפנים ומיהו לא כטעמא דרבה דאמר לרבנן מלא חפניו לאו דוקא דכולי עלמא מלא חפניו דוקא ובפנים דכ\"ע לא פליגי דשלימה בעינן כי פליגי כגון שהקטיר כזית מן הקטרת של חפינת פנים בחוץ מר סבר ילפינן פנים מחוץ ילפינן קטרת של פנים מקטרת של היכל מה הקטרה של היכל בבמה בחוץ בכזית אף הקטרה של פנים חייבין עליה בבמה בכזית ואע\"ג דבדוכתה לא הויא הקטרה הואיל ובהיכל הויא הקטרה:"],[14,"ור' אליעזר סבר לא ילפינן פנים מחוץ","הקטרה דהיכל הוא דמיחייב עלה בחוץ בכזית דהא בדוכתה בהכי חשיבא אבל הקטרת פנים לא מיחייב עלה בחוץ בכזית הואיל ובדוכתה לאו הקטרה היא:"],[15,"השתא חוץ מחוץ","כגון ניסוך היין שהוא על המזבח החיצון לא ילפי רבנן מהקטר חלבים שהוא על המזבח החיצון לחייב על פחות משלשה לוגין בחוץ אע\"פ שיש שם כמה זיתים וגבי כל הקטרות של מזבח החיצון הקטרה היא הואיל וגבי ניסוך שיעורא אחרינא הוא לא מיחייב עליה אלא בכשיעור:"],[15,"פנים מחוץ","לחייב על קטרת שלפני ולפנים בבמה בחוץ ילפינן מהקטרה דהיכל:"],[16,"פחות מכזית קומץ","על כרחך רבנן היא דאי רבי אליעזר אפילו אכזית לא מיחייב דהא אמר עד שיקריב את כולן:"],[18,"אלא אמר רבא כגון דקבעינהו במנא","לעולם מתניתין וברייתא בהקטרה דהיכל הויא הקטרה בדוכתה בכזית ומשום הכי קתני לה בברייתא חייב ור' אליעזר מודה בה כדרב ופלוגתא דמתניתין כגון דקבעיה (דכולה) שני חצאי פרס במנא וקסבר ר\"א [קביעותא] דמנא מילתא הוא הואיל ונתן שני חצאי פרס בכלי הקטרת היכל קבעיה מנא ואי חסיר כל שהוא מיפסל הילכך בחוץ לא מיחייב עד שיקריב את כולו:"]],[[11,"ומר סבר מלא חפניו לאו דוקא","תימה למה לי למימר לאו דוקא אפילו יהא דוקא הוו מחייבי רבנן אכזית ממנו בחוץ מידי דהוה אקומץ וכמו כן קשה בסמוך למה לי למימר דסברי רבנן קביעות דמנא לאו כלום היא ויש לומר דעד כאן לא מחייבי רבנן בקומץ אלא משום דחשיב להתפגל על מנת להקטיר כזית מקומצה בחוץ הלכך חשיבא נמי הקטרה לחייב אכזית ממנו בחוץ ומנחת כהנים ומנחת כהן משיח אע\"ג דלא שייך בהם פיגול כיון דמנחה נינהו ומצינו במנחה דכזית נמי חשיבא הקטרה שם מנחה אחד הוא אבל קטרת לא אשכחן דחשיב הקטרה בכזית דלא שייך ביה פיגול ועוד דהא א\"ר יוסי דאין פיגול אלא בדבר שהוא על מזבח החיצון הלכך הא דמחייבי רבנן בקטרת בכזית על כרחין משום דמלא חפניו לאו דוקא וקביעות מנא לאו כלום היא:"],[18,"דקבעינהו במנא","למאי דאסיקנא (למאי) דקבעינהו במנא הוי לבונה דמתניתין שיעור שלם ופטור בחוץ לרבי אליעזר הואיל וקבעינהו במנא:"]]],[["במנא מר סבר קביעות מנא מילתא היא ומר סבר לאו מילתא היא","אמר רבא השתא למאן דאמר קביעותא דמנא ולא כלום הוא קבע ששה לפר ומשך מהן ארבעה והקריבן בחוץ חייב שראויין לאיל","קבע ארבעה לאיל ומשך מהן שלשה והקריבן בחוץ חייב שראויין לכבש","חסרו כל שהוא והקריבן בחוץ פטור","רב אשי אמר ניסוך מהקטרה לא ילפי רבנן","אף על גב דחוץ מחוץ לא ילפי הקטרה מהקטרה ילפי אף על גב דחוץ מפנים:","וכולן שחסרו: איבעיא להו חסרון דחוץ שמיה חסרון או לא שמיה חסרון","מי אמרינן כיון דנפק איפסלו להו מה לי חסר מה לי יתר או דילמא יוצא דאיתיה בעיניה אין דליתיה בעיניה לא","אמר אביי ת\"ש ר' אליעזר פוטר עד שיקריב את כולן","אמר ליה רבה בר רב חנן לאביי מדר' אליעזר פשיט מר","אמר ליה בפירוש שמיע לי מיניה דרב עד כאן לא פליגי רבנן עליה דר' אליעזר אלא דאיתיה בעיניה אבל בחסרון מודו ליה לאו דחסר בחוץ לא דחסר בפנים","ת\"ש וכולן שחסרו והקריבן בחוץ פטור לאו דחסר בחוץ לא דחסר בפנים:","המקריב קדשים: אמאי והאיכא חציצה","אמר שמואל כשהפכן","ור' יוחנן אמר אפילו תימא שלא הפכן והא מני רבי שמעון היא דאמר אפילו העלו על הסלע חייב","רב אמר מין במינו אינו חוצץ:","\u0001מתני׳\u0002 מנחה שלא נקמצה והקריבה בחוץ פטור קמצה וחזר קומצה לתוכה והקריבו בחוץ חייב:","\u0001גמ׳\u0002 ואמאי ליבטלי שירים לקומץ","אמר רבי זירא נאמרה הקטרה בקומץ ונאמרה הקטרה בשירים מה הקטרת קומץ אין קומץ מבטל חבירו אף הקטרת שירים אין שירים מבטלין קומץ:","\u0001מתני׳\u0002 הקומץ והלבונה שהקריב את אחד מהן בחוץ חייב ר' אליעזר פוטר עד שיקריב את השני אחד בפנים ואחד בחוץ חייב","שני בזיכי לבונה שהקריב את אחד מהם בחוץ חייב ר' אליעזר פוטר עד שיקריב את השני אחד בפנים ואחד בחוץ חייב:","\u0001גמ׳\u0002 בעי ר' יצחק נפחא קומץ מהו שיתיר כנגדו בשירים מישרא שרי או קלושי מיקלש","אליבא דמאן אי אליבא דרבי מאיר דאמר מפגלין בחצי מתיר מישרא שרי","אי אליבא דרבנן דאמרי אין מפגלין בחצי מתיר לא מישרא שרי ולא מקלש קליש","אלא אליבא דרבי אליעזר ר\"א כרבנן סבירא ליה דאמר אין מפגלין בחצי מתיר","אלא אליבא דרבנן דהכא מאי מישרא שרי או קליש מקלש","תיקו:","\u0001מתני׳\u0002 הזורק מקצת דם בחוץ"],[[0,"ורבנן סברי","קביעותא דמנא לאו כלום היא:"],[1,"קבע ששה לוגין","דהוא חצי ההין לנסכי פר ונתנן בכלי ומשך ארבעה מהן והקריבן בחוץ חייב שהרי ראויין בפנים לאיל:"],[3,"פטור","דבציר משלשת לוגין לא חזו בפנים:"],[4,"רב אשי אמר","לעולם כדתרצה אביי דבהקטרה של פנים בחוץ פליגי ובמילף פנים מחוץ ודקא קשיא לך השתא חוץ מחוץ לא ילפי רבנן כו' לא דמי ניסוך להקטרה דניסוך מהקטרה לא ילפי רבנן ואע\"ג דחוץ מחוץ אבל קטרת של פנים מקטרת של היכל ילפי ואע\"ג דפנים מחוץ:"],[6,"חסרון דחוץ","הוציאן שלימים לחוץ וחסרו לאיבוד:"],[6,"שמיה חסרון","ואם העלה את המשוייר בחוץ פטור:"],[6,"או לא שמיה חסרון","וחייב לרבנן כאילו כולו קיים:"],[7,"איפסיל ליה","ואפי' הכי מיחייב עליה בחוץ ומה לי יוצא ומה לי חסרון:"],[8,"עד שיקריב כולו","אלמא כוליה בעינן:"],[9,"מדרבי אליעזר פשיט מר","בתמיה רבי אליעזר אפי' בכולו קיים נמי פטר ואנן לרבנן מיבעי לן דמחייבי בכולו קיים ומודו בשחסר בפנים:"],[12,"והאיכא חציצה","שהבשר אינו ראוי להקטרה חוצץ בין אימורין למערכה ודכוותיה בפנים לאו העלאה היא דרחמנא אמר (ויקרא א׳:ח׳) על העצים אשר על האש וקס\"ד דמתני' רבי יוסי היא דאמר אינו חייב עד שיעלה לראש המזבח כהקטרת פנים:"],[13,"כשהפכן","החלבים למטה:"],[16,"מתני' מנחה שלא נקמצה","לא חזי לפנים הילכך המקריבה בחוץ פטור:"],[16,"קמצה וחזר קומצה לתוכה והקריבה בחוץ חייב","שכיוצא בה בפנים כשירה כדתנן בהקומץ (מנחות דף כג.) נתערב קומצה בשיריה לא יקטיר ואם הקטיר עלתה לבעלים:"],[17,"גמ' וניבטלי שירים לקומץ","ברובא והוי כמאן דליתיה ולא ניחייב עליה ובמנחות (דף כג:) נמי פרכינן לה גבי הקטרת פנים:"],[18,"נאמר הקטרה בקומץ","וקמץ והקטיר (ויקרא ב):"],[18,"ונאמר הקטרה בשירים","לא תקטירו ממנו אשה לה' (שם) כל שממנו לאשים הרי הוא בבל תקטירו דהיינו שירים:"],[18,"אין קומץ מבטל קומץ","ואפי' רבה עליו כדאמרינן בהקומץ רבה (מנחות דף כב.) ולקח מדם הפר ומדם השעיר הדבר ידוע שדם הפר מרובה מדם השעיר מכאן לעולין שאין מבטלין זה את זה:"],[19,"מתני' הקומץ והלבונה","של מנחת נדבה שניהם מתירין את שיריה לאכילה הילכך רבי אליעזר פוטר דבעי הקטרת כל המתיר:"],[19,"אחד בפנים","תחילה ואחר כך השני בחוץ:"],[19,"חייב","שזה גמר ובו הכל תלוי:"],[20,"שני בזיכי לבונה","מתירין לחם הפנים דכתיב (ויקרא כ״ד:ז׳) והיתה ללחם לאזכרה ואמרינן נאמר כאן אזכרה ונאמר להלן אזכרה מה להלן קומץ מתיר את השירים אף הלבונה מתרת את הלחם ובשירי מנחה כתיב (ויקרא ו׳:ט׳) יאכלו אהרן ובניו קדש קדשים מאשי ה' אין לנו אלא לאחר מתנות האשים:"],[21,"גמ' מהו שיתיר כנגדו בשירים","הקטיר קומץ לבדו על מנת להתיר חצי השירים ובוררן לחלקן:"],[21,"מהו","לאוכלן:"],[21,"מישרא שרי","פלגא לגמרי:"],[21,"או אקלושי מקליש","לאיסורא דכולהו שירים וקומץ ולבונה תרוייהו אכולהו שיריים דמו וכי מקטיר לחד מקליש ליה איסורייהו ומיהו לא אישתרי מידי מינייהו לגמרי:"],[22,"","פלוגתא דרבי מאיר ורבנן במנחות בהקומץ זוטא (דף טז.):"],[22,"מפגלין בחצי מתיר","פיגל בקומץ או בלבונה שהקטיר קומץ ע\"מ לאכול זית מן השירים חוץ לזמנו פיגול:"],[22,"מישרא שרי","דאי כי מקטיר ליה בשתיקה לא שרי כזית מינייהו לגמרי היכי הויא מחשבה בההוא זית הא דומיא דזריקה בעינן דשרי לגמרי:"],[23,"לא מישרא שרי כו'","כלומר דילמא לא הא ולא הא והיכי פשיטא ליה לר' יצחק נפחא דאו הא או הא עביד:"],[24,"אלא אליבא דר\"א","קמיבעיא דאמר לא מחייב עלה לחודיה בחוץ ומשום הכי מספקא ליה לרבי יצחק דילמא שרי:"],[24,"ר\"א כרבנן ס\"ל","ולא שריא ולא מיקלש לשון קושיא הוא אמאי פשיטא ליה אליביה דאו הא או הא והא ר\"א מדקאמר לאו הקטרה הוא כרבנן דפליגי עליה דר\"מ סבירא ליה:"],[25,"אלא אליבא דרבנן דהכא","דמחייבי אחד מינייהו אלמא הקטרה היא בפנים וקא מיבעי ליה למאי הילכתא הויא הקטרה למישרי פלגא או לאקלושי והכא ליכא למיפשט מדמחייבי עלה בחוץ ש\"מ מישרא שרי דאי נמי לאקלושי אתיא הויא הקטרה לחיובי בחוץ עלה:"],[27,"מתני' הזורק מקצת דמים","כגון מתנה אחת ואפילו מחטאות הפנימיות שכל מתנותיהן מעכבות:"]],[[10,"אבל בחסרון מודו ליה","ומסיק בחסרו מבפנים ותימה מאי קא משמע לן תנינא לעיל (זבחים דף קט:) וכולן שחסרו כל שהוא כו' וכל הפחות היינו חסרו מבפנים:"],[13,"אמר שמואל כשהפכן","וכי תימא מאי קמ\"ל סד\"א דאין דרך הקטרה בכך:"],[15,"מין במינו אינו חוצץ","והא דאמרינן לעיל (זבחים דף טו:) גבי רגל חבירו פסול אין דרך שירות בכך:"],[21,"קומץ מהו שיתיר כנגדו בשירים","פירש בקונטרס דהקטיר קומץ לבדו על מנת להתיר חצי השירים ובוררן לחלקן מהו לאוכלן מישרא שרי פלגא לגמרי או אקלושי מקלש לאיסורא דכולהו שירים וקומץ ולבונה תרוייהו אכולהו שירים דמו וכי מקטיר חד איקליש ליה איסורייהו ומיהו לא אישתרי מידי מינייהו לגמרי עכ\"ל והא דתנן בהקומץ רבה (מנחות דף כז.) הקומץ והלבונה מעכבין זה את זה היינו דבעי שיהו שניהם דלא לייתי מנחה בלא לבונה ובעי קמיצה ומכל מקום תימה דאפילו למאן דאמר מישרא שרי לה היאך מתברר חלקו של קומץ ונראה לפרש דלאו לאשתרויי באכילה קאמר אלא דאי משרא שרי פלגא אידך פלגא באיסור' קיימא ואי אכיל לה לקי כמו אוכל בשר חטאת ואשם קודם זריקה ואי איקלושי מקליש לכולה מנחה לא לקי כלל אי נמי לענין מעילה וכי האי גוונא בנדרים בפרק נערה (נדרים דף סח.) בעל מיגז גייז או אקלושי מיקליש כגון דנדרה מן תרין זיתין ושמע ארוס והפר לה ואכלתינון אי אמר מיגז גייז לקיא אי אמר מקלש קליש איסורא בעלמא הוא:"],[24,"ואי אליבא דר\"מ דאמר מפגלין בחצי מתיר","הך סוגיא דלא כריש לקיש דאמר לעיל בפרק בית שמאי (זבחים דף מא:) טעמא דרבי מאיר משום דכל העושה על דעתו ראשונה הוא עושה וצ\"ע אי שחט סימן אחד וקבל אחד דמו וזרקו כיון דחשיב חצי מתיר אי אמרינן מישרא שרי ומיהו הא פשיטא אי לא גמר אחר כך שחיטתו לא שרי:"]]],[["חייב ר\"א אומר אף המנסך מי החג בחג בחוץ חייב רבי נחמיה אומר שירי הדם שהקריבו בחוץ חייב:","\u0001גמ׳\u0002 אמר רבא ומודה רבי אלעזר בדמים","דתניא רבי אלעזר ורבי שמעון אומרים ממקום שפסק הוא מתחיל:","רבי אלעזר אומר אף המנסך מי החג [בחג] בחוץ: א\"ר יוחנן משום רבי מנחם יודפאה רבי אלעזר בשטת רבי עקיבא רבו אמרה דאמר ניסוך המים דאורייתא דתניא רבי עקיבא אומר (במדבר כט, לא) ונסכיה בשני ניסוכים הכתוב מדבר אחד ניסוך המים ואחד ניסוך היין","אמר ליה ריש לקיש לר' יוחנן אי מה להלן שלשת לוגין אף כאן שלשת לוגין והא ר\"א מי החג קאמר אי מה להלן בשאר ימות השנה אף כאן בשאר ימות השנה [ור\"א] בחג קאמר","אישתמיטתיה הא דאמר רבי אסי דאמר רבי אסי אמר רבי יוחנן משום רבי נחוניא איש בקעת בית חורתן עשר נטיעות ערבה וניסוך המים הלכה למשה מסיני","תנו רבנן המנסך שלשת לוגין מים בחג בחוץ חייב ר\"א (בר\"ש) אומר אם מלאן לשם חג חייב","מאי בינייהו אמר רב נחמן בר יצחק ביש שיעור במים קמיפלגי","רב פפא אמר"],[[0,"חייב","לרבנן דלא בעו כולו מתיר ורבי אלעזר נמי מודה בה כדאמרינן בגמרא:"],[0,"מי החג","שנתמלאו לשם ניסוך המים בחג הסוכות:"],[0,"שירי הדם","של חטאות הטעונין שפיכה ליסוד שהקריב בחוץ חייב דקסבר שירים מעכבין הילכך מתקבלים בפנים וזריקה גמורה הן:"],[1,"גמ' מודה ר' אלעזר בדמים","ואפי' בחטאות הפנימיות דהא בפנים אם נשפך הדם אחר שנתן מתנה אחת מהניא הך דיהבה ומביא פר אחר ומתחיל ממקום שפסק:"],[3,"דתנן כו'","במסכת יומא בהוציאו לו (יומא דף ס.):"],[3,"יודפאה","דמן יודפת:"],[3,"ניסוך המים דאורייתא","הילכך בחוץ נמי מיחייב עלה:"],[4,"אמר ליה ריש לקיש","אי רבי אלעזר מההוא קרא יליף ובההוא קרא מים ויין איתקוש אלמא שלשת לוגין בעינן כנסכי יין של עולת התמיד:"],[4,"והא ר' אלעזר מי החג קאמר","ואפילו פחות משלשת לוגין דאיכא למאן דאמר סוכה (דף מח.) בלוג היה מנסך:"],[4,"בחג קאמר","בלשון קושיא גרסינן ליה:"],[5,"אישתמיטתיה","למנחם יודפאה:"],[5,"הא דא\"ר יוחנן כו'","אלמא לכולי עלמא דאורייתא הוא הילכך איכא למ\"ד בלוג גמירי לה או אין להם שיעור:"],[7,"[מאי בינייהו]","במאי קמיפלגי ומאי קא אתי רבי אלעזר למימר:"],[7,"ביש שיעור למים","דקאמר תנא קמא המנסך שלשת לוגין חייב והוא הדין יותר משלשת לוגין דיש בכלל מאתים מנה ואף על גב דמלינהו בכלי גדול קדשינהו כלי דאין שיעור למי החג למעלה ואתא רבי אלעזר למימר והוא שמילאן לשם חג כדרך מילואן דהיינו שלשת לוגין ותו לא כדתנן (שם) צלוחית של זהב מחזקת שלשת לוגין ממלא מן השילוח אבל אי הוי טפי לא קדשינהו כלי דלא חזו ליה דיש שיעור למים ואין כלי שרת מקדשין אלא הראוי להם:"]],[[1,"ומודה רבי אלעזר בדמים","תימה מאי קמ\"ל רבא מתניתין היא דהא תנן רבי אלעזר אומר אף המנסך כו' שמע מינה דמודה ברישא וי\"ל דסלקא דעתך דרבי אלעזר קאי אהנהו דלעיל ולא אמקצת דמים ועוד י\"ל דמתניתין איכא לאוקומי בדמים החיצונים דבמתנה אחת כיפר ואתא רבא לאשמועינן דאפילו בפנימיים דכל מתנות מעכבות אפ\"ה מודה ר\"א דחייב על מקצת בחוץ דתניא ר\"א אומר ממקום שפסק הוא מתחיל ולעיל נמי בפרק בית שמאי (זבחים דף מב.) דאמר והאמר רבא מודה ר\"א בדמים גבי חטאות פנימיות מייתי לה:"],[4,"אי מה להלן בשאר ימות השנה אף כאן בשאר ימות השנה","תימה דהא רבי עקיבא מודה דאין ניסוך המים אלא בחג ויש ספרים דגרסי הסך נסך בשני ניסוכים וההוא קרא בתמיד כתיב וליתא דר' נתן גריס הכי בריש מסכת תענית (דף ג.) ואפילו לרבי נתן נמי לא מישתמיט תנא דלימא ניסוך המים כל השנה כולה ואמר רבינו תם דמצא בספרים ישנים אי מה להלן בשאר ימות החג לא דלרבי עקיבא לא רמזה אלא בששי ואמרינן במסכת תענית (שם) אלא הך דתנן ניסוך המים כל שבעה מני אי רבי עקיבא האמר בששי מזכיר תרי יומי הוו ורבי אלעזר בחג קאמר משמע כל ימות החג ונראה שפיר ליישב גרסת הספרים דאף על גב דאין ניסוך המים אלא בחג מכל מקום חייבין עליו בחוץ כל השנה כדאשכחן בשמעתין למאן דאמר קרבו נסכים במדבר דמחייב בלא כלי שרת אע\"ג דאין מתקבל בפנים הואיל ובשעת היתר הבמות קריבים בלא קדושת כלי וכדאמרינן לעיל (זבחים דף קח:) במעלה על גבי הסלע דמשום דהויא הקטרה בבמת יחיד מחייב עליו בחוץ בשעת איסור הבמות ומיהו לא דמי דאין לך מחוסר זמן גדול מזה וכיון דהשתא לא חזו בפנים היכי מיחייב ואמרינן ביומא בריש פרק שני שעירי (יומא דף סב:) שלמים ששחטן בחוץ קודם שיפתחו דלתות ההיכל פטור מ\"ט מחוסר פתיחה כמחוסר מעשה דמי וא\"ת ומאי שנא נסכים בכלי חול מקבלת דם בכלי חול דאמר רבא לעיל דקבלה בכלי חול לרבי פטור ויש לומר דלא דמי לקבלה בכלי חול בפנים וזרק בחוץ אין לנו לחייב מחמת דכשר בבמה הואיל וכבר נפסל בפנים ולא דמי לנסכים שמקריבין בחוץ בכלי חול דלא נפסלו בפנים:"],[5,"אישתמיטתיה כו'","פי' בקונטרס למנחם יודפאה ותימה דהא רבי יוחנן אמרן לתרוייהו ושמא לבתר הכי שמעה רבי יוחנן וי\"ל דאישתמיטתיה לריש לקיש דאי הוה שמעה לא היה מקשה כלום דהוי מצי לפרושי בשיטת רבי עקיבא רבו אמרה דאמר ניסוך המים דאורייתא ולאו מטעמיה ולפי זה משמע דאיכא למאן דאמר ניסוך המים דרבנן וזהו תימה דאפילו למאן דאמר (מנחות דף קו.) חולין בעזרה לאו דאורייתא שתקנו חכמים לנסך חולין בעזרה שמא לפי שהוא אז זמן גשמים כדי שיזכרו לפני המקום להתברך במי גשמים וקצת משמע בריש לולב וערבה (סוכה דף מד.) דריש לקיש הוה ידע להא דר' יוחנן דעשר נטיעות ערבה וניסוך המים גבי הא דאמר ריש לקיש התם כהנים בעלי מומין היו נכנסים בין האולם ולמזבח כדי לצאת בערבה ושמא נהי דשמיע ליה ערבה ניסוך המים לא שמיע ליה ומיהו לא יתכן פי' זה לפי' הקונטרס במעילה פרק ולד חטאת (מעילה דף יג:) דתנן התם נתנן לצלוחית מועלין בהן אמר ריש לקיש אין מועלין אלא בשלשת לוגין ורבי יוחנן אמר מועלין בכולן ופריך למימרא דקסבר ריש לקיש יש שיעור למים והא תנן רבי אלעזר אומר אף המנסך מי החג בחוץ חייב ואמר רבי יוחנן משום ר' מנחם יודפאה רבי אלעזר בשיטת רבי עקיבא אמרה דדריש ונסכיה אחד נסכי יין ואחד נסכי מים ואמר ליה ריש לקיש אי מה יין שלשת לוגין אף מים נמי שלשת לוגין מכלל דקסבר ריש לקיש אין שיעור למים ומשני לטעמיה דמנחם יודפאה קאמר ופי' בקונטרס דריש לקיש דאמר יש שיעור למים היינו לטעמיה דמנחם דאמר רבי אלעזר בשיטת רבי עקיבא אבל איהו סבירא ליה כרבי יוחנן רביה דאין שיעור למים ומיהו לא יתכן אותו פי' דמעילה דלמה ליה למימר לטעמא דמנחם יודפאה הוה ליה למימר לטעמיה דרבי עקיבא ורבי אלעזר ור' נתן ונראה לפרש לטעמיה דמנחם יודפאה היינו מה שהקשה אי מה להלן שלשת לוגין דלרבי עקיבא יש שיעור ורבי אלעזר מי החג קאמר אלמא סבירא ליה אין שיעור ולא משום דסבירא ליה כרבי אלעזר דר\"ל קסבר יש שיעור אלא לאפוקי ממנחם יודפאה קאתי דאמר רבי אלעזר בשיטת רבי עקיבא:"],[7,"ביש שיעור במים קא מיפלגי","פירש בקונטרס דקאמר תנא קמא המנסך שלשת לוגין חייב והוא הדין יותר מג' לוגין דיש בכלל מאתים מנה ואע\"ג דמלינהו בכלי גדול קדשינהו כלי דאין שיעור למי החג למעלה ואתא רבי אלעזר למימר והוא שמלאן לשם חג כדרך מילואן דהיינו שלשת לוגין ותו לא כדתנן צלוחית של זהב מחזקת שלשת לוגין ממלא מן השילוח אבל אי הוו טפי לא קדשינהו כלי דלא חזו ליה דיש שיעור למי החג ואין כלי שרת מקדשין אלא הראויין להן עד כאן לשונו וקשה דהא רבי אלעזר מי החג קאמר לעיל דאין שיעור למים כלל לא למעלה ולא למטה כדמוכחא נמי ההיא דמעילה (שם) ומפרש הר' חיים איפכא דתנא קמא סבר יש שיעור דנקט שלשת לוגין לא פחות ולא יותר ואתא רבי אלעזר למימר והוא שמלאן לשם חג דקבעינהו מנא דרבי אלעזר לטעמיה דאמר לעיל קביעותא דמנא מילתא הוא אבל לא קבעינהו מנא חייב בפחות משלשת לוגין דאין שיעור למים ור' אלעזר לטעמיה דאמר במתני' מי החג:"]]],[["בקרבו נסכים במדבר פליגי","רבינא אמר בלמדין ניסוך המים מניסוך היין פליגי","ת\"ר המנסך שלשה לוגין יין בחוץ חייב ר' אלעזר בר\"ש אומר והוא שקדשן בכלי","מאי בינייהו אמר רב אדא בר רב יצחק בירוצי מידות איכא בינייהו","רבא בריה דרבה אמר קרבו נסכים בבמה איכא בינייהו","ובפלוגתא דהני תנאי דתניא במת יחיד אינה צריכה נסכים דברי רבי וחכ\"א טעונה נסכים","והני תנאי כהני תנאי דתניא (במדבר טו, ב) כי תבאו להטעינה נסכים בבמה גדולה הכתוב מדבר","אתה אומר בבמה גדולה או אינו אפי' בבמה קטנה כשהוא אומר (במדבר טו, ב) אל ארץ מושבותיכם וגו' אשר אני נותן לכם הרי בבמה הנוהגת לכולכם הכתוב מדבר דברי רבי ישמעאל","ר\"ע אומר כי תבאו להטעינה נסכים בבמה קטנה הכתוב מדבר","אתה אומר לבמה קטנה או אינו אלא לבמה גדולה כשהוא אומר אל ארץ מושבותיכם הרי בבמה הנוהגת בכל מושבות הכתוב מדבר","כשתמצא לומר לדברי רבי ישמעאל לא קרבו נסכים במדבר ולדברי ר\"ע קרבו נסכים במדבר:","רבי נחמיה אומר שירי הדם שהקריבן בחוץ חייב:","א\"ר יוחנן [תנא] רבי נחמיה כדברי האומר שיריים מעכבין","מיתיבי רבי נחמיה אומר שירי הדם שהקריבן בחוץ חייב אמר לו ר\"ע והלא שירי הדם שירי מצוה הם אמר לו איברין ופדרין יוכיחו שהן שירי מצוה והמקריבן בחוץ חייב אמר לו לא אם אמרת באיברים ופדרים שהן תחלת עבודה תאמר בשירי הדם שאינן תחלת עבודה","ואם איתא לימא ליה הני נמי מעכבי תיובתא","והשתא דאמר רב אדא בר אהבה מחלוקת בשיריים הפנימיים אבל בשיריים החיצונים דברי הכל לא מעכבי כי קאמר רבי נחמיה בשיריים הפנימים כי תניא ההיא בשיריים החיצונים","(ורבי עקיבא לא ידע מאי קאמר רבי נחמיה הוא סבר רבי נחמיה שיריים חיצונים אמר וקא מהדר ליה שיריים החיצונים ורבי נחמיה) לדבריו דר' עקיבא קאמר:","\u0001מתני׳\u0002 המולק את העוף בפנים והעלה בחוץ חייב מלק בחוץ והעלה בחוץ פטור השוחט את העוף בפנים והעלה בחוץ פטור"],[[0,"בקרבו נסכים במדבר קמיפלגי","ותרוייהו אית להו יש שיעור למים וכי מלי טפי לא קדשינהו כלי ותנא קמא דמחייב לא בעי בנסכים קדושת כלי לחייב עליהן בחוץ דקסבר קרבו נסכים באהל מועד שבמדבר כל ארבעים שנה הילכך ביאת הארץ האמורה בפרשת נסכים בשלח לך ללמדנו בא שבשבע של כיבוש הארץ ושבע של חילוק הארץ כשהיו בגלגל והותרו הבמות כדתנן בפרק בתרא (לקמן זבחים דף קיב:) תהא במה קטנה של כל יחיד טעונה נסכים דמשום במת ציבור לא איצטריך למימר ביאת הארץ דהא מן המדבר נתחייבו בכך וכיון דבמות יחיד טעונין נסכים והתם כלי שרת ליכא כדאמר בפרק בתרא (לקמן זבחים דף קיג.) בחוץ נמי מיחייב עלייהו בשעת איסור הבמות בלא קידוש כלי הואיל ובשעת היתר הבמות קריבין בלא קדושת כלי כדאמרן לעיל במעלן על גבי סלע משום דהויא הקרבה בבמת יחיד בשעת היתר הבמות מיחייב עלה בשעת איסור דהא בפנים אם עלה לא ירד כדאמרן לעיל (זבחים דף פד:) מנין ליוצא אם עלה לא ירד שהרי יוצא כשר בבמה ור' אלעזר סבר לא קרבו נסכים במדבר וביאת הארץ האמור בנסכים לאחר ירושה וישיבה לאחר שקבעו משכן בשילה הוא דנתחייבו לפיכך הוצרכה ביאת הארץ לכתוב משום שכל ארבעים שנה שבמדבר לא קרבו במשכן ובא הכתוב לחייבו בשילה ובית עולמים ולא בשנות הכיבוש והחילוק בבמות הקטנות הילכך לא קרבו נסכים בבמה קטנה שהיא שלא בכלי שרת ואי אסקינהו בשאין מוקדשין בחוץ לא מיחייב עלייהו והכי נמי אמרינן לקמן דמאן דבעי קדושת כלי בנסכים סבר לא קרבו נסכים במדבר:"],[1,"רבינא אמר בלמדין ניסוך המים כו'","ודכ\"ע קרבו נסכים במדבר וביאת הארץ האמור בנסכים לבמה קטנה אתא וקרבו בבמה בלא קידוש כלי ומיהו בניסוך היין אשכחן בניסוך המים לא אשכחן דהא חובת ציבור הן ולא קרבו אלא בבמת ציבור בכלי שרת ובהא פליגי תנא קמא סבר למידין ניסוך המים מניסוך היין לחייב בחוץ ואפי' לא קדשו בכלי ורבי אלעזר סבר אין למידין וניסוך היין הוא דמתחייב בחוץ בלא כלי אבל ניסוך המים קדשו אין לא קדשו לא:"],[3,"מאי בינייהו","במאי פליגי:"],[3,"בירוצי המדות","מה שצף על שפת הכלי ותרוייהו קדושת כלי בעו מיהו רבנן סברי בירוצי מדות של לח נתקדשו ורבי אלעזר סבר לא נתקדשו ותוך כלי בעינן ופלוגתא דתנאי היא במנחות (דף פח.):"],[4,"רבה בריה דרבא אמר","תנא קמא לא בעי קדושת כלי ובקרבו נסכים במדבר קמיפלגי לתנא קמא קרבו לרבי אלעזר בר\"ש לא קרבו כדפרישית:"],[5,"ובפלוגתא דהני תנאי","ר\"א בר\"ש [כרבי] דאמר אין נסכים בבמה קטנה הילכך לא אשכחן ניסוך בלא קידוש כלי ות\"ק כרבנן ס\"ל דאמרי יש נסכים בבמת יחיד ואשכחן ליה בלא כלי שרת:"],[6,"כי תבאו","בפרשת נסכים כתיב בשלח לך:"],[6,"להטעינה נסכים בבמה גדולה","בא הכתוב ללמדך שלא קרבו נסכים במדבר ומשבאו לארץ נתחייבו בהן ובבמת ציבור ולא בבמת יחיד:"],[7,"או אינו אלא בבמה קטנה","דאילו בבמה גדולה במדבר נמי קרבי ומיהו עד השתא במה קטנה לא הואי דכל מ' שנה נאסרו הבמות משהוקם המשכן וכשנכנסו לארץ הותרו בשנים שכיבשו וחילקו ובא הכתוב להטעינם נסכים לקדשי במת יחיד: כשהוא אומר אשר אני נותן לכם כו':"],[8,"ורבי עקיבא אומר להטעינה נסכים לבמה קטנה","דאגדולה לא איצטריך דהא במדבר נמי קרבי:"],[9,"או אינו אלא לבמה גדולה","ואשמועינן קרא דלא קרבו נסכים במדבר:"],[9,"בכל מושבות","דהיינו במת יחיד דאילו במת ציבור אינה אלא במקום אחד ור' ישמעאל משמע ליה מושבות לאחר ירושה וישיבה:"],[12,"תנא ר' נחמיה","במתני' כדברי האומר באיזהו מקומן (לעיל זבחים דף נב.) שירי הדם מעכבין בחטאת הילכך עבודה היא להתחייב עליה בחוץ כשאר זורק מקצת דמים:"],[13,"שירי מצוה הן","שאין מעכבין את הכפרה כדאמר באיזהו מקומו (שם) יכול יעכבנו תלמוד לומר ואת כל הדם נתקו הכתוב ועשאו שירי מצוה:"],[13,"הקטר איברים ופדרים","אין מעכבין את הכפרה דאין כפרה אלא בדם:"],[14,"ואם איתא","דלרבי נחמיה מעכבין נימא ליה הני נמי כתחילת עבודה הן כשאר מתנות:"],[15,"מחלוקת","באיזהו מקומן דעיכוב שירים:"],[15,"בחטאות הפנימיות","כל מתנותיהן מעכבות:"],[15,"וכי תניא ההיא","דאודי ליה רבי נחמיה דשירי מצוה הן בשירים החיצונים ומודה רבי נחמיה בהו דהמקריבן בחוץ פטור:"],[16,"אי הכי","אמאי אהדר ליה הקטר איברים יוכיח נימא ליה כי אמרי בפנימים ולא בחיצונים ואת אמרת לי חיצונים:"],[16,"ה\"ג אלא לדבריו דרבי עקיבא קא\"ל","לדידי שירים מעכבין לדידך נמי דאמרת שירי מצוה הן הקטר איברים יוכיח:"],[17,"מתני' מלק בחוץ","נבלה היא שאין מליקה אלא בפנים לפיכך פטור על העלאתו ועל מליקתו נמי פטור כדאמרן בריש פירקין (זבחים דף קז.) השוחט ולא המולק:"],[17,"השוחט את העוף בפנים","פסול ושוב אינו ראוי בפנים לפיכך פטור על העלאתו בחוץ ואם תאמר והלא כל העולין בחוץ נפסלין ביציאתן וכל השוחט בחוץ פסול הוא וחייבין על העלאתו התם רחמנא רבייה אבל לענין שאר פסולין מתקבל בפנים בעינן:"]],[[0,"בקרבו נסכים במדבר קא מיפלגי","פי' בקונטרס ותרוייהו אית להו יש שיעור למים ואי אפשר לומר כן דר\"א על כרחין סבר אין שיעור אלא תרוייהו סברי אין שיעור ושלשת לוגין דתנא קמא לאו דוקא:"],[6,"במה גדולה ובמה קטנה","יש מפרשים דבמה גדולה קרי שעת איסור הבמות ובמה קטנה שעת היתר ופירוש הקונטרס עיקר דתרוייהו היתר הבמות אלא דבמה גדולה היא במת ציבור ובמה קטנה היא במת יחיד ואע\"ג דרבי ישמעאל אמר להטעינה נסכים לבמה גדולה ודריש מושבות לאחר ירושה וישיבה כדפירש בקונטרס וכדתניא בספרי ובפרק קמא דקדושין (דף לז.) ואז נאסרו הבמות שבאו לשילה ומ\"מ אף כשהותרו אחרי כן בנוב וגבעון מודה רבי ישמעאל דבמת ציבור טעונה נסכים:"],[10,"לדברי רבי ישמעאל לא קרבו נסכים במדבר","בקדושין (ג\"ז שם) פירש בקונטרס דלכולי עלמא קרבו בקרבן ציבור ואיני יודע מי הזקיקו לכך ושמא משום דקתני בסיפרי אמר אחד מתלמידי רבי ישמעאל בא הכתוב ללמדך על הנסכים שלא נתחייב יחיד על הנסכים אלא מביאתן לארץ וזה לשון הקונטרס דפירש בקדושין (ג\"ז שם) ר' ישמעאל סבר לא קרבו נסכים במדבר ואף על גב דכתיב במילואים וזה אשר תעשה על המזבח וכתיב בה נסכים בעולת תמיד בקרבן ציבור הוא דהוי אבל היחידים לא נתחייבו בנסכים אלא מביאת הארץ לאחר ירושה וישיבה ורבי עקיבא סבר קרבו נסכים ליחיד במדבר:"],[15,"כי קאמר רבי נחמיה בשיריים הפנימיים","לעיל בפרק ב\"ש (זבחים דף לט.) משמע דרבי נחמיה איירי בשיריים החיצונים ושם פירשתי:"],[15,"וכי תניא ההיא בשיריים החיצונים","ומה שהשיב לו איברים יוכיחו אע\"ג דאיהו גופיה לא חייש בהאי טעמא אורחיה דתנא הכי כדפרישית בפרק התערובת (לעיל זבחים דף עז:):"]]],[["שחט בחוץ והעלה בחוץ חייב","נמצא דרך הכשירו בפנים פטורו בחוץ דרך הכשירו מבחוץ פטורו בפנים","ר\"ש אומר כל שחייבין עליו בחוץ חייבין על כיוצא בו בפנים שהעלה בחוץ חוץ מן השוחט בפנים ומעלה בחוץ:","\u0001גמ׳\u0002 האי הכשירו חיובו הוא תני חיובו:","ר\"ש אומר [וכו']: אהיכא קאי","אילימא ארישא קאי המולק עוף בפנים והעלה בחוץ חייב מלק בחוץ והעלה בחוץ פטור וא\"ל ר\"ש כי היכי דפנים מיחייב בחוץ נמי מיחייב האי כל שחייבין עליו בחוץ כל שחייבין עליו בפנים מיבעי ליה","אלא כי היכי דבחוץ לא מיחייב בפנים נמי לא ליחייב האי כל שאין חייבין עליו בחוץ מיבעי ליה","אלא אסיפא קאי השוחט עוף בפנים והעלה בחוץ פטור שחט בחוץ והעלה בחוץ חייב ואמר ליה ר\"ש כי היכי דבפנים לא מיחייב בחוץ נמי לא מיחייב האי כל שאין חייבין מיבעי ליה","אלא כי היכי דבחוץ מיחייב בפנים נמי מיחייב הא קתני חוץ מן השוחט בפנים והמעלה בחוץ","אמר זעירי שחיטת בהמה בלילה איכא בינייהו והכי קאמר [וכן] השוחט בהמה בפנים בלילה והעלה בחוץ פטור שחט בחוץ בלילה והעלה בחוץ חייב","ר\"ש אומר כל שחייבין עליו בחוץ חייבין על כיוצא בו בפנים והעלה בחוץ חוץ מן השוחט עוף בפנים והעלה בחוץ","רבא אמר קבלה בכלי חול איכא בינייהו וה\"ק [וכן] המקבל בכלי חול בפנים והעלה בחוץ פטור המקבל בכלי חול בחוץ והעלה בחוץ חייב","ר\"ש אומר כל שחייבין עליו בחוץ חייבין על כיוצא בו בפנים והעלו בחוץ חוץ מן השוחט עוף בפנים והעלו בחוץ","השתא דתני אבוה דשמואל בר רב יצחק המולק עוף בפנים והעלו בחוץ חייב מלק בחוץ והעלה בחוץ פטור ור\"ש מיחייב ר\"ש התם קאי ותני כל שחייבין עליו בפנים והעלה בחוץ חייבין עליו בחוץ:","\u0001מתני׳\u0002 חטאת שקבל דמה בכוס אחד נתן בחוץ וחזר ונתן בפנים בפנים וחזר ונתן בחוץ חייב שכולו ראוי בפנים","קבל דמה בשתי כוסות נתן שניהם בפנים פטור שניהם בחוץ חייב אחד בפנים ואחד בחוץ פטור אחד בחוץ ואחד בפנים חייב על החיצון והפנימי מכפר","למה הדבר דומה למפריש חטאתו ואבדה והפריש אחרת תחתיה ואח\"כ נמצאת הראשונה והרי שתיהן עומדות שחט שתיהן בפנים פטור שתיהן בחוץ חייב אחת בפנים ואחת בחוץ פטור אחת בחוץ ואחת בפנים חייב על החיצונה והפנימית מכפרת","כשם שדמה פוטר את בשרה כך היא פוטרת את בשר חבירתה:"],[[0,"שחט בחוץ והעלה בחוץ חייב","אף על העלאה שחיטה בחוץ בעוף רבייה רחמנא (ויקרא יז) מאו אשר ישחט ואהעלאתו נמי אמרינן לקמן (זבחים דף קיט:) ואליהם תאמר לערב פרשיות דכל שמתחייב על שחיטתו בחוץ אם חזר והעלן או הוא או אחר חייב:"],[1,"נמצא דרך הכשירו בפנים כו'","בגמרא פריך אסיפא דרך הכשירו בחוץ חיובו הוא דעוף קדשים אין לו הכשר בחוץ בשחיטה והכי איבעי למיתני דרך חיובו בחוץ פטורו בפנים דרך חיובו בפנים פטורו בחוץ כגון שחט בפנים והעלה בחוץ פטור שחט בחוץ והעלה בחוץ חייב מלק בפנים והעלה בחוץ חייב מלק בחוץ והעלה בחוץ פטור נמצא במקום שמתחייב על העלאתו אם נעשית עבודה הראשונה בפנים כגון במליקת פנים פטור על העלאתו אם נעשית עבודה ראשונה בחוץ ודרך שמתחייב על העלאה אם נעשית העבודה ראשונה בחוץ כגון בשחיטה פטורו בפנים אם נשחט בפנים והעלה בחוץ:"],[2,"ר\"ש אומר כל שחייבין עליו בחוץ חייבין על כיוצא בפנים והעלה בחוץ כו'","בגמרא מפרש לה ומיהו הכי משמע כל שחייבין על העלאתו כו' אם נעשית עבודתו כולו בחוץ חייבין עליו בנעשית עבודתו ראשונה בפנים ואח\"כ העלהו בחוץ חוץ מן השוחט עוף בפנים והעלה בחוץ דפטור ואילו דכותיה בחוץ הוה מתחייב אף בהעלאה:"],[3,"גמ' הכשרו חיובו הוא","דבחוץ מאי הכשר שייך למימר חיובו שייך למימר כדפרישית לעיל:"],[4,"ר\"ש אהייא","פליג:"],[5,"בחוץ נמי מיחייב","אם מלקו בחוץ נמי מחייב אהעלאתו בחוץ:"],[10,"חייבין על כיוצא בפנים והעלה בחוץ","והשוחט בהמה בלילה בפנים והעלה בחוץ חייב כאילו שוחטה בחוץ דהא בפנים אם עלתה לא תרד אית ליה בפרק המזבח מקדש (שם) דקתני ר\"ש אומר עולה אין לי אלא עולה כשירה מנין לרבות שנשחטה בלילה כו':"],[10,"חוץ מן השוחט העוף בפנים והעלה בחוץ","דפנים נמי אם עלה ירד דהא מיקטל קטליה כדאמרי' בהמזבח מקדש (לעיל זבחים דף פה.):"],[11,"שחיטת לילה בבהמה והעלה בחוץ איכא בינייהו","וחסורי מחסרא מתניתין במילתיה דתנא קמא והכי קאמר וכן השוחט בהמה בלילה בפנים והעלה בחוץ פטור דאינה מתקבלת בפנים דכתיב (ויקרא יט) ביום זבחכם ואפי' עלתה תרד ורבי יהודה היא דאמר בפרק המזבח (לעיל זבחים דף פד.) פרט לנשחטה בלילה:"],[11,"[וכן] המקבל בכלי חול בפנים והעלה בחוץ פטור","דהא בפנים אם עלה ירד דה\"ל כנשפך דמה ורבי יהודה היא דלית ליה אם עלו לא ירדו אלא בלן ויוצא ונשחט חוץ לזמנו וחוץ למקומו ושקיבלו פסולין את דמו בהנך פסולין דחזו לעבודת צבור כדמפרש בהמזבח מקדש (שם דף פד:):"],[12,"רבי שמעון אומר כו'","דהא בפנים נמי אית ליה אם עלתה לא תרד ואפי' נשפך דמה כדקתני התם:"],[13,"והשתא דתני אבוה דשמואל","דרבי שמעון מחייב אמלק בחוץ והעלה בחוץ תני במילתיה דר\"ש במתני' כל שחייבין עליו בפנים כגון המולק בפנים והמעלה בחוץ חייבין עליו בחוץ ודקתני סיפא חוץ מן השוחט בפנים ומעלה בחוץ כדיוקא קאי דאיכא למידק ממילתא דר\"ש הא כל שאין חייבין עליו בפנים והעלה בחוץ כגון קדשים פסולין שלא היה פסולן בקדש כגון הרובע והנרבע כו' אין חייבין עליהן אם שחטן בחוץ והעלן בחוץ אשחיטתן לא מיחייב דלא קרינא ביה ואל פתח אהל מועד לא הביאו והעלאתן מהיכא תיתי דהא לא קרינא ביה נמי אל פתח אהל מועד לא יביאנו חוץ מן השוחט עוף בפנים והעלו בחוץ שאף על פי שפטור על העלאתו בחוץ חייבין על כיוצא בו בשוחט בחוץ והעלה בחוץ דהא איתרבאי לעיל (זבחים דף קז.) שחיטתו מאו אשר ישחט והעלאתו מואליהם תאמר:"],[14,"מתני' נתן בחוץ וחזר ונתן בפנים חייב","כדי נסבה אלא משום סיפא דבעי מיתני בפנים וחזר ונתן בחוץ ואשמעינן דאע\"ג דשיריים נינהו מיחייב עלייהו וסתמא כרבי נחמיה:"],[15,"שניהם בחוץ חייב","אחת ואם היתה לו ידיעה בינתיים חייב שתים:"],[15,"אחד בפנים ואח\"כ השני בחוץ פטור","ואפילו לרבי נחמיה כדמפרש בגמרא דקסבר כוס אחד עושה את חבירו דחוי הילכך אפילו שיריים לא הוי:"],[15,"והפנימי מכפר","להכשיר הזבח כדאמרן בכל הזבחים שנתערבו (שם דף פב.) דלא עשה את המשוייר כיוצא בו:"],[16,"למה הדבר דומה","בגמרא מפרש למה לי לדמויינהו ומאי גמרי מהדדי:"],[16,"שתיהן בחוץ חייב","על כל אחת ואחת דבשעת שחיטה כל אחת היתה ראויה לפנים:"],[16,"אחת בפנים והשניה בחוץ פטור","דהויא לה חטאת שכיפרו בעליה ולמיתה אזלא ואינה מתקבלת בפנים:"],[16,"חייב על החיצונה","דהא חזיא לפנים דאיזו מהן שירצה יקריב:"],[16,"והפנימית מכפרת","על הבעלים:"],[17,"כשם שדמה פוטר בשרה","מן המעילה דזריקת דם מוציאה בשר קדשי קדשים מן המעילה דיהא בה שעת היתר לכהנים כך היא פוטרת את בשר חברתה ואע\"פ שפסולה ואשחט שתיהם בפנים קאי ואשמעינן דהיכא דמונח בכוסות וקדם וזרק את דם האחת פוטרת את חברתה מן המעילה משום חטאת שכיפרו בעליה דקיימא לן חטאות המתות לא נהנין ולא מועלין אבל משום שחוטי חוץ לא איצטריכא ליה דכמאן דקטלינהו דמי ולית בהו מעילה כדאמרינן בשמעתא קמייתא קדשים שמתו יצאו מידי מעילה ואגב גררא נסבה הכא איידי דנקטא משום שחיטת חוץ ובפרק קמא דמעילה (דף ו:) נמי קתני לה לכולה:"]],[[9,"השוחט בלילה בהמה כו'","ואם תאמר שחט בחוץ בלילה והעלה בחוץ אמאי חייב ומאי שנא משלמים ששחטן בחוץ קודם פתיחת דלתות ההיכל דפטור כדאיתא בפרק שני שעירי (יומא דף סב:) ויש לומר דלילה אין מחוסר זמן אבל התם מחוסר מעשה ואם תאמר לר\"ש מאי שנא שוחט בהמה בלילה בפנים משוחט עוף בפנים ויש לומר דשוחט עוף בפנים מקטל קטליה ואם עלה ירד אפי' לר\"ש אע\"ג דלא מטמא בגדים אבית הבליעה שאין שום שחיטה מטמא בגדים אבית הבליעה אפילו טרפה או נרבע:"]]],[["\u0001גמ׳\u0002 בשלמא בחוץ וחזר ונתן בפנים שכולו ראוי להיות בפנים אבל בפנים והעלן בחוץ שיריים נינהו","הא מני רבי נחמיה היא דאמר שירי הדם שהקריבן בחוץ חייב","אי רבי נחמיה אימא סיפא קבל דמה בשני כוסות נתן שניהם בפנים פטור שניהם בחוץ חייב אחד בפנים ואחד בחוץ פטור והאמר רבי נחמיה שירי הדם שהקריבן בחוץ חייב","סיפא אתאן לתנא קמא דרבי אלעזר ברבי שמעון דאמר כוס עושה דחוי לחבירו:","למה הדבר דומה למפריש חטאתו ואבדה והפריש אחרת תחתיה ואחר כך נמצאת הראשונה:","למה הדבר דומה למה לי הא מני רבי היא דאמר אבודה בשעת הפרשה מתה","והכי קאמר טעמא דאבדה הא הפריש שתי חטאות לאחריות חדא מינייהו מעיקרא עולה היא","וכדרב הונא אמר רב דאמר רב הונא אמר רב אשם שניתק לרעייה ושחטו סתם כשר לעולה","מי דמי התם אשם זכר ועולה זכר אבל חטאת נקבה היא א\"ר חייא מיוסתיניא בשעיר נשיא:","\u0001הדרן עלך השוחט והמעלה\u0002","מתני׳ \u0001פרת\u0002 חטאת ששרפה חוץ מגתה וכן שעיר המשתלח שהקריב בחוץ פטור","שנאמר (ויקרא יז, ד) ואל פתח אהל מועד לא הביאו כל שאין ראוי לבא אל פתח אהל מועד אין חייבין עליו","הרובע והנרבע והמוקצה והנעבד והמחיר [והאתנן] והכלאים והטריפה ויוצא דופן שהקריבן בחוץ פטור","שנאמר (ויקרא יז, ד) לפני משכן ה' כל שאין ראוי לבא לפני משכן ה' אין חייבין עליו","בעלי מומין בין בעלי מומין קבועין בין"],[[1,"גמ' מאן תנא דפליג עליה דר' אלעזר בר' שמעון","בפרק כל הפסולין (לעיל זבחים דף לד:) ואומר כוס עושה חבירו דחוי דקתני חטאת שקבל דמה בארבע כוסות ונתן ארבע מתנות מאחד מהם הוא לבדו נשפך ליסוד והן נשפכין לאמה ורבי אלעזר ב\"ר שמעון אמר התם כולן נשפכין ליסוד דקסבר כוס אחד עושה את חבירו שירים:"],[1,"רבי נחמיה הוא","דפליג עליה דאמר הכא קבל דמה בכוס אחד נתן בפנים וחזר ונתן בחוץ חייב דשירים נינהו ושירי הדם שהקריבו בחוץ חייב והיכא דקיבלו בשני כוסות אמר פטור אלמא כוס שני לאו שירים חשיב ליה אלא דחוי היה לשפוך לאמה הלכך לא מיחייב עליה בחוץ:"],[5,"מאי למה הדבר דומה","למאי הלכתא דמינהו ומאי גמר מינה:"],[5,"הא מני רבי היא דאמר","במסכת תמורה (דף כב:) אבודה בשעת הפרשה מתה כחטאת שכיפרו בעליה דקיימא לן (שם דף כא:) דאזלא למיתה אפילו לא היתה ראשונה אבודה בשעה שמתכפר בשניה אלא בשעת הפרשה ומשהפריש זו תחתיה נמצאת קיימא לן בה דאם נתכפר באחת מהן שניה מתה והכי קאמר תנא דמתני' טעמא דאבדה כלומר זו שהופרשה על ידי איבוד חבירתה הוא דכי שוחט אחת מהן בחוץ אחר שקרבה חבירתה פטור דדמיא לכוס דחוי משום דכרבי סבירא ליה דאמר למיתה אזלא אבל המפריש שתי חטאות לאחריות מעיקרא שאם תאבד האחת יתכפר בחבירתה דאפי' רבי מודה בו דמתכפר באחת מהן והשניה תרעה ודמיה לעולת קיץ המזבח וכן לרבנן באבודה בשעת הפרשה דאית להו תרעה בההוא לא אמרינן דאם שחטה בחוץ לשניה דנפטר ואף על גב דלכתחילה לא קרבה היא גופה עולה אלא דמיהן חייב עליה בחוץ דאי אקרבה לדידה גופה עולה בפנים מתקבלת היא:"],[7,"כדרב הונא [א\"ר] אשם שניתק לרעייה","כגון תמורת אשם ואשם שמתו בעליו או נתכפרו באחר וקיימא לן (שם דף יח.) כל שבחטאת מתה באשם רועה ונמלך בב\"ד ואמרו לו ירעה ושחטו סתם כשר לעולה ודוקא ניתק אבל לא ניתק לא כדאמר בפ\"ק (לעיל זבחים ד' ה:) הוא בהוייתו יהא:"],[8,"מי דמי","מתני' לדרב הונא לחיובי אחטאת שניה בחוץ מהאי טעמא הא לא חזיא היא גופה לעולה כלל דהא נקבה היא:"],[8,"מיוסתיניא","מקום:"],[8,"בשעיר נשיא","שהפריש שנים לאחריות דהתם זכר הוא:"],[10,"מתני' פרת חטאת. חוץ מגתה","בגמרא מפרש היכא:"],[10,"גתה","לשון גת כלומר מקום עמוק:"],[10,"","ששחטה חוץ מגתה גרסי':"],[10,"פטור","ולא אמרינן שוחט קדשים בחוץ שלא במקום מצוה דרחמנא פטריה מואל פתח אהל מועד וגו' הראוי לפתח אהל מועד שחובה עליו להביאו שם דמדקפיד קרא לענשו על שלא הביאו ש\"מ בעומד להביאו שם משתעי קרא:"],[11,"כל שאינו ראוי","כל שאינו עתיד [לבא] ובגמרא פריך הא שעיר המשתלח עתיד לבא להגריל ולהתוודות:"],[13,"שנאמר לפני משכן","להקריב קרבן לפני משכן אע\"פ שכשר לבא הואיל ואינו כשר ליקרב ובגמרא פריך הני נמי תיפוק לי מואל פתח אהל מועד:"]],[[0,"אלא בפנים וחזר ונתן בחוץ שיריים נינהו","אע\"ג דאית לאוקומא בג' מתנות שבחטאת דאמרינן בפ' ב\"ש (לעיל זבחים דף לח:) דלענין חוץ הוי כתחילתן לא משמע ליה אלא בשיריים דומיא דסיפא דשני כוסות אחד בפנים ואחד בחוץ שלא היה עושה חבירו דחוי אא\"כ נתן לכולם:"],[0,"","כשם שדמה פוטר את בשרה מן המעילה דזריקת דם מוציאה בשר קדשי קדשים מן המעילה כך הוא פוטר את בשר חבירתה מן המעילה ופי' בקונטרס משום חטאת שכיפרו בעליה דקי\"ל חטאות המתות לא נהנין ולא מועלין וקשה לפירושו דבסוף פרק קמא דמעילה (דף ו:) תנן אמר רבי עקיבא והרי מפריש חטאתו ואבדה והפריש אחרת תחתיה ואחר כך נמצאת הראשונה הרי שניהם עומדים לא כשם שדמה פוטר את בשרה כך פוטר את בשר חבירתה ואמרינן בגמרא אמר רבי אלעזר לא אמר רבי עקיבא אלא ששחט שניהם בבת אחת רצה מזה זורק רצה מזה זורק אבל בזה אחר זה לא ואי חשיב כחטאות המתות אפילו בזה אחר זה נמי אלא ודאי כיון דנשחטה קודם זריקת דמה של חבירתה שראוי להתכפר לא הויא חטאת המתה והיינו טעמא דיש חילוק בין בת אחת לזה אחר זה דבבת אחת חשיבי תרוייהו כחד גופא ולכך פוטר את בשר חבירתה וכן מוכחת הסוגיא:"],[5,"הא מני רבי היא דאמר אבודה בשעת הפרשה מתה","למאן דאמר בפרק ולד חטאת (תמורה דף כג.) דהכל מודים במתכפר בשאינה אבודה דאבודה מתה מיירי הכא בכל ענין דהשניה מתה לרבי ואיכא למאן דאמר התם דבבא לימלך פליגי והיכא דמשך מדעתו אחת מהן והקריב השניה מתה לכולי עלמא דנתכוין לדחותה והיכא דנמלך מודה רבי דנתכפר באבודה דשאינה אבודה רועה והכא מיירי בשחט שאינה אבודה בפנים ואבודה בחוץ וקשה קצת מאי רבי היא רבנן נמי לא פליגי בהכי:"],[6,"והכי קאמר טעמא דאבדה אבל הפריש שתי חטאות לאחריות כו'","משמע היכא דקתני אבדה הוי אבדה דוקא ותימה דבסוף פ\"ק דמעילה (דף ז.) תניא אמר רבי שמעון כשהלכתי לכפר (בגא) [פאני] כו' עד אמר לי בני אתה אומר כן והרי מפריש חטאת ואבדה והפריש אחרת תחתיה כו' ולר\"ש על כרחין לא מחלק דרועה לר' שמעון לית ליה כלל כדאיתא בפרק מי שהיה טמא (פסחים דף צז:) ובתמורה פרק ולד חטאת (תמורה דף י) וי\"ל דבמעילה אינו יורד לחידוש זה אלא לאשמועינן דזריקה מועלת ליוצא וחד מינייהו נקט אבל מתני' דהכא לחידוש תנייה דאין זה דמיון כ\"כ ולא נקטה אלא לאשמועינן דרבי היא חדא מינייהו מעיקרא עולה היא ואפילו למ\"ד בעי עקירה חסרון עקירה לא שמיה חסרון בהאי דעומד ליעקר ולא דמי להא דאמרינן בפ' בתרא (לקמן זבחים דף קיד:) אי הכי לשמו ליחייב הואיל וראוי שלא לשמו ומשני מחוסר עקירה דהתם אינו עומד ליעקר:"],[8,"בשעיר נשיא","וא\"ת לר\"ש חטאת זכר אמאי מתה הא אמרי' בפרק קמא דהוריות (דף ו:) ובפרק שני דתמורה ' (דף טו:) דחמש חטאות בחד מקום גמירי להו ולא משכחת ולד חטאת בחטאת זכר וי\"ל דמתני' דלא כר\"ש והא דאמרינן בפ' ולד חטאת (שם דף כג.) גבי שעירי יום הכיפורים והשני ירעה לרבי שמעון ודייקא הא ביחיד מתה לאו בזכר כיוצא באלו אלא בנקבה:"],[10,"מתני'. פרת חטאת ששחטה חוץ מגתה","ברוב ספרים גרסינן ששרפה וכן במסכת פרה פרק ד' (מ\"ב) תנן שרפה חוץ לגתה פסולה והוא הדין בשחיטה דאין חיוב חוץ לא בשחיטה ולא בהעלאה כדמוכח בגמרא ועיקר גת ניתקן לשריפה שהוא כעין גומא כדפירש בערוך ושורפין אותה שם ואוספין אפרה:"]]],[["בעלי מומין עוברין שהקריבן בחוץ פטור ר\"ש אומר בעלי מומין קבועין פטור בעלי מומין עוברין חייב בלא תעשה","תורים שלא הגיע זמנן ובני יונה שעבר זמנן שהקריבן בחוץ פטור ר\"ש אומר בני יונה שעבר זמנן פטור ותורים שלא הגיע זמנן בלא תעשה","אותו ואת בנו ומחוסר זמן פטור ר\"ש אומר הרי זה בלא תעשה שר\"ש אומר כל שהוא ראוי לבא לאחר זמן ה\"ז בלא תעשה ואין בו כרת וחכ\"א כל שאין בו כרת אין בו לא תעשה","מחוסר זמן בין בגופו בין בבעליו","איזהו מחוסר זמן בבעליו הזב והזבה והיולדת והמצורע שהקריבו חטאתם ואשמם בחוץ פטורין עולותיהן ושלמיהן בחוץ חייבין","המעלה מבשר חטאת מבשר אשם מבשר קדשי קדשים מבשר קדשים קלים ומותר העומר ושתי הלחם ולחם הפנים ושירי מנחות","והיוצק והפותת והבולל והמולח והמניף והמגיש והמסדר את השולחן והמטיב את הנרות והקומץ והמקבל דמים בחוץ פטור","ואין חייבין עליו לא משום זרות ולא משום טומאה ולא משום מחוסר בגדים ולא משום [שלא] רחוץ ידים ורגלים","עד שלא הוקם המשכן היו הבמות מותרות ועבודה בבכורות ומשהוקם המשכן נאסרו הבמות ועבודה בכהנים קדשי קדשים נאכלין לפנים מן הקלעים וקדשים קלים בכל מחנה ישראל באו לגלגל הותרו הבמות קדשי קדשים נאכלין לפנים מן הקלעים וקדשים קלים בכל מקום","באו לשילה נאסרו הבמות ולא היה שם תקרה אלא בית אבנים בלבד מלמטן והיריעות מלמעלן והיא היתה מנוחה קדשי קדשים נאכלין לפנים מן הקלעים וקדשים קלים ומעשר שני בכל הרואה","באו לנוב וגבעון הותרו הבמות קדשי קדשים נאכלין לפנים מן הקלעים קדשים קלים בכל ערי ישראל","באו לירושלים נאסרו הבמות ולא היה להן היתר והיא היתה נחלה קדשי קדשים נאכלין לפנים מן הקלעים קדשים קלים ומעשר שני לפנים מן החומה","כל הקדשים שהקדישן בשעת איסור הבמות והקריבן בשעת איסור הבמות מבחוץ הרי אלו בעשה ולא תעשה וחייבין עליו כרת","הקדישן בשעת היתר הבמות והקריבן בשעת איסור הבמות בחוץ הרי אלו בעשה ולא תעשה ואין חייבין עליהן כרת הקדישן בשעת איסור הבמות והקריבן בשעת היתר הבמות הרי אלו בעשה ואין בהן לא תעשה","ואלו קדשים קרבין במשכן קדשים שהוקדשו למשכן קרבנות ציבור קרבין במשכן וקרבנות היחיד בבמה קרבנות היחיד שהוקדשו למשכן יקריבו במשכן ואם הקריבן בבמה פטור","ומה בין במת יחיד לבמת ציבור סמיכה ושחיטת צפון"],[[0,"שהיה ר\"ש אומר כו'","בגמרא מפרש לא תעשה דידהו:"],[0,"עובר בל\"ת","הואיל וראוי לבא לאחר זמן כדקתני בסיפא:"],[1,"תורין שלא הגיע זמנן","כדתנן בחולין (דף כב.) משיזהיבו כשירין ומקמי הכי פסולין דתורין משמע גדולים ולא קטנים בני יונה קטנים משמע ולא גדולים ופסולין מתחילת הציהוב ואילך:"],[1,"בלא תעשה","הואיל וראוין לאחר זמן יש בו לא תעשה לשוחטן בחוץ:"],[2,"מחוסר זמן","שאמרנו פטור בין שהוא מחוסר זמן בגופו בין שהוא מחוסר זמן בבעלים שלא הגיע זמן בעלים להקריב קרבנותיהם:"],[4,"והמצורע","לא גרסי' במתני':"],[4,"ויולדת","בתוך מלאת:"],[4,"ואשמם","בגמרא פריך מאי אשם איכא בהני:"],[4,"פטור","שאין מתקבלין בפנים לא חובה ולא לנדבה:"],[4,"עולותיהן","דזב וזבה דעוף ודיולדת בהמה:"],[4,"חייבין","שהרי מתקבלות בפנים נדבה לשמן:"],[4,"ושלמיהן","בגמ' פריך מאי שלמים איכא בהני:"],[5,"קדשי קדשים","כבשי עצרת:"],[5,"ומותר העומר","לאחר קמיצה:"],[6,"היוצק","שמן על המנחה כדכתיב (ויקרא ב) ויצקת וגו':"],[6,"והפותת","מנחת מאפה כדכתיב (שם) פתות אותה פתים:"],[6,"והמגיש","מנחה בחוץ והיא טעונה הגשה בפנים בקרן מערבית דרומית כמשפטה:"],[6,"המטיב את הנרות","מדשן את המנורה בבקר:"],[6,"פטור","טעמא יליף בברייתא בגמ':"],[7,"אין בהן משום זרות","חיוב מיתה כל הנך הקטרות בדבר שדרכן לאכול לאו הקטרה נינהו וכל הנך עבודות הואיל ויש אחריהן עבודה אין זר חייב עליה מיתה כדאמרינן בפרק בראשונה (יומא דף כד.) עבודת מתנה ולא עבודת סילוק עבודה תמה ולא עבודה שיש אחריה עבודה:"],[7,"ולא משום טומאה","כהן טמא ששימש דאזהרת זרות ושימוש בטומאה מחד קרא נפקי מוינזרו ולא יחללו בכל הזבחים תנינא (לעיל זבחים יז.) מאי דמחייב אזרות מחייב אשימוש טומאה:"],[7,"ולא משום מחוסר בגדים","דאינהו נמי כזר בזמן שאין בגדיהן עליהם אין כהונתם עליהם והוו להו זרים הכי נפקא לן בפרק שני (שם יז:):"],[7,"ולא משום שלא רחוץ ידים ורגלים","גמר חוקה חוקה ממחוסר בגדים התם לענין אחולי עבודה ולענין מיתה נמי אנן גמרינן לה מהתם:"],[8,"ועבודה בבכורות","כדכתיב וישלח את נערי בני ישראל וגו' (שמות כ״ד:ה׳):"],[8,"אסרו הבמות","כדכתיב בשחוטי חוץ:"],[8,"ועבודה בכהנים","כדכתיב קרב אל המזבח: לפנים מן הקלעים. דכתיב בחטאת ואשם ומנחה (ויקרא ו׳:ט׳) בחצר אהל מועד:"],[8,"קדשים קלים בכל מחנה ישראל","כמות שהן שרויין בדגליהם והא ילפינן באיזהו מקומן (לעיל זבחים נה.) מקראי:"],[8,"באו לגלגל","כשעברו את הירדן והוקבע אהל מועד שם שבע שנים שכבשו ושבע שחלקו:"],[8,"הותרו הבמות","כדילפינן לקמן מאיש כל הישר בעיניו:"],[8,"קדשי קדשים","הנאכלין לא קרב בבמת יחיד כל שאין נידר ונידב אין קרב בבמה קטנה ואין מנחה בבמה הלכך עולה הוא דהואי ואין נאכלת וחטאת ואשם בבמת ציבור הוא דקרבי ונאכלין לפנים מן הקלעים:"],[8,"קדשים קלים בכל מקום","דכיון שבטלו הדגלים והן היו הולכים בכל הארץ לכבשה ולא היתה חנייתן סביבות המשכן בטלה קדושת מחנה ישראל מעשר שני לא הוזכר כאן לפי שלא נהגו מעשרות עד לאחר ירושה וישיבה:"],[9,"באו לשילה","לאחר חילוקו מיד קבעוהו בשילה:"],[9,"נאסרו הבמות","כדקתני והיא היתה מנוחה וכתיב כי לא באתם עד עתה וגו' כלומר כשתעברו את הירדן לא תקריבו בבמות ככל אשר אנחנו עושים פה היום שאנו מקריבין במשכן חטאות ואשמות אלא איש כל הישר בעיניו תעשו דהיינו נדרים ונדבות שאינן עליכם חובה אלא לפי מה שישר בעיניכם כי בעוד שתכבשו ותחלקו לא באתם עד עתה אל המנוחה ועברתם את הירדן וישבתם בארץ היינו לאחר ירושה וישיבה והיה המקום וגו' השמר לך וגו' היינו איסור הבמות:"],[9,"תקרה","(של) גג של נסרים:"],[9,"ויריעות מלמעלן","בגמרא יליף לה:"],[9,"בכל הרואה","במקום שרואין משם את שילה ובגמרא יליף לה:"],[10,"באו לנוב וגבעון","כשחרבה שילה ונלקח הארון בימי עלי באו לנוב וגבעון כמו שנאמר אין לחם חול [וגו'] כי אם לחם קדש אשר מלפני ה' (שמואל א כ״א:ה׳) אלמא שולחן ומזבח התם הוה חרבה נוב בימי שאול באו לגבעון כדכתיב במלכים (א ג) כי שם הבמה גדולה:"],[10,"הותרו הבמות","יליף בגמרא:"],[10,"קדשים קלים בכל ערי ישראל","דהא בכל מקום שהוא שם עושה במה ומקריבו:"],[11,"והיא היתה נחלה","ההיא דכתיב בקרא דמשבאו אל המנוחה ואל הנחלה יאסרו הבמות:"],[11,"ומעשר שני","פריך בגמרא נסקיה להתם:"],[11,"לפנים מן החומה","של ירושלים שהיא במקום מחנה ישראל שבמדבר כדכתיב ואכלת שם לפני ה' (דברים יב):"],[12,"בעשה","והביאום לה' וגו' (ויקרא יז):"],[12,"ולא תעשה","כדילפי' משם תעלה לשחיטה ואזהרה דהעלאה השמר לך פן תעלה עולותיך וגו' (דברים יב):"],[12,"וחייבין עליהן כרת","כדכתיב (ויקרא י״ז:ד׳) ואל פתח אהל מועד לא הביאו:"],[13,"ואין חייבין עליהן כרת","כדאמרן בהשוחט (לעיל זבחים קו:) עד כאן הוא מדבר בקדשים שהקדישן כו' וקתני סיפא יכול יהו חייבין עליהן כרת תלמוד לומר זאת להם ואין אחרת להם:"],[13,"הקדישן בשעת איסור הבמות","מההיא שעתא קרינא בהו והביאום לה' וכיון שהמתין עד שלא יבא לקיימו נתבטל העשה על ידו אבל לאו וכרת ליכא דאזהרה ועונש בשעת הקרבה כתיבי והרי הותרו הבמות:"],[14,"ואלו קדשים קרבין במשכן","קדשים שהוקדשו למשכן בזמן שהיה המשכן בגלגל והותר במה אלו קדשים צריכין להקריבן במשכן ולא יקרבו בבמה אותם שהוקדשו לשם משכן מפרש ואזיל:"],[14,"קרבנות ציבור","סתמן למקדש:"],[14,"קרבנות יחיד","סתמן בבמה:"],[14,"קרבנות יחיד שהוקדשו למשכן","שפירש בשעת הקדישן על מנת להקריבן למשכן:"],[14,"פטור","מאזהרה ומעונש שהרי הותרו הבמות ומיהו אסור לשנות משום כאשר נדרת תשמור ועשית (דברים כ״ג:כ״ד):"],[15,"ומה בין במת יחיד כו'","כולהו יליף בגמרא דלא נהיגי בבמת יחיד:"],[15,"במת ציבור","גלגל נוב וגבעון:"]],[]],[["ומתן סביב ותנופה והגשה ר\"י אומר אין מנחה בבמה וכיהון ובגדי שרת וכלי שרת וריח ניחוח ומחיצה לדמים וריחוץ ידים ורגלים","אבל הזמן הנותר והטמא שוין בזה ובזה:","\u0001גמ׳\u0002 מאי חוץ מגתה אמר ר\"ל חוץ ממקום הבדוק לה אמר לו רבי יוחנן והלא כל א\"י בדוקה היא","אלא א\"ר יוחנן כגון ששחטה לפנים מן חומת ירושלים","ולוקמה כגון ששחטה חוץ לחומה שלא כנגד הפתח דאמר רב אדא בר אהבה שחטה שלא כנגד הפתח פסולה שנאמר (במדבר יט, ג) ושחט והזה","מה הזאתה כנגד הפתח אף שחיטתה כנגד הפתח וכי תימא דלא מקיש והא אתמר (שחטה שלא כנגד הפתח רבי יוחנן אמר פסולה ושחט והזה ר\"ל אמר כשרה (במדבר יט, ג) אל מחוץ למחנה ושחט","ואיתמר נמי) שרפה שלא כנגד הפתח רבי יוחנן אמר פסולה ור' אושעיא אמר כשרה ר' יוחנן אמר פסולה ושרף והזה","ורבי אושעיא אמר כשרה (במדבר יט, ה) על פרשה ישרף מקום שפורשת למיתה שם תהא שריפתה","אמרי לא מיבעיא קאמר לא מיבעיא חוץ לחומה דרחוקי רחקה אלא אפי' לפנים מן החומה דקרובי קרבה ואימא תתכשר קמ\"ל","אמר מר אמר לו רבי יוחנן והלא כל א\"י בדוקה היא במאי קמיפלגי מר סבר ירד מבול לא\"י ומר סבר לא ירד","אר\"נ בר יצחק ושניהם מקרא אחד דרשו (יחזקאל כב, כד) בן אדם אמר לה את ארץ לא מטוהרה היא לא גושמה ביום זעם","רבי יוחנן סבר אתמוהי מתמה קרא א\"י מי לא מטוהרה את כלום ירדו עליך גשמים ביום זעם ור\"ל סבר כפשטיה ארץ לא מטוהרה את מי לא ירדו עליך גשמים ביום זעם","איתיביה ר\"ל לר' יוחנן חצירות היו בירושלים בנויות על הסלע ותחתיהן חלול מפני קבר התהום ומביאין נשים מעוברות ויולדות ומגדלות שם בניהם לפרה","ומביאין שוורים ועל גביהן דלתות ותינוקות יושבין עליהן וכוסות של אבן בידן ומלאו וישבו במקומן","אמר רב הונא בריה דרב יהושע מעלה עשו בפרה","איתיבי' רבי יוחנן לריש לקיש פעם אחד מצאו עצמות בלשכת דיר העצים ובקשו לגזור טומאה על ירושלים עמד רבי יהושע על רגליו ואמר לא בושה וכלימה היא לנו שנגזור טומאה על עיר אבותינו איה מתי מבול איה מתי נבוכדנצר","מדקאמר הכי לאו למימרא דלא הוו ולטעמיך הרוגי נבוכדנצר הכי נמי דלא הוו אלא הוו ופנינהו הכא נמי הוו ופנינהו ואי אפנו"],[[0,"","ומתן סובב מתן סביב שתהא נראית המתנה לשתי רוחות המזבח דהיינו ב' מתנות שהן ארבע:"],[0,"תנופה והגשה","דמנחות:"],[0,"אין מנחה בבמה","מפרש בגמ' מנא ליה:"],[0,"וכיהון","כהונה דאפי' זר בבמת יחיד כשר:"],[0,"בגדי שרת","בגדי כהונה:"],[0,"ריח ניחוח","כדאמרינן בפרק בית שמאי (לעיל זבחים דף מו:) לשם ששה דברים הזבח נזבח לשם ריח לאפוקי אברים שצלאן והעלן שאין בהם משום ריח ניחוח:"],[0,"ומחיצה לדמים","חוט הסיקרא להבדיל בין דמים העליונים לדמים התחתונים:"],[1,"הזמן","שנפסלין במחשבת חוץ לזמנו וחייבין על קדשים משום נותר וטמא שוין בשתיהם:"],[2,"גמ' ממקום הבדוק לה","לשוחטה שם שאין תחתיה קבר התהום:"],[2,"בדוקה היא","לקמן מפרש פלוגתייהו:"],[3,"לפנים מן החומה","של ירושלים דכתיב בה (במדבר יט ג) והוציא אותה וגו':"],[4,"שלא כנגד הפתח","של היכל:"],[5,"הזאה","מפרש בה אל נוכח וגו':"],[6,"ושרף והזה","בתר והזה סמך ושרף:"],[7,"מקום שפורשת למיתה","מקום שנפשה יוצאה בגמר פירכוסה וליציאת נפשה שלא קבע לה הכתוב מקום:"],[8,"לא מיבעיא לחוץ לחומה","שלא כנגד הפתח:"],[8,"דרחוקי רחקה","מכנגד הקדושה:"],[9,"ר\"ל סבר ירד מבול לא\"י","ונשקעו בה עצמות המתים:"],[12,"ותחתיהן חלל","שאם יש קבר מפסיק החלל ושוב אין טומאה בוקעת למעלה מן החלל אבל טומאה רצוצה בוקעת ועולה עד לרקיע:"],[12,"ומגדלות שם בניהם","לפרה דמשום דמטמאין את הכהן השורף את הפרה מפני הצדוקים עשו בה שאר מעלות הרבה שאין אחיו הכהנים נוגעין בו כל שבעת ימי פרישתו והוו אלו תינוקות נוגעין בו ומזין עליו:"],[13,"ועל גביהן דלתות","להפסיק בין התינוקות לקרקע שלא יאהילו על קבר התהום בלכתם למלאות מים חיים לקידוש מן השילוח אלמא לאו כולה בדוקה היא:"],[13,"וכוסות של אבן","שכל מעשה פרה בכלי גללים בכלי אבנים שאין מקבלים טומאה כדאמר טעמא בשמעתא קמייתא דסדר יומא (דף ב.):"],[14,"מעלה עשו בפרה","משום קולא דאקילו בה משום צדוקין שהיו אומרים במעורבי שמש היתה נעשית והיו מטמאין את הכהן ומטבילין אותו ושרפה טבול יום עשו בה מעלות אחרות דלא לזלזלו בה ומיהו אם שחטה במקום שאין בדוק לה לא מיפסלא בהכי דכל א\"י בדוקה היא:"],[15,"איה מתי מבול","שנמצאים בשאר מקומות וכאן אינן נמצאין:"],[16,"איה הרוגי נבוכדנאצר","שהרג בה והופנו כולם ואין אחד מצוי בה על כרחינו בדוקה היא:"]],[[2,"חוץ ממקום הבדוק לה","קסבר דבמי בדיקה משום דירד מבול לא\"י תימה וכי מדאורייתא בעי בדיקה וי\"ל דאיצטריך קרא (שלא) לשרפה במקום טומאה דאסור מדאורייתא דבעי' שחיטה ושריפה במקום טהור כשריפת פרים דאיתקוש אהדדי כדמשמע לעיל בסוף טבול יום (זבחים דף קה:) ואם תאמר אמאי לא מיחייב משום חוץ כששחטה חוץ למקומה כיון דתמימה היא וראויה לשאר קרבנות כדאמרינן בפרק שני שעירי (יומא דף סב:) גבי שעירי יום הכפורים ששחטן בחוץ דחייב על שניהם הואיל וראויין לשעיר הנעשה בחוץ ויש לומר דלא דמי דיכול לשנותם דאין עליהם קריאת שם עד שעת הגרלה ועוד דאין קרבן שתהא פרה זו ראויה דאי לשלמים אין שלמים בציבור ועוד דפרה קדשי בדק הבית היא ואין יכול לשנותה בקדשי מזבח:"],[4,"שנאמר ושחט והזה מה הזאה כנגד הפתח וכו'","יש ספרים דגרסי ושרף והזה וכן משמע מדמייתי עלה מפלוגתא דרבי יוחנן ור' אושעיא ומיהו אפי' גרסינן הכא ושחט והזה ניחא דמשמע ליה דאי מקשינן שריפה להזאה ה\"ה שחיטה:"],[8,"אבל לפנים מן החומה דקרובי קרבה אימא תתכשר קא משמע לן","דפסולה משום דבעיא חוץ לשלש מחנות:"],[9,"לא ירד מבול לא\"י","תימה והכתיב (בראשית ז׳:י״ט) ויכסו כל ההרים הגבוהים אשר תחת כל השמים ובבראשית רבה אמרינן דר' ישמעאל ב\"ר יוסי ובהמי אחד היו הולכין בדרך פירוש בהמי שומר בהמות אמר להון ההוא כותאה איתו צלויי על טורא גריזים דלא נחית עליה טופנא אמר אותו בהמי לפני ר' ישמעאל בר' יוסי רבי תן לי רשות להשיב לו תשובה א\"ל השב א\"ל הר גריזים תחת כל השמים הוא א\"ל הן ולא כתיב ויכסו כל ההרים הגבוהים אשר תחת כל השמים קרא עליו ולא יהיה בך עקר ועקרה ובבהמתך אפי' הבהמי שבך לא יתעקר מן התשובה ושמא י\"ל דויכסו כל ההרים היינו ששלט הבל המבול בכל מקום כדאמרינן לקמן דמתו בהבלא ואותו כותי היה ר\"ל שלא היה שם לא הבל ולא שום דבר אי נמי לאותו כותי נתכונו לדחות בקש וקרא (להכא) ל\"ק דבמקום שירד מבול התם קאמר שנתכסו ההרים:"],[12,"ומביאין נשים עוברות ויולדות שם","אף על פי שהתינוקות טמאין בנדה ויולדות לא היו חוששין אלא לשמרם מטומאת מת דבעי הזאה ומטומאה היוצאה מגופן כגון בעל קרי:"],[13,"ועל גביהן דלתות","מאן דאמר בפ' קמא דגיטין (דף ח:) ובנזיר פרק כ\"ג (דף נה.) ובפ' בכל מערבין (עירובין דף ל:) ובפ' בתרא דחגיגה (דף כה.) אהל זרוק לא שמיה אהל סבר כר' יהודה דאמר בריש הישן (סוכה דף כא.) לא היו מביאין דלתות אלא שוורים שכריסן רחבה והתם טעמא משום דכתיב קרא (איוב י׳:י״א) ובעצמות וגידים תסוככני אע\"ג דבעלמא אהל שאינו עשוי בידי אדם לא שמיה אהל ומיהו רבי יהודה ודאי סבר שמיה אהל דהא קא אמר טעמא מפני שדעתו של תינוק גסה עליו:"],[13,"ומלאו ועלו וישבו במקומן","קצת תימה מה מועיל בתינוקות דסוף סוף בעינן איש בשעת קידוש שנותנין האפר במים או בשעת הזאה לרבי יהודה או לרבנן כדמוכח בפרק טרף בקלפי (יומא דף מג.):"],[14,"מעלה עשו בפרה","ר\"ל נמי ידע דמעלה עשו אלא דאי לא ירד מבול לא\"י אין ראוי לעשות מעלה זו ומיהו קצת קשה דהא מודה רבי יוחנן דמתו בהבלא כדלקמן:"],[16,"מדקאמר איה מתי מבול מכלל דלא הוו","תימה דלרבי יוחנן גופיה תקשי ליה הכא דמתו בהבלא:"]]],[["הא איפני נהי דאיפני מירושלים מכולה א\"י לא איפני","איכא דאמרי איתיביה ר\"ל לרבי יוחנן איה מתי מבול איה מתי נבוכדנאצר מאי לאו מדהני הוו הני נמי הוו מידי אירי' הא כדאיתיה והא כדאיתיה","איתיביה (בראשית ז, כב) מכל אשר בחרבה מתו בשלמא לדידי דאמינא ירד מבול לא\"י משום הכי מתו אלא לדידך אמאי מתו משום הבלא","כדרב חסדא דאמר רב חסדא ברותחין קלקלו וברותחין נידונו דכתיב הכא (בראשית ח, א) וישוכו המים וכתיב התם (אסתר ז, י) וחמת המלך שככה","איכא דאמרי איתיביה רבי יוחנן לר\"ל מכל אשר בחרבה מתו בשלמא לדידי דאמינא לא ירד מבול לא\"י משום הכי הוי חרבה אלא לדידך מאי חרבה חרבה שהיתה מעיקרא","ואמאי קרי ליה חרבה כדרב חסדא דאמר רב חסדא בדור המבול לא נגזרה גזרה על דגים שבים שנאמר מכל אשר בחרבה מתו ולא דגים שבים","בשלמא למ\"ד לא ירד מבול לא\"י היינו דקם רימא התם אלא למ\"ד ירד רימא היכא קם א\"ר ינאי גוריות הכניסו בתיבה","והאמר רבה בר בר חנה לדידי חזי לי אורזילא דרימא בת יומא והוי כהר תבור והר תבור כמה הויא ארבעין פרסי משכא דצואריה תלתא פרסי מרבעתא דרישא פרסא ופלגא רמא כבא וסכר ירדנא","א\"ר יוחנן ראשו הכניסו לתיבה והאמר מר מרבעתא דרישא פרסא ופלגא אלא ראש חוטמו הכניסו לתיבה","והא א\"ר יוחנן לא ירד מבול לא\"י לדברי ר\"ל קאמר","והא קסגיא תיבה אמר ר\"ל קרניו קשרו בתיבה והאמר רב חסדא אנשי דור המבול ברותחין קלקלו וברותחין נידונו","ולטעמיך תיבה היכי סגיא ועוד עוג מלך הבשן היכא קאי אלא נס נעשה להם שנצטננו בצידי התיבה","ולר\"ש [בן לקיש] נהי נמי דירד מבול לא\"י והא לא פש דאמר ר\"ל למה נקרא שמה מצולה שכל מתי מבול נצתללו שם ורבי יוחנן אמר למה נקרא שמה שנער שכל מתי מבול ננערו שם אי אפשר דלא אידבקו","א\"ר אבהו למה נקרא שמה שנער שמנערת עשיריה והא קחזינן דהוו תלתא דרי לא משכי","א\"ר אמי כל האוכל מעפרה של בבל כאילו אוכל בשר אבותיו תנ\"ה כל האוכל מעפרה של בבל כאילו אוכל בשר אבותיו וי\"א כאילו אוכל שקצים ורמשים:","שעיר המשתלח:","ורמינהי (ויקרא יז, ד) או קרבן שומע אני אפילו קדשי בדק הבית שנקראו קרבן שנאמר (במדבר לא, נ) ונקרב את קרבן ה'","ת\"ל ואל פתח אהל מועד לא הביאו מי שראוי לבא באהל מועד יצאו קדשי בדק הבית שאינן ראוין","אוציא את אלו שאינן ראוין ולא אוציא את שעיר המשתלח שהוא ראוי לבא אל פתח אהל מועד ת\"ל לה' להוציא שעיר המשתלח שאינו מיוחד לה'","לא קשיא כאן קודם הגרלה כאן לאחר הגרלה אחר הגרלה נמי האיכא וידוי","אלא אמר רב מני לא קשיא כאן קודם וידוי כאן לאחר וידוי:","הרובע והנרבע:","והא נמי תיפוק לי מפתח אהל מועד"],[[0,"נהי דאיפני מירושלים","כולה ר\"ל קאמר לה:"],[2,"מהבלא מתו","וקברום הבאים אחריהם בבתי קברות ואין לחוש לכל הארץ אלא לשאר ארצות שהיה שם מבול ונשקעו בטיט:"],[3,"ברותחין נידונו","ונמצא נמלג ברותחין:"],[4,"חרבה דמעיקרא","קודם מבול:"],[5,"מכל אשר בחרבה","לאפוקי דגים שבים:"],[6,"דהיינו דקם רימא התם","הראם זכר ונקבה שהוא גדול ואינו יכול ליכנס לתיבה עמדו שם:"],[6,"גוריות","הכניסם לתיבה:"],[7,"אורזילא","הוא ראם דימא שהוא על שפת הים:"],[7,"בר יומא","ביום שנולד:"],[7,"משכא דצוארי'","משך צוארו:"],[7,"בי מרבעתא דרישיה","בי מרבץ של ראשו:"],[7,"רמא כבא וסכר לירדנא","הטיל גלל בירדן וסכר הירדן וסתם הילוך מימיו כבא כמו (עירובין דף כט:) כיבוי דרעותא דניסן:"],[8,"חוטמו","שיוכל להנשים:"],[9,"לא ירד מבול לא\"י","ולמה ליה לשנויי הכי. לימא דהתם קם נ\"ל דל\"ג:"],[10,"והא קא סגיא תיבה","והא התיבה מהלכת על פני המים מגבוה לנמוך נמצא חוטמו נשמטת מן התיבה ומת:"],[11,"וליטעמיך תיבה היכי סגיא","והלא זפותה היא מבית ומבחוץ כדכתיב וכפרת אותה וגו' (בראשית ו׳:י״ד) וכיון דרותחין הן היא מהלכת שאין זפתה נפשר:"],[11,"עוג מלך הבשן","דכתיב ביה ויבא הפליט וא\"ר יוחנן (נדה דף סא:) זה עוג שפלט מאנשי דור המבול:"],[11,"נס נעשה ונצטננו המים","שבצידי התיבה ושם עמד עוג והראם וגם הזפת לא נפשר והראם לא הוצרך לתיבה ומפני גובהן לא טבעו:"],[12,"הא לא פש","מן המתים שם כלום דאיידי דגבוה היא השפילום המים לבבל שהיא מצולה:"],[12,"למה נקרא שמה מצולה","דכתיב (ישעיהו מ״ד:כ״ז) האומר לצולה חרבי:"],[12,"אי אפשר דלא אדביקו","בטיט:"],[13,"שמנערת עשיריה","מפני שאינן מרחמים על הבריות כדאמרינן במסכת ביצה (דף לב:) עשירי בבל יורדי גיהנם הן:"],[14,"כאילו אוכל שקצים ורמשים","של מבול:"],[16,"או קרבן שומע אני כו'","קרבן דכתיב בשחוטי חוץ (ויקרא י״ז:ד׳) להקריב קרבן וגו' דריש ליה בת\"כ על הקרבן חייב ואינו חייב על השוחט חולין בפנים או קרבן לאו להכי אתא אלא לחייב על קדשי בדק הבית ששחטן בחוץ שאף הן נקראו קרבן כענין שנאמר (במדבר ל״א:נ׳) ונקרב את קרבן ה' איש אשר מצא כלי זהב אצעדה וצמיד ואין זה אלא לבדק הבית:"],[18,"שאין ראוין לפתח אהל מועד","אני שמעתי בסדר יומא לפי שסתמן בעלי מומין דקי\"ל המתפיס תמימים לבדק הבית עובר בעשה במס' תמורה (דף ז:) אבל לענין הסוגיא אני למד כאן דאפילו תמים נמי קרי אינו ראוי דלא הועתד לבא אל אהל מועד דהא פרת חטאת תמימה היא וקרי לה אינו ראוי:"],[18,"אוציא את אלו שאין עתידין לאהל מועד","ולא אוציא שעיר המשתלח דראוי הוא שהוא תמים דבעינן שיהא ראוי לשם דלא ידעינן הי מתרמי זה שמעתי ולפי סוגיא של שמועה זו משמע דקרי ליה ראוי ועתיד ליכנס משום הגרלה ווידוי:"],[18,"ת\"ל לה'","להקריב קרבן לה' המיוחד לה' להוציא שעיר המשתלח שאינו מיוחד לשם:"],[19,"קודם הגרלה","הוי ראוי ועתיד ליכנס משום הגרלה ואי לאו דמעטינן מלה' ה\"א לחייב:"],[19,"אחר הגרלה","לא ראוי לבא הוא ומימעיט מאל פתח:"],[19,"הא איכא וידוי","דבעי ליכנס להתוודות עליו:"],[22,"תיפוק לי מאל פתח אהל מועד","דהא לאו ראוין הן לבא לעזרה:"]],[[6,"היינו דקם רימא התם","ואע\"ג דכל השאר מתו בהבלא מחמת שהיה גדול וגבור לא הזיק לו ההבל:"],[7,"אורזילא דרימא","גר' ר\"ת פי' עופר של ראם דעופר האילים מתרגמי' אורזילא דאיילא (שיר ב) ורימא הוא ראם ולא כרבי שמואל דגרס בהמוכר את הספינה (ב\"ב דף עג:) אורזילא דימא ומפרש דג של ים ואגב ריהטיה לא דק דהא אמר הכא לא נגזרה גזרה על דגים שבים ואותם בופל\"ש שאנו קורין ראם ליתא וחלבם אסור דראם ודאי מין חיה הוא וחלבו מותר כדכתיב אקו ודישון ומתרגמינן ויעלא ורימא ובופל\"ש שבמקומינו קטנים דאין לומר שהוא מין ראם ויש במינו גדול דא\"כ מאי קשיא ליה היכא קם הא לא קשיא ליה אריה דבי עילאי בפרק אלו טרפות (חולין דף נט:) היכא קם שהיו אריות אחרים קטנים שיכול להכניס ועוד הא קא חזינן דאותן בופל\"ש בני מלאכה נינהו ומושכין בקרון וחורשין בהן וראם לאו בר מלאכה הוא דכתיב התקשר ראם בתלם עבותו אם ישדד עמקים אחריך (איוב לט):"],[17,"יצאו קדשי בדק הבית","בלשון אחר פי' בקונטרס דממעט אפי' תמימים דהא פרת חטאת תמימה וממעטא משום דאינה ראויה לפתח אהל מועד ונראה דאין זו ראיה דפרת חטאת לא קיימא למזבח ולאו מתפיס תמימים לבדק הבית הא אמר בסוף תמורה (דף לג:) דכל הראוי למזבח אינו יוצא מידי מזבח לעולם ונמכרו לצורכי עולות ושלמים וא\"ת מאי שנא קדשי בדק הבית תמימים משעירי יוה\"כ דאמר בפ' שני שעירי (יומא דף סב:) דחייב על שניהם בחוץ הואיל וראויים לשעיר הנעשה בחוץ וכ\"ש הנך דאין יוצאין מידי מזבח וי\"ל כיון דעדיין לאו קדשי מזבח נינהו לא חשיבי ראוין לפתח אהל מועד:"],[19,"כאן קודם הגרלה כו'","בפ' שני שעירי (יומא דף סב:) אמרי' דחייב על שניהם והיינו למסקנא דשמעתין דמשני כאן קודם וידוי וכו' אבל קודם הגרלה חייב דראוי לשעיר הנעשה בחוץ:"],[20,"כאן קודם וידוי כאן לאחר וידוי","ומדפטר קרא קודם וידוי כ\"ש לאחר וידוי וכי איצטריך פתח אהל מועד משום פרה ומשום קדשי בדק הבית ומיהו היא גופה תימה אמאי לא ממעטינן מלה' ובפ\"ק דתמורה (דף יג.) גרס בכל הספרים ולא אוציא פרת חטאת ושעיר המשתלח שהם ראויין לפתח אהל מועד ת\"ל לה' שמיוחדים לה' יצאו אלו שאין מיוחדין לה' ומיהו קדשי בדק הבית שפיר מיקרו מיוחדין לה' דכולם לשמים וע\"כ נמי לא גרס פרת חטאת בבריית' דלא תיקשי מתני' ועוד אצטריך אל פתח אהל מועד למעוטי גגו כדאמרינן לעיל בפ' השוחט והמעלה (זבחים דף קז:):"]]],[["בשלמא רובע ונרבע משכחת ליה דאקדשינהו מעיקרא והדר רבעו","אלא מוקצה ונעבד אין אדם אוסר דבר שאינו שלו בקדשים קלים ואליבא דר' יוסי הגלילי דאמר קדשים קלים ממון בעלים הוא","דתניא (ויקרא ה, כא) ומעלה מעל בה' לרבות קדשים קלים שהן ממונו דברי רבי יוסי הגלילי","הלכך רובע ונרבע דבר ערוה מוקצה ונעבד עבודת כוכבים בקדשים קלים","אתנן ומחיר כלאים יוצא דופן בולדות קדשים","קסבר ולדי קדשים בהוייתן הן קדושים:","בעלי מומין וכו' אותו ואת בנו וכו':","וצריכי דאי תנא בעלי מומין משום דמאיסי אבל תורין דלא מאיסי אימא (לא) דמודו ליה לר\"ש","ואי תנא תורין משום דלא חזי ואידחו אבל בעלי מומין דאיחזו ואידחו אימא (לא) דמודה להו ר\"ש לרבנן","ואי תנא הני תרתי משום דפסולא דגופייהו אבל אותו ואת בנו דפסולא מעלמא קאתי לה אימא מודו ליה רבנן לר\"ש צריכא:","שהיה רבי שמעון אומר: מאי טעמא דר\"ש","אמר רבי אילעא אמר ריש לקיש דאמר קרא (דברים יב, ח) לא תעשון ככל אשר אנחנו עושים פה היום אמר להו משה לישראל כי עייליתו לארץ ישרות תקריבו חובות לא תקריבו","וגלגל לגבי שילה מחוסר זמן הוא וקאמר להו משה לא תעשון","אמר רבי ירמיה לרבי זירא אי הכי"],[[0,"בשלמא רובע ונרבע משכחת לה","דאיצטריך למעוטינהו מלהקריב דאקדשינהו והדר נרבעו וכיון דחזו כבר ואידחו ראויים קרינא בהו שנראו כבר ולא מימעטי מאל פתח דאיכא למימר הכי אמר קרא ואל פתח אהל מועד לא הביאו בשנראה לבא ואחר כך שחטו בחוץ חייב אבל שעיר המשתלח לאחר וידוי מימעיט מאל פתח שהרי זה הביאו כשנראה לבא ומשיצא לאחר וידוי לא נראה לבא:"],[1,"אלא מוקצה ונעבד","על כרחך מקמי דאקדשינהו הוו להו מוקצה ונעבד דאי לבתר דאקדשינהו תו לא מיתסרי בהקצאה ועבודה דאין אדם אוסר דבר שאינו שלו:"],[2,"בה'","וכחש בעמיתו דברים שיש בהם לשם ולעמיתו:"],[2,"לרבות קדשים קלי'","שהכופר בהן ונשבע והודה חייב עליהם אשם גזילות שהן ממון בעלים דקרינא ביה וכחש בעמיתו:"],[3,"דבר ערוה","וחייל אף על המוקדשים כבר הלכך ממעטי בחוץ מלהקריב קרבן דלאו בני הקרבה נינהו דכתיב (ויקרא כ״ב:כ״ה) כי משחתם בהם וכל מקום שנאמר השחתה אינו אלא דבר ערוה ועבודת כוכבים:"],[4,"נראה לי דה\"ג אתנן ומחיר וכלאים ויוצא דופן בולדות קדשים","כלומר הנך דאצרכנו למעוטינהו מלהקריב קרבן ולא נפקי מאל פתח על כרחך בשנראו כבר מיירי לא משכחת אלא בולדות קדשים ואירע להו פסול במעי אמן דנראו לבא אל פתח אהל מועד קודם שנעשו אתנן ומחיר אם בא להקריב את אמן היו הן באין אל פתח דאי בדאקדשינהו לא משכחת לה דאין אתנן ומחיר חל על המוקדשין לפי שאינן שלו ומקרא נפקא לן בתמורה (דף ל:) ואי בדהוו אתנן והדר אקדשינהו מאל פתח נפקי וכן כלאים ויוצא דופן דאי אקדשינהו משנולדו מאל פתח נפקי אלא בולדות קדשים דמעיקרא עם אמן נראו לבא:"],[5,"וקסבר ולדות קדשים בהוייתן הן קדושין","בלידתן מתקדשות הלכך חל אתנן ומחיר עליהן אם נתן לה עובר של מוקדשין באתנן דלא קדיש עד שנולד:"],[5,"בהוייתן (הן)","לשון הוייה נקט בהו משום דמאשר יהיה לך נפקי לן ולדות קדשים ליקרב רק קדשיך אלו התמורות אשר יהיו לך אלו הולדות במסכת תמורה (דף יז:):"],[7,"וצריכי","הנך תלת פלוגתא דר' שמעון ורבנן במתני':"],[7,"משום דמאיסי","בעודן במומן פטרי רבנן בחוץ דלא מתקבלין בפנים:"],[7,"מודו ליה","דהואיל וחזו לאחר זמן קאי בלא תעשה: ובני יונה לא גרסינן:"],[8,"דאיחזו ואידחו","אימא אע\"ג דכי עבר מומן ירצו השתא מיהא דחויין נינהו ונפטר בחוץ:"],[11,"לא תעשון כן","בספרי דריש ליה בתחילת ביאת הארץ היום אנו מטלטלין את המשכן ואנו אסורין בבמה ואין אנו מקריבין אלא במשכן לפיכך כל הקרבנות כשרים להקריב משנבוא לארץ י\"ד שנים של כיבוש וחילוק אנו מותרין בבמה ושם לא תעשון ככל אשר אנחנו עושים פה להקריב חובות ומה אנו מותרין בה איש כל הישר בעיניו נדרים ונדבות שאינן חובה עליו אלא שישרו בעיניו להתנדב כי לא באתם עד עתה וגו' עד שתבאו אל המנוחה לשילה שאע\"פ שנכנסתם לארץ בעברכם את הירדן עדיין לא באתם אל המנוחה:"],[11,"כי עייליתו לארץ","י\"ד שנים שתכבשו ותחלקו:"],[11,"ישרות תקריבו","נדרים ונדבות הקרב בבמת ציבור:"],[11,"חובות לא תקריבו","איש איש שבכם לא יקריב שום חובה ואפילו בבמת ציבור עד שתבאו אל המנוחה ותקריבום אלמא חובות דגלגל מחוסרי זמן הם עד כי יבא שילה ויקריבום שם וקאמר רחמנא לא תעשון אותם בגלגל ומשמע בין בבמת ציבור בין בבמת יחיד אלמא מחוסר זמן בבמה בלא תעשה:"],[13,"אי הכי","דהנך דגלגל מחוסרי זמן קרית להו:"]],[[4,"אתנן ומחיר יוצא דופן וכלאים בוולדות קדשים","אתנן ומחיר לא מיתוקם בקדשים קלים אפילו לרבי יוסי הגלילי דאף על גב דממונו הוי אינו חל עליו כדדרשינן פ' כל האסורין (תמורה ל:) לכל נדר פרט לנדור:"],[5,"וקסבר ולדות קדשים בהוייתן הן קדושים","וא\"ת למה לי קרא למעוטי הלא חולין גמורים נינהו ודינם כשאר חולין לישחט בחוץ דאפילו פדיון לא בעו דאין קדושה חלה עליהן כלל כדמוכח בתמורה בפרק כיצד מערימין (תמורה דף כד:) דתנן אם זכר עולה ואם נקבה זבחי שלמים ופריך בגמ' ל\"ל למימר אם נקבה זבחי שלמים נקבה מי קדשה בבכורה ומשני סיפא אתאן לבהמה דהקדש וקתני סיפא ילדה טומטום או אנדרוגינוס רשב\"ג אומר אין קדושה חלה עליהן ומפרש בגמ' משום דסבר בהוייתן הן קדושים ואין קדושה חלה בדבר שאין ראוי ליקרב א\"כ הכא נמי לא חיילא אאתנן ומחיר וכלאים ויוצא דופן וי\"ל דהא דאמר רשב\"ג אין קדושה חלה עליהן היינו קדושת הגוף (לפדות) וליאסר בגיזה ועבודה אבל קדושת דמים איכא ליפדות שלא במום ולכך בעי האי קרא דלא ממעטי מפתח אהל מועד בקדשי בדק הבית ולמאן דאמר במעי אמן הן קדושים אפילו קדושת הגוף נחתא עלייהו דתפסתינהו קדושה דאימיה וא\"ת למאן דאמר בהוייתן נמי נימא מיגו דנחתא להן קדושת דמים נחתא להן קדושת הגוף כדאמר בתמורה בפרק אלו קדשים (תמורה דף יט: ושם) גבי מפריש נקבה לאשם ודוחק לומר רשב\"ג סבר לה כרבי שמעון דלית ליה מיגו דאמר תמכר שלא במום ועוד דאי כרבי שמעון אפילו סבר במעי אמן קדושים לא חיילא עליה קדושת הגוף כדמפרש התם רבי שמעון לטעמיה דאמר כל מידי דלא חזי לגופיה לא נחתא ליה קדושת הגוף וגם אין לפרש דשאני מפריש נקבה דחזי לשאר קרבנות ושייך מגו טפי דהא אפילו בטרפה אשכחן דאמרינן מגו בסוף יש בקרבנות (תמורה דף יז.) וה לפרש דהכא מיירי כגון דלאחר שנעשו אתנן ומחיר הקדישן או בעודן במעי אמן או אחר שנולדו דכיון שהקדישן בפירוש חיילא עלייהו קדושה וא\"ת ולוקמה נמי הכא כמ\"ד במעי אמן הן קדושים וכגון שהקדיש בהמה מעוברת ושייר העובר כר' יוחנן דאמר בפ' כיצד מערימין (תמורה כה.) אם שייר משוייר ועשה העובר אתנן ומחיר ואחר כך הקדישן ואע\"ג דרבי יוחנן איתותב התם הא לבסוף מסיק כתנאי ועוד מצי לאוקומה בבהמה של חולין מעוברת ועשה העובר אתנן ומחיר ואחר כך הקדישה וי\"ל דניחא ליה לאוקומה בפשיטות כמאן דאמר בהוייתן הן קדושים והקדישן ואח\"כ נתעברה ואם תאמר בההיא דכיצד מערימין (ג\"ז שם) דדייק ארשב\"ג דסבר בהוייתן הן קדושין מרישא נמי הוה מצי למידק הכי דאם נקבה זבחי שלמים דאוקימנא בבהמה דהקדש ואי במעי אמן הן קדושות לא היה יכול להפקיע קדושת הולד ויש לומר דנטר עד סיפא ומפרש לה וה\"ה לרישא ואם תאמר בסוף בהמה המקשה (חולין עז.) דתנן המבכרת שהפילה שיליא ישליכנה לכלבים ובמוקדשין תקבר ומפרש בגמ' (שם:) משום דרובא בר מיקדש היא על כרחך מדקאמר תקבר קסבר במעי אמן הן קדושין דאי בהוייתן אמאי תקבר הא לא חיילא קדושה אלא בחזי להקרבה כדפריש ואם כן כולה בר מיקדש היא ואמאי נקט רובא דאפי' אכלאים ונדמה תפשה קדושת אימיה אי במעי אמן הן קדושים כדאשכחן בתמורה בסוף יש בקרבנות (תמורה דף יז.) דאמרינן גבי כלאים טומטום ואנדרוגינוס דאי אתה מוצא אלא בולדות קדשים ולכל הפחות אתיא כמאן דאמר במעי אמן הן קדושים ויש לומר דנקט רובא ולא כולה משום דאיכא דמות יונה או קלוט לר' שמעון דכיון דלא מישתרי באכילה לא מיסתבר דתפשינהו קדושת אמן אף על גב דבמעי אמן הן קדושין:"],[9,"משום דפסולא דגופייהו","בכל דוכתי משמע דפסול הגוף חמיר מפסולא דאתי מעלמא כדאמרינן בפרק קמא (לעיל זבחים דף ד.) מה לשינוי קודש שכן פסולו בגופו ובפסחים בסוף אלו דברים (פסחים דף עג:) נמי אמרינן כל שפסולו בגופו ישרף מיד דהא דמשמע הכא איפכא לאו משום דפסול הגוף קיל אלא הכי קאמר דמום עובר ותורין שלא הגיע זמנן הפסול תלוי בגופו ואם היה מום עובר מיד והתורים גדילין לאלתר היו ראויין אבל אותו ואת בנו אין הפסול תלוי בגופו שיועיל לו שום תיקון דלכולי יומא לא חזי:"]]],[["מילקי נמי לילקי אלמה אמר רבי זירא הכתוב נתקו לעשה","הני מילי לרבנן לרבי שמעון הכי נמי","רב נחמן בר יצחק אמר פנים דגלגל לגבי שילה כחוץ דמי","רבה אמר טעמיה דרבי שמעון כדתניא רבי שמעון אומר מנין לזובח פסח בבמת יחיד בשעת איסור הבמות שהוא בלא תעשה ת\"ל (דברים טז, ה) לא תוכל לזבוח את הפסח","יכול אף בשעת היתר הבמות כן ת\"ל באחד שעריך לא אמרתי לך אלא בשעה שכל ישראל נכנסין בשער אחד","אימת אי נימא אחר חצות כרת נמי מחייב אלא לאו קודם חצות","לעולם לאחר חצות ובשעת היתר הבמות קאי","והא בשעת איסור הבמות קאמר איסור במה לו היתר במה לחבירו:","מחוסר זמן כו': והני בני אשמות נינהו אמר זעירי תני מצורע בהדייהו:","עולותיהן ושלמיהן: והני בני שלמים נינהו אמר רב ששת תני נזיר דזעירי קבעוה תנאי דרב ששת לא קבעוה תנאי","א\"ר חלקיה (דבי) רב טובי לא שנו אלא לשמו אבל שלא לשמו חייב הואיל וראוי לשלא לשמו בפנים","אי הכי לשמו נמי ניחייב הואיל וראוי לשלא לשמו בפנים בעי עקירה","מתקיף לה רב הונא וכי יש לך דבר שאינו כשר לשמו וכשר שלא לשמו ולא והרי"],[[0,"מילקי נמי לילקי","השוחט מחוסר זמן דהא משכן דגלגל דהיא במת ציבור פנים הוא שאהל מועד של מדבר היה שם וקאמר רחמנא ביה נמי לא תעשון:"],[0,"אלמה אמר רבי זירא","בפ' אותו ואת בנו (חולין פ:) דקתני קדשים בפנים סופג את הארבעים משום לאו דאותו ואת בנו והוינן בה ונילקי נמי משום לאו דמחוסר זמן דתניא מנין שכל הפסולים שבשור ושבשה שהן בלא ירצה ת\"ל ושור ושה שרוע וקלוט ומחוסר זמן פסול הוא ומשני ר' זירא הנח לאו דמחוסר זמן דהכתוב נתקו לעשה דכתיב ביה עשה יתירא כדמפרש התם למימרא שהוציאו ונתקו מכלל לאו דלא קאי עליה בלאו דשאר פסולין והשתא דאמרת הכא לאו בהדיא כתיב ביה נילקי עליה:"],[1,"(דלמא) ה\"מ","דמשני נמי התם דלא לקי לרבנן דפליגי עליה דרבי שמעון דלא דרשי להאי לא תעשה למחוסר זמן דההוא דאותו ואת בנו דשני ר' זירא עלה מיתוקמא התם דלא כר\"ש אבל לר' שמעון ה\"נ דלקי אלאו דמחוסר זמן בפנים:"],[2,"רב נחמן בר יצחק אמר","לר' שמעון נמי לא לקי אמחוסר זמן בפנים דגלגל לגבי שילה חוץ הוא לגבי חובות הואיל דאינו כשר להקרבתו הלכך בחוץ הוא דאשכחן ביה לא תעשה משום איסור במה ולא בפנים:"],[3,"בשעת איסור הבמות","קס\"ד במדבר ושילה ובית עולמים:"],[5,"אחר חצות","די\"ד דמטי זימניה:"],[5,"כרת נמי ניחייב","דהא מתקבל בפנים:"],[5,"קודם חצות","דהוי מחוסר זמן לשמו:"],[6,"בשעת היתר הבמות קאמר","כמו בגלגל ונוב וגבעון דהותרו במות יחיד לעולה ושלמים ואשמעינן קרא דלגבי חובות איכא לא תעשה ולאו משום מחוסר זמן דהא חזו השתא בבמה גדולה:"],[7,"איסור במה לו","לקרבן זה:"],[7,"היתר במה לחבירו","לעולה ושלמים דנדר ונדבה וסיפא ה\"ק יכול אף בשעה שהוא מותר בבמה כגון קודם חצות שהוא לשלמים ת\"ל כו' בשער אחד בבמה גדולה לשחוט פסחיהם:"],[9,"דזעירי קבעוה תנאי","למיתני במתניתין מצורע בהדיא:"],[9,"דרב ששת לא קבעוה תנאי","ומיהו אנן משנינן לה בגמרא וקבעינן לה בגמ' הכי ככל חסורי מחסרא דהש\"ס:"],[10,"רב חלקיה","אאשם קאי ולא אחטאת דאילו חטאת פסולה שלא לשמו בפנים:"],[10,"לא שנו","דפטור בחוץ:"],[10,"אלא לשמו","ואפילו סתמא דבהאי שמא אינו מתקבל עכשיו בפנים:"],[10,"אבל שלא לשמו","כגון לשם עולה ובשם זה הוא ראוי לבא לפנים דכל הזבחים שנזבחו שלא לשמן כשרין חוץ מן הפסח והחטאת:"],[11,"אי הכי כי שחיט ליה לשמו בחוץ נמי ניחייב","דהא ראוי היה לעקור שם זה ממנו ולבא לפנים:"],[11,"מחוסר עקירה","וכל כמה דלא איעקר שם אשם מיניה סתמיה לאו למיעקר קאי ולא ראוי הוא:"],[12,"וכי יש לך דבר שאינו כשר לשמו","לפנים:"],[12,"וכשר שלא לשמו","אפי' דקי\"ל לעיל (זבחים דף ב.) כל הזבחים כשרין שלא לשמן ה\"מ היכא דכשרין לשמן אבל מחוסר זמן בבעלים זה שאינו כשר לשמו היאך יוכשר שלא לשמו:"]],[[0,"אלמה אמר רבי זירא הכתוב נתקו לעשה","אין זה כשאר לאו הניתק לעשה דבפ' בתרא דחולין (דף קמא.) ובפ' ב' דמכות (דף יד. טו. טז.) כגוץ לאו דגזילה ולקט שכחה ופיאה ונותר. ולא יוכל לשלחה כל ימיו דא\"כ מאי פריך דללקי משום לאו דלא תעשון והא ניתק לעשה הוא אלא הוי כמו נתקו הכתוב מטומאה חמורה לטומאה קלה דבאותו ואת בנו (חולין פ:) דרשינן ולנדר לא ירצה לימד על כל הפסולים שבשור ושה שהם בלא ירצה וכתב רחמנא במחוסר זמן מיום השמיני והלאה ירצה להוציאו מכלל שאר פסולים שהם בלא ירצה ולומר דבהאי ליכא אלא עשה כעין דבר שהיה בכלל ויצא לידון בדבר החדש בסוף פ\"ק דתמורה (דף יג:) וכענין זה הוי בדד ישב דמצורע בפ' אלו דברים (פסחים סז.) דאמרי' שהכתוב נתקו לעשה והוציאו מכלל שאר טמאים שהם בלאו דלא יטמאו את מחניהם ולהכי פריך דלילקי משום דמפורש בגופיה לאו בהדיא כדדרשינן מלא תעשון וכן פי' בקונטרס אבל בפרק אותו ואת בנו (חולין פא.) פירש בקונטרס דהוי כשאר לאו הניתק לעשה דעלמא דמיום השמיני והלאה ירצה משמע קודם זמנו לא ירצה והניחהו עד שיעבור זמנו וקשה מהך דשמעתא וכי תימא דהכי פריך משום דאיכא נמי לאו דלא תעשון לא אמרינן דאתי חד עשה ועקר תרי לאוי כדאמרי' בפ\"ק דתמורה (דף ד:) לא דמי דהני מילי התם דסמיכי גבי הדדי הלאוין אצל העשה תדע דהא בפרק ב' דמכות (ד' טו. ושם ד\"ה תנינא) חשיב לא יטמאו את מחניהם ניתק לעשה אי לאו משום דקדמו עשה אף על גב דאיכא לאו נמי דואל המקדש לא תבא ומיהו התם איכא למימר משום דאיכא תרי עשה דכתיב מחוץ למחנה תשלחום אבל אשכחן גזלה דאיכא תרי לאוי לאו דלא תעשוק ולא תגזול דבפרק המקבל (ב\"מ קיא.) אמר רבא זהו עושק זהו גזל וחשבי ליה ניתק לעשה במכות (דף יד:) ובחולין (דף פ:) הלכך צריך לחלק בההיא דתמורה (דף ד:) כדפרישית דלכך סמך שני הלאוין אצל העשה לומר שאין העשה מנתקם:"],[2,"רב נחמן בר יצחק אמר פנים דגלגל כו'","שינויא הוא דקמשני (התם) דאפילו לר\"ש לא לקי במחוסר זמן בפנים כי אם בחוץ כדפי' בקונטרס ויש גירסא אחרת בספרים לרבי שמעון ה\"נ והא גלגל פנים הוא אמר רב נחמן בר יצחק פנים דגלגל כו' וריש לקיש פריך דנפקא ליה מלא תעשון לאו במחוסר זמן דהאי קרא בגלגל קאי ופנים הוא וכי תימא קל וחומר בחוץ הא אין מזהירין מן הדין ומשני פנים דגלגל לגבי שילה כחוץ דמי:"],[5,"אלא לאו קודם חצות","ואע\"ג דחזי בפנים שלא לשמו לא מיחייב כרת כיון דמחוסר עקירה ואין עומד האי ליעקר קודם זמנו:"],[7,"היתר במה לחבירו","ושעת היתר הבמות דקתני היינו קודם חצות דכשר בבמה שלא לשמו וא\"ת דמשמע הכא דתורין שלא הגיע זמנן לרבי שמעון חיילא קדושה עלייהו והשוחטן בחוץ בלאו ובמעילה בפרק ולד חטאת (מעילה דף יב.) נמי אמר רבי שמעון דמועלין משום דראוין לאחר זמן ובתמורה בפרק אלו קדשים (תמורה דף יט:) גבי אשם בן שתים והביאו בן שנה אמר ר' שמעון דכל עצמן אינן קדושים משום דכל מידי דלא חזי ליה לגופיה לא נחתא ליה קדושת הגוף ופריך התם מאי שנא ממחוסר זמן דלא חזי ליה לגופיה (לא נחתא ליה קדושת הגוף) ואמר ר\"ש דקדוש פירוש במתני' דהכא דתנן מחוסר זמן רבי שמעון אומר בלא תעשה ומשני דאיתקוש לבכור דקדוש לפני זמנו וקרב לאחר זמן והשתא תינח מחוסר זמן תורין שלא הגיע זמנן מאי טעמא וי\"ל דדבר שאינו ראוי לשם קרבן ילפינן ממחוסר זמן שאין ראוי לשום קרבן אבל דבר שראוי לקרבן אחר ולקרבן זה שהוא מקדישו אינו ראוי לא נחתא ליה קדושת הגוף ופסח קודם חצות דקדוש לר' שמעון וכן חטאת ואשם דזב וזבה ויולדת ומצורע דקדושים קודם זמנן כדתנן בפירקין (לעיל זבחים קיב.) ולא פליג ר' שמעון ובתורת כהנים בפ' אחרי מות קאמר נמי רבי שמעון והשוחטן בחוץ בלאו הני אין מחוסר זמן בגופן ולא דמי לאשם בן שנה והביאו בן שתים בן שתים והביאו בן שנה דמחוסרי זמן בגופן וא\"ת דמחוסר זמן היאך קדוש הא אמרינן לעיל בפ\"ק (זבחים דף יב.) לילה לקדושה יום להרצאה אבל ביום שביעי לא ובבכורות פרק הלוקח בהמה (בכורות דף כא.) קאמר ר\"ש מחוסר זמן נכנס לדיר להתעשר יליף מבכור דקדוש לפני זמנו ופריך ואדיליף מבכור לילף מקדשים אלמא משמע דקדשים קודם זמנן לא קדשי וי\"ל דאסור להקדישם אבל אם הקדישם תוך זמנם קדושין אלא דעבד איסור דרחמנא אמר מיום השמיני אין הא קודם לכן לא אבל מעשר לרבי שמעון שרי להכניסו תוך זמנו לדיר להתעשר כדיליף התם מעשר העברה העברה מבכור והא דלא ניחא ליה למילף תחת תחת מקדשים דניחא ליה למילף העברה טפי משום דהעברה דתרוייהו משתעי שמעבירה להקדישה ויש ליתן טעם לרבא דריש תמורה (דף ד:) היאך מחוסר זמן קדוש קדושת הגוף דכל היכא דאמר. רחמנא לא תעביד אי עביד לא מהני ושמא לענין זה יליף תחת תחת ממעשר או שמא יש טעם אחר:"],[9,"דזעירי קבעוה תנאי","משום דמצורע יש בו טומאה כעין זב וזבה ויולדת אבל נזיר דלא דמי להו שייריה וכן בכריתות בפרק ארבעה מחוסרי כפרה (כריתות דף ח:) נמי אשכחן דתני זב וזבה ויולדת ומצורע והתם מפרש מאי טעמא לא תני מצורע ומצורעת כדקתני זב וזבה וניחא השתא לזעירי דבנזיר בלא מצורע סגי דאיכא תרתי בנזיר דנזיר טמא מביא אשם:"]]],[["פסח בשאר ימות השנה דאינו כשר לשמו וכשר שלא לשמו פסח בשאר ימות השנה שלמים נינהו","לימא מסייע ליה יכול שאני מוציא אף עולת מחוסר זמן בבעלים ואשם נזיר ואשם מצורע","ת\"ל (ויקרא יז, ג) שור מ\"מ כשב מ\"מ עז מ\"מ ואילו חטאת שיירא","במאי עסקינן אילימא בזמנו מאי איריא אשם אפילו חטאת נמי אלא שלא לזמנו","ובמאי אילימא לשמו אשם אמאי חייב אלא לאו שלא לשמו לעולם בזמנו ושלא לשמו","ורבי אליעזר היא דאמר מקשינן אשם לחטאת","ותנא טפל וה\"ה עיקר","ת\"ש יכול שאני מרבה עולת מחוסר זמן בגופה וחטאת בין בגופה בין בבעלים","ת\"ל (ויקרא יז, ד) ואל פתח אהל מועד כל שאינו ראוי לבא בפתח אהל מועד אין חייבין עליהן ואילו אשם שיירא","במאי עסקינן אילימא לשמו אשם נמי ליפטריה אלא לאו שלא לשמו","לעולם שלא לשמו ור\"א היא דמקיש אשם לחטאת תנא עיקר וכ\"ש לטפל","ת\"ש דכי אתא רב דימי אמר תנא דבי ר' ליואי יכול שאני מוציא אף עולת מחוסר זמן בבעלים אשם נזיר ואשם מצורע (מנין ונסיב להו תלמודא לחיובא ולא ידענא מאי היא)","מאי תלמודא אמר רבינא שור מכל מקום כשב מכל מקום עז מכל מקום הא מאי רומיא כדאמרת","אמר ר\"נ משום [דרמי] דתנא דבי ר' ליואי אדתני לוי אשם נזיר ואשם מצורע ששחטן שלא לשמן כשירין ולא עלו לבעלים לשום חובה","שחטן מחוסר זמן בבעלים או שהיו בני שתי שנים ושחטן פסולין","ומשני רב דימי לא קשיא כאן לשמו כאן שלא לשמו","רב אשי רמי מתני' אברייתא ומשני כאן לשמו וכאן שלא לשמו","לימא תיהוי תיובתיה דרב הונא","אמר לך רב הונא הכא במאי עסקינן כגון שהפריש שתי אשמות לאחריות דחד מינייהו מעיקרא עולה היא"],[[0,"פסח בשאר ימות השנה","אינו כשר לשמו דתנן שחטו קודם חצות פסול שנאמר בין הערבים:"],[0,"שלמים הוא","ואין זה אלא לשמו:"],[1,"לימא מסייע ליה","לרב חלקיה:"],[1,"יכול שאני מוציא","מאל פתח שלא יתחייב בחוץ על עולת מחוסר זמן בבעלים כגון של יולדת ומצורע הואיל ואינה ראויה לבא לפנים למצותה:"],[1,"ואשם נזיר ואשם מצורע","שיש בה פסול ולקמיה מפרש ואזיל מאי פסולה:"],[2,"שור מ\"מ כו'","דמצי למימר אשר ישחט במחנה או אשר ישחט מחוץ למחנה ואל פתח וגו' ואנא ידענא דשור או כשב או עז הוא:"],[2,"ואילו חטאת שייריה","ולא רבייה לחיובא:"],[3,"אי נימא בזמנו","ולשמו:"],[3,"מאי איריא","אשם דרבייה חטאת נמי מחייב דלא בעי רבוייא ואפילו אשם דהא חזי בפנים:"],[3,"אלא שלא בזמנו","רבייה לחיובא באשם:"],[4,"אי לשמו אשם אמאי חייב","והא אינו כשר ליקרב ומתני' תנא פטור ואי משום דראוי לשלא לשמו בפני' הא מחוסר עקיר' וכולהו מודו בו אלא לאו שלא לשמו רבי לחיובא בחוץ כרב חלקיה אלמא דבר שאינו כשר לשמו בפנים כשר לשלא לשמו ומחייב עליה שלא לשמו בחוץ:"],[4,"ה\"ג לעולם בזמנו ושלא לשמו","א\"נ ה\"ג לעולם בזמנו ותו לא וממילא אשלא לשמו דאוקימנא קאי ושכתבו בספרים ולשמו מפרש טועה כתבו ולפום ריהטא משום דפרכינן לעיל אי נימא בזמנו מאי איריא כו' וקא בעי לשנויי לעולם בזמנו ולשמו ודקא קשיא לך אי הכי חטאת נמי אין ה\"נ ותנא אשם והוא הדין לחטאת ולאו מילתא היא דא\"כ ר\"א מאי בעי הכא מכדי ר\"א לענין שלא לשמו אקשיה בפ\"ק (לעיל זבחים י:) בפסול אשם שלא לשמו כחטאת אבל לענין לשמו מאי עיקר ומאי טפל איכא תרוייהו כתיבי להכשיר בפנים וחיוב בחוץ ותו ל\"ל לרבויי להאי משור וכשב ועז הרי כשר ליקרב וכמצותו בפנים הוא שוחטו בחוץ אלא קא משני לעולם בזמנו ושלא לשמו ואיצטריך לרבוייה משום דשלא לשמו פסול הוא:"],[5,"ור\"א היא","דמקיש אשם לחטאת דמיפסיל בשלא לשמו בפנים באשמות דאפ\"ה מחייב עלה בחוץ אע\"ג דעקר מיניה שם אשם אכתי אי הוה מעייל ליה לפנים הוה כשר למישחטיה סתמא וכשר לשם אשם ועולה לשם חובה דמשום דיבוריה לא מיעקר שמיה מיניה וכל כמה דלא שחטיה ליה בעיקרה קאי סתמא לשמו הלכך כי שחיט ליה ראוי לפנים לשמו היה וה\"ה דאחטאת שלא לשמו נמי חייב אלא תנא טפל ואשמעינן אע\"ג דכה\"ג פסול בפנים מיחייב עליה בחוץ וה\"ה לעיקר דמ\"ש סוף סוף תרוייהו פסילי שלא לשמן ובת\"כ קתני בה בהדיא שלא לשמו וע\"כ מוקי לה כר\"א דאילו לרבנן לא איצטריך ליה לרבויי דהא כי האי גוונא מתקבלת בפנים היא:"],[7,"ת\"ש","סייעתא לרב חלקיה ותיובתא דרב הונא:"],[7,"בגופה","כגון תוך שמונה ללידתה:"],[7,"יכול שאני מרבה","גרס הכא דרישא דלעיל היא ובתורת כהנים הכי תניא לה אוציא את אלו שאינן מיוחדין לשם ולא אוציא עולה מחוסרת זמן בגופה וחטאת בין בגופה כו' והגרסנין שינו את הלשון וגרסינן הכא יכול שאני מרבה את כו' לפי שהביאוה בלימודא אחרינא וסברי דסיפא דההיא דלעיל היא: יכול שאני מרבה משום מכ\"מ אף עולה מחוסר זמן וכו':"],[7,"וחטאת בין בגופה בין בבעלים","כגון של נזיר ומצורע שלא מלאו ימיהם ואילו אשם נזיר ומצורע מחוסרי זמן בעלים שייריה ולא רבייה לפטורא שמע מינה ס\"ל דחייב:"],[9,"ובמאי אי נימא בלשמו אשם נמי ניפטריה","דהא לא חזי:"],[9,"אלא שלא לשמו","הלכך חטאת פטור דלא חזי לפנים ואשם חייב דחזי לפנים ואף על גב דאין ראוי לשמו והיינו כרב חלקיה ודלא כרב הונא:"],[10,"","ה\"ג הא מני ר\"א היא כו' ולא גרסינן לעולם בלשמו:"],[10,"הא מני ר\"א היא","כלומר ודאי בשלא לשמו היא כדקאמרת הלכך חטאת פטור דלא חזי בפנים לא בלשמו ולא בשלא לשמו דמחוסר זמן הוא ואשם נמי פטור דלא חזי לפנים לשמו במחוסר זמן ולא לשלא לשמו דר\"א קאמר דפסול באשם שלא לשמו והאי דשייריה לאשם לאו דס\"ל דחייב אלא כיון דחד טעמא הוא משום דתרוייהו פסולין שלא לשמו בפנים הוא תנא עיקר חטאת דפטור וכ\"ש טפל אשם והאי כ\"ש גמגום ודוחקיה דרב הונא לאוקמיה כר\"א משום סיפא דעל כרחיך כרבי אליעזר מיתוקמא כדפרישנא לעיל ועוד משום דלרבנן לא ילפינן אשם מחטאת ליכא למימר תנא האי והוא הדין להאי ואף על גב דלרבנן נמי קאמר דפטור דאין לך דבר שאינו כשר לשמו וכשר שלא לשמו לא מצי לאוקומא כרבנן דא\"כ נשמעינן אשם דפטור דנשמעינן בה תרתי וכ\"ש חטאת:"],[11,"ת\"ש דכי אתא רב דימי כו' ואילו חטאת שיירא ובמאי כו'","כדאותיבנא בקמייתא:"],[12,"ומאי קושיא","לסיועה לרב חלקיה דלמא ה\"נ כדאמרינן דבזמנו קאי כדאוקמא בקמייתא לעיל ור\"א היא:"],[13,"אמר ר\"נ בר יצחק","לא מצי לאוקומי להא בזמנו משום דרב דימי קשיא ליה דתני (ליה) בר ליואי אדתני לוי שחטן מחוסר זמן בבעלים פסולין ובחוץ נמי נפטר:"],[15,"ומשני ליה רב דימי","הא דתני חייב שלא לשמו והא דתני פסולין ודכוותיה בחוץ פטור בששחטן לשמו ומדקשיא ליה דתני לוי אבר ליואי ש\"מ שמיע ליה לרב דימי דמתני' דבר ליואי נמי במחוסר זמן וקאמר חייב ואע\"ג דאינו ראוי לשמו בפנים ראוי לשלא לשמו וסייעתא לרב חלקיה:"],[16,"רב אשי רמי מתני'","דקתני לשמו פטור אברייתא קמייתא דתניא לעיל חייב:"],[16,"ומשני מתני' לשמו וברייתא שלא לשמו","כרב חלקיה:"],[17,"נימא תהוי תיובתיה דרב הונא","מדכי אתא רב דימי כדאמרן דליכא לאוקומא בזמנו מדקשיא ליה תני לוי אדתני בר ליואי:"],[18,"הכא במאי עסקינן","דמחוסר זמן חייב בשלא לשמו:"],[18,"כגון שהפריש שני אשמות לאחריות","שאם יאבד האחד יתכפר בשני ושחט אחד מהם בחוץ קודם זמנו לשם עולה דהאי כיון דסופו לרעייה קאי דאשם שכיפרו בעליו רועה ודמיו לקיץ המזבח שהיא עולה חזי לדוכתיה בפנים אי שחיט לגופיה לעולה:"]],[[0,"פסח בשאר ימות השנה שלמים הוא","פי' בקונטרס ואין זה אלא לשמו משמע שרוצה לומר דכיון דשלמים הוא כששוחטו לשם שלמים היינו לשמו וא\"ת והלא כששחטו לשם עולה או לשם זבח אחר הוי נמי שלמים כדאמרי' בפ\"ק (לעיל זבחים ח:) לכל דשחיט ליה שלמים ליהוי וי\"ל דמ\"מ כיון דשלמים הוא הרי הוא כשר לשמו ושלא לשמו כגון לשם שלמים ולשם זבח אחר:"],[1,"מחוסר זמן בבעלים","אעולה דוקא קאי ולא אאינך:"],[14,"או שהיו בני שתי שנים ושחטן פסולין","הך ברייתא איתא בפ' התכלת (מנחות מח:) והכא והתם קתני פסולין ועוד תניא התם באידך ברייתא פסולין ותעובר צורתן ויצאו לבית השריפה ותימה דבתמורה בפ' אלו קדשים (תמורה דף יט:) תניא אשם בן שנה והביאו בן שתים בן שתים והביאו בן שנה כשרים ולא עלו לשם בעלים לשם חובה ר\"ש אומר כל עצמן אינן קדושים וי\"ל דכאן לשמו כאן שלא לשמו כדמשני הכא ומיהו קשה דא\"כ קשיא לרב הונא הא איכא האי דפסול לשמו וכשר שלא לשמו ועוד דאי בשלא לשמו מיירי בתמורה ל\"ל למיתני ולא עלו לשם חובה הא אפי' במצותו נמי דכיון דשלא לשמו הוא אין עולה לשם חובה:"]]],[["כדרב הונא אמר רב דאמר רב הונא אמר רב אשם שניתק לרעיה ושחטו סתם כשר לעולה:","המעלה מבשר חטאת [וכו']: ת\"ר מנין למעלה מבשר חטאת ומבשר אשם ומבשר קדשי קדשים ומבשר קדשים קלים וממותר העומר ושתי הלחם ולחם הפנים ושירי מנחות שפטור","ת\"ל עולה מה עולה שהיא ראויה להעלאה אף כל שראויה להעלאה","מנין שאף היוצק והבולל והפותת והמולח והמניף והמגיש והמסדר השלחן והמטיב את הנרות והקומץ והמקבל בחוץ שפטור","ת\"ל (ויקרא יז, ח) אשר יעלה עולה או זבח מה העלאה שהיא גמר עבודה אף כל שהוא גמר עבודה:","עד שלא הוקם המשכן [וכו']: יתיב רב הונא בר רב קטינא קמיה דרב חסדא וקא קרי (שמות כד, ה) וישלח את נערי בני ישראל א\"ל הכי אמר ר' אסי (קרבו) ופסקו","סבר לאותוביה ממתניתין שמעיה דקאמר משמיה דרב אדא בר אהבה עולה שהקריבו ישראל במדבר אינה טעונה הפשט וניתוח אותביה ברייתא דשויא בכולהו","דתני' עד שלא הוקם המשכן הבמות מותרות ועבודה בבכורות והכל כשירין להקריב בהמה חיה ועוף זכרים ונקבות תמימין ובעלי מומין טהורין אבל לא טמאין","והכל קרבו עולות ועולה שהקריבו ישראל במדבר טעונה הפשט וניתוח ונכרים בזמן הזה רשאין לעשות כן","תנאי היא דתניא (שמות יט, כב) וגם הכהנים הנגשים אל ה' יתקדשו ר' יהושע בן קרחה אומר זו פרישות בכורות רבי אומר זו פרישות נדב ואביהוא","בשלמא למ\"ד זו פרישות נדב ואביהוא היינו דכתיב (ויקרא י, ג) הוא אשר דבר ה' לאמר בקרובי אקדש","אלא למ\"ד זו פרישות בכורות היכא רמיזא דכתיב (שמות כט, מג) ונועדתי שמה לבני ישראל ונקדש בכבודי אל תקרי בכבודי אלא במכובדיי","דבר זה אמר הקב\"ה למשה ולא ידעו עד שמתו בני אהרן כיון שמתו בני אהרן אמר לו אהרן אחי לא מתו בניך אלא להקדיש שמו של הקב\"ה כיון שידע אהרן שבניו ידועי מקום הן שתק וקבל שכר שנאמר (ויקרא י, ג) וידום אהרן","וכן בדוד הוא אומר (תהלים לז, ז) דום לה' והתחולל לו אע\"פ שמפיל לך חללים חללים את שתוק וכן בשלמה הוא אומר (קהלת ג, ז) עת לחשות ועת לדבר פעמים ששותק ומקבל שכר על השתיקה פעמים מדבר ומקבל שכר על הדבור","והיינו דא\"ר חייא בר אבא א\"ר יוחנן מאי דכתיב (תהלים סח, לו) נורא אלהים ממקדשך אל תיקרי ממקדשך אלא ממקודשיך בשעה שעושה הקב\"ה דין בקדושיו מתיירא ומתעלה ומתהלל","אלא קשיא עולה תרי תנאי היא דתניא ר' ישמעאל אומר כללות נאמרו בסיני ופרטות באהל מועד","ר\"ע אומר כללות ופרטות נאמרו בסיני ונשנו באהל מועד ונשתלשו בערבות מואב","אמר מר הכל כשירין להקריב מנא הני מילי אמר רב הונא דאמר קרא (בראשית ח, כ) ויבן נח מזבח לה' ויקח מכל הבהמה הטהורה ומכל עוף הטהור בהמה כמשמעו חיה בכלל בהמה"],[[0,"כדרב הונא אמר רב כו' שניתק לרעייה","שניתק מדין הקרבה ומסרוהו לרועה עד שיסתאב דקי\"ל (תמורה דף יח.) כל שבחטאת מתה באשם רועה:"],[2,"עולה","אשר יעלה עולה:"],[4,"גמר עבודה","שאין אחריה עבודה ואיתרבו להו באף כל כגון המנסך ומקטיר קטרת ומקטיר קמצים ומקטיר מנחת כהנים:"],[5,"ויתיב רב חסדא וקאמר וישלח את נערי בני ישראל","נראה בעיני שהספרים חסרים כאן ולא ידעתי מה ואם אין חסרין זהו פירושו יתיב רב חסדא וקאמר להאי קרא וישלח את נערי וגו' ומפרש דאלו הבכורות:"],[5,"א\"ל רב הונא הכי אמר רב אסי ופסקו","אותו היום פסקה עבודה מן הבכורות שמסיני נצטוו על הכהונה כדיליף לקמן ושמשו נדב ואביהוא כל אותה שנה ראשונה עד שהוקם המשכן ומתו:"],[5,"לישנא אחרינא הכי אמר רב אסי ופסקיה","צריך להפסיק כאן נגינת טעם המקרא באתנחתא ולא יקרא בטעם פשטא כמו שאנו קורין אותו דכשהוא נקרא בטעם פשטא משמע שקריאת נערי בני ישראל דבק על ויעלו עולות משמע שהם העלום אבל כשאתה קורהו באתנחתא עומדת התיבה לבדה ואינה דבק על ויעלו וי\"ל שלא שלחם אלא להביא הקרבנות ולעמוד עליהם ויעלו עולות אותם שכשרים להעלותם דהיינו נדב ואביהוא שמשבאו לסיני הופרשו הכהנים כדיליף לקמן:"],[6,"סבר רב חסדא לאותביה מתני'","דקתני שנהגו עבודה בבכורות עד יום הקמת המשכן:"],[6,"שמעיה","רב חסדא לרב חנא דיתיב וקאמר תו משמיה דרב אדא כו':"],[6,"עולה שהקריבו ישראל במדבר סיני","קודם מתן תורה וישלח את נערי וגו':"],[6,"איתיביה מברייתא דשוויא בכולהו","שתהא שוה להשיב על כל דבריו:"],[7,"והכל כשרין ליקרב","כדמפרש ואזיל בהמה וחיה ועוף כו':"],[8,"והכל קרבו עולות","השתא משמע שלא היו מקריבין אלא עולות ולקמיה פריך עליה:"],[8,"רשאין לעשות כן","דלא נאסרו להן הבמות:"],[9,"יתקדשו","מלעלות ואע\"פ שרגילין לגשת אלי ולהעלות העד בהן שלא יעלו בהר:"],[9,"זו פרישת בכורות","הזהיר את הבכורות להפריש מן ההר:"],[9,"זו פרישת נדב ואביהוא","כלומר לא נקראו בכורות כהנים אלא מי הן הכהנים הנגשים שהוזהרו כאן לפרוש מן ההר זה נדב ואביהוא שנעשו בסיני כהנים והן הכהנים הנגשים אל ה' להקריב קרבנות:"],[10,"היינו דכתיב","כשמתו נדב ואביהוא אשר דבר וגו' כדקאמר בסיני (שמות יט) פן יפרוץ בהם ה' וכיון שלא נזהרו לפרוש מן ההיכל בהקמת המשכן פרץ בהם:"],[11,"אלא למ\"ד זו פרישת בכורות היכא רמיזא","ה\"ג ולא גרסי' פרישת נדב ואביהוא היכא רמיזא מיתת נדב ואביהוא היכא רמזה למשה קודם לכן דקאמר הוא אשר דבר:"],[11,"ונקדש בכבודי","נאמרה לו למשה ביום שנצטווה על מלאכת המשכן ורמז לו שביום שישרה שכינתו על הבית יתקדש בכבודיו ולא נרמז להבין מה הוא עד שמתו:"],[12,"אלא כדי להתקדש כבודו של מקום עליהם","להודיע שהוא נורא על יראיו ומיודעיו וזהו הוא אשר דבר אלי ביום שנצטויתי על המשכן ונקדש בכבודי באותם הנכבדים וקרובים לי אקדש:"],[12,"שנאמר וידום אהרן","הרי ששתק וקבל השכר מפרש בב\"ר שמתוך כך זכה ונתייחד אליו הדיבור שנאמר אחרי אותו ענין פרשת שתויי יין ולא הוזכר באותו דיבור משה אלא אהרן:"],[14,"נורא אלהים ממקדשך","אלהים זו מדת הדין אימתי הוא נורא ע\"י שהוא עושה דין במקודשיו:"],[15,"אלא עולה קשיא","דקתני הכא [דטעונה הפשט] וניתוח:"],[15,"כללות נאמרו בסיני","כגון מזבח אדמה תעשה לי וזבחת עליו וגו' ולא נתפרשו הלכות עולה ושלמים שם:"],[15,"ופרטות באהל מועד","לאחר שהוקם המשכן נאמרה ת\"כ למשה ושם נתפרשו והפשיט ונתח לרבי ישמעאל שמעי' דעולה שהקריבו בסיני לא הוטענה הפשט וניתוח:"],[16,"נשתלשו בערבות מואב","משנה תורה שחזר משה ואמרה להם על הסדר כדכתיב (דברים א׳:ה׳) בעבר הירדן בארץ מואב הואיל משה וגו':"],[17,"חיה בכלל בהמה","דכתיב זאת הבהמה אשר תאכלו וגו' וסמיך ליה איל וצבי ויחמור וגו' (שם יד):"]],[[4,"מה העלאה שהיא גמר עבודה כו'","סוגיא זו קשה אההיא דלעיל בריש השוחט (זבחים דף קז: ושם) דדרשינן להכי כתב רחמנא או לרבות את הזורק דלא תיתי מבינייא ומשום הכי פטור מקבל בחוץ:"],[5,"ויתיב וקאמר וישלח וגו'","פירש בקונטרס ויתיב רב חסדא וקאמר ונראה לפרש דיתיב וקאמר ארב הונא קאי:"],[5,"א\"ל הכי אמר רב אסי ופסקוהו","פי' כמו שאמרת אמר רב אסי דוישלח היינו עבודה בבכורות אבל חכמים הפסיקוהו ומנעוהו מלומר כן ושני לשונות שבקונטרס עיקר:"],[12,"רמזו הקב\"ה למשה ולא ידעו","פי' ולא ידע במי אבל היה יודע שעתיד הקב\"ה לקדש את המשכן באדם גדול דאמרי' במדרש שאמר לו משה לאהרן הייתי סבור בי או בך:"],[13,"וקיבל שכר על שתיקתו","תניא בתורת כהנים שבשכר זה נתייחד אצלו הדיבור דכתיב בפרשת יין ושכר אל תשת וידבר ה' אל אהרן ולא כתיב אל משה ותימה דבסיפרי דריש בפרשת קרח דכתיב וידבר אל אהרן שומע אני שהדיבור אל אהרן ת\"ל כאשר דבר ה' ביד משה לו בפרשת מחתות השרופים הא למדנו שהדיבור למשה שיאמר לאהרן ושמא זה קורא נתייחד הא דכתיב אל אהרן ולא שיאמר לבני ישראל:"],[15,"כללות נאמרו בסיני כו'","הוה מצי לאיתויי מדר' יוסי הגלילי דאמר בפ\"ק דחגיגה (דף ו: ולקמן זבחים קכ.) דאין טעונה הפשט וניתוח:"]]],[["זכרים ונקבות תמימין ובעלי מומין (דאמר מר תמות וזכרות בבהמה ואין תמות וזכרות בעופות","ואיתקש בהמה לעוף","תמימין ובעלי מומין) לאפוקי מחוסר אבר דלא א\"ר אלעזר מנין למחוסר אבר שנאסר לבני נח ת\"ל (בראשית ו, יט) ומכל החי מכל בשר אמרה תורה הבא בהמה שחיין ראשי איברין שלה","ודילמא למעוטי טריפה ההוא מלחיות זרע נפקא","הניחא למ\"ד טריפה אינה יולדת אלא למ\"ד טריפה יולדת מאי איכא למימר האמר קרא אתך בדומין לך","ודילמא נח גופיה טריפה הוה תמים כתיב ביה ודילמא תמים בדרכיו צדיק כתיב ביה","ודילמא תמים בדרכיו צדיק במעשיו אי סלקא דעתך דנח גופיה טריפה הוה מי קאמר ליה לנח דכוותך עייל שלמים לא תעייל","ומאחר דנפקא לן מאתך לחיות זרע למה לי מהו דתימא אתך לצותא בעלמא אפי' זקן אפילו סריס קמשמע לן:","טהורין אבל לא טמאין: ומי הוו טמאין וטהורין בההיא שעתא א\"ר שמואל בר נחמני א\"ר יונתן מאותן שלא נעבדה בהן עבירה","מנא הוו ידעי כדרב חסדא דאמר רב חסדא העבירן לפני התיבה כל שהתיבה קולטתן בידוע שהוא טהור אין התיבה קולטתן בידוע שהן טמאין","רבי אבהו אמר אמר קרא (בראשית ז, טז) והבאים זכר ונקבה הבאין מאיליהן","אמר מר והכל קרבו עולות עולות אין שלמים לא והא כתיב (שמות כד, ה) ויזבחו זבחים שלמים לה' פרים אלא אימא הכל קרבו עולות [ושלמים","והתניא אבל שלמים לא כי אם עולות] עולות אין שלמים לא כמ\"ד לא קרבו שלמים בני נח דאיתמר ר\"א ור' יוסי בר חנינא חד אמר קרבו [שלמים בני נח] וחד אמר לא קרבו","מ\"ט דמ\"ד קרבו שלמים בני נח דכתיב (בראשית ד, ד) והבל הביא גם הוא מבכורות צאנו ומחלביהן איזהו דבר שחלבו קרב לגבי מזבח ואין כולו קרב לגבי מזבח הוי אומר זה שלמים","מ\"ט דמ\"ד לא קרבו דכתיב (שיר השירים ד, טז) עורי צפון ובואי תימן תתנער אומה שמעשיה בצפון ותבוא אומה שמעשיה בצפון ובדרום","ומר נמי הכתיב ומחלביהן משמניהן [דידהו]","ומר נמי הכתיב עורי צפון [ההוא] בקיבוץ גליות הוא דכתיב","והא כתיב (שמות י, כה) ויאמר משה גם אתה תתן בידינו זבחים ועולות ועשינו לה' אלהינו זבחים לאכילה ועולות להקרבה","והא כתיב (שמות יח, יב) ויקח יתרו [חותן משה] עולה וזבחים ההוא לאחר מתן תורה הוא דכתיב","הניחא למ\"ד [יתרו] אחר מתן תורה היה אלא למ\"ד [יתרו] קודם מתן תורה היה מאי איכא למימר דאיתמר בני ר' חייא ור' יהושע בן לוי חד אמר יתרו קודם מתן תורה היה וחד אמר יתרו אחר מתן תורה היה למ\"ד יתרו קודם מתן תורה היה קסבר שלמים הקריבו בני נח","כתנאי (שמות יח, א) וישמע יתרו כהן מדין מה שמועה שמע ובא ונתגייר ר' יהושע אומר מלחמת עמלק שמע שהרי כתיב בצדו (שמות יז, יג) ויחלש יהושע את עמלק ואת עמו לפי חרב","ר\"א המודעי אומר מתן תורה שמע [ובא] שכשניתנה תורה לישראל היה קולו הולך מסוף העולם ועד סופו וכל [מלכי] עובדי כוכבים אחזתן רעדה בהיכליהן ואמרו שירה שנאמר (תהלים כט, ט) ובהיכלו כולו אומר כבוד","נתקבצו כולם אצל בלעם הרשע ואמרו לו מה קול ההמון אשר שמענו שמא מבול בא לעולם (אמר להם) (תהלים כט, י) ה' למבול ישב [אמר להם] וישב ה' מלך לעולם כבר נשבע הקב\"ה שאינו מביא מבול לעולם","אמרו לו מבול של מים אינו מביא אבל מבול של אש מביא שנא' (ישעיהו סו, טז) כי (הנה) באש ה' נשפט אמר להן כבר נשבע שאינו משחית כל בשר","ומה קול ההמון הזה ששמענו אמר להם חמדה טובה יש לו בבית גנזיו שהיתה גנוזה אצלו תתקע\"ד דורות קודם שנברא העולם וביקש ליתנה לבניו שנאמר (תהלים כט, יא) ה' עוז לעמו יתן [מיד] פתחו כולם ואמרו (תהלים כט, יא) ה' יברך את עמו בשלום","ר\"א אומר קריעת ים סוף שמע ובא שנא' (יהושע ה, א) ויהי כשמוע כל מלכי האמורי ואף רחב הזונה אמרה לשלוחי יהושע (יהושע ב, י) כי שמענו את אשר הוביש ה' את מי ים סוף","מאי שנא התם דאמר (ליה) (יהושע ה, א) ולא היה בם עוד רוח ומ\"ש הכא דקאמר (יהושע ב, יא) ולא קמה עוד רוח באיש"],[[2,"ה\"ג זכרים ונקבות תמימים ובעלי מומין לאפוקי מחוסר אבר דלא","ולא גרסי' תמות וזכרות בבהמות כו' דמאי איריא קודם מתן תורה לאחר הקמת המשכן נמי איתא להא ועוד מדקאמר אבל מחוסר אבר לא מכלל דבעלי מומין לא נפסלו לא בבהמה ולא בעוף:"],[2,"שנאסר לבני נח","להקריב לגבוה:"],[2,"שחיין ראשי איברים","ולמה לי לאזהורי עלייהו אי לאו משום הקרבה שהקריב מהן בצאתו מן התיבה:"],[3,"מלחיות זרע נפקא","דטריפה אינה יולדת:"],[4,"בדומין לך","למעוטי טריפה:"],[6,"תמים בדרכיו","עניו וסבלן:"],[7,"מהו דתימא אתך","לאו למידרש בדומין לך אלא שהודיע שאינו עושה אלא לכבודו להיות לו לצוותא:"],[7,"קמ\"ל לחיות זרע","לאו לצוותא בעי להו ומהשתא על כרחך אתך יתירא הוא למידרש ביה בדומין לך:"],[8,"מי הוו","הרי לא נתנה תורה:"],[10,"הבאין מאיליהן","וכל אותן שבאו אל התיבה מאיליהן באו ובהן הכיר אותם שבאו שבעה שבעה ידע שהן טהורין ושבאו שנים שנים שהן טמאין:"],[11,"ויזבחו זבחים שלמים","וסיני קודם הקמת המשכן הוה ואת אמרת דעד [שלא] הוקם המשכן לא קרבו שלמים כלל:"],[11,"לכל","בין לישראל בין לבני נח קרבו עולות אבל שלמים לא קרבו לבני נח ומשעת מתן תורה שנבחרו ישראל קרבו להם שלמים:"],[14,"תתנער","לשון (שמות י״ד:כ״ז) וינער ה' את מצרים:"],[14,"שמעשיה בצפון","היינו עולה שטעונה צפון:"],[14,"ותבא","אל מלך המשיח:"],[14,"אומה שמעשיה צפון ודרום","דהיינו ישראל שמקריבין עולות ושלמים:"],[15,"משמניהון דידהו","מן השמנין שבהן ומיהו עולות הוו:"],[16,"בקיבוץ גליות","[וה\"ק] עורי רוח צפונית ובואי רוח דרומית לקבץ גליות המפוזרות בכם:"],[17,"זבחים ועולות","זבחים היינו שלמים וקודם מתן תורה כולהו בני נח. ומשני זבחים אינן שלמים אלא לשון שחיטה בעלמא ולאכילה:"],[19,"הניחא למ\"ד כו'","פלוגתא לקמן:"],[20,"כתנאי","אי קודם מתן תורה הוה [יתרו] אי לאחר:"],[21,"ובהיכלו כולו אומר כבוד כו'","רישא דקרא קול ה' יחולל אילות ובמתן תורה משתעי ובהיכלו של כל מלך ומלך כולו אומר כבוד להקב\"ה:"],[24,"אמר להם וישב ה' מלך לעולם","כבר נשבע שיהא מלך לעולם על בריותיו ולא ישחיתם:"],[24,"תשע מאות ושבעים וארבעה דורות קודם שנברא העולם","וכ\"ו מאדם ועד משה רבינו הרי דבר צוה לאלף דור (תהילים ק״ה:ח׳):"],[24,"עוז","התורה שהיא מעוזן של ישראל:"]],[[3,"ודילמא למעוטי טריפה","תימה דבפ' שילוח הקן (חולין דף קמ. ושם) גבי שתי צפרים חיות דרשי' מינה תרתי שחיין ראשי איברים שלה ולמעוטי טריפה וי\"ל דשאני ציפורי מצורע שהוא כעין קרבן ושניהן שוין לענין פסול אבל גבי נח דשאר מומין כשרין הו\"ל לאוקמיה למעוטי טריפה דוקא:"],[4,"אבל למ\"ד טריפה יולדת מאי איכא למימר","פי' דלדידיה לא מייתר ליה מכל החי למחוסר אבר ואיצטריך למעוטי טריפה וא\"ת כיון דטריפה חיה ויולדת היכי מימעטא מכל החי הא בפ' שילוח הקן (ג\"ז שם) לא ממעט מחיות טריפות למ\"ד טריפה חיה ויש לומר דשאני הכא דמכל החי מיותר ושפיר משתמע למעוטי טריפה אע\"ג דחיה דמשתמע חיות גמורה ומסתבר למעוטי טריפה אע\"ג דחיה ויולדת טפי ממחוסרת אבר דמ\"מ אין טריפה בריאה נשארת ולא חזיא לקיום העולם כולי האי:"],[4,"אתך בדומין לך","וא\"ת א\"כ האי מכל החי למה לי דתרוייהו מאתך נפקא וכי תימא דלמא נח גופיה מחוסר אבר הוה מי קאמר רחמנא דכוותך עייל שלמים לא תעייל וי\"ל דמוקמא קרא בדדמי לטריפה ולא דמי למחוסרת אבר דלענין קיום העולם לא חיישינן:"],[5,"דילמא נח גופיה טריפה הוה","וא\"ת והלא חי אחרי כן ג' מאות שנה וי\"ל דשמא לא היה בכח ובריאות כראוי לו וסוגיין כמ\"ד טריפה חיה ור\"ת היה רגיל לחלק בין טריפות דאדם לטריפות דבהמה משום דאדם אית ליה מזלא וקשה דבריש אלו טריפות (חולין דף מג.) מייתי ראיה מאיוב אטריפות דבהמה:"]]],[["דאפילו אקשויי נמי לא אקשו ומנא ידעה דאמר מר אין לך כל שר ונגיד שלא בא על רחב הזונה","אמרו בת י' שנים היתה כשיצאו ישראל ממצרים וזנתה [כל] מ' שנה שהיו ישראל במדבר אחר נ' שנה נתגיירה אמרה יהא מחול לי בשכר חבל חלון ופשתים:","אמר מר ועובדי כוכבים בזמן הזה רשאין לעשות כן מנא ה\"מ דת\"ר (ויקרא יז, א) דבר אל בני ישראל בני ישראל מצווין על שחוטי חוץ ואין העובדי כוכבים מצווין על שחוטי חוץ","לפיכך כל אחד ואחד בונה לו במה לעצמו ומקריב עליה כל מה שירצה א\"ר יעקב בר אחא אמר רב אסי אסור לסייען ולעשות שליחותן אמר רבה ולאורינהו [להו] שרי","כי הא דאיפרא הורמיז אימיה דשבור מלכא שדרה קורבנא לרבא שלחה ליה אסקוה ניהליה לשם שמים אמר להו לרב ספרא ולרב אחא בר הונא זילו ודברו תרי עולמי גולאי וחזו היכא דמסקא ימא שירטון ושקלו ציבי חדתי ואפיקו נורא ממרא חדתא ואסקוה ניהליה לשם שמים","א\"ל אביי כמאן כר\"א בן שמוע דתניא ר' אלעזר בן שמוע אומר מה מזבח שלא ישתמש בו הדיוט אף עצים שלא ישתמש בהן הדיוט והא מודה ר\"א בן שמוע בבמה","דתניא כתוב אחד אומר (דברי הימים א כא, כה) ויתן דוד לארנן במקום שקלי זהב משקל שש מאות וגו' וכתיב (שמואל ב כד, כד) ויקן דוד את הגרן ואת הבקר בכסף שקלים חמשים הא כיצד","גובה מכל שבט ושבט חמשים שהן שש מאות רבי אומר משום אבא יוסי בן דוסתאי בקר [ועצים] ומקום מזבח בנ' וכל הבית כולו בשש מאות","ר\"א בן שמוע אומר בקר ועצים ומקום מזבח בנ' וכל הבית כולו בשש מאות דכתיב (שמואל ב כד, כב) ויאמר ארונה אל דוד יקח ויעל אדוני המלך [הטוב בעיניו] ראה הבקר לעולה והמוריגים [וכלי הבקר] לעצים ורבא אמר לך התם נמי בחדתי","מאי מוריגים אמר עולא מטה של טורבל מאי מטה של טורבל אמר אביי עיזא דקרקסא דדיישן דישאי אמר אביי מאי קרא (ישעיהו מא, טו) הנה שמתיך למורג חרוץ חדש בעל פיפיות","מקרי ליה רבא לבריה ורמי ליה קראי אהדדי כתיב ויתן דוד לארנן וגו' וכתיב ויקן דוד וגו' הא כיצד גובה מכל שבט ושבט חמשים שהן שש מאות","ואכתי קשיין אהדדי התם כסף הכא זהב אלא ה\"ק גובה כסף במשקל שש מאות זהב:","קדשים קלים נאכלים [בכל מחנה ישראל]: אמר רב הונא בכל מקומות ישראל אבל מחנה לא הוי","איתיביה ר\"נ לרב הונא ומחנות במדבר לא הואי והא תניא כשם שמחנה במדבר כך מחנה בירושלים מירושלים להר הבית מחנה ישראל מהר הבית לשער נקנור מחנה לויה","מכאן ואילך מחנה שכינה והן הן קלעים שבמדבר","אלא אימא בכל מקום מחנה ישראל פשיטא מהו דתימא איפסלו ביוצא קמ\"ל","ואימא ה\"נ אמר קרא (במדבר ב, יז) ונסע אהל מועד אע\"פ שנסע אהל מועד הוא","תניא רשב\"י אומר עוד אחרת היתה וחיל עזרת נשים היא ולא היו עונשין עליה ובשילה לא היו אלא שני מחנות בלבד","הי מינייהו לא הוה אמר רבה מסתברא דמחנה לויה הואי דאי סלקא דעתך מחנה לויה לא הואי"],[[0,"דאפי' אקשויי","אבר לתשמיש לא אקשו והיא שהיתה יודעת בדבר אמרה לשלוחי יהושע בלשון זה:"],[0,"דאמר מר","במכילתא בפ' יתרו:"],[1,"אמרה ימחל לי בשביל חבל ופשתים וחלון","במכילתא תניא הכי אמרה רבש\"ע בג' דברים חטאתי בג' ימחל בחבל ופשתים וחלון שהיו מנאפים עולין אליה בחבלים דרך החלון ויורדים וגם טמנתם בפשתי העץ ובאותן שלשה דברים עצמן זכתה להציל השלוחים:"],[3,"אסור לסייען","בשעת איסור הבמות כגון בזמן הזה דקדושת ירושלים אין אחריה היתר:"],[3,"אורויי להן","היאך יעשו:"],[4,"זילו דברו תרין עולמי גילאי","לכו וקחו שני עובדי כוכבים בחורים בני גיל אחד שכן נוי לדבר:"],[4,"דמסקא ימא שירטון","לימון בלע\"ז ומתייבש ונעשה קרקע דבעינן שלא נשתמש הדיוט במזבח:"],[4,"ואייתו ציבי חדתי","שלא נשתמש בהן אדם שלא יהא שברי כלים:"],[4,"ואפקו נורא ממרא חדתא","נ\"ל שהוא פויישי\"ר של איסתמא אציי\"ר בלע\"ז שמוציאין בו אש מן האבנים:"],[5,"","ה\"ג כמאן כר\"א בן שמוע דתניא ר\"א בן שמוע אומר מה מזבח כו'. ובת\"כ היא שנויה בפרשה ראשונה:"],[5,"הא מודה ר' אלעזר בבמה","דקתני המוריגים לקח דוד לעצים כדבר ארונה:"],[6,"כתוב אחד אומר","ברייתא זו משובשת בספרים ושנויה היא בספרי בברכת כהנים וכך היא שנויה הא כיצד מקום מזבח בחמשים וכל הבית בשש מאות רבי אומר בשם אבא יוסי בן דוסתאי גבה מכל שבט חמשים שהן שש מאות ר\"א בן שמוע אומר ויקן דוד את הגורן כדמפרש בענין ויתן דוד לארונה במקום [שקלי] זהב משקל שש מאות אבל הבקר לעולה והמוריגים וכלי הבקר לעצים בכסף שקלים חמשים ויאמר ארונה וגו' (ע\"כ הגי') והכי פירושא דקרא ויקן דוד את הגורן ולא פירש במה קנאו שהרי פירשו במקום אחר כבר (דברי הימים א כ״א:כ״ה) ויתן דוד לארונה במקום וגו' ואת הבקר קנה בכסף שקלים חמשים (זהב):"],[6,"משקל שש מאות","לקמיה מפרש כסף שוה משקל שש מאות זהב:"],[9,"מטה של טורבל","כך נקרא במסכת פרה (פי\"ב מ\"ט):"],[9,"עיזא דקורקסא","כמין עז של עץ ויש בו יתידות חדים [וגם עשוי] חריצים חריצים קרני\"ש ומוליכו ומביאו על הקשים של דישה לאחר שנידושה ומתחתכין ונעשין תבן:"],[9,"מאי קרא","דהוא עשוי חריצים ומוכן לדוך ולדוק:"],[11,"כסף שש מאות שקלי זהב","וה\"ק כסף שוה שקלים חמשים של זהב גבה מכל שבט ושבט:"],[12,"בכל מקומות ישראל","קא סלקא דעתך השתא דאפי' יצא אחד מהן חוץ למחנה ישראל אוכל קדשים קלים שם:"],[13,"שער נקנור","של עזרה היה שער המזרח:"],[14,"והן הן קלעים שבמדבר","לפנים משער נקנור הוה כמקום לפנים מן הקלעים במשכן:"],[15,"אימא בכל מקומות מחנה ישראל","שאפי' בשעת סילוק מסעות אין נפסלים אלא מוליכן עמו ובמקום חנייתן אוכלין במחנה:"],[17,"עוד אחרת היתה","מחנה רביעית חלוקה מהר הבית ומעזרה ולא היו עונשין עליה על הנכנס לה בטומאה במסכת כלים (פ\"א מ\"ח) מפרש מה היא חלוקתו מהר הבית:"],[18,"דמחנה לויה מיהא הואי","ומחנה ישראל הוא דחסר דאם לא כן דמחנה ישראל הואי ולא מחנה לויה:"]],[[3,"אסור לסייען ואסור לעשות שליחותן","תימה לר' יוסי דאמר לעיל בפרק ב\"ש (זבחים דף מה.) דקדשי עובדי כוכבים השוחטן בחוץ חייב לא ה\"ל למיתני הכא לשון אסור כדמוכח בריש פ' בתרא דיומא (דף עג:) דחיוב כרת לית ליה למיתני אסור וי\"ל דקתני אסור לפי שיש כמה עבודות דלא מיחייב עלייהו בחוץ דאסור לסייען דגזרינן אטו עבודה דבת חיובא:"],[5,"כמאן כרבי אלעזר בן שמוע כו'","עיקר מילתיה במנחות בהקומץ רבה (מנחות דף כב.):"],[7,"גבה חמשים מכל שבט ושבט שהן שש מאות","הא דכתיב הכא כסף והכא זהב מפרש לקמיה דה\"ק גבה כסף שוה נ' שקלים של זהב לכל שבט דהיינו שוה שש מאות זהב לכל השבטים ור\"ת אומר שיש במדרש דנתן לו חמשים שקלי זהב דהיינו שש מאות שקלי כסף וקשה דבפ' שור שנגח (ב\"ק דף לו.) משמע דדינר של זהב שוה כ\"ה של כסף ואומר ר\"ת דדינר של זהב עב כפלים משל כסף ותדע מדאמרי' בפ' אלו טריפות (חולין דף נה:) גבי טחול ואי אישתייר ביה כעובי דינר זהב כשירה משמע דמשונה בעוביו משל כסף:"],[15,"אימא בכל מקומות מחנה ישראל","שאפילו בשעת סילוק המסעות אין נפסלין אלא מוליכן עמו ובמקום חנייתן אוכלין במחנה כך פירש בקונטרס ונראה דאף שעת הליכתם שרי כיון דאמרי' לעיל (זבחים דף סא.) אע\"פ שנסע אהל מועד הוא ודוקא לקדשים קלים אע\"פ שנסע אהל מועד הוא אבל קדשי קדשים דבעי מחיצה כיון דנסתלקו מסעות אין מחנה שכינה קיים ולחם הפנים ושאר קדשי קדשים מיפסלי ביוצא כדמוכח במנחות בפ' שתי הלחם (מנחות דף צה.) ולעיל בפ' קדשי קדשים (זבחים דף ס:) דאמר בשני מקומות קדשים נאכלין ומוקי לה בקדשי קדשים ולאחר שיפרקו לוים את המשכן היינו כל זמן שלא נסע מכל וכל דעדיין המזבח וקלעי החצר במקומן וא\"ת בריש שתי הלחם (מנחות דף צה.) דפליגי בלחם הפנים אם נפסל במסעות ומפרש דבמסודר כ\"ע לא פליגי דלא מיפסיל כי פליגי במסולק מאן דאמר אינו נפסל כדדרשינן דאע\"פ שנסע אהל מועד הוא ואידך ההוא לדגלים הוא דאתא פי' להודיע איזה דגל יסע תחלה והשתא אמאי לא משני דאתא לקדשים קלים ולקדשי קדשים קודם סילוק הקלעים:"]]],[["נמצאו זבין וטמאי מתים משתלחין חוץ למחנה אחת והתורה אמרה (במדבר ה, ג) ולא יטמאו את מחניהם","תן מחנה לזה ומחנה לזה","א\"ל רבא אלא מאי מחנה ישראל לא הואי נמצאו זבין ומצורעין משתלחין למקום אחד והתורה אמרה (ויקרא יג, מו) בדד ישב שלא ישב טמא אחר עמו","אלא לעולם כולהו תלתא הוו ומאי לא היו אלא שתי מחנות לקליטה מכלל דבמדבר הואי קלטה מחנה לויה","אין והא תניא (שמות כא, יג) ושמתי לך מקום בחייך מקום מקומך (שמות כא, יג) אשר ינוס שמה מלמד שמגלין במדבר להיכן גולין למחנה לויה","מכאן אמרו בן לוי שהרג גולה מפלך לפלך ואם גלה לפלכו פלכו קולטו","מאי קרא אמר רב אחא בריה דרב איקא (במדבר לה, כח) כי בעיר מקלטו ישב עיר שקלטתו כבר:","באו לגלגל: ת\"ר כל נידר ונידב היה קרב בבמה שאין נידר ונידב אין קרב בבמה מנחה ונזירות קריבין בבמה דברי ר\"מ וחכ\"א לא קרבו יחיד אלא עולות ושלמים בלבד","ר' יהודה אומר כל שהצבור והיחיד מקריבין באהל מועד שבמדבר מקריבין באהל מועד שבגלגל מה בין אהל מועד שבמדבר לבין אהל מועד שבגלגל אהל מועד שבמדבר לא היו במות מותרות אהל מועד שבגלגל היו הבמות מותרות ובמתו שבראש גגו לא היה מקריב עליה אלא עולה ושלמים","וחכ\"א כל שהצבור מקריבין באהל מועד שבמדבר מקריבין באהל מועד שבגלגל וכאן וכאן לא קרבו יחיד אלא עולה ושלמים בלבד ר' שמעון אומר אף צבור לא הקריבו אלא פסחים"],[[0,"נמצאו זבין וטמאי מתים משתלחין חוץ למחנה","שכינה לבדה דהא שניהם מותרין במחנה ישראל כדאמרי' בפסחים בפ' אלו דברים (פסחים דף סז.):"],[0,"מחניהם","שני מחנות משמע אחת לכל זב ואחת לכל טמא נפש אלא ודאי הואי מחנה לויה ומשתלחין טמאי מתים ממחנה שכינה ומותרין במחנה לויה וזבין ובעלי קריין משתלחין חוץ למחנה לויה:"],[2,"אלא מאי מחנה ישראל לא הואי","ומשיצא חוץ למחנה לויה שוב אין שם קבע מחנה והרי הוא כשדה בעלמא ומותרין מצורעין לישב שם הצריכין להשתלח ממחנה ישראל וישבו עכשיו עם הזבין:"],[2,"א\"כ נמצאו זבין ומצורעים","חוץ למחנה לויה בלבד:"],[3,"אלא כולהו הוו","ודקתני לא היו אלא שתי מחנות לענין קליטה הוא דנסתלקה תורת מחנה לויה מלקלוט את ההורגים שוגג:"],[4,"ושמתי לך מקום בחייך","רמז לו הקב\"ה למשה במתן תורה שיזכה למצוה זו כדכתיב (דברים ד׳:מ״א) אז יבדיל משה שלש ערים בסוף ארבעים שנה:"],[4,"לך מקום","המקום שלך דהיינו מחנה לויה אף הוא נקלט:"],[5,"מכאן אמרו בן לוי","שהיה דר בערי מקלט שכל ארבעים ושמנה עיירות של לוים ערי מקלט היו כדאמרי' במס' מכות (דף יד.) ואם הרג בשוגג גולה לאחד מערי חביריו דדריש ביה נמי הכי ושמתי לך מקום אף הלוים גולים:"],[5,"ואם גלה בפלכו","עצמו כגון משכונה לשכונה:"],[5,"פלכו קולטו","דומיא דמדבר שהיה מחנה לויה קולטת:"],[7,"כל הנידר והנידב קרב בבמה","קטנה דאילו בבמה גדולה ע\"כ קרבו חובת צבור דכתיב ויעשו את הפסח בגלגל אלא בקטנה ואמר דקרבי נדרים ונדבות ולא חובות ובתורת כהנים תני לה בהדיא לר' מאיר:"],[7,"כל שאין נידר ונידב אין קרב בבמה קטנה","כדיליף טעמיה לקמיה שאין יחיד מקריב חובה בשעת היתר הבמות ואפילו בגדולה וצבור בקטנה לא מקרבי כו' אישתכח דאין חובות קריבין בקטנה ואי קשיא לר' מאיר א\"כ יחיד לא עשה פסחו בגלגל וקרא כתיב ויעשו את הפסח (במדבר ט׳:ה׳) פסח קרבן צבור קרי ליה דאתי בכנופיא במס' יומא (דף נא.) והכי נמי בדר\"ש קתני אף צבור לא הקריבו אלא פסחיהם אלמא קרבן צבור קרי ליה לקמן יליף טעמא דכולהו:"],[7,"מנחות ונזירות","נידר ונידב הוא וקרבי:"],[8,"כל שהצבור והיחיד מקריבין באהל מועד שבמדבר","דהיינו כל הקרבנות כולן נדרים ונדבות וחובות (שקבוע להם זמן) מקריבין באהל מועד שבגלגל דהיא במה גדולה והשתא פליג אדר\"מ ואדרבנן דמדקתני כל שהצבור כו' לאשמועינן דאין חילוק באהל מועד שבמדבר לאהל מועד שבגלגל מכלל דשמעינהו לר\"מ ורבנן דאמרי יש חילוק ומה חילוקו שאין יחיד מקריב בו חובות וטעמייהו נמי שמעינן לקמן דאפי' בבמה גדולה לא קרבי ליחיד אלא נדרים ונדבות ולר' מאיר מנחות ונזירות בכלל:"],[8,"במות מותרות","במות יחיד:"],[8,"ובמתו שבראש הגג","היא במת יחיד:"],[9,"אלא עולה ושלמים","ולא מנחות ונזירות:"],[9,"וכאן וכאן","במת צבור ובמת יחיד לא קרבו בהן ליחיד אלא עולות ושלמים ולקמן פריך היינו תנא קמא דהא חכמים דלעיל נמי הכי אמרי:"],[9,"","ר' שמעון פליג אכולהו דכולהו סבירא להו דאין חילוק לצבור בין מדבר לגלגל בבמה גדולה ורבי שמעון אומר אף צבור עצמם לא הקריבו בגדולה יותר מיחיד בקטנה:"],[9,"אלא פסחים כו'","אבל לא פר העלם דבר ושעירי עבודת כוכבים לא קרבו להם בגלגל:"]],[[2,"והתורה אמרה בדד ישב","שלא יהו טמאים אחרים יושבים עמו אע\"ג דהך סוגיא לר\"ש והך דרשא לר' יהודה דלר\"ש דריש ליה מקרא אחרינא בפסחים בריש אלו דברים (פסחים דף סו.) ניחא ליה להש\"ס לאתויי דרשא הפשוטה והקצרה:"],[5,"פלכו קלטתו","כף דגושה בנחמיה כמו נסך נסכו:"],[6,"עיר שקלטתו כבר","עיקר קרא ברוצח שהרג בעיר מקלטו ותרוייהו תנינהו במכות פ\"ב (דף יב:) הרג באותה העיר גולה משכונה לשכונה ולוי גולה מעיר לעיר ושמא היינו לכתחלה דבן לוי גולה מעיר לעיר אבל דיעבד הא אמרי' דאם גולה לתוך פלכו פלכו קולטו ומפלך לפלך היינו מעיר לעיר ואם גולה לתוך פלכו כגון משכונה לשכונה וכן משמע פי' הקונטרס אי נמי גם לכתחלה אין זקוק לצאת מן העיר והא דגולה לעיר אחרת כדי להלך כולה ובתחומה דאי בעירו משכונה לשכונה אם חזר לשכונתו כיצא חוץ לתחום:"],[7,"כל הנידר ונידב קרב בבמה","אפי' מנחות ונזירות קרב בבמה קטנה כדמפרש ושאין נידר ונידב אין קרב בבמה קטנה דאילו צבור אין מקריבין בקטנה וחובות דיחיד אפי' בגדולה לא קרבי בשעת היתר הבמות לר' מאיר כדמוכח מלתא דר' יהודה כדפי' בקונטרס דמדקאמר ר' יהודה כל שהצבור ויחיד מקריבין כו' מכלל דשמעינהו לר' מאיר ורבנן שיש חילוק וזהו חלוקו שאין יחיד מקריב חובות בגלגל אפי' בבמה גדולה דר' מאיר ורבנן דרשי לא תעשו בגלגל ככל אשר אנחנו עושים פה היום חובות ואפי' בבמה גדולה אלא איש הישר בעיניו יעשה ישרות דהיינו נדבות ר' יהודה סבר דכי כתיב הישר אבעיניו קאי דהיא במת יחיד:"],[9,"רבי שמעון אומר אף צבור לא הקריבו כו'","פי' בקונטרס ר\"ש פליג אכולהו דכולהו סבירא להו דאין חילוק לצבור בין מדבר לגלגל בבמה גדולה ור\"ש אומר אף צבור עצמן לא הקריבו בגדולה יותר מיחיד בקטנה אלא פסחים כו' וחובות הקבוע להם זמן אבל פר העלם דבר ושעירי עבודת כוכבים לא קרבו להם בגלגל עכ\"ל ובחנם הזכיר פר העלם דבר ושעירי עבודת כוכבים שהן חטאות שאין קבוע להם זמן דאפי' חטאות הקבוע להם זמן כגון שעירי הרגלים לא קרבו לר\"ש כדמסיק לקמן תתרגם מתני' בעולה. (הג\"ה וא\"כ ביוה\"כ לא קרבו צבור באהל מועד' בנוב וגבעון לא פרים ולא שעירים כי אם תמידים והא דאמרי' בתוספתא ר' יהודה אומר אבשלום נזיר היה שנאמר ויאמר אבשלום אלכה נא ואשלם נדרי אשר נדרתי בחברון כי נדר נדר עבדך בשבתי בגשור והאי קרא בהיותם בגבעון כתיב ומפרש פ\"ב דתמורה (דף יד:) שהקריבם בחברון בבמת יחיד דאי הלך בחברון להביא כבשים טובים ולהקריבם בבמה גדולה א\"כ מחברון מיבעי ליה והשתא לר' יהודה אי נזירות נידר ונידב הוא אתי שפיר שהקריבן בבמת יחיד בחברון ואי נזירות חובה הוי א\"כ הקריבן בגבעון באהל מועד שהיה שם דלר' יהודה יחיד נמי מצי מקריב חובות בבמה גדולה אף בשעת היתר הבמות ולא דייק בין מחברון ובחברון אבל רבנן דאמרי נזירות חובה הוא ולא קרב יחיד חובות אף בבמת צבור בנוב וגבעון א\"כ אבשלום לא נזיר היה והא קרא דאלכה ואשובה ואשלם נדרי מיירי בנדרים ונדבות. הג\"ה):"],[9,"רבי שמעון אומר אף צבור לא הקריבו כו'","לכאורה ר\"ש אדרבנן דלעיל מיניה קאי ואינהו סברי כרבנן קמאי דמנחות ונזירות לא קרבו בבמה דליכא בינייהו אלא נסכים כדמפרש לקמיה ש\"מ דלר\"ש נמי לא קרבו דהא אפי' בצבור ממעט יותר משאר תנאים ותימה דבפ\"ק דמגילה (דף ט:) [במתני' דקתני] אין בין במה גדולה לבמה קטנה אלא פסחים זה הכלל כל הנידר ונידב קרב כו' ומפרש בגמ' כעין פסחים דהיינו חובות הקבוע להם זמן אבל שאין קבוע להם זמן הכא והכא לא קרב ומוקי לה כר\"ש אלמא ר\"ש תני האי כללא א\"כ מנחות ונזירות קרבי לר\"ש וכדאמרינן הכא לר\"מ דתני האי כללא ואי הוה גרסי' במגילה זה הכלל נידר ונידב בלא כל הוה ניחא ליה דכל דר\"מ אתי לרבויי מנחות ונזירות ועוד יש לומר דהא דפשיטא ליה לר\"מ דמנחות ונזירות ישרות משום דתניא בת\"כ בפרשת אחרי מות מה שלמים מיוחדין שהן נידר ונידב קריבין בבמה אף כל נידר ונידב קרב בבמה אף המנחות והנזירות דברי ר\"מ וקצת תימה אי אההיא סמיך דלא מייתי לה ועוד לר\"ש דמגילה מי נפקא מנחה מכלל נידר ונידב ונראה ליישב מתניתין דהכי קאמר דאין חילוק בין במה גדולה לבמה קטנה אלא פסחים כל הנידר ונידב הקרב בבמה גדולה קרב בקטנה וכל שאין נידר ונידב שאין קרב בגדולה אין קרב בקטנה ולא נחת אלא לפרש מה ששוותה הגדולה והקטנה אבל יש נידר ונידב שאין קרב לא בזו ולא בזו כגון מנחות ונזירות אבל לנידר ונידב דר\"מ אין לפרש דלא איירי במנחות ונזירות דשפיר מישתמע מלישנא דנידב ועוד דקתני לה בהדיא בת\"כ וכן נראה ודאי לפרש דאההיא דתורת כהנים סמיך אע\"ג דלא מייתי לה דבתמורה מייתי לה בפ\"ב (דף יד:) דאמרי' התם אמר ליה אביי ולימא מר שלמי פסח דאי שלמי נזיר נידר ונידב הוא דהא תניא זה הכלל כל הנידר ונידב קרב בבמת יחיד וכל שאינו נידר ונידב אינו קרב בבמת יחיד ותניא המנחות ונזירות קריבות בבמת יחיד דברי ר\"מ משמע דמההיא דייק ולא מלישנא ומאן דלא חשיב התם נזירות נידר ונידב קמשני סמי מכאן נזירות:"]]],[["וחובות שקבוע להן זמן","מאי טעמא דר\"מ דאמר קרא (דברים יב, ח) לא תעשון ככל אשר אנחנו עושים פה היום","אמר להן משה לישראל כי עייליתו לארץ ישרות תקריבו חובות לא תקריבו מנחות ונזירות ישרות נינהו","ורבנן אין מנחה בבמה נזירות חובות נינהו","אמר שמואל מחלוקת בחטאת ואשם אבל בעולות ושלמים דברי הכל ישרות נינהו וקרבי","מותיב רבה חזה ושוק ותרומת לחמי תודה נוהגין בבמה גדולה ואין נוהגין בבמה קטנה ואילו הזרוע בשלה שיירה","אי אמרת בשלמא בעולה ושלמים פליגי הא מני רבנן היא אלא אי אמרת בחטאת ואשם פליגי הא מני","אלא אי איתמר הכי איתמר אמר שמואל מחלוקת בעולה ושלמים אבל בחטאת ואשם דברי הכל חובות נינהו ולא קרבי","אמר מר וחכמים אומרים כל שהצבור מקריבין באהל וכו'","מאי טעמייהו דרבנן אמר קרא (שופטים יז, ו) איש הישר בעיניו יעשה איש ישרות הוא דליקרוב חובות לא ליקרוב וצבור אפי' חובות ליקרוב"],[[1,"לא תעשון וגו'","לאחר ביאת הארץ משתעי וקאמר לא תעשון כשתבאו בגלגל:"],[1,"ככל אשר אנחנו עושים פה היום","שאנו בין צבור בין יחיד מקריבין חטאות ואשמות ובכור ומעשר שהן חובות שאין קבוע להם זמן וכ\"ש חובות הקבוע להם זמן אבל מה אנו עושים שם איש כל הישר בעיניו היחיד לא יקריב שם אלא נדרים ונדבות שישרו בעיניו לנדור ולנדוב עד מתי כי לא באתם וגו' עד שתבאו לשילה:"],[2,"ישרות תקריבו","נדרים ונדבות:"],[2,"חובות לא תקריבו","היחידים דאיש כתיב ולא פליג קרא בין גדולה בין קטנה דליחיד לא קרב אלא נידר ונידב הלכך שאין נידר ונידב אין קרב בבמת יחיד דהא אין קדשי צבור קריבין כדתנן במתני' (דף קיב:) קרבנות צבור קריבין במשכן קרבנות יחיד קריבין בבמה:"],[2,"מנחות ונזירות ישרות נינהו","דאע\"ג דבמלאת נזרו הויין קרבנותיו חובה עליו מיהו ע\"י נדר באו עליו:"],[3,"אין מנחה בבמה","כדאמרי' לקמן זבחים ולא מנחות [דכתיב] למען אשר יביאו בני ישראל וגו' על פני השדה היינו במות שעת היתר שלהם והביאום לה' אותם שהוקדשו בשעת היתר ולא הספיק להביאם עד שנאסרו כדאמרן בהשוחט לעיל (זבחים דף קו:) דפסוק זה בקדשי קדשים שהוקדשו בשעת היתר והקריבום בשעת איסור קאי וזבחו זבחי שלמים ומפרש בת\"כ אין לי שקרבו בבמה אלא שלמים דהא אוקימנא בקדשי במה מניין אף עולה ת\"ל זבחים יכול אף חטאת ואשם ת\"ל אותם ומה ראית אחרי שריבה ומיעט אמרת מה שלמים הבאים בנדר ונדבה אף כל הבא בנדר ונדבה ולר\"מ איתרבו נמי מנחות ונזירות ורבנן דייקי זבחים ולא מנחות אלא דבר הזבוח:"],[3,"נזירות חובה היא","דהוא לא התנדב [אלו] הקרבנות אלא אסר עצמו ביין ובתגלחת ומאליו נתחייב בקרבנות:"],[4,"מחלוקת","דר\"מ ורבנן בנזירות בחטאת ואשם שבה אבל עולות ושלמים דנזיר דברי הכל קרבי:"],[5,"חזה ושוק","המורם משלמים ותודה וארבע חלות המורמות לכהן מארבע מיני חלות שבתודה כדכתיב והקריב ממנו אחד מכל קרבן וגו' (ויקרא ז׳:י״ד):"],[5,"ואין נוהגין בבמה קטנה","גרסינן בסוף פירקין (זבחים דף קיט:) דכתיב בהו להניף תנופה לה' ולא בבמה ואילו מורם מאיל נזיר דהיינו זרוע בשלה שיירה ולא תנייה שמע מינה לא קרבי שלמי נזיר בבמה דאי הוו קרבי הוה תני דלא נהיג ביה נמי תרומה דידיה:"],[6,"אלא אי אמרת בחטאת ואשם הוא דפליג","אבל שלמי נזיר דברי הכל קרבי הא מני:"],[9,"איש הוא דחובות לא הקריבו","ואפי' בגדולה אבל צבור מקריבים חובות:"]],[[3,"ורבנן מנחות אין מנחה בבמה ליחיד","בין בבמה גדולה בין בבמה קטנה קאמר כדתניא אינך רבנן כאן וכאן לא קרבו (נסכים) ליחיד אלא עולה ושלמים בלבד ואמרי' דנסכים איכא בינייהו ותו לא וה״ה דעופות נמי לא קרבו לרבנן כדאמרי' בסוף פירקין (זבחים דף קיט.) לדברי האומר אין מנחה בבמה אין עופות בבמה מ״ט זבחים ולא עופות זבחים ולא מנחות דאוקימנא ההוא קרא לעיל בריש השוחט (זבחים דף קו:) בקדשים שהקדישן בשעת היתר הבמות ותימה דבסוף פירקין (זבחים קיג.) תנן ר' יהודה אומר אין מנחה בבמה והכא קא״ר יהודה כל שהצבור והיחיד מקריבין באהל מועד שבמדבר מקריבין באהל מועד שבגלגל והרי מנחות ועופות דבגלגל כאן וכאן לא קרבו ולא מיסתבר למימר דנהי דלרבנן כאן וכאן לא קרבו לר' יהודה קרבו בבמה לצבור דמהיכי תיתי הך דרשא למר ולמר ועוד א״כ לקמן דפריך חכמים היינו תנא קמא ומשני קרבו נסכים במדבר איכא בינייהו לימא דמנחה קריבה בבמת צבור איכא בינייהו דלרבנן קדמאי קרבה ולבתראי לא קרבה:"],[4,"מחלוקת בחטאת ואשם","בחטאת ואשם של נזירות איירי:"],[5,"ואין נוהגין בבמה קטנה","פי' בקונטרס דכתיב בהו להניף תנופה לה' וא\"ת הרי מנחה לת\"ק דר' יהודה דמתני' דאיתא בבמה קטנה ואין תנופה והגשה בה וא\"כ הנך נמי ליהוי בבמה ולא ליבעי תנופה ויש לומר דהני חזה ושוק ותרומת לחמי תודה עיקר מצותן בתנופה הלכך בטלה תנופה בטלי אינהו אבל מנחה עיקר מצותה קמיצה והקטרה:"],[7,"מחלוקת בעולה (ואשם) [ושלמים]","של נזירות קאמר ותימה דמאן דאמר לא קרבו ואפי' בבמה גדולה היכי משני קרא דאבשלום דכתיב (שמואל ב טו) ואשלם נדרי דליכא למימר בשאר נדרים דבפרק שני דתמורה (דף יד:) משמע דאיירי בקרבן נזירות:"]]],[["ורבי יהודה אמר לך כי כתיב הישר (בעיניו) הוא דכתיב אבל בבמה גדולה אפילו חובות נמי ליקרוב","אלא הא כתיב איש לאו למימרא דאיש ישרות הוא דליקרוב הא חובות לא ליקרוב כי כתיב איש להכשיר את הזר","זר (ויקרא יז, ו) מוזרק הכהן את הדם על מזבח ה' נפקא","מהו דתימא ליבעי קדוש בכורות כמעיקרא קא משמע לן","חכמים היינו תנא קמא","אמר רב פפא קרבו נסכים במדבר איכא בינייהו:","אמר מר רבי שמעון אומר וכו': מ\"ט דרבי שמעון דכתיב (יהושע ה, י) ויעשו בני ישראל את הפסח בגלגל","פשיטא אלא הא קמ\"ל דחובות כעין פסח הוא דקרב הא לאו כעין פסח לא קרב ואידך","מיבעי ליה לכדרבי יוחנן דא\"ר יוחנן משום רבי בנאה ערל מקבל הזאה","תני תנא קמיה דרב אדא בר אהבה אין בין במה גדולה לבמה קטנה אלא פסח וחובות הקבוע להן זמן (א\"ל יחיד חובות שקבוע להן זמן מנא ליה","א\"ל אסמייה) א\"ל תתרגם מתניתך בעולת חובה דאיכא עולת נדבה דאי חטאת יחיד הוא חובות דקביע ליה זמן מי איכא","ולוקמה במנחת חובה דהא איכא חביתין קא סבר אין מנחה בבמה:","באו לשילה וכו': מנא הני מילי א\"ר חייא בר אבא אמר רבי יוחנן כתוב אחד אומר (שמואל א א, כד) ותביאהו בית ה' שילה וכתוב אחד אומר (תהלים עח, ס) ויטש (את) משכן שילה אהל שכן באדם וכתיב (תהלים עח, סז) וימאס באהל יוסף ובשבט אפרים לא בחר","הא כיצד לא היתה שם תקרה אלא אבנים מלמטן ויריעות מלמעלן והיא היתה מנוחה:","קדשי קדשים: מנא הני מילי א\"ר אושעיא דאמר קרא (דברים יב, יג) השמר לך פן תעלה עולותיך בכל מקום אשר (אתה) תראה בכל מקום אשר תראה אי אתה מעלה אבל אתה אוכל בכל מקום שאתה רואה","אימא בכל מקום שאתה רואה אי אתה מעלה אבל אתה זובח בכל מקום שתראה","א\"ר ינאי אמר קרא (דברים יב, יד) שם תעלה ושם תעשה","רבי אבדימי בר חסא אמר אמר קרא"],[[0,"ורבי יהודה","דאמר יחיד נמי מקריב חובות בגדולה אמר לך כי כתיב הישר דממעט יחיד מהקרבת חובות אבעיניו כתיב:"],[1,"אלא לרבי יהודה הא כתיב איש","ואי לאו למעוטי אף מבמה גדולה אתא למה לי דכתיב איש נכתוב כל הישר בעיניו וכיון דבעיניו היינו קטנה פשיטא דאיש הוא דמימעיט דהא צבור לא מקרבי בה:"],[1,"להכשיר את הזר","לעבודת במה:"],[2,"זר מוזרק הכהן נפקא לן","לקמן בפירקין דכתיב (ויקרא י״ז:ו׳) וזרק הכהן את הדם על מזבח ה' פתח אהל מועד כהן פתח אהל מועד ואין כהן בבמה אלא אפי' זר ואפי' עבד הכי דריש ליה בתורת כהנים:"],[4,"חכמים היינו תנא קמא","רבנן בתראי היינו רבנן קמאי דהא אינהו נמי הכי אמרי דיחיד לא קרבו אלא עולות ושלמים וצבור קרבי [נמי חובות] דהא מאיש נפקא להו מיעוטא:"],[5,"קרבו נסכים במדבר איכא בינייהו","לרבנן קמאי לא קרבו נסכים במדבר ועולה ושלמים גרידא בלא נסכים קא גמרי דקרבי בבמה דבמדבר לא קרבי דכי תבאו דפרשת נסכים (במדבר טו) להטעינה נסכים במשכן שילה אתא לאחר ירושה וישיבה כדאמרן בהשוחט (לעיל זבחים קיא.) ורבנן בתראי לטפויי אתו מדתנן משנה יתירא כל שהצבור מקריבין באהל מועד שבמדבר מקריבין בגלגל למה להו למיתני הא רבי יהודה נמי בצבור כוותייהו קאמר והכי איבעי להו למימר כאן וכאן לא קרבו ליחיד אלא עולה ושלמים אלא לטפויי אדרבנן קמאי אתו ואמרי כל שהציבור צריכין להקריב מקריבין באהל מועד שבמדבר מקריבין באהל מועד שבגלגל ולטפויי נסכים אתו ולמימר דקרבו במדבר לצבור וליחיד וכן בגלגל לשתי הבמות ולמאן דאית ליה קרבו במדבר אית ליה דקרבו בבמת יחיד בגלגל דכי תבאו לא אתא אלא להטעינה נסכים לבמה קטנה דהא בגדולה כבר היו קריבין:"],[7,"פשיטא","דבעו למיעבד פסח:"],[8,"ערל","שנטמא במת מקבל הזאה וטהור מטומאת מת ליגע בקדשים ויליף מהכא דכתיב (יהושע ה׳:י׳) ויעשו את הפסח בגלגל דמשמע שעשאוהו כהלכתו במילה בטהרה ורובן ערלים היו במדבר דכתיב (שם) לא מלו ואמרינן ביבמות בעשרה בניסן שעברו את הירדן לא מהול משום חולשא דאורחא אלא בחד סרי הוא דמהול ואשתכח דטמאי מתים שהיו בהם שהרי רובן טמאי מתים היו שמתו אבותיהם כל ארבעים שנה במדבר ונטמאו בהם ואם לא קבלו הזאה ונטהרו בערלותן אין להם שהות להזות משמלו דהא צריך להפריש שלשה ימים בין הזאה להזאה רביעי חמישי וששי וכאן אי לא הזו עד יום אחד עשר בניסן הזאה ראשונה לאחר שמלו תו לא מטי זמן הזאה שניה עד יום חמשה עשר וביבמות איתיה להא דרבי יוחנן בפרק הערל (יבמות דף עא:):"],[10,"ותתרגם מתניתך","דקתני חובות הקבוע להם זמן קרבו בגדולה:"],[10,"בעולה","כגון עולות של תמידין ומוספין צבור קרבו בה [אבל] חטאות הקבוע להם זמן כגון שעירי הרגלים של צבור לא קרבו בה:"],[10,"דאי בחטאת","דאי חובות הקבוע להם זמן בחטאת נמי קאמר:"],[10,"חטאת נדבה מי איכא","ליקרב כיוצא בה בקטנה ועל כרחיך מתניתין קמ\"ל דלא קרבו לר\"ש בגדולה לבד מפסחים אלא חובות שיש כיוצא בהן נדבה מדקתני אלא פסחים וחובות הקבוע להם זמן ואי ס\"ד כל חובות הקבוע להם זמן קאמר פסחים דקתני למה לי הכי הוה ליה למימר אין בין במה גדולה לבמה קטנה אלא חובות הקבוע להם זמן והוו להו פסחים בכלל אלא ה\"ק אלא פסחים שקרבו בגדולה ולא קרבו בקטנה כלל ושאר דברים שקרבו כאן וכאן אין חילוק בהן אלא שבזו לא קרבו אלא נדבות ובזו קרבו אף חובות הקבוע להם זמן:"],[11,"ונוקמה נמי במנחה","דמשכחת לה כאן מנחת נדבה בקטנה ובגדולה עודפת מנחת חביתין שהיא חובות הקבוע להן זמן בכל יום:"],[11,"קא סבר רב אדא בר אהבה אין מנחה בבמה","דזבחים כתיב ובשלמי צבור דעצרת ליכא לאוקמה משום דשלמי במה קטנה לא דמי להו שאלו קדשי קדשים ואלו קדשים קלים:"],[12,"מנה\"מ","דבית אבנים למטן ויריעות לגג:"],[12,"","ויטש משכן שילה אהל שכן באדם:"],[14,"השמר לך","משתבאו אל המנוחה קאי קרא:"]],[[10,"ותתרגם מתניתך בעולה","פירוש כגון עולות תמידין ומוספין שיש כיוצא בהם נדבות אבל חטאות הצבור כגון שעירי הרגלים אע\"ג דקבוע להם זמן לא קרבו והא מילתא דייק לה מדקתני פסחים דליתני קבוע להם זמן ותו לא והוו להו פסחים בכלל אלא על כרחך מתניתין קמ\"ל דלא קרבו לרבי שמעון בגדולה לבד מפסחים אלא שיש כיוצא בהם בבמה והכי קאמר אלא פסחים שקרבו בגדולה לא קרבו בקטנה כלל ושאר דברים שקרבו כאן וכאן אין חילוק בהם אלא שבזה לא הקריבו אלא נדבות ובזה קרבו חובות הקבוע להם זמן כדפירש בקונטרס והכי נמי הוה מצי למידק אברייתא דלעיל דקאמר ר\"ש אף צבור לא הקריבו כו' ואי משום דלא איירי התם רבי שמעון בחילוק שבין במה גדולה לבמה קטנה כדאיירי הכא מ\"מ על חנם הזכיר פסחים דהא הוו בכלל חובות הקבוע להם זמן ותימה מנא ליה לר' שמעון הא מילתא דחטאת דקבוע להם זמן לא קרב דהא לעיל מפרשינן טעמא דרבי שמעון דיליף מפסח גלגל והא ליכא למילף מפסח דפסח נמי אין כיוצא בו נדבה ואי הוה מפרשינן כן דפסח חשיב כיוצא בו נדבה משום דהוי קדשים קלים כעין שלמים הוה ניחא אבל בקונטרס לא פירש כן וע\"ק היכי דייק מדקתני פסחים דלמא הא דקתני פסחים משום דעיקר טעמא מפסח יליף וכן בפ\"ק דמגילה (דף ט:) תני פסחים לחוד ופריך בגמרא פסחים ותו לא אלא כעין פסחים ע\"כ מה שהזכיר פסחים טפי מאינך משום דכולהו מפסח ילפינן לכן נראה לפרש דקא אמר תתרגם מתניתך בעולה היינו משום דכיון דמפסח יליף אית לן למימר מה פסח שקבוע לו זמן וישנו בצבור כביחיד בשעת היתר הבמות צבור בפסח ראשון ויחיד בפסח שני כדאמרי' פסחים (דף סז.) איש נדחה ואין צבור נדחין אף כל שקבוע להם זמן וישנו בצבור כביחיד בשעת היתר הבמות דהיינו עולות שישנן בצבור בתמידין ומוספין וביחיד בנדבה אבל חטאת לא משכחת ביחיד בשעת היתר הבמות דאפילו בבמה גדולה לא קרבו חובות דיחיד לרבי שמעון כמו לר\"מ ורבנן והכי פירושו דשמעתא ותתרגם מתניתך בעולה דאיכא עולת נדבה ונדבות דיחיד קרבו והוי דומיא דפסח דאי בחטאת חטאת נדבה מי איכא דמשכחת ביה חטאת ביחיד דאילו חובות דיחיד לא קרבו לא עולות ולא חטאות ופריך ונוקמה במנחה דאיכא חביתים ומשני אין מנחה בבמה וא\"ת ונוקמה בשלמים כגון כבשי עצרת דהא איכא ביה שלמי נדבה וי\"ל כדפרש\"י דכבשי עצרת קק\"ד נינהו ושלמי יחיד קדשים קלים ולא משכחת כיוצא בהן ביחיד:"]]],[["ולו תאנת שילה מקום שכל הרואה אותו מתאנח עליו על אכילת קדשים שלו","רבי אבהו אמר אמר קרא (בראשית מט, כב) בן פרת יוסף בן פרת עלי עין עין שלא רצתה לזון וליהנות מדבר שאינו שלו תזכה ותאכל כמלא עיניה","רבי יוסי ברבי חנינא אמר (דברים לג, טז) ורצון שוכני סנה עין שלא רצתה ליהנות מדבר שאינו שלו תזכה ותאכל בין השנואין","תנא רואה שאמרו רואה כולו ולא המפסיק בינו לבינו אמר ליה רבי שמעון בן אליקום לר' אלעזר אסברא לך כגון בי כנישתא דמעון אמר רב פפא רואה שאמרו לא רואה כולו אלא רואה מקצתו","בעי רב פפא עומד ורואה יושב ואינו רואה מאי בעי ר' ירמיה עומד על גבי הנחל ורואה (יושב) בתוך הנחל ואינו רואה מאי תיקו","כי אתא רב דימי אמר רבי בשלשה מקומות שרתה שכינה על ישראל בשילה ונוב וגבעון ובית עולמים ובכולן לא שרתה אלא בחלק בנימין שנאמר (דברים לג, יב) חופף עליו כל היום כל חפיפות לא יהו אלא בחלקו של בנימין","כי אזיל אביי אמרה קמיה דרב יוסף אמר חד ברא הוה ליה לכייליל ולא מיתקן והכתיב (תהלים עח, ס) ויטש (את) משכן שילה וכתיב (תהלים עח, סז) וימאס באהל יוסף ובשבט אפרים לא בחר","אמר רב אדא מאי קא קשיא ליה דלמא שכינה בחלק בנימין וסנהדרי גדולה בחלק יוסף מדמצינו בבית עולמים דשכינה בחלקו של בנימין וסנהדרין בחלק יהודה","אמר ליה הכי השתא התם מיקרבן נחלות גבי הדדי הכא מי מקרבן הכא נמי מקרבן כדאמר רבי חמא בר' חנינא רצועה היתה יוצאת מחלקו של יהודה ונכנסת לחלקו של בנימין ובה היה מזבח בנוי והיה בנימין הצדיק מצטער עליה לבלעה","ה\"נ רצועה היתה יוצאת מחלקו של יוסף לחלקו של בנימין והיינו דכתיב (יהושע טז, ו) תאנת שילה","כתנאי חופף עליו זה מקדש ראשון כל היום זה מקדש שני ובין כתיפיו שכן אלו ימות המשיח","רבי אומר חופף עליו זה העולם הזה כל היום אלו ימות המשיח ובין כתיפיו שכן זה העולם הבא","ת\"ר ימי אהל מועד שבמדבר ארבעים שנה חסר אחת ימי אהל מועד שבגלגל ארבע עשרה ז' שכבשו וז' שחלקו ימי אהל מועד שבנוב וגבעון חמשים ושבע נשתיירו לשילה ג' מאות ושבעים חסר אחת","ימי אהל מועד שבמדבר ארבעים חסר אחת מנלן דאמר מר שנה ראשונה עשה משה את המשכן שניה הוקם המשכן ושלח משה מרגלים","שבגלגל ארבע עשרה שבע שכבשו ושבע שחלקו מנלן דקאמר כלב (יהושע יד, ז) בן ארבעים שנה אנכי בשלוח משה עבד ה' אותי מקדש ברנע לרגל את הארץ ואשיב אותו דבר כאשר עם לבבי וכתיב ועתה הנה אנכי היום בן חמש ושמונים שנה","כי עבריה לירדן בר כמה הוי בר שבעין ותמני וקאמר בן חמש ושמונים שנה הרי שבע שכבשו","ושבע שחלקו מנלן איבעית אימא מדשבע שכבשו שבע נמי שחלקו","ואיבעית אימא מדלא משכחת לה (יחזקאל מ, א) בארבע עשרה שנה אחר אשר הוכתה העיר:","אהל מועד שבנוב וגבעון חמשים ושבע מנ\"ל דכתיב (שמואל א ד, יח) ויהי כהזכירו את ארון האלהים","ותנא כשמת עלי הכהן חרבה שילה ובאו לנוב כשמת שמואל הרמתי חרבה נוב ובאו לגבעון","וכתיב (שמואל א ז, ב) ויהי מיום שבת הארון בקרית יערים וירבו הימים ויהיו עשרים שנה וינהו כל בית ישראל אחרי ה'","הני עשרים שנה עשר שנה שמלך שמואל בעצמו ושנה שמלך שמואל ושאול ושתים שמלך שאול ושבע דדוד"],[[0,"ולו תאנת שילה","חפשתיו ולא מצאתיו במקרא אבל מצאתיו (ועבר) מזרחה תאנת שילה (יהושע ט״ז:ו׳):"],[0,"תאנת","לשון תאניה ואניה (איכה ב׳:ה׳) שהיו מתאנחין ורואין שמשם היו זוכרין אכילת קדשים שהיתה במקום מראיתו:"],[1,"שאינו שלו","אשת אדוניו:"],[1,"בן פרת יוסף","לשון פריה ורביה מקום אכילת קדשים נתרבה לו על ידי העין ושילה בחלקו של יוסף היתה כדכתיב (תהילים ע״ח:ס״ז) וימאס באהל יוסף וגו' אחר ויטש משכן שילה כתיב:"],[2,"ורצון","ע\"י רצון שלא רצה ליזון ממה שאינו שלו:"],[2,"בין השנואים","שילה קדשיו נאכלין אף בגבולי שאר שבטים ששנאוהו:"],[3,"אסברא לי","הראני דוגמא לדבר:"],[3,"בי כנישתא דמעון","משם היו רואין את שילה ולא היה דבר מפסיק:"],[3,"לא רואה את כולה","לראות משם את כולה שילה אלא מקצת:"],[6,"חד ברא הוה ליה לכייליל ולא מיתקן","נראה בעיני כי אביו של אביי כייליל שמו:"],[8,"מי מקרבן","שילה וגבול נחלת בנימין:"],[9,"תאנת שילה","על שהיה בנימין מתאונן עליה:"],[11,"העולם הזה","כל מקום ששרתה שכינה ואף שילה ונוב וגבעון:"],[12,"נשתיירו לשילה","מארבע מאות ושמונים מיציאת מצרים לבנין הבית שס\"ט:"],[13,"שניה הוקם המשכן","דכתיב ויהי בשנה השנית בחדש הראשון וגו' (שמות מ׳:י״ז):"],[14,"וקאמר כלב","בשעת חילוק כשבא לתבוע חברון בן מ' שנה וגו' והיא היתה השנה השניה נתעכבו במדבר שוב שלשים ושמונה שנה נמצא כלב בן ע\"ח שנים כשעברו הירדן וקאמר בשעת חילוקה בן חמש ושמונים שנה הרי שבע נשתהו לכיבוש:"],[16,"מדשבע כיבשו שבע חילקו","סברא בעלמא היא:"],[17,"ואיבעית אימא מדלא אשכח י\"ד שנה אחר שהוכתה העיר","דלא מיתוקם קרא דכתיב ביחזקאל (לג) בארבע עשרה שנה אחר אשר הוכתה העיר בראש השנה שנאמר בעשור לחדש היה דבר ה' אלי וגו' ודרשינן במסכת ערכין (דף יב.) איזה היא שנה שראש השנה בעשור לחדש הוי אומר זה יובל ולא מנו שמיטין ויובלות אלא לאחר ירושה וישיבה וכי אמרת דשנות כיבוש וחילוק י\"ד היו ודלית להו ממנין היובלות משכחת לה דחרב הבית בשנת ל\"ו ליובל והוה ליה שנת היובל שנת י\"ד שנה אחר שנה שהוכתה העיר ואי לא לא משכחת לה כיצד ויהי בשמנים שנה וד' מאות שנה וגו' ויבן הבית לה' צא מהן מ' שהיו במדבר נמצא משבאו לארץ עד שנבנה הבית ארבע מאות וארבעים והבית עמד ד' מאות ועשר הרי ח' מאות וחמשים הרי י\"ז יובלות שלימים צא מהן י\"ד שכבשו ושחלקו שלא מנו יובלות נמצא בית חרב קודם השלמת היובל י\"ד שנה והכי תניא בהדיא בערכין (שם:) י\"ז יובלות מנו ישראל משנכנסו לארץ עד שיצאו ואי אתה יכול לומר משנכנסו מנו שאם אתה אומר כן נמצא בית חרב בתחילת היובל ואי אתה מוצא י\"ד שנה אחרי אשר הוכתה העיר אלא צא מהן שבע שכבשו ושבע שחלקו ואתה מוצא ארבע עשרה שנה אחר שהוכתה העיר:"],[19,"חרבה נוב","ע\"י שאול:"],[20,"בקרית יערים","שם נתנוהו לסוף ד' חדשים שעמד בשדה פלשתים שנאמר (שמואל א ה׳:ו׳) ותכבד יד ה' אל האשדודים והחזירוהו בעגלה חדשה ונתנוהו שם ועשה שם עשרים שנה עד שהביאו דוד משם בשנה ראשונה שנעשה מלך על כל ישראל שהיא שנה שמינית למלכו על יהודה:"],[21,"הכי גרסינן עשרה דשמואל עצמו","שהיה שופט לבדו משמת עלי עד שמלך שאול ובמסכת תמורה (דף יד: טו.) ה\"ג לה עשר שנים שמלך שמואל לעצמו דאותה שנה ששאלו להם מלך היא שנה עשירית לשמואל הרמתי ושנה אחת מלכו שמואל ושאול יחד שהיה שאול הולך אחר עצת שמואל עד שסרח במעשה אגג וסר שמואל מעליו כדכתיב (שמואל א טו) ולא יסף שמואל לראות את שאול וגו' ומלך שוב שאול שתי שנים והן שכתב במקרא (שם יג) ושתי שנים מלך על ישראל דלא חשיב אותם דמלך שמואל בהדיה והיינו דאמרינן בסמכת תענית (דף ה:) מי גרם לשאול שישב בגבעה שתי שנים ומחצה תפלתו של שמואל ברמה דבחצי שנה ראשונה סרח ונגזרה עליו מיתה אלא שעמדה לו תפלת שמואל ושבע שמלך דוד בחברון על יהודה ולכשהמליכוהו כל ישראל עליהם הביא את הארון מקרית יערים עיר דוד הרי עשרים:"]],[]],[["דכתיב (מלכים א ב, יא) והימים אשר מלך דוד על ישראל מ' שנה בחברון מלך ז' שנים [וגו']","ובשלמה כתיב (דברי הימים ב ג, ב) ויחל לבנותו בשנת ארבע למלכותו נשתיירו לשילה שלש מאות ושבעים חסר אחת:","באו לנוב וגבעון [וכו']: מנא ה\"מ דת\"ר (דברים יב, ט) כי לא באתם עד עתה אל המנוחה ואל הנחלה","אל המנוחה זו שילה נחלה זו ירושלי' למה חלקן כדי ליתן היתר בין זה לזה","א\"ל ריש לקיש לר' יוחנן מעשר שני נמי ליתני א\"ל מעשר שם שם מארון קא ילפי כיון דארון לא הוה מעשר נמי לא הואי","אי הכי פסח וקדשים נמי דשם שם מארון ילפי דכיון דארון לא הוה אינהו נמי לא הוו","א\"ל [דאמר לך] הא מני ר\"ש היא דאמר אף צבור לא הקריבו אלא פסח וחובות הקבוע להן זמן אבל חובות שאין קבוע להם זמן הכא והכא לא קרב מעשר בהמה חובות שאין קבוע להן זמן הוא ואיתקש מעשר דגן למעשר בהמה","מכלל דלרבי יהודה קרב אין דהאמר רב אדא בר מתנה מעשר שני ומעשר בהמה נאכלין בנוב וגבעון לדברי רבי יהודה והא בעי בירה ולאו תני רב יוסף שלש בירות הן שילה ונוב וגבעון ובית עולמים הוא תני לה והוא אמר לה לאכילת מעשר שני ואליב' דרבי יהודה:","באו לירושלים [וכו']: ת\"ר כי לא באתם עד עתה אל המנוחה ואל הנחלה מנוחה זו שילה נחלה זו ירושלים","ואומר (ירמיהו יב, ח) היתה לי נחלתי כאריה ביער ואומר (ירמיהו יב, ט) העיט צבוע נחלתי לי העיט סביב עליה דברי רבי יהודה","ר\"ש אומר מנוחה זו ירושלים נחלה זו שילה ואומר (תהלים קלב, יד) זאת מנוחתי עדי עד פה אשב כי אויתיה ואומר (תהלים קלב, יג) כי בחר ה' בציון אוה למושב לו","בשלמא למ\"ד מנוחה זו שילה היינו דכתיב אל המנוחה ואל הנחלה אלא למ\"ד מנוחה זו ירושלים נחלה זו שילה אל הנחלה ואל המנוחה מיבעי ליה הכי קאמר לא מיבעיא מנוחה דלא מטיתו אלא אפילו לנחלה נמי לא מטיתו","תנא דבי רבי ישמעאל זו וזו שילה רבי שמעון בן יוחי אומר זו וזו ירושלים בשלמא למאן דאמר מנוחה זו"],[[0,"דכתיב והימים אשר מלך וגו'","ל\"ג שנה הרי נ\"ג וארבע שמלך שלמה לפני בנין הבית ואותה שנה שלמו ארבע מאות ושמונים ליציאת מצרים נשתיירו לשילה שס\"ט:"],[2,"מנהני מילי","שהיה היתר לבמות אחר קדושת שילה משחרבה:"],[2,"כי לא באתם","בימי גלגל אל המנוחה וגו':"],[3,"ולמה חלקן","הכתוב לכתוב את שניהם:"],[3,"ליתן היתר במה בין זה לזה","דהא קרא בהיתר במות דגלגל משתעי וקאמר עד מתי אני אומר לכם איש כל הישר בעיניו כי לא באתם עד עתה וגו' אבל לא משבאתם ואי אין היתר בין זו לזו לא ה\"ל למיכתב אלא מנוחה ומדכתיב נחלה ש\"מ דה\"ק להו אחר קדושת המנוחה תחזרו להיתר הראשון עד בואכם אל הנחלה:"],[5,"אי הכי","דשעת היתר הואי נייתי נמי מעשר שני לנוב וגבעון שהרי נסתלקו כל קדושת שילה ומאי טעם לא תנן במתני' לאוכלו שם:"],[5,"שם שם","ואכלתם שם (דברים י״ב:י״ח) אי נמי (כי אם) לפני ה' אלהיך (תאכלנו) במקום אשר יבחר לשכן שמו שם (שם יד) ובארון כתיב (שמות מ) [ונתת] שם את הארון וגו':"],[5,"וכיון דארון לא הוה","דכל ימי נוב וגבעון היה הארון בקרית יערים כ' שנה ובעיר דוד עד שנבנה הבית:"],[5,"פסח וקדשים נמי","דהא ואכלתם שם בהו נמי כתיב (דברים יב):"],[6,"מני","הך מתני' דקתני מעשר שני בכל ערי ישראל ולא היה צריך להביאן שם:"],[6,"ר\"ש היא","דאמר חובות שאין קבוע להם זמן לא קרבו בנוב וגבעון והיינו בכורות ומעשר בהמה ויליף טעמא כדאמרן לעיל בגלגל וכיון דמעשר בהמה לא הוה התם מעשר דגן נמי לא בעי לאיתויי התם דאיתקוש להדדי דכתיב (שם יד) עשר תעשר ואמרינן בשתי מעשרות הכתוב מדבר במסכת בכורות (דף נג:):"],[7,"","ה\"ג אבל לר' יהודה ה\"נ דאמר רב אדא בר אהבה מעשר שני נאכל בנוב וגבעון לדברי ר' יהודה:"],[7,"והא בעינן בירה","דכתיב (דברים יב) לפני ה' אלהיכם:"],[7,"נוב וגבעון","חדא חשיב לה:"],[12,"זו וזו שילה","ואפי' הכי יש היתר בתרה דקסבר קדושה ראשונה קדשה לשעתה ולא קדשה לעתיד לבא ובקדושת ירושלים גופה סבירא ליה דיש אחריה היתר כדאמרינן במגילה (דף י.) שמעתי שמקריבין בבית חוניו בזמן הזה ואוקימנא כר' ישמעאל:"],[12,"זו וזו ירושלים","ועד שיבנה הבית לא נאסרו הבמות:"]],[[2,"באו לנוב וגבעון [כו'] קדשים קלים ומעשר שני בכל ערי ישראל","בריש פירקין במתניתין (דף קיב:) פירש בקונטרס דלעיל בבאו לגלגל לא הוזכר מעשר שני לפי שלא נהגו מעשרות עד לאחר ירושה וישיבה ותימה דהא פריך הכא בגמרא דמעשר שני נמי נסקיה להתם בנוב וגבעון ומסיק דמתני' ר' שמעון היא דאמר חובות שאין קבוע להם זמן לא קרבו דהיינו בבכור ומעשר בהמה וכיון דמעשר בהמה לא הוה התם מעשר דגן לא בעי לאתויי התם דאיתקוש להדדי והשתא מהאי טעמא דאיתקש למעשר לא יהא נאכל כלל כמו מעשר בהמה בנוב וגבעון למ\"ד לא קרבו חובות והיו צריכין להמתין בבכור ומעשר עד שיוממו ונאכלין במומן לבעלים ומעשר שני לא יהא לו תקנה אלא בפדיון ויש ספרים דלא גרסי במתניתין מעשר שני כלל גבי נוב וגבעון ונראה לפרש דלענין הבאה הוא שייך להקיש דאי האי טעון הבאת מקום גם זה יהא טעון הבאת מקום כדקאמר לר' יהודה דאמר חובות קרבו דבנוב וגבעון נאכל גם מעשר שני נאכל שם אבל מה שאין מעשר בהמה קרב לרבי שמעון משום דחובות לא קרבו לענין זה אין שייך להקיש מעשר שני שלא יהא נאכל בכל מקום דהא דאין מעשר בהמה נאכל משום דבעי מתן דמים ואימורים ולא אפשר אבל מעשר שני שרי ומיהו קשה דלעיל בפרק קדשי קדשים (זבחים דף ס:) ילפינן מעשר מבכור דאין נאכל בזמן הזה ויש גירסות בספרים ושם פירשתי ועוד קשה אי משכחת מעשר דנאכל בכל ערי ישראל א\"כ הא דאמר בפרק כל שעה (פסחים דף לו:) מרבה אני מעשר שיש לו היתר בכל מושבות דאמר ר' אלעזר מנין למעשר שנטמא כו' למה לי דרבי אלעזר הא כיון דבנוב (נאכל) וגבעון נאכל בכל ערי ישראל א\"כ יש היתר בכל מושבות כדאמר התם (דף לח:) לקמיה בההוא פירקא גבי חלות תודה ורקיקי נזיר נאכלין בנוב וגבעון וי\"ל דאיצטריך התם דרבי אלעזר משום רבי יהודה דאמר בשמעתין שלש בירות הן של שילה ושל נוב וגבעון ושל בית עולמים לאכילת מעשר שני ואליבא דרבי יהודה וא\"ת והיכי קאמר התם ומוציא אני בכורים שאין להם היתר בכל מושבות והלא נאכלין בנוב וגבעון בכל ערי ישראל כמעשר שני ויש לומר דבכורים לא אפשר משום דבעו הנחה אצל המזבח ובנוב וגבעון ממטו להו התם כדאמרינן לעיל בפרק קדשי קדשים (זבחים דף ס:) ובפרק בתרא דמכות (דף יט:) ובתמורה בפרק אלו קדשים (תמורה דף כא.) דבכורים אינם שלא בפני הבית משום דבעי הנחה ועוד מידי דהוה אחזה ושוק ותרומת לחמי תודה דאמרי' לעיל (זבחים דף קיז:) נוהגין בבמה גדולה ואין נוהגין בבמה קטנה משום דבעו תנופה ובכורים נמי בעו תנופה דלא דמי למנחה דקרבה בבמה בלא תנופה לרבנן דפליגי עליה דר' יהודה במתניתין בפירקין כדפרישית לעיל דמנחה עיקר מצותה (סמיכה) והקטרה הלכך משום תנופה לא בטלה אבל הני דעיקר מצותן תנופה בטלה תנופה בטלי אינהו:"],[6,"הא מני רבי שמעון היא","הכי נמי מצי למימר רבנן היא דאמרי חובות ליחיד לא קרבו בשעת היתר הבמות אף בבמת צבור וכן רבי מאיר אלא נקט ר' שמעון משום דעביד הך דרשא עשר תעשר בשני מעשרות הכתוב מדבר:"],[6,"הג\"ה ואיתקש [מעשר] דגן למעשר בהמה","לעיל בפרק קדשי קדשים (זבחים דף ס:) נקט היקשא דמעשר לבכור והכא והתם סגי בחדא:"],[12,"זו וזו שילה","פירש בקונטרס ואפילו הכי הוי היתר בתרה דקסבר קדושה ראשונה קדשה לשעתה ולא קדשה לעתיד לבא ובקדושת ירושלים גופה סבירא ליה דיש אחריה היתר כדאמרינן במגילה (דף י.) שמעתי שמקריבין בבית חוניו בזמן הזה ואוקימנא כרבי ישמעאל עכ\"ל ולא דק דהתם רבי ישמעאל ב\"ר יוסי דהוא בתראה בימי רבי והכא רבי ישמעאל בן אלישע בר פלוגתיה דר' עקיבא רבו של ר' שמעון בן יוחי וההוא אסיקנא לעיל לפום חד גירסא דכולי עלמא קידשה ומיהו אי אפשר לומר לדידיה שלא יהא היתר אחר שילה דהא מצינו אבשלום שהקריב בחברון כדכתיב (שמואל ב ט״ו:ז׳-ח׳) אלכה נא ואשלמה את נדרי אשר נדרתי לה' בחברון וכתיב (שם) כי נדר נדר עבדך בשבתי בגשור דאין לומר דהוה מפרש דלא הלך אבשלום אלא להביא כבשים מחברון שהיו שם טובים ולהקריבם בגבעון בבמה גדולה באהל מועד כדבעי למימר בריש פרק שני דתמורה (דף יד.) דהא מסקינן התם על כרחין דלאקרובי בחברון בבמת יחיד אזל דאי להביא מחברון מיבעי ליה ועוד כתיב בשמואל (א ט) כי הוא יברך הזבח ובשאול כתיב (שם יג) הגישו אלי העולה והשלמים ויעל העולה ובסמוך מייתי לה קראי שהקריב בלילה בבמה:"]]],[["שילה נחלה זו ירושלים אי נמי איפכא היינו דכתיב (דברים יב, ט) אל המנוחה ואל הנחלה אלא למאן דאמר זו וזו שילה או זו וזו ירושלים מנוחה נחלה מיבעי ליה קשיא","בשלמא למ\"ד זו וזו שילה מנוחה דנחו מכיבוש נחלה (זו) דפלגו התם נחלות דכתיב (יהושע יח, י) ויחלק להם יהושע ויפל להם גורל בשילה על פי ה'","אלא למ\"ד זו וזו ירושלים בשלמא נחלה נחלת עולמים אלא מנוחה מאי מנוחה מנוחת ארון דכתיב ויהי כנוח הארון","בשלמא למ\"ד זו וזו ירושלים אבל שילה הוה שריא במות היינו דכתיב (שופטים יג, יט) ויקח מנוח את גדי העזים ואת המנחה ויעל על הצור לה'","אלא למ\"ד זו וזו שילה ובמות הוה אסירן מאי ויקח מנוח הוראת שעה היתה","תנא דבי רבי ישמעאל כרבי שמעון בן יוחי דאמר זו וזו ירושלים וסימניך משכי גברא לגברי:","כל הקדשים [וכו']: אמר רב כהנא לא שנו אלא בשחיטה אבל בהעלאה כרת נמי מיחייב","מאי טעמא דאמר קרא (ויקרא יז, ח) ואליהם תאמר על הסמוכין תאמר","מתקיף לה רבה מי כתיב ועליהם תאמר אליהם כתיב (ואליהם קרינן)","ועוד תניא ארבעה כללות היה רבי שמעון אומר בקדשים הקדישן בשעת איסור הבמות ושחט והעלה בשעת איסור הבמות בחוץ הרי הן בעשה ולא תעשה ויש בהן כרת הקדישן בשעת היתר הבמות ושחט והעלה בשעת איסור הבמות הרי הן בעשה ולא תעשה ואין בהן כרת","הקדישן בשעת איסור הבמות ושחט והעלה בחוץ בשעת היתר הבמות הרי הן בעשה ואין בהן בלא תעשה","הקדישן בשעת היתר הבמות ושחט והעלה בשעת היתר הבמות פטור מכלום תיובתא דרב כהנא תיובתא:","ואלו קדשים [וכו']: סמיכה דכתיב (ויקרא א, ג) לפני ה' וסמך","שחיטת צפון דכתיב צפונה לפני ה' מתנות סביב דכתיב (ויקרא א, ה) וזרק על המזבח סביב (סביב)","תנופה דכתיב (ויקרא יד, יב) והניף הכהן לפני ה' הגשה דכתיב (ויקרא ב, ח) והגישה אל המזבח:","רבי יהודה אומר אין מנחה בבמה: אמר רב ששת לדברי האומר יש מנחה בבמה יש עופות בבמה לדברי האומר אין מנחה בבמה אין עופות בבמה","(ויקרא יז, ה) זבחים ולא מנחות זבחים ולא עופות","וכהן דכתיב (ויקרא יז, ו) וזרק הכהן בגדי שרת (שמות כח, מג) לשרת בקדש","וכלי שרת (במדבר ד, יב) אשר ישרתו בם בקודש: לריח ניחוח דכתיב (ויקרא א, ט) לריח ניחוח לה':","מחיצה בדמים דכתיב (שמות כז, ה) והיתה הרשת עד חצי המזבח: ריחוץ ידים דכתיב (שמות מ, לב) ובקרבתם אל המזבח ירחצו","אמר רמי בר חמא לא שנו אלא בקדשי במה קטנה והקריבום בבמה קטנה אבל בקדשי במה קטנה דקרבינהו בבמה גדולה יש חיצוי","מותיב רבה חזה ושוק תרומת לחמי תודה נוהגין בקדשי במה גדולה ואין נוהגין בקדשי במה קטנה אימא נוהגין בבמה גדולה ואין נוהגין בבמה קטנה","איכא דאמרי אמר רמי בר חמא לא שנו אלא בקדשי במה גדולה והקריבן בבמה גדולה אבל בקדשי במה קטנה אף על גב דקרבינהו בבמה גדולה אין חיצוי","לימא מסייע ליה חזה ושוק ותרומת לחמי תודה נוהגין בקדשי במה גדולה ואין נוהגין בקדשי במה קטנה","אימא נוהגין בבמה גדולה ואין נוהגין בבמה קטנה ופליגא דרבי אלעזר דאמר רבי אלעזר עולת במת יחיד שהכניסה בפנים קלטוה מחיצות לכל דבר","בעי רבי זירא עולת במת יחיד"],[[2,"ויהי כנוח הארון","חיפשתיו ולא מצאתיו ואם אינו בכתובים יש לי מקרא אחר בדברי הימים (ב ו) בשלמה קומה ה' אלהים לנוחך אתה וארון עוזך:"],[3,"מנוח","בימי שילה היה שהרי לא חרבה עד שמת עלי:"],[5,"הכי גרסינן תנא דבי ר' ישמעאל כר' שמעון בן יוחי","ברייתא נמצאת בבית מדרשו של ר' שמעון שהיו תלמידי ר' ישמעאל שונים כמותו:"],[5,"משכינהו גברא לגברי","ר' שמעון שהוא יחידי משך את תלמידי ר' ישמעאל להניח דברי רבם שאמר זו וזו שילה:"],[6,"לא שנו","הא דקתני דהקדישן בשעת היתר והקריבם בשעת איסור אין בהם כרת:"],[6,"אלא בשחיטה","כדתניא בהשוחט (לעיל זבחים דף קו:) יכול יהא חייבין עליו כרת תלמוד לומר זאת להם ואין אחרת להם:"],[7,"ואליהם תאמר","גבי העלאה כתיב ובתר קרא דאיירי בשוחט קדשים שהקדישן בשעת היתר ושחטן בשעת איסור ולא יזבחו עוד וגו' דאוקימנא בהכי:"],[9,"ושחט והעלה","אחד שחט והעלה אחד שחט וחבירו העלה אלמא בהעלאה נמי קתני דאין בה כרת:"],[12,"לפני ה' וסמך","לרצונו לפני ה' וסמיך ליה (ויקרא א) וסמך את ידו:"],[13,"צפונה לפני ה'","ולא צפונה בבמה והכי דריש ליה נמי בתורת כהנים:"],[13,"על המזבח סביב","ומהכא נפקא לן מתן סובב באיזהו מקומן (לעיל זבחים דף נג:) וסיפיה דקרא אשר פתח אהל מועד:"],[14,"","נראה בעיני דהכי גרסינן הגשה דכתיב (ויקרא ו) הקרב אותה לפני ה' וגו' ומהאי קרא נפקא לן הגשה בקרן מערבית דרומית במסכת סוטה (דף יד:) ובמנחות (דף יט:):"],[16,"זבחים","(ויזבחו זבחים) שלמים לה' אותם ואוקימנן לעיל (זבחים דף קו:) להאי קרא בקדשים שהקדישן בשעת היתר במות וכתיב אותם מיעוטא אלמא זבחים הוא דהוו נהגי בהו ולא עופות ומנחות:"],[17,"","וזרק הכהן את הדם על מזבח ה' פתח וגו' (ויקרא י״ז:ו׳) ודרשינן ליה בת\"כ בפרשת שחוטי חוץ זריקת כהן פתח אהל מועד ואין זריקת כהן בבמה אלא אף הזרים והעבדים:"],[18,"ישרתו בם בקדש","היינו משכן:"],[18,"ריח ניחוח","בההוא קרא נמי והקריב החלב לריח ניחוח לה':"],[19,"עד חצי המזבח","מהכא נפקא לן מחיצה לדמים בפרק איזהו מקומן (לעיל זבחים דף נג.) וכתיב המזבח היינו מיעוטא בההוא מזבח לחודיה דאיירי בה קרא והיינו מזבח של משכן:"],[20,"לא שנו","דיש מחיצה לדמים בבמה גדולה:"],[20,"אלא קדשים","שהוקדשו לשמו והקריבו בה:"],[20,"אבל קדשים ששחטן לבמה קטנה","והכניסן והקריבן בגדולה אין חיצוי ואם בא ליתן עולה למעלה מן החוט יתן:"],[21,"ואין נוהגין בקטנה","דכתיב בהו תנופה לה' מכל מקום בבמה גדולה איתנהו ואפילו בקדשי במה קטנה וה\"ה לכולהו:"],[22,"לא שנו","דיש חיצוי בבמה גדולה אלא בזמן במה גדולה כלומר בשעת איסור הבמות אבל בזמן היתר הבמות אין חילוק בין זו לזו בדבר הקרב בשתיהן הלכך אפילו גדולה הקריבין לגדולה אין חיצוי:"]],[[2,"ויהי כנוח הארון","פירש רש\"י פסוק בדברי הימים (ב ו) קומה ה' אלהים לנוחך אתה וארון עוזך והוה מצי להביא פסוק דכתיב ביהושע והיה כנוח כפות רגלי הכהנים נושאי הארון א\"נ (במדבר י׳:ל״ה) ויהי בנסוע הארון וגו' ובנוחה יאמר וגו':"],[5,"ה\"ג משכינהו גברא לגברי","פירשתי לעיל בפ' איזהו מקומן (זבחים דף נג:) גבי זה וזה יסוד דרומי:"],[8,"ואליהם כתיב","והא דאמרן לעיל ואליהם לערב פרשיות היינו שחיטה והעלאה אבל כולי האי לא אמרן לערב היתר הבמות על איסור הבמות:"],[9,"ה\"ג הקדישן בשעת היתר הבמות ושחט והעלה בשעת היתר הבמות פטור מכלום","וקשה היאך שייך למיתני בדבר שמצותו בכך וכי תימא דאיצטריך משום חובות דאין קריבין בבמה או משום קרבנות צבור ואם שחט והעלה בחוץ פטור מכלום הא איכא לאו הבא מכלל עשה ונראה לפרש דמיירי בעולת במת יחיד דאפילו הקדישה על מנת להקריבה בבמה גדולה ואפי' הכניסה בפנים דקלטוה מחיצות כדבסמוך אפי' הכי אם חזר והוציאה ושחט והעלה בחוץ פטור מכלום:"],[15,"אין מנחה בבמה וכיהון ובגדי שרת כו'","מנחה לא הויא דומיא דאינך דמאן דלית ליה מנחה בבמה היינו דלא קרבה כלל אפילו בבמה גדולה כגון מזבח הנחושת שבנוב וגבעון וכולהו נהגו דכולי עלמא מודו דבקדשי במה גדולה יש חיצוי:"],[25,"","בעי רב אדא עולת במת יחיד שהכניסה בפנים וחזר והוציאה לחוץ מהו מי אמרינן כיון דעיילא לה קלטה להו מחיצות או דלמא כיון דהדור הדור לאו היינו דרבה ורב יוסף דתנן קדשי קדשים ששחטן בדרום מועלין בהן ואיבעיא להו מהו שירדו רבה אמר ירדו רב יוסף אמר לא ירדו תיבעי לרבה תיבעי לרב יוסף כך גירסת רש\"י ז\"ל אבל בספרים ישנים גרסינן קדשי קדשים ששחטן בדרום מועלין בהן אם עלו לא ירדו ואיבעיא להו ירדו מהו שיעלו רבה אמר לא יעלו רב יוסף אמר יעלו תיבעי לרבה כו' ומיירי במשלה בהן האור להכי לכ\"ע אם עלו לא ירדו ובריש מעילה (דף ב:) דאמר רבה אם עלו ירדו מיירי בלא משלה בהן האור ותדע בלא ההיא דמעילה צריך לאוקמא הכא במשלה בהן האור דאי בלא משלה אמאי אמר רב יוסף אם ירדו יעלו הא אמרינן פרק ב\"ש (לעיל זבחים מג.) כשם שאם עלו לא ירדו כך אם ירדו לא יעלו וכל שכן בשחיטת דרום דגרוע משאר פסולין והכא מיירי בהכניסה חיה וקלטוה כדין במה גדולה להצריך כיהון וריחוץ ידים ורגלים מן הכיור ואם היא שלמים בעי תנופת חזה ושוק ולפי גירסא זו גרסינן בסמוך אברי עולת במת יחיד שעלו למזבח של במה גדולה וירדו מהו שיעלו פירוש דכיון דשחטן בחוץ שמא הוי כמו שחטן בדרום וגם שמא כיון ששחטה בהיתר בחוץ בבמת יחיד שלכך הקדישה תחילה לכולי עלמא היכא דמשלה האור יעלה אבל ללשון ראשון דמבעיא ליה בלא משלה ומדמי ליה לשחיטת דרום הלא פשיטא אפי' שאר פסולין דלא גריעי כמו שחיטת דרום אם עלו וירדו לא יעלו כדאמר עולא פרק ב\"ש (שם) אם לא משלה בהן האור כשם שאם עלו לא ירדו כך אם ירדו לא יעלו וצריך לומר הא דקאמר מילתא דפשיטא לרבה ורב יוסף מיבעיא ליה לרבי ינאי היינו לאיכא דאמרי:"]]],[["שהכניסה לפנים והוציאה לחוץ מהו מי אמרי כיון דעיילא קלטה לה מחיצתא או דלמא כיון דהדר הדר","לאו היינו פלוגתא דרבה ורב יוסף דתנן קדשי קדשים ששחטן בדרום מועלין בהן (ואם עלו לא ירדו)","ואיבעיא להו ירדו מהו שיעלו רבה אמר לא יעלו ורב יוסף אמר יעלו","תיבעי לרבה תיבעי לרב יוסף תיבעי לרבה עד כאן לא קאמר רבה אלא במזבח דחזי ליה מקדש דלא חזי לא מקדש אבל מחיצה אע\"ג דלא חזי ליה קלטה","או דלמא אפי' לרב יוסף עד כאן לא קאמר רב יוסף התם אלא דחד מקום הוא אבל הכא דתרי מקומות נינהו לא או דלמא לא שנא תיקו","מילתא דפשיטא ליה לרבה בחד גיסא ולרב יוסף בחד גיסא מיבעי ליה לרבי ינאי דבעי רבי ינאי אברי עולת במת יחיד שעלו למזבח וירדו מהו היכא דלא משלה בהן האור לא תיבעי לך כי תיבעי לך היכא דמשלה בהן האור מאי תיקו","איתמר שחיטת לילה בבמת יחיד רב ושמואל חד אמר כשרה וחד אמר פסולה וקא מיפלגי בדרבי אלעזר","דרבי אלעזר רמי קראי אהדדי כתיב (שמואל א יד, לג) ויאמר בגדתם גלו אלי היום אבן גדולה","וכתיב (שמואל א יד, לד) ויאמר שאול פוצו בעם ואמרתם להם הגישו אלי איש שורו ואיש שיהו ושחטתם בזה ואכלתם ולא תחטאו לה' לאכול על הדם ויגישו כל העם איש שורו בידו הלילה וישחטו שם","מר משני כאן בחולין כאן בקדשים ומר משני כאן בקדשי במה גדולה כאן בקדשי במה קטנה","איתמר עולת במת יחיד רב אמר אין טעונה הפשט וניתוח ורבי יוחנן אמר טעונה הפשט וניתוח וקא מיפלגי בדר\"י הגלילי דתניא ר\"י הגלילי אומר עולה שהקריבו ישראל במדבר אין טעונה הפשט וניתוח שאין הפשט וניתוח אלא מאהל מועד ואילך","מר סבר מאהל מועד ואילך לא שנא במה גדולה ולא שנא במה קטנה ומר סבר בבמה גדולה אין בבמה קטנה לא","תניא כותיה דרבי יוחנן דברים שבין במה גדולה לבמה קטנה קרן וכבש ויסוד וריבוע בבמה גדולה ואין קרן ויסוד וכבש וריבוע בבמה קטנה כיור וכנו בבמה גדולה ואין כיור וכנו בבמה קטנה חזה ושוק בבמה גדולה ואין חזה ושוק בבמה קטנה","דברים ששוותה במה גדולה לבמה קטנה שחיטה בבמה גדולה וקטנה הפשט וניתוח בגדולה וקטנה דם מתיר ומפגל בגדולה וקטנה מומין וזמן בגדולה וקטנה","אבל נותר והזמן והטמא שוין בזה ובזה:","ת\"ר מנין לעשות זמן בבמה קטנה כבמה גדולה (אמרה תורה לן ישרף) ופיגול ישרף מה פיגול פסול בבמה אף לן פסול בבמה","או כלך לדרך זו) דהא אמרה תורה לן ישרף ויוצא ישרף מה יוצא כשר בבמה אף לן כשר בבמה ולאו ק\"ו הוא מעופות"],[[0,"שהכניסה","גרס בדרבי אלעזר שהכניסה לאחר ששחטה בחוץ קלטוה מחיצות לכל דבר גרס במסכת מעילה (דף ג.) אלמא אף קדשים שנשחטו בבמה קטנה שהקריבן בגדולה כל דין במה גדולה נוהג בהן ושמעינן מינה נמי דבשעת היתר במה נמי לא נשתנה דין גדולה מהלכתא ושתיהן הלשונות דרמי בר חמא פליגי אדרבי אלעזר:"],[0,"שהכניסה לפנים","אחר ששחטה בחוץ וחזר והוציאה:"],[0,"מהו","מי נהוג בה דין קדשי במה גדולה ליטעון בתרומת חזה ושוק וצריך להחזירה לפנים או לא:"],[1,"ה\"ג דתנן קדשי קדשים כו'","ולא גרסינן דאיתמר ולא גרס אם עלו לא ירדו ומשנה היא במסכת מעילה:"],[1,"מועלין בהן","ולא אמרינן כמאן דחנקינון דמי והוי להו כקדשים שמתו דיצאו מידי מעילה כדתניא במסכת מעילה:"],[1,"","ה\"ג במסכת מעילה והכי נמי גרסינן לה לאו היינו דרבה ורב יוסף דתנן קדשי קדשים ששחטן בדרום מועלין בהם ואיבעיא להו עלו מהו שירדו רבה אמר ירדו ורב יוסף אמר אם עלו לא ירדו רבה אמר ירדו דלא דמו לשאר פסולין שפסולן בקדש אלא כמאן דחנקינון דמי אלמא לרבה לא אמרינן קלוט לרב יוסף אמרינן קלוט:"],[3,"דלא חזי לא מקדש","דתניא בפ' המזבח [מקדש] (לעיל זבחים פג:) מתוך שנאמר כל הנוגע במזבח יקדש שומע אני בין ראוי בין שאינו ראוי ת\"ל עולה והני לאו ראוי נינהו דלרבה כמאן דחנקינון דמי:"],[4,"דחד מקום הוא","שהרי בעזרה נשחטו:"],[5,"דבעי רבי ינאי אברי עולת במת יחיד שעלו למזבח מהו שירדו","ה\"ג ובמעילה (דף ג:) נמי הכי גרס לה אבל לא ברבי ינאי גרס לה התם:"],[6,"אברי עולה שנשחטה בבמת יחיד","שלא במקומה הוא לגבי במה גדולה כקדשי קדשים ששחטן בדרום:"],[6,"","ה\"ג איתמר עולת במת יחיד ששחטה בלילה רב אמר כשר ושמואל אמר פסול וקמיפלגי בהא דרבי אלעזר רמי כתיב גולו אלי היום אבן גדולה בעוד שהוא יום אלמא דלילה פסולה בבמה קטנה והתם במה קטנה הואי שהרי במלחמה היו רודפים אחרי פלשתים וכתיב סיפא דקרא ויגישו כל העם איש שורו בידו הלילה:"],[9,"רב משני כאן בקדשי במה גדולה","שהוקדשו ליקרב בבמה גדולה ואע\"ג דאקרבינהו בבמה קטנה בעינן יום:"],[9,"כאן בקדשי במה קטנה","קרבו בלילה:"],[9,"","ושמואל משני הא דכתיב יום אקדשים קאי ואפילו בקדשי במה קטנה בעינן יום הא דכתיב לילה בחולין:"],[10,"שחיטה הפשט וניתוח כו'","דלא אשכחן בהו מיעוטא:"],[10,"במדבר","סיני:"],[11,"מאהל מועד ואילך","ששם נאמר בויקרא:"],[12,"קרן וכבש ויסוד וריבוע","ילפינן להו בפרק קדשי קדשים (לעיל זבחים סב.) ובמזבח של משכן כתיב כיור וכן בין אהל מועד ובין המזבח כתיב ביה (שמות ל׳:י״ח):"],[12,"חזה ושוק","תנופה לפני ה' כתיב בהו (ויקרא ז׳:ל׳):"],[13,"שחיטה הפשט וניתוח כו'","דלא אשכחן בהו מיעוטא:"],[13,"דם","לזריקה מתיר את הבשר בזריקה ומקמי זריקה אסירא:"],[13,"ומפגל","פיגול נוהג בהן כדיליף לקמן:"],[13,"ומומין","דלא אשכחן דשרינהו בקטנה:"],[13,"וזמן","לאכילה:"],[15,"אבל הזמן והנותר והטמא כו'","סיפא דמתני' היא ולא בברייתא הוא:"],[15,"מנין לעשות זמן","להיות נפסל בנותר:"],[15,"הלן","היינו נותר:"],[16,"והיוצא ישרף","נפקא לן בפסחים (דף פב.) מהן לא הובא את דמה אל הקדש פנימה היתה לפיכך אכל תאכלו אותה הא אם לא היתה פנימה ראויה היא לישרף:"],[16,"מה יוצא כשר בבמה","קטנה שהרי כשירה בלא מחיצות אף לן כשר ומעתה לא יהא הזמן פוסל דהא אתיא מהאי דינא כדאמרן:"],[16,"ודין הוא","מדרך אחרת שיהא הזמן פוסל בה:"]],[]],[["מה עופות שאין המום פוסל בהן זמן פוסל בהן קדשי במה קטנה שהמום פוסל בהן אינו דין שזמן פוסל בהן","מה לעופות שכן אין הזר כשר בהן תאמר בבמה קטנה שהזר כשר בה לא יהא זמן פסול בה ת\"ל (ויקרא ז, יא) וזאת תורת זבח השלמים לעשות זמן במה קטנה כזמן במה גדולה:","\u0001הדרן עלך פרת חטאת וסליקא לה מסכת זבחים\u0002"],[[0,"ומה עופות שאין המום פוסל בהן","דאמר מר (תמורה דף יד.) אין תמות וזכרות בעופות:"],[0,"זמן פוסל בהן","דהא רבינהו להו גבי פיגול בפ' בית שמאי (לעיל זבחים מד.) אלמא פסול בהו זמן:"],[1,"תורת זבח השלמים","תורה אחת לכל השלמים ואפילו לשלמי במה קטנה למה שאמור בענין ומה אמור באותו ענין זמן לתודה וזמן לשלמים ומחשבת פיגול והא דאיצטריך לרבויינהו משום דאתי מבנין אב דהלן ישרף והיוצא ישרף דלא יפסול בה זמן לפיכך הוצרך לרבותו:"],[1,"לעשות זמן במה קטנה כזמן במה גדולה","לתודה יום ולילה ולשלמים שני ימים ולילה אחד ונותר נמי מפיגול יליף (שם) מג\"ש דעון עון וטמא נמי בההיא פרשתא כתיב (ויקרא ז׳:כ׳) והנפש אשר תאכל וגו':"]],[]]]};
